reviews.source_excerpt:
def emit(value) -> None:
    if _ACTIVE_ARGS is not None:
        record_cli_operation(_ACTIVE_ARGS, value)
    print(json.dumps(value, ensure_ascii=False, indent=2))

def main() -> int:
    global _ACTIVE_ARGS
    args = parser().parse_args()
    _ACTIVE_ARGS = args
    if args.command == "doctor":
        report = doctor_report()
        report["runtime"] = deployment_plan()
        emit(report)
        return 0 if report["status"] == "ready" else 3
    if args.command == "init":
        emit(initialize(args.repo.resolve(), args.out.resolve(), args.format, args.scope_path, args.entry, args.expand_depth, args.expand_direction, args.include, args.init_git, args.initial_commit_message, args.git_author_name, args.git_author_email, args.csharp_solution, args.csharp_project, args.allow_dotnet_restore, args.page_config.resolve() if args.page_config else None))
    elif args.command == "run":
        emit(run_fast(repo=args.repo.resolve() if args.repo else None, output=args.out.resolve(), format_name=args.format, resume=args.resume, scope_paths=args.scope_path, entries=args.entry, expand_depth=args.expand_depth, expand_direction=args.expand_direction, includes=args.include, init_git=args.init_git, initial_commit_message=args.initial_commit_message, git_author_name=args.git_author_name, git_author_email=args.git_author_email, csharp_solution=args.csharp_solution, csharp_project=args.csharp_project, allow_dotnet_restore=args.allow_dotnet_restore, page_config_path=args.page_config.resolve() if args.page_config else None))
    elif args.command == "build-chunk":
        emit(build_chunk(args.out.resolve(), args.chunk, args.stage))
    elif args.command == "review-chunk":
        emit(review_chunk(args.out.resolve(), args.chunk, args.review.resolve()))
    elif args.command == "review-pack":
        emit(review_pack(args.out.resolve(), args.pack, args.review.resolve()))
    elif args.command == "audit":
        result = audit_global(args.out.resolve()) if args.global_audit else audit_chunk(args.out.resolve(), args.chunk)
        emit(result)
        return 0 if result.get("status") == "passed" else 5
    elif args.command == "merge":
        emit(merge(args.out.resolve()))
    elif args.command == "finalize":
        emit(finalize(args.out.resolve()))
    elif args.command == "status":
        emit(status(args.out.resolve()))
    elif args.command == "human-refresh":
        result = refresh_human_navigation(args.out.resolve(), staging=args.staging)
        emit(result)
        return 0 if result.get("status") == "passed" else 5
    elif args.command == "migrate":
        if args.migration_command == "batch":
            if args.migration_batch_command == "plan":
                result = create_knowledge_batch_plan(args.manifest, args.write)
                emit(result)
                return 0 if result.get("status") == "ready" else 5
            if args.migration_batch_command == "apply":
                result = apply_knowledge_batch_plan(args.plan, args.state)
                emit(result)
                return 4 if result.get("status") == "review-pending" else 0 if result.get("status") in {"ready", "cutover-complete"} else 5
            if args.migration_batch_command == "resume":
                result = resume_knowledge_batch_state(args.state)
                emit(result)
                return 4 if result.get("status") == "review-pending" else 0 if result.get("status") in {"ready", "cutover-complete"} else 5
            if args.migration_batch_command == "status":
                result = knowledge_batch_status(args.state)
                emit(result)
                return 4 if result.get("status") == "review-pending" else 0 if result.get("status") not in {"failed", "drifted"} else 5
            if args.migration_batch_command == "audit":
                result = audit_knowledge_batch_state(args.state)
                emit(result)
                return 0 if result.get("status") == "passed" else 4 if result.get("status") == "review-pending" else 5
            if args.migration_batch_command == "cutover":
                result = cutover_knowledge_batch_state(args.state, args.project)
                emit(result)
                return 0 if result.get("status") == "passed" else 5
            result = rollback_knowledge_batch_state(args.state, args.project)
            emit(result)
            return 0 if result.get("status") == "passed" else 5
        if args.migration_command == "start":
            result = migrate_output(args.from_out, args.repo, args.out, args.format)
            emit(result)
            return 4 if result.get("status") == "pending-agent-review" else 0
        if args.migration_command == "status":
            result = migration_status(args.out)
            emit(result)
            return 4 if result.get("status") == "pending-agent-review" else 0
        result = audit_migration(args.out, require_complete_reviews=not args.allow_pending_reviews)
        emit(result)
        return 0 if result.get("status") == "passed" else 4 if result.get("status") == "pending-agent-review" else 5
    elif args.command == "scope":
        if args.scope_extend_command == "start":
            result = start_scope_extension(args.from_out, args.repo, args.staging, args.entry, args.expand_depth, args.expand_direction)
            emit(result)
            return 4 if result.get("status") == "pending-agent-review" else 0
        if args.scope_extend_command == "status":
            result = extension_status(args.out)
            emit(result)
            return 4 if result.get("status") in {"pending-agent-review", "ready-for-audit"} else 0
        if args.scope_extend_command == "audit":
            result = audit_scope_extension(args.out)
            emit(result)
            return 0 if result.get("status") == "ready" else 5
        if args.scope_extend_command == "cutover":
            emit(cutover_scope_extension(args.out))
        else:
            emit(rollback_scope_extension(args.out))
    elif args.command == "context":
        emit(build_context(args.out.resolve(), args.module, args.entry))
    elif args.command == "query":
        emit(query_graph(args.out.resolve(), args.question, args.budget, args.dfs))
    elif args.command == "retrieve":
        output = args.out.resolve()
        fallback_options = keyword_fallback_options(args)
        session_value = (
            _session_query(
                output,
                {
                    "id": "retrieve-" + os.urandom(8).hex(),
                    "method": "retrieve",
                    "question": args.question,
                    "budget": args.budget,
                    "max_pages": args.max_pages,
                    "profile": args.profile,
                },
            )
            if fallback_options is None
            else None
        )
        if session_value is not None:
            emit(session_value)
            return 0
        if (output / "machine/knowledge.sqlite").is_file():
            emit(
                retrieve_machine(
                    output,
                    args.question,
                    args.budget,
                    args.max_pages,
                    args.profile,
                    keyword_fallback=fallback_options,
                )
            )
        else:
            if fallback_options is not None:
                raise CkbError("keyword fallback requires machine/knowledge.sqlite")
            emit(retrieve(output, args.question, args.budget, args.max_pages))
    elif args.command == "brief":
        output = args.out.resolve()
        fallback_options = keyword_fallback_options(args)
        session_value = (
            _session_query(
                output,
                {
                    "id": "brief-" + os.urandom(8).hex(),
                    "method": "brief",
                    "question": args.question,
                    "budget": args.budget,
                    "max_pages": args.max_pages,
                    "profile": args.profile,
                },
            )
            if fallback_options is None
            else None
        )
        if session_value is not None:
            emit(session_value)
            return 0
        if fallback_options is not None and not (output / "machine/knowledge.sqlite").is_file():
            raise CkbError("keyword fallback requires machine/knowledge.sqlite")
        retrieval_result = (
            retrieve_machine(
                output,
                args.question,
                args.budget,
                args.max_pages,
                args.profile,
                keyword_fallback=fallback_options,
            )
            if (output / "machine/knowledge.sqlite").is_file()
            else retrieve(output, args.question, args.budget, args.max_pages)
        )
        emit(compact_agent_brief(output, retrieval_result))
    elif args.command == "keyword-benchmark":
        if args.keyword_provider_no_cache:
            raise CkbError("keyword benchmark requires cache measurement")
        result = run_keyword_benchmark(
            args.out.resolve(),
            args.cases.resolve(),
            args.write.resolve(),
            keyword_provider_config(args),
        )
        emit(result)
        return 0 if result.get("status") == "passed" else 5
    elif args.command == "capabilities":
        if args.write:
            emit(write_capability_matrix(args.write, args.format))
        elif args.format == "markdown":
            print(render_capability_matrix_markdown(), end="")
        else:
            emit(capability_matrix())
    elif args.command == "maintain":
        result = maintenance_check(args.out.resolve())
        emit(result)
        return 0 if result.get("status") == "passed" else 5
    elif args.command == "operations":
        if args.operations_command == "list":
            emit(list_operations(args.out.resolve(), args.operation, args.result_status, args.limit))
        else:
            result = audit_operation_journal(args.out.resolve())
            emit(result)
            return 0 if result.get("status") == "passed" else 5
    elif args.command == "gaps":
        if args.gaps_command == "create":
            emit(create_gap(args.out.resolve(), args.kind, args.summary.resolve(), args.evidence))
        elif args.gaps_command == "list":
            emit(list_gaps(args.out.resolve(), args.status, args.kind))
        elif args.gaps_command == "resolve":
            emit(resolve_gap(args.out.resolve(), args.gap, args.resolution.resolve(), args.evidence))
        else:
            result = audit_gap_register(args.out.resolve())
            emit(result)
            return 0 if result.get("status") == "passed" else 5
    elif args.command == "reference":
        if args.reference_command == "ingest":
            result = ingest_reference(
                args.out.resolve(), args.source.resolve(), args.title, args.origin, args.license_name,
                args.author, args.revision_of,
            )
            emit(result)
            return 4 if result.get("status") == "pending-agent-review" else 0
        if args.reference_command == "review-template":
            emit(write_reference_review_template(args.out.resolve(), args.reference, args.write))
        elif args.reference_command == "review":
            emit(submit_reference_review(args.out.resolve(), args.review.resolve()))
        elif args.reference_command == "audit":
            result = audit_references(args.out.resolve())
            emit(result)
            return 0 if result.get("status") == "passed" else 4 if result.get("status") == "pending-agent-review" else 5
        elif args.reference_command == "list":
            emit(list_references(args.out.resolve(), args.status))
        else:
            emit(rollback_reference(args.out.resolve(), args.reference))
    elif args.command == "serve":
        serve_stdio(args.out.resolve())
    elif args.command == "stdio-session":
        if args.session_stdio_command == "request":
            raw_text = args.request.read_text(encoding="utf-8-sig") if args.request else sys.stdin.read()
            request = json.loads(raw_text)
            emit(
                request_session(
                    harness=args.harness,
                    session_id=args.session_id,
                    output=args.out,
                    request=request,
                    root=args.root,
                    parent_pid=args.parent_pid,
                    start_timeout=args.start_timeout,
                    request_timeout=args.request_timeout,
                )
            )
        elif args.session_stdio_command == "list":
            emit(list_sessions(root=args.root, active_only=args.active))
        elif args.session_stdio_command == "status":
            listing = list_sessions(root=args.root)
            opaque = session_digest(args.session_id)
            output_identity = str(args.out.resolve()).replace("\\", "/").casefold()
            matches = [
                item
                for item in listing["leases"]
                if item.get("harness") == args.harness
                and item.get("session_digest") == opaque
                and str(item.get("output") or "").replace("\\", "/").casefold() == output_identity
            ]
            emit(
                {
                    "schema_version": 1,
                    "status": "ready" if any(item.get("active") for item in matches) else "closed" if matches else "not-started",
                    "count": len(matches),
                    "leases": matches,
                }
            )
        elif args.session_stdio_command in {"close", "terminate", "cancel"}:
            emit(
                close_session(
                    harness=args.harness,
                    session_id=args.session_id,
                    output=args.out,
                    root=args.root,
                    reason=args.session_stdio_command,
                    timeout=args.timeout,
                )
            )
        elif args.session_stdio_command == "cleanup":
            emit(cleanup_sessions(root=args.root))
        elif args.session_stdio_command == "audit":
            result = audit_sessions(root=args.root)
            emit(result)
            return 0 if result.get("status") == "passed" else 5
        elif args.session_stdio_command == "metrics":
            emit({"schema_version": 1, "status": "passed", "metrics": process_metrics(args.pid)})
        else:
            controller_main(
                root=args.root,
                key=args.key,
                harness=args.harness,
                opaque_session=args.session_digest,
                output=args.out,
                executable=args.python,
                ckb=args.ckb,
                parent_pid=args.parent_pid,
                generation=args.generation,
            )
    elif args.command == "reindex":
        output = args.out.resolve()
        emit({"status": "passed", "machine": build_machine_knowledge(output), "compatibility": build_agent_index(output)})
    elif args.command == "coverage":
        emit(machine_coverage(args.out.resolve()))
    elif args.command == "entity":
        emit(
            _session_query(
                args.out.resolve(),
                {"id": "entity-" + os.urandom(8).hex(), "method": "entity", "selector": args.selector},
            )
            or entity_lookup(args.out.resolve(), args.selector)
        )
    elif args.command == "neighbors":
        emit(
            _session_query(
                args.out.resolve(),
                {
                    "id": "neighbors-" + os.urandom(8).hex(),
                    "method": "neighbors",
                    "selector": args.selector,
                    "depth": args.depth,
                    "relation": args.relation,
                    "limit": args.limit,
                },
            )
            or neighbor_lookup(args.out.resolve(), args.selector, args.depth, args.relation, args.limit)
        )
    elif args.command == "source":
        emit(
            _session_query(
                args.out.resolve(),
                {
                    "id": "source-" + os.urandom(8).hex(),
                    "method": "source",
                    "selector": args.selector,
                    "context_lines": args.context_lines,
                },
            )
            or source_lookup(args.out.resolve(), args.selector, args.context_lines)
        )
    elif args.command == "changes":
        emit(
            _session_query(
                args.out.resolve(),
                {"id": "changes-" + os.urandom(8).hex(), "method": "changes", "kind": args.kind, "limit": args.limit},
            )
            or change_documents(args.out.resolve(), args.kind, args.limit)
        )
    elif args.command == "path":
        emit(shortest_path(args.out.resolve(), args.source, args.target))
    elif args.command == "explain":
        emit(explain_node(args.out.resolve(), args.selector))
    elif args.command == "record":
        emit(
            record_note(
                args.out.resolve(),
                args.kind,
                args.title,
                args.body.resolve(),
                args.link,
                (args.from_query or args.from_pack).resolve() if (args.from_query or args.from_pack) else None,
                args.append,
            )
        )
    elif args.command == "obsidian-plugin":
        if args.obsidian_plugin_command == "register":
            emit(register_obsidian_plugin(args.package.resolve()))
        elif args.obsidian_plugin_command == "deploy":
            emit(deploy_obsidian_plugin(args.out.resolve()))
        elif args.obsidian_plugin_command == "status":
            emit(obsidian_plugin_status(args.out.resolve() if args.out else None))
        else:
            emit(remove_obsidian_plugin(args.out.resolve()))
    elif args.command == "feedback":
        if args.feedback_command == "create":
            emit(
                create_feedback(
                    args.out.resolve(),
                    args.target,
                    args.start_line,
                    args.end_line,
                    args.comment.resolve(),
                    args.severity,
                    args.author,
                    args.source,
                )
            )
        elif args.feedback_command == "list":
            emit(list_feedback(args.out.resolve(), args.status))
        elif args.feedback_command == "locate":
            result = locate_feedback(args.out.resolve(), args.feedback)
            emit(result)
            return 0 if result.get("status") == "passed" else 5
        elif args.feedback_command == "resolve":
            emit(
                resolve_feedback(
                    args.out.resolve(),
                    args.feedback,
                    args.decision,
                    args.resolution.resolve(),
                    args.applied_record.resolve() if args.applied_record else None,
                )
            )
        else:
            result = audit_feedback(args.out.resolve())
            emit(result)
            return 0 if result.get("status") == "passed" else 5
    elif args.command == "workspace":
        if args.workspace_command == "sync":
            output = args.out.resolve()
            workspace = sync_workspace(output, args.repo.resolve())
            emit({**workspace, "machine": sync_workspace_changes(output)})
        elif args.workspace_command == "status":
            emit(workspace_status(args.out.resolve()))
        elif args.workspace_command == "session-start":
            emit(start_session(args.out.resolve(), args.repo.resolve(), args.question, args.budget, args.profile))
        elif args.workspace_command == "session-finish":
            emit(finish_session(args.out.resolve(), args.repo.resolve(), args.session, args.summary.resolve(), args.title))
        else:
            emit(sessions_status(args.out.resolve()))
    elif args.command == "agent-policy":
        if args.agent_policy_command == "batch":
            if args.agent_policy_batch_command == "plan":
                result = create_batch_plan(args.manifest, args.write)
                emit(result)
                return 0 if result.get("status") == "ready" else 5
            if args.agent_policy_batch_command == "apply":
                result = apply_batch_plan(args.plan, args.state)
                emit(result)
                return 0 if result.get("status") == "completed" else 5
            if args.agent_policy_batch_command == "status":
                result = batch_status(args.state)
                emit(result)
                return 0 if result.get("status") == "completed" else 5
            if args.agent_policy_batch_command == "audit":
                result = audit_batch_state(args.state)
                emit(result)
                return 0 if result.get("status") == "passed" else 5
            result = rollback_batch_state(args.state, args.project)
            emit(result)
            return 0 if result.get("status") == "passed" else 5
        elif args.agent_policy_command == "install":
            emit(
                install_agent_protocol(
                    args.out.resolve(),
                    [path.resolve() for path in args.workspace_root],
                    python=args.python.resolve() if args.python else None,
                    ckb=args.ckb.resolve() if args.ckb else None,
                )
            )
        elif args.agent_policy_command == "check":
            result = audit_agent_protocol(args.out.resolve())
            emit(result)
            return 0 if result.get("status") == "passed" else 5
        else:
            emit(agent_protocol_status(args.out.resolve()))
    elif args.command == "automation":
        if args.automation_command == "register":
            emit(
                register_project(
                    args.repo,
                    args.out,
                    args.registry,
                    args.harness or None,
                    max_field_chars=args.max_field_chars,
                    custom_redactions=args.redact,
                    workspace_roots=args.workspace_root,
                )
            )
        elif args.automation_command == "unregister":
            emit(unregister_project(args.repo, args.registry))
        elif args.automation_command == "registry":
            emit(registry_status(args.registry))
        elif args.automation_command == "activate":
            emit(
                activate_skill_session(
                    args.harness,
                    args.session_id,
                    args.cwd,
                    args.registry,
                    args.source,
                    args.parent_pid,
                    args.stdio_root,
                )
            )
        elif args.automation_command in {"ingest", "hook"}:
            try:
                raw_text = args.event.read_text(encoding="utf-8-sig") if args.event else sys.stdin.read()
                raw = json.loads(raw_text)
                result = ingest_event(args.harness, raw, args.registry)
                emit(result["hook_output"] if args.automation_command == "hook" else result)
            except Exception as exc:
                if args.automation_command != "hook":
                    raise
                print(f"CKB_AUTOMATION_HOOK_ERROR={type(exc).__name__}: {exc}", file=sys.stderr)
                emit({})
        elif args.automation_command == "drain":
            emit(drain_automation(args.out, args.limit))
        elif args.automation_command == "retry":
            emit(retry_failed_automation(args.out, args.limit))
        elif args.automation_command == "status":
            emit(automation_status(args.out))
        elif args.automation_command == "pending":
            emit(pending_automation_reviews(args.out, args.all))
        elif args.automation_command == "review":
            emit(review_automation(args.out, args.review))
        elif args.automation_command == "review-template":
            emit(write_automation_review_template(args.out, args.review_id, args.write))
        else:
            emit(render_integration(args.harness, args.destination, args.python, args.ckb, args.registry, force=args.force))
    elif args.command == "manager":
        if args.manager_command == "bind":
            if args.input:
                payload = json.loads(args.input.read_text(encoding="utf-8-sig"))
            else:
                required = {
                    "conversation_id": args.conversation_id,
                    "harness_id": args.harness,
                    "workspace_root": str(args.workspace_root) if args.workspace_root else None,
                    "repo_root": str(args.repo) if args.repo else None,
                    "knowledge_base": str(args.out) if args.out else None,
                    "integration_branch": args.integration_branch,
                }
                missing = sorted(key for key, value in required.items() if not value)
                if missing:
                    raise CkbError(f"manager bind requires --input or direct fields: missing={missing}")
                payload = {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    **required,
                    "notification_policy": args.notification_policy,
                }
            emit(bind_conversation(payload, args.registry))
        elif args.manager_command == "status":
            result = binding_status(args.conversation_id, args.harness, args.registry)
            emit(result)
            return 0 if result.get("status") == "ready" else 5
        elif args.manager_command == "context":
            result = management_context(
                args.conversation_id,
                args.harness,
                args.question,
                args.registry,
                python=args.python,
                ckb=args.ckb,
            )
            if args.format == "prompt":
                print(result["prompt"], end="")
            else:
                emit(result)
            return 0 if result.get("status") == "ready" else 5
        elif args.manager_command == "unbind":
            emit(unbind_conversation(args.conversation_id, args.harness, args.registry))
        elif args.manager_command == "audit":
            result = audit_manager_registry(args.registry)
            emit(result)
            return 0 if result.get("status") == "passed" else 5
        elif args.manager_command == "schema":
            value = binding_schema()
            if args.write:
                if args.write.exists():
                    raise CkbError(f"management schema target already exists: {args.write}")
                args.write.parent.mkdir(parents=True, exist_ok=True)
                args.write.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
                emit({"schema_version": MANAGEMENT_SCHEMA_VERSION, "status": "written", "path": str(args.write.resolve())})
            else:
                emit(value)
        elif args.manager_command == "capabilities":
            harnesses = args.harness or sorted(SUPPORTED_HARNESSES)
            emit(
                {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    "status": "ready",
                    "harnesses": {harness: harness_capabilities(harness) for harness in harnesses},
                }
            )
        elif args.manager_command == "task-create":
            emit(
                create_management_task(
                    args.conversation_id,
                    args.harness,
                    args.task_id,
                    args.branch,
                    args.worktree,
                    args.registry,
                    allowed_paths=args.allow_path,
                    forbidden_paths=args.forbid_path,
                    tests=args.test,
                    python=args.python,
                    ckb=args.ckb,
                )
            )
        elif args.manager_command == "task-status":
            result = management_task_status(args.dispatch_id, args.registry)
            emit(result)
            return 0 if result.get("status") == "merge-ready" else 5
        else:
            result = review_management_task(args.dispatch_id, args.registry)
            emit(result)
            return 0 if result.get("status") == "passed" else 5
    elif args.command == "relink":
        emit(relink_sources(args.out.resolve(), args.repo_root.resolve(), args.editor, args.source_view, args.custom_template))
    elif args.command == "showcase":
        emit(package_showcase(args.dist.resolve(), args.sample))
    elif args.command == "page-config":
        if args.write:
            emit(write_page_config(args.write, DEFAULT_PAGE_CONFIG, overwrite=args.force))
        else:
            config, source = load_page_config(args.validate)
            emit({"schema_version": config["schema_version"], "status": "passed", "source": source, "sha256": page_config_sha256(config), "normalized": config})
    elif args.command == "runtime":
        if args.runtime_command == "plan":
            emit(deployment_plan())
        elif args.runtime_command == "deploy":
            emit(deploy_runtime(args.accept))
        elif args.runtime_command == "remove":
            emit(remove_runtime(args.lock_id))
    return 0

"""SQLite page-first retrieval index for bounded Agent context packs."""

from __future__ import annotations

from collections import defaultdict
import datetime
import json
import math
from pathlib import Path
import re
import sqlite3
from typing import Any

from .common import CkbError, json_load, json_write, utc_now
from .obsidian import NOTE_DIRECTORIES
from .query_terms import build_fts_query, index_terms, search_terms
from .source_links import ensure_local_openers, source_markdown_link


INDEX_SCHEMA_VERSION = 1
DEFAULT_PAGE_LIMIT = 8


def _tokens(text: str) -> int:
    return math.ceil(len(text.encode("utf-8")) / 3)


def _note_documents(markdown_root: Path) -> list[dict[str, Any]]:
    documents = []
    for directory in NOTE_DIRECTORIES:
        for path in sorted((markdown_root / directory).glob("*.md")):
            text = path.read_text(encoding="utf-8")
            title = text.splitlines()[0].removeprefix("# ").strip() if text else path.stem
            tag_match = re.search(r"#类型/[\w\u3400-\u9fff-]+", text)
            documents.append(
                {
                    "title": title,
                    "tag": tag_match.group(0) if tag_match else "",
                    "file": path.relative_to(markdown_root).as_posix(),
                    "content": text,
                    "links": re.findall(r"\[\[([^\]|#]+)", text),
                }
            )
    return documents


def _projection(output: Path) -> tuple[dict[str, Any], str]:
    """Select the richest completed human projection without requiring Markdown."""
    state_path = output / "state.json"
    if state_path.is_file() and json_load(state_path).get("format") == "logseq-db":
        logseq = output / "logseq-db/projection.json"
        if logseq.is_file():
            return json_load(logseq), "logseq-db"
    markdown = output / "markdown/projection.json"
    if markdown.is_file():
        return json_load(markdown), "markdown"
    logseq = output / "logseq-db/projection.json"
    if logseq.is_file():
        return json_load(logseq), "logseq-db"
    raise CkbError("Agent index requires a finalized Markdown or Logseq DB projection")


def _page_documents(
    output: Path,
    projection: dict[str, Any],
    projection_format: str,
    graph: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    """Return readable page documents for either projection.

    Markdown pages are indexed byte-for-byte.  A DB-only build has no page
    files, so the same reviewed source facts are rendered into a compact
    index-only narrative.  This keeps retrieval format-neutral without adding
    another visible knowledge-base projection.
    """
    page_by_id = {page["id"]: page for page in projection.get("pages", [])}
    title_by_id = {page_id: page["title"] for page_id, page in page_by_id.items()}
    owner_by_entity = projection.get("entity_owner_pages", {})
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    owned: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            owned[owner].append(entity)

    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    documents: dict[str, dict[str, Any]] = {}
    for page_id, page in page_by_id.items():
        entity = entity_by_id.get(page_id)
        if projection_format == "markdown":
            relative = Path("markdown") / page["file"]
            content = (output / relative).read_text(encoding="utf-8")
        else:
            relative = Path("logseq-db/normalized.edn")
            lines = [f"# {page['title']}", "", f"标签：{page.get('tag') or ''}", ""]
            if entity:
                overview = " ".join(
                    value.strip()
                    for value in (str(entity.get("meaning_zh", "")), str(entity.get("role_zh", "")))
                    if value.strip()
                )
                if overview:
                    lines.extend([f"> {overview}", ""])
                if entity.get("change_when_zh"):
                    lines.extend(["## 什么时候需要修改", "", str(entity["change_when_zh"]), ""])
                if entity.get("path") and entity.get("range"):
                    lines.extend(
                        [
                            "## 源码位置",
                            "",
                            source_markdown_link(
                                openers,
                                str(entity["path"]),
                                int(entity["range"]["start_line"]),
                                int(entity["range"]["end_line"]),
                            ),
                            "",
                        ]
                    )
            else:
                lines.extend(["> 这是由相关类、函数和辅助实现组成的职责导航页。", ""])
            appendix = [item for item in owned.get(page_id, []) if item.get("classification") == "appendix"]
            if appendix:
                lines.extend(["## 内部细节", ""])
                for item in sorted(appendix, key=lambda value: (value.get("path", ""), value.get("range", {}).get("start_line", 0), value.get("qualified_name", ""))):
                    lines.append(f"- `{item.get('qualified_name') or item.get('name')}`：{item.get('description_zh') or item.get('role_zh') or '承担局部辅助处理。'}")
                lines.append("")
            neighbors = []
            for link in projection.get("links", []):
                if link.get("source") == page_id and link.get("target") in title_by_id:
                    neighbors.append(title_by_id[link["target"]])
                elif link.get("target") == page_id and link.get("source") in title_by_id:
                    neighbors.append(title_by_id[link["source"]])
            if neighbors:
                lines.extend(["## 相关代码", "", *[f"- [[{title}]]" for title in sorted(set(neighbors))], ""])
            content = "\n".join(lines).rstrip() + "\n"
        summary = next(
            (
                line.removeprefix("> ").strip()
                for line in content.splitlines()
                if line.startswith("> ") and line.removeprefix("> ").strip()
            ),
            page["title"],
        )
        source_range = entity.get("range", {}) if entity else {}
        documents[page_id] = {
            "content": content,
            "summary": summary,
            "page_file": relative.as_posix(),
            "source_path": entity.get("path") if entity else None,
            "start_line": source_range.get("start_line"),
            "end_line": source_range.get("end_line"),
        }
    return documents


def build_agent_index(output: Path) -> dict[str, Any]:
    markdown_root = output / "markdown"
    projection, projection_format = _projection(output)
    graph = json_load(output / "graph.json")
    pages = projection.get("pages", [])
    documents = _page_documents(output, projection, projection_format, graph)
    page_by_id = {page["id"]: page for page in pages}
    owner_by_entity = projection.get("entity_owner_pages", {})
    symbols_by_page: dict[str, list[str]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            for value in (entity.get("name"), entity.get("qualified_name")):
                if value:
                    symbols_by_page[owner].append(str(value))
    index = output / "agent-index.sqlite"
    temporary = output / "agent-index.sqlite.tmp"
    temporary.unlink(missing_ok=True)
    connection = sqlite3.connect(temporary)
    try:
        connection.executescript(
            """
            PRAGMA foreign_keys=ON;
            CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE pages(
                page_id TEXT PRIMARY KEY,
                title TEXT NOT NULL UNIQUE,
                page_type TEXT NOT NULL,
                tag TEXT NOT NULL,
                page_file TEXT NOT NULL,
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER,
                summary TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE symbols(
                symbol TEXT NOT NULL,
                qualified_name TEXT NOT NULL,
                owner_page_id TEXT NOT NULL REFERENCES pages(page_id),
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER
            );
            CREATE INDEX symbols_name ON symbols(symbol COLLATE NOCASE);
            CREATE INDEX symbols_qname ON symbols(qualified_name COLLATE NOCASE);
            CREATE TABLE edges(
                source_page_id TEXT NOT NULL REFERENCES pages(page_id),
                target_page_id TEXT NOT NULL REFERENCES pages(page_id),
                relation TEXT NOT NULL,
                weight REAL NOT NULL,
                PRIMARY KEY(source_page_id,target_page_id,relation)
            );
            CREATE INDEX edges_target ON edges(target_page_id);
            CREATE TABLE terms(
                term TEXT NOT NULL,
                page_id TEXT NOT NULL REFERENCES pages(page_id),
                weight REAL NOT NULL,
                PRIMARY KEY(term,page_id)
            );
            CREATE INDEX terms_term ON terms(term);
            CREATE TABLE notes(
                note_title TEXT PRIMARY KEY,
                tag TEXT NOT NULL,
                note_file TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE note_links(
                note_title TEXT NOT NULL REFERENCES notes(note_title),
                page_title TEXT NOT NULL,
                PRIMARY KEY(note_title,page_title)
            );
            CREATE VIRTUAL TABLE page_fts USING fts5(
                page_id UNINDEXED,
                title,
                summary,
                symbols,
                source_path,
                tokenize='trigram'
            );
            CREATE VIRTUAL TABLE note_fts USING fts5(
                note_title UNINDEXED,
                title,
                content,
                tokenize='trigram'
            );
            """
        )
        connection.executemany(
            "INSERT INTO meta(key,value) VALUES(?,?)",
            [
                ("schema_version", str(INDEX_SCHEMA_VERSION)),
                ("status", "ready"),
                ("built_at_utc", utc_now()),
                ("page_count", str(len(pages))),
                ("projection_format", projection_format),
            ],
        )
        entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
        for page in pages:
            document = documents[page["id"]]
            content = document["content"]
            summary = document["summary"]
            source_path = document["source_path"]
            symbols = sorted(set(symbols_by_page.get(page["id"], [])))
            connection.execute(
                "INSERT INTO pages VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (
                    page["id"],
                    page["title"],
                    page["page_type"],
                    page.get("tag") or "",
                    document["page_file"],
                    source_path,
                    document["start_line"],
                    document["end_line"],
                    summary,
                    content,
                    _tokens(content),
                ),
            )
            connection.execute(
                "INSERT INTO page_fts(page_id,title,summary,symbols,source_path) VALUES(?,?,?,?,?)",
                (page["id"], page["title"], summary, " ".join(symbols), source_path or ""),
            )
            weighted_terms: dict[str, float] = {}
            for value, weight in ((page["title"], 8.0), (" ".join(symbols), 6.0), (summary, 3.0), (source_path or "", 2.0)):
                for term in index_terms(value):
                    weighted_terms[term] = max(weighted_terms.get(term, 0.0), weight)
            connection.executemany(
                "INSERT INTO terms(term,page_id,weight) VALUES(?,?,?)",
                [(term, page["id"], weight) for term, weight in sorted(weighted_terms.items())],
            )
        for entity in graph.get("entities", []):
            owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
            if owner not in page_by_id:
                continue
            source_range = entity.get("range", {})
            connection.execute(
                "INSERT INTO symbols VALUES(?,?,?,?,?,?)",
                (
                    str(entity.get("name") or entity.get("qualified_name") or ""),
                    str(entity.get("qualified_name") or entity.get("name") or ""),
                    owner,
                    entity.get("path"),
                    source_range.get("start_line"),
                    source_range.get("end_line"),
                ),
            )
        relation_weight = {"tested-by": 1.4, "calls": 1.3, "invokes": 1.3, "depends-on": 1.2, "uses": 1.1, "contains": 0.8}
        for link in projection.get("links", []):
            if link["source"] not in page_by_id or link["target"] not in page_by_id:
                continue
            connection.execute(
                "INSERT OR REPLACE INTO edges VALUES(?,?,?,?)",
                (link["source"], link["target"], link["type"], relation_weight.get(link["type"], 1.0)),
            )
        for note in _note_documents(markdown_root) if projection_format == "markdown" else []:
            connection.execute(
                "INSERT INTO notes VALUES(?,?,?,?,?)",
                (note["title"], note["tag"], note["file"], note["content"], _tokens(note["content"])),
            )
            connection.execute(
                "INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)",
                (note["title"], note["title"], note["content"]),
            )
            for title in note["links"]:
                connection.execute("INSERT OR IGNORE INTO note_links VALUES(?,?)", (note["title"], title))
        connection.commit()
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        if integrity != "ok" or foreign_keys:
            raise CkbError(f"Agent index integrity failed: integrity={integrity}; foreign_keys={foreign_keys}")
    finally:
        connection.close()
    temporary.replace(index)
    return audit_agent_index(output)


def audit_agent_index(output: Path) -> dict[str, Any]:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        return {"schema_version": 1, "status": "failed", "errors": [{"reason": "agent-index-missing"}]}
    projection, projection_format = _projection(output)
    expected_notes = len(_note_documents(output / "markdown")) if projection_format == "markdown" else 0
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        counts = {
            "pages": connection.execute("SELECT count(*) FROM pages").fetchone()[0],
            "symbols": connection.execute("SELECT count(*) FROM symbols").fetchone()[0],
            "edges": connection.execute("SELECT count(*) FROM edges").fetchone()[0],
            "terms": connection.execute("SELECT count(*) FROM terms").fetchone()[0],
            "notes": connection.execute("SELECT count(*) FROM notes").fetchone()[0],
        }
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
        forbidden_columns = []
        for table in ("pages", "symbols", "edges", "notes", "meta"):
            for row in connection.execute(f"PRAGMA table_info({table})"):
                if "hash" in str(row[1]).casefold():
                    forbidden_columns.append(f"{table}.{row[1]}")
    finally:
        connection.close()
    errors = []
    if integrity != "ok":
        errors.append({"reason": "sqlite-integrity", "detail": integrity})
    if foreign_keys:
        errors.append({"reason": "foreign-key-errors", "detail": foreign_keys})
    if counts["pages"] != len(projection.get("pages", [])):
        errors.append({"reason": "page-count-mismatch", "actual": counts["pages"], "expected": len(projection.get("pages", []))})
    if counts["notes"] != expected_notes:
        errors.append({"reason": "note-count-mismatch", "actual": counts["notes"], "expected": expected_notes})
    if forbidden_columns:
        errors.append({"reason": "new-index-hash-column-present", "columns": forbidden_columns})
    if meta.get("projection_format") != projection_format:
        errors.append({"reason": "projection-format-mismatch", "actual": meta.get("projection_format"), "expected": projection_format})
    return {
        "schema_version": INDEX_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "path": str(index.resolve()),
        "integrity": integrity,
        "counts": counts,
        "projection_format": projection_format,
        "errors": errors,
    }


def _agent_index_ready(output: Path) -> None:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        raise CkbError("Agent index is missing; run reindex or finalize")
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
    except sqlite3.DatabaseError as exc:
        raise CkbError(f"Agent index metadata is unavailable: {exc}") from exc
    finally:
        connection.close()
    if meta.get("status") != "ready" or meta.get("schema_version") != str(INDEX_SCHEMA_VERSION):
        raise CkbError(f"Agent index metadata is incompatible: {meta}")


def _fts_query(question: str) -> str | None:
    return build_fts_query(question, 12)


def _next_pack_path(output: Path) -> tuple[Path, Path]:
    directory = output / "agent-packs"
    directory.mkdir(parents=True, exist_ok=True)
    prefix = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    counter = 1
    while True:
        stem = f"pack-{prefix}-{counter:02d}"
        markdown = directory / f"{stem}.md"
        record = directory / f"{stem}.json"
        if not markdown.exists() and not record.exists():
            return markdown, record
        counter += 1


def retrieve(output: Path, question: str, budget: int = 1500, page_limit: int = DEFAULT_PAGE_LIMIT) -> dict[str, Any]:
    if budget < 200:
        raise CkbError("retrieve budget must be at least 200")
    if page_limit < 1 or page_limit > 32:
        raise CkbError("retrieve page limit must be in [1, 32]")
    _agent_index_ready(output)
    index = output / "agent-index.sqlite"
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    scores: dict[str, float] = defaultdict(float)
    reasons: dict[str, list[str]] = defaultdict(list)
    terms = search_terms(question)
    try:
        for row in connection.execute("SELECT page_id,title FROM pages WHERE title=? COLLATE NOCASE", (question,)):
            scores[row["page_id"]] += 160
            reasons[row["page_id"]].append("页面标题精确匹配")
        for term in terms:
            for row in connection.execute(
                "SELECT owner_page_id,symbol,qualified_name FROM symbols WHERE symbol=? COLLATE NOCASE OR qualified_name=? COLLATE NOCASE LIMIT 20",
                (term, term),
            ):
                scores[row["owner_page_id"]] += 120
                reasons[row["owner_page_id"]].append(f"符号精确匹配：{row['qualified_name']}")
            for row in connection.execute("SELECT page_id,weight FROM terms WHERE term=? LIMIT 50", (term,)):
                scores[row["page_id"]] += float(row["weight"])
                reasons[row["page_id"]].append(f"索引词匹配：{term}")
        fts = _fts_query(question)
        if fts:
            for row in connection.execute(
                "SELECT page_id,bm25(page_fts,8.0,3.0,6.0,2.0) AS rank FROM page_fts WHERE page_fts MATCH ? ORDER BY rank LIMIT 30",
                (fts,),
            ):
                scores[row["page_id"]] += 40.0 / (1.0 + abs(float(row["rank"])))
                reasons[row["page_id"]].append("全文索引匹配")
        if not scores:
            return {
                "schema_version": INDEX_SCHEMA_VERSION,
                "status": "needs-grep",
                "question": question,
                "budget": budget,
                "grep_terms": terms[:12],
                "reason": "Agent index found no page candidate",
            }
        seeds = [page_id for page_id, _score in sorted(scores.items(), key=lambda item: (-item[1], item[0]))[:3]]
        for seed in seeds:
            for row in connection.execute(
                "SELECT source_page_id,target_page_id,relation,weight FROM edges WHERE source_page_id=? OR target_page_id=?",
                (seed, seed),
            ):
                neighbor = row["target_page_id"] if row["source_page_id"] == seed else row["source_page_id"]
                scores[neighbor] += 18.0 * float(row["weight"])
                reasons[neighbor].append(f"与高相关页面一跳关联：{row['relation']}")
        ordered = sorted(scores, key=lambda page_id: (-scores[page_id], page_id))
        pack_path, record_path = _next_pack_path(output)
        header = ["# Agent 阅读包", "", f"问题：{question}", "", "按顺序阅读以下页面；源码链接可以直接打开对应位置。", ""]
        selected = []
        pack = "\n".join(header)
        for page_id in ordered:
            if len(selected) >= page_limit:
                break
            row = connection.execute("SELECT * FROM pages WHERE page_id=?", (page_id,)).fetchone()
            if row is None:
                continue
            reason_text = "；".join(dict.fromkeys(reasons[page_id]))
            block = (
                f"## {row['title']}\n\n"
                f"选择原因：{reason_text}\n\n"
                f"知识页：`{row['page_file']}`\n\n"
                f"{row['content'].strip()}\n\n"
            )
            candidate = pack + block
            if _tokens(candidate) > budget:
                if selected:
                    continue
                allowed_bytes = max(0, budget * 3 - len((pack + f"## {row['title']}\n\n选择原因：{reason_text}\n\n").encode("utf-8")) - 80)
                content_bytes = row["content"].encode("utf-8")[:allowed_bytes]
                while True:
                    try:
                        truncated = content_bytes.decode("utf-8")
                        break
                    except UnicodeDecodeError as exc:
                        content_bytes = content_bytes[: exc.start]
                block = f"## {row['title']}\n\n选择原因：{reason_text}\n\n{truncated.rstrip()}\n\n> 页面内容已按预算截断。\n\n"
                candidate = pack + block
            if _tokens(candidate) <= budget:
                pack = candidate
                selected.append(
                    {
                        "page_id": page_id,
                        "title": row["title"],
                        "page_file": str((output / row["page_file"]).resolve()),
                        "tag": row["tag"],
                        "source_path": row["source_path"],
                        "start_line": row["start_line"],
                        "end_line": row["end_line"],
                        "page_tokens": row["token_estimate"],
                        "score": round(scores[page_id], 6),
                        "reasons": list(dict.fromkeys(reasons[page_id])),
                    }
                )
        note_rows = []
        if fts:
            for row in connection.execute(
                "SELECT note_title,bm25(note_fts,8.0,2.0) AS rank FROM note_fts WHERE note_fts MATCH ? ORDER BY rank LIMIT 5",
                (fts,),
            ):
                note = connection.execute("SELECT * FROM notes WHERE note_title=?", (row["note_title"],)).fetchone()
                if note:
                    note_rows.append({"title": note["note_title"], "file": str((output / "markdown" / note["note_file"]).resolve()), "tag": note["tag"]})
    finally:
        connection.close()
    if not selected:
        raise CkbError("retrieve budget is too small for the highest-ranked page")
    pack_path.write_text(pack.rstrip() + "\n", encoding="utf-8", newline="\n")
    result = {
        "schema_version": INDEX_SCHEMA_VERSION,
        "status": "passed",
        "question": question,
        "budget": budget,
        "estimated_tokens": _tokens(pack),
        "selected_pages": selected,
        "related_notes": note_rows,
        "pack": str(pack_path.resolve()),
        "record": str(record_path.resolve()),
        "retrieval": "sqlite-exact-terms-fts5-trigram-plus-one-hop-graph",
        "grep_fallback_required": False,
    }
    json_write(record_path, result)
    return result

