def _gemini_hooks(command: str) -> dict[str, Any]:
    def handler(timeout_ms: int) -> dict[str, Any]:
        return {"type": "command", "command": command, "timeout": timeout_ms}

    return {
        "hooks": {
            "SessionStart": [{"matcher": "startup|resume|clear", "hooks": [handler(8_000)]}],
            "BeforeAgent": [{"hooks": [handler(20_000)]}],
            "AfterTool": [{"matcher": ".*", "hooks": [handler(8_000)]}],
            "AfterAgent": [{"hooks": [handler(15_000)]}],
            "PreCompress": [{"hooks": [handler(8_000)]}],
            "SessionEnd": [{"hooks": [handler(3_000)]}],
        }
    }


def _copilot_hooks(posix: str, powershell: str) -> dict[str, Any]:
    def handler(timeout: int, matcher: str | None = None) -> dict[str, Any]:
        value: dict[str, Any] = {
            "type": "command",
            "bash": posix,
            "powershell": powershell,
            "timeoutSec": timeout,
        }
        if matcher:
            value["matcher"] = matcher
        return value

    # PascalCase selects Copilot's VS Code-compatible snake_case payloads,
    # which keeps the adapter aligned with Codex/Claude without pretending the
    # event names or output decisions are otherwise interchangeable.
    return {
        "version": 1,
        "hooks": {
            "SessionStart": [handler(8)],
            "UserPromptSubmit": [handler(20)],
            "PostToolUse": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "PostToolUseFailure": [handler(8, "Bash|Edit|Write|NotebookEdit")],
            "Stop": [handler(15)],
            "PreCompact": [handler(8)],
            "SessionEnd": [handler(3)],
        },
    }


def _cursor_hooks(command: str) -> dict[str, Any]:
    def handler(matcher: str | None = None, timeout: int = 8) -> dict[str, Any]:
        value: dict[str, Any] = {"command": command, "timeout": timeout}
        if matcher:
            value["matcher"] = matcher
        return value

    return {
        "version": 1,
        "hooks": {
            "sessionStart": [handler()],
            "beforeSubmitPrompt": [handler("UserPromptSubmit", 20)],
            "postToolUse": [handler("Shell|Write|Delete|MCP:.*")],
            "postToolUseFailure": [handler("Shell|Write|Delete|MCP:.*")],
            "afterFileEdit": [handler("Write")],
            "afterAgentResponse": [handler()],
            "preCompact": [handler()],
            "stop": [handler("Stop", 15)],
            "sessionEnd": [handler(timeout=3)],
        },
    }


def _opencode_stable_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function value(object, keys) {{
  if (!object || typeof object !== "object") return undefined
  for (const key of keys) if (object[key] !== undefined && object[key] !== null) return object[key]
  for (const child of Object.values(object)) {{
    const found = value(child, keys)
    if (found !== undefined) return found
  }}
}}

function text(object) {{
  if (typeof object === "string") return object
  if (Array.isArray(object)) return object.map(text).filter(Boolean).join("\\n")
  if (!object || typeof object !== "object") return ""
  if (typeof object.text === "string") return object.text
  for (const key of ["content", "parts", "message", "delta"]) {{
    const found = text(object[key])
    if (found) return found
  }}
  return ""
}}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

export const CodeKnowledgeBuilderSync = async ({{ directory, worktree }}) => {{
  const cwd = worktree || directory || process.cwd()
  const assistants = new Map()
  return {{
    event: async ({{ event }}) => {{
      const data = event?.properties ?? event?.data ?? event ?? {{}}
      const info = data?.info ?? data
      const sessionID = String(value(info, ["sessionID", "sessionId", "session_id", "id"]) ?? "session-unknown")
      const base = {{ session_id: sessionID, cwd }}
      if (event?.type === "session.created") emit({{ ...base, hook_event_name: "SessionStart", source: "startup", event_id: `session-created:${{sessionID}}` }})
      if (event?.type === "message.updated") {{
        const role = String(value(info, ["role"]) ?? "").toLowerCase()
        const body = text(info)
        const messageID = String(value(info, ["messageID", "messageId", "id"]) ?? "")
        if (role === "user") emit({{ ...base, hook_event_name: "UserPromptSubmit", prompt: body, event_id: `message:${{messageID}}` }})
        if (role === "assistant") {{
          assistants.set(sessionID, body)
          emit({{ ...base, hook_event_name: "AssistantMessage", assistant_message: body, event_id: `message:${{messageID}}` }})
        }}
      }}
      if (event?.type === "command.executed") {{
        const commandName = String(value(data, ["command", "commandName", "name"]) ?? "")
        if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ ...base, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
      }}
      if (event?.type === "file.edited") emit({{ ...base, hook_event_name: "FileChanged", file_path: value(data, ["file", "filePath", "path"]), event: "change" }})
      if (event?.type === "session.compacted") emit({{ ...base, hook_event_name: "PostCompact", trigger: "auto" }})
      if (event?.type === "session.idle") emit({{ ...base, hook_event_name: "Stop", last_assistant_message: assistants.get(sessionID) ?? "", stop_hook_active: false }})
      if (event?.type === "session.deleted") emit({{ ...base, hook_event_name: "SessionEnd", reason: "other" }})
    }},
    "tool.execute.after": async (input, output) => {{
      emit({{
        session_id: String(input?.sessionID ?? input?.sessionId ?? "session-unknown"),
        cwd,
        hook_event_name: "PostToolUse",
        tool_name: String(input?.tool ?? "unknown"),
        tool_use_id: String(input?.callID ?? input?.toolCallID ?? input?.id ?? ""),
        tool_input: input?.args ?? input?.input ?? input,
        tool_response: output,
        status: "completed",
      }})
    }},
  }}
}}
'''


def _opencode_v2_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode-v2", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"
import {{ Plugin }} from "@opencode-ai/plugin"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

function messageText(message) {{
  const parts = message?.parts ?? message?.content ?? []
  if (typeof parts === "string") return parts
  return Array.isArray(parts) ? parts.map((part) => typeof part === "string" ? part : part?.text ?? "").filter(Boolean).join("\\n") : ""
}}

function unwrapMessages(value) {{
  if (Array.isArray(value)) return value
  if (Array.isArray(value?.data)) return value.data
  if (Array.isArray(value?.messages)) return value.messages
  return []
}}

function eventSessionID(event) {{
  return String(event?.sessionID ?? event?.properties?.sessionID ?? event?.data?.sessionID ?? "session-unknown")
}}

function eventCwd(event) {{
  return String(event?.cwd ?? event?.location?.directory ?? event?.properties?.cwd ?? event?.data?.cwd ?? process.cwd())
}}

export default Plugin.define({{
  id: "code-knowledge-builder.sync",
  setup: async (ctx) => {{
    const seenSessions = new Set()
    const sessionCwds = new Map()
    await ctx.session.hook("context", (event) => {{
      const sessionID = String(event.sessionID ?? "session-unknown")
      const cwd = eventCwd(event)
      sessionCwds.set(sessionID, cwd)
      if (!seenSessions.has(sessionID)) {{
        seenSessions.add(sessionID)
        emit({{ session_id: sessionID, cwd, hook_event_name: "SessionStart", source: "startup", event_id: `session:${{sessionID}}` }})
      }}
      const messages = Array.isArray(event.messages) ? event.messages : []
      const latest = [...messages].reverse().find((item) => item?.role === "user")
      if (latest) emit({{ session_id: sessionID, cwd, hook_event_name: "UserPromptSubmit", prompt: messageText(latest), event_id: `message:${{latest.id ?? latest.messageID ?? "latest"}}` }})
    }})
    await ctx.tool.hook("execute.after", (event) => {{
      emit({{
        session_id: String(event.sessionID ?? "session-unknown"),
        cwd: String(event.cwd ?? process.cwd()),
        hook_event_name: "PostToolUse",
        tool_name: String(event.tool ?? "unknown"),
        tool_use_id: String(event.toolCallID ?? event.callID ?? ""),
        tool_input: event.input,
        tool_response: event.status === "error" ? event.error : event.result,
        output_paths: event.outputPaths ?? [],
        status: event.status ?? "completed",
      }})
    }})
    const controller = new AbortController()
    void (async () => {{
      try {{
        for await (const event of ctx.event.subscribe({{ signal: controller.signal }})) {{
          const sessionID = eventSessionID(event)
          const cwd = eventCwd(event)
          if (event.type === "command.executed") {{
            const commandName = String(event?.command ?? event?.properties?.command ?? event?.data?.command ?? "")
            if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ session_id: sessionID, cwd, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
          }}
          if (["session.execution.succeeded", "session.execution.succeeded.1", "session.idle"].includes(event.type)) {{
            const messages = unwrapMessages(await ctx.session.context({{ sessionID }}))
            const latest = [...messages].reverse().find((item) => item?.role === "assistant")
            emit({{ session_id: sessionID, cwd, hook_event_name: "Stop", last_assistant_message: messageText(latest), stop_hook_active: false, event_id: `stop:${{sessionID}}:${{latest?.id ?? event.id ?? event.type}}` }})
          }}
          if (["session.execution.failed", "session.execution.failed.1"].includes(event.type)) emit({{ session_id: sessionID, cwd, hook_event_name: "StopFailure", last_assistant_message: String(event.error?.message ?? event.error ?? "OpenCode 执行失败。"), event_id: `stop-failed:${{sessionID}}:${{event.id ?? event.type}}` }})
          if (event.type === "session.deleted") emit({{ session_id: sessionID, cwd, hook_event_name: "SessionEnd", reason: "other", event_id: `session-end:${{sessionID}}` }})
          if (event.type === "session.compacted") emit({{ session_id: sessionID, cwd, hook_event_name: "PostCompact", trigger: "auto", event_id: `compact:${{sessionID}}:${{event.id ?? "auto"}}` }})
        }}
      }} catch {{}}
    }})()
    return () => {{
      for (const sessionID of seenSessions) emit({{ session_id: sessionID, cwd: sessionCwds.get(sessionID) ?? process.cwd(), hook_event_name: "SessionEnd", reason: "plugin-unload", event_id: `plugin-unload:${{sessionID}}` }})
      controller.abort()
    }}
  }},
}})
'''


def _generic_schema() -> dict[str, Any]:
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "https://code-knowledge-builder.local/automation-event.schema.json",
        "title": "Code Knowledge Builder canonical automation event",
        "type": "object",
        "required": ["canonical_type", "session_id", "cwd"],
        "properties": {
            "canonical_type": {
                "enum": [
                    "skill.applied",
                    "session.start",
                    "turn.prompt",
                    "turn.assistant",
                    "tool.result",
                    "file.changed",
                    "turn.stop",
                    "compact.before",
                    "compact.after",
                    "session.end",
                ]
            },
            "event_id": {"type": "string", "minLength": 1},
            "session_id": {"type": "string", "minLength": 1},
            "turn_id": {"type": "string"},
            "cwd": {"type": "string", "minLength": 1},
            "prompt": {"type": "string"},
            "assistant_message": {"type": "string"},
            "tool_name": {"type": "string"},
            "tool_use_id": {"type": "string"},
            "tool_input": {},
            "tool_output": {},
            "changed_paths": {"type": "array", "items": {"type": "string"}},
            "skill_name": {"type": "string", "const": "code-knowledge-builder"},
            "ckb_skill_applied": {"type": "boolean", "const": True},
            "harness_pid": {"type": "integer", "minimum": 1},
        },
        "additionalProperties": True,
    }


def render_integration(
    harness: str,
    destination: Path,
    python: Path | None = None,
    ckb: Path | None = None,
    registry: Path | None = None,
    *,
    force: bool = False,
) -> dict[str, Any]:
    from .management_agent import binding_schema, harness_capabilities

    if harness not in SUPPORTED_HARNESSES:
        raise CkbError(f"unsupported integration harness: {harness}")
    destination = destination.resolve()
    python = (python or Path(sys.executable)).expanduser().resolve()
    ckb = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    registry = (registry or Path.home() / ".ckb" / "automation-registry.json").expanduser().resolve()
    if not python.is_file():
        raise CkbError(f"integration Python executable is missing: {python}")
    if not ckb.is_file():
        raise CkbError(f"integration CKB entrypoint is missing: {ckb}")
    if destination.exists() and any(destination.iterdir()) and not force:
        raise CkbError(f"integration destination is not empty: {destination}; use --force to replace generated files")
    destination.mkdir(parents=True, exist_ok=True)
    posix, windows = _commands(python, ckb, harness, registry)
    windows_args = [str(python), "-X", "utf8", str(ckb), "automation", "hook", "--harness", harness, "--registry", str(registry)]
    powershell = _powershell_command(python, ckb, harness, registry)
    files: list[Path] = []

    def write(relative: str, value: str | dict[str, Any]) -> Path:
        path = destination / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        text = json.dumps(value, ensure_ascii=False, indent=2) + "\n" if isinstance(value, dict) else value
        path.write_text(text, encoding="utf-8", newline="\n")
        files.append(path)
        return path

    if harness == "codex":
        windows, windows_bridge = _codex_windows_bridge(destination, windows_args)
        write(
            ".codex-plugin/plugin.json",
            {
                "name": "code-knowledge-builder-sync",
                "version": INTEGRATION_VERSION,
                "description": "仅在会话明确应用 code-knowledge-builder Skill 后，同步已登记项目的 Codex 会话和修改证据。",
                "author": {"name": "Code Knowledge Builder"},
                "interface": {
                    "displayName": "Code Knowledge Builder Sync",
                    "shortDescription": "同步明确应用 CKB Skill 的项目会话",
                    "longDescription": "会话明确应用 code-knowledge-builder Skill 后，把 Codex 生命周期事件写入脱敏机器队列，并等待 Agent 中文审阅后再进入人类知识库。",
                    "developerName": "Code Knowledge Builder",
                    "category": "Productivity",
                    "capabilities": ["Read", "Write"],
                    "defaultPrompt": "检查当前项目的 Code Knowledge Builder 自动同步状态。",
                },
            },
        )
        write("hooks/ckb-hook.cmd", windows_bridge)
        write("hooks/hooks.json", _codex_hooks(posix, windows))
    elif harness == "claude":
        command = windows if _looks_windows(python) else posix
        write(".claude/settings.json", _claude_hooks(command))
    elif harness == "opencode":
        write(".opencode/plugins/code-knowledge-builder-sync.mjs", _opencode_stable_plugin(python, ckb, registry))
    elif harness == "opencode-v2":
        write(".opencode/plugins/code-knowledge-builder-sync-v2.mjs", _opencode_v2_plugin(python, ckb, registry))
    elif harness == "dsh":
        # The current DSH Codex bridge intentionally reads `command` and ignores
        # Codex's `commandWindows` extension, so stamp the platform command into
        # both fields when rendering on Windows.
        dsh_command = windows if _looks_windows(python) else posix
        write("hooks.json", _codex_hooks(dsh_command, dsh_command, dsh_subset=True))
        config_path = (destination / "hooks.json").as_posix()
        write(
            "cordis.yml.fragment",
            "- dsh-hooks-codex:\n"
            f"    configPath: {json.dumps(config_path)}\n"
            "    model: ckb-sync\n",
        )
    elif harness == "gemini":
        command = windows if _looks_windows(python) else posix
        write(".gemini/settings.json", _gemini_hooks(command))
    elif harness == "copilot":
        write(".github/hooks/code-knowledge-builder.json", _copilot_hooks(posix, powershell))
    elif harness == "cursor":
        command = windows if _looks_windows(python) else posix
        write(".cursor/hooks.json", _cursor_hooks(command))
    else:
        write("automation-event.schema.json", _generic_schema())
        write("management-binding.schema.json", binding_schema())
        write(
            "example-event.json",
            {
                "canonical_type": "skill.applied",
                "event_id": "HARNESS_EVENT_ID",
                "session_id": "HARNESS_SESSION_ID",
                "cwd": "/absolute/project/path",
                "skill_name": "code-knowledge-builder",
                "ckb_skill_applied": True,
            },
        )
        write(
            "example-management-binding.json",
            {
                "schema_version": 1,
                "conversation_id": "HARNESS_CONVERSATION_ID",
                "harness_id": "generic",
                "workspace_root": "/absolute/workspace/path",
                "repo_root": "/absolute/workspace/path/source",
                "knowledge_base": "/absolute/workspace/path/knowledge-base",
                "integration_branch": "INTEGRATION_BRANCH",
                "notification_policy": "none",
            },
        )
    manifest = {
        "schema_version": 1,
        "status": "rendered",
        "integration_version": INTEGRATION_VERSION,
        "harness": harness,
        "python": str(python),
        "ckb": str(ckb),
        "registry": str(registry),
        "project_opt_in_required": True,
        "session_skill_activation_required": True,
        "required_skill": "code-knowledge-builder",
        "transcript_parsing": False,
        "management_capabilities": harness_capabilities(harness),
        "session_stdio_capability": {
            "activation": "exact-skill-application",
            "session_end": harness not in {"dsh"},
            "parent_monitor": (
                "native-plugin-process"
                if harness in {"opencode", "opencode-v2"}
                else "caller-supplied"
                if harness == "generic"
                else "unavailable"
            ),
            "degraded": harness not in {"opencode", "opencode-v2"},
        },
        "files": [str(path.relative_to(destination).as_posix()) for path in files],
    }
    manifest_path = write("integration.json", manifest)
    return {**manifest, "destination": str(destination), "manifest": str(manifest_path)}

"""Explicit, bounded contracts for the optional LLM keyword fallback."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import time
from typing import Any, Sequence

from .common import CkbError, background_process_options, json_load, json_write


KEYWORD_FALLBACK_SCHEMA_VERSION = 1
KEYWORD_PROMPT_SCHEMA = "ckb-keyword-fallback-v1"
MAX_KEYWORDS = 16
MAX_ANCHORS = 12
MAX_REWRITES = 4
MAX_KEYWORD_CHARS = 80
MAX_ANCHOR_CHARS = 160
MAX_REWRITE_CHARS = 320

_MACHINE_TOKEN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$")
_KEYWORD_TEXT = re.compile(r"^[\w\u3400-\u9fff./:+# -]+$", flags=re.UNICODE)
_ANCHOR_TEXT = re.compile(
    r"^[A-Za-z_][A-Za-z0-9_]*(?:(?:::|\.)[A-Za-z_][A-Za-z0-9_]*)*$"
)
_REWRITE_TEXT = re.compile(r"^[\w\u3400-\u9fff\s./:+#(),（）-]+$", flags=re.UNICODE)
_PROMPT_INJECTION = re.compile(
    r"(?:"
    r"(?:ignore|disregard).{0,24}(?:previous|system|instruction)|"
    r"system\s*(?:prompt|message)|developer\s*message|jailbreak|"
    r"<\s*/?(?:script|system)|"
    r"忽略.{0,12}(?:之前|以上|系统|指令)|系统提示|开发者消息|越狱"
    r")",
    flags=re.IGNORECASE,
)
_CREDENTIAL_SHAPE = re.compile(
    r"(?:sk-[A-Za-z0-9_-]{20,}|bearer\s+[A-Za-z0-9._-]{20,})",
    flags=re.IGNORECASE,
)
_FAILURE_TYPES = {
    "invalid-json",
    "invalid-output",
    "missing-credentials",
    "process-failed",
    "rate-limit",
    "timeout",
    "unavailable",
}
_CACHE_FIELDS = {
    "schema_version",
    "status",
    "cache_key",
    "input_hash",
    "prompt_schema",
    "provider",
    "model",
    "version",
    "response",
}
_REQUEST_FIELDS = {
    "schema_version",
    "status",
    "input_hash",
    "prompt_schema",
    "trigger",
    "original",
    "provider",
    "model_candidates",
    "validated_extensions",
    "final",
}


@dataclass(frozen=True)
class KeywordProviderConfig:
    """Public identity and bounded execution settings for one provider adapter."""

    command: tuple[str, ...]
    provider: str
    model: str
    version: str
    timeout_seconds: float = 20.0
    retries: int = 1
    required_environment: tuple[str, ...] = ()


@dataclass(frozen=True)
class KeywordFallbackOptions:
    """One explicit retrieval request's trigger and provider settings."""

    config: KeywordProviderConfig
    force: bool = False
    use_cache: bool = True


def keyword_input_hash(question: str) -> str:
    return hashlib.sha256(question.encode("utf-8")).hexdigest()


def keyword_request_id(question: str) -> str:
    return f"keyword-{keyword_input_hash(question)[:24]}"


def keyword_cache_key(question: str, config: KeywordProviderConfig) -> str:
    validate_provider_config(config)
    material = {
        "input_hash": keyword_input_hash(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
    }
    serialized = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("ascii")).hexdigest()


def canonical_keyword_request(question: str) -> dict[str, Any]:
    """Build the only request shape accepted by command/stdio providers."""

    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
        "request_id": keyword_request_id(question),
        "input_hash": keyword_input_hash(question),
        "question": question,
        "limits": {
            "keywords": MAX_KEYWORDS,
            "anchors": MAX_ANCHORS,
            "rewrites": MAX_REWRITES,
            "keyword_chars": MAX_KEYWORD_CHARS,
            "anchor_chars": MAX_ANCHOR_CHARS,
            "rewrite_chars": MAX_REWRITE_CHARS,
        },
    }


def _machine_token(value: Any, name: str) -> str:
    if not isinstance(value, str) or not _MACHINE_TOKEN.fullmatch(value):
        raise CkbError(f"keyword provider {name} must be a bounded machine token")
    return value


def validate_provider_config(config: KeywordProviderConfig) -> None:
    if not config.command or any(not isinstance(value, str) or not value for value in config.command):
        raise CkbError("keyword provider command must contain at least one non-empty argument")
    _machine_token(config.provider, "provider")
    _machine_token(config.model, "model")
    _machine_token(config.version, "version")
    if not 0.1 <= config.timeout_seconds <= 300.0:
        raise CkbError("keyword provider timeout must be between 0.1 and 300 seconds")
    if config.retries not in {0, 1}:
        raise CkbError("keyword provider retries must be zero or one")
    for name in config.required_environment:
        if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", name):
            raise CkbError("keyword provider required environment names must be bounded identifiers")


def _bounded_strings(
    value: Any,
    *,
    name: str,
    maximum_items: int,
    maximum_chars: int,
    pattern: re.Pattern[str],
) -> list[str]:
    if not isinstance(value, list) or len(value) > maximum_items:
        raise CkbError(f"keyword provider {name} must be an array with at most {maximum_items} items")
    result: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, str):
            raise CkbError(f"keyword provider {name} items must be strings")
        normalized = item.strip()
        if not normalized or len(normalized) > maximum_chars:
            raise CkbError(f"keyword provider {name} items must contain 1 to {maximum_chars} characters")
        if not pattern.fullmatch(normalized):
            raise CkbError(f"keyword provider {name} contains unsupported characters")
        if _PROMPT_INJECTION.search(normalized):
            raise CkbError(f"keyword provider {name} contains prompt-injection text")
        if _CREDENTIAL_SHAPE.search(normalized):
            raise CkbError(f"keyword provider {name} contains credential-shaped text")
        identity = normalized.casefold()
        if identity in seen:
            raise CkbError(f"keyword provider {name} contains duplicate items")
        seen.add(identity)
        result.append(normalized)
    return result


def _usage(value: Any) -> dict[str, Any]:
    if value is None:
        value = {}
    if not isinstance(value, dict):
        raise CkbError("keyword provider usage must be an object")
    allowed = {"input_tokens", "output_tokens", "total_tokens", "cost_usd"}
    if set(value) - allowed:
        raise CkbError("keyword provider usage contains unsupported fields")
    result: dict[str, Any] = {}
    for name in ("input_tokens", "output_tokens", "total_tokens"):
        item = value.get(name, 0)
        if isinstance(item, bool) or not isinstance(item, int) or item < 0:
            raise CkbError(f"keyword provider usage {name} must be a non-negative integer")
        result[name] = item
    cost = value.get("cost_usd", 0.0)
    if isinstance(cost, bool) or not isinstance(cost, (int, float)) or cost < 0:
        raise CkbError("keyword provider usage cost_usd must be a non-negative number")
    result["cost_usd"] = round(float(cost), 8)
    if result["total_tokens"] and result["total_tokens"] != result["input_tokens"] + result["output_tokens"]:
        raise CkbError("keyword provider usage total_tokens does not match input plus output")
    return result


def validate_provider_response(
    value: Any,
    *,
    question: str,
    config: KeywordProviderConfig,
) -> dict[str, Any]:
    """Validate and normalize model output before it reaches deterministic retrieval."""

    validate_provider_config(config)
    if not isinstance(value, dict):
        raise CkbError("keyword provider response must be a JSON object")
    allowed = {
        "schema_version",
        "status",
        "failure_type",
        "request_id",
        "provider",
        "model",
        "version",
        "keywords",
        "anchors",
        "rewrites",
        "usage",
    }
    if set(value) - allowed:
        raise CkbError("keyword provider response contains unsupported fields")
    if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION:
        raise CkbError("keyword provider schema version mismatch")
    status = value.get("status")
    if status != "passed":
        failure_type = value.get("failure_type")
        if status != "failed" or failure_type not in _FAILURE_TYPES:
            raise CkbError("keyword provider failure response is not canonical")
        return {
            "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
            "status": "failed",
            "failure_type": failure_type,
            "request_id": keyword_request_id(question),
            "provider": config.provider,
            "model": config.model,
            "version": config.version,
            "keywords": [],
            "anchors": [],
            "rewrites": [],
            "usage": _usage(value.get("usage")),
        }
    identity = {
        "request_id": keyword_request_id(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
    }
    for name, expected in identity.items():
        if value.get(name) != expected:
            raise CkbError(f"keyword provider {name} does not match the request configuration")
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed",
        **identity,
        "keywords": _bounded_strings(
            value.get("keywords"),
            name="keywords",
            maximum_items=MAX_KEYWORDS,
            maximum_chars=MAX_KEYWORD_CHARS,
            pattern=_KEYWORD_TEXT,
        ),
        "anchors": _bounded_strings(
            value.get("anchors"),
            name="anchors",
            maximum_items=MAX_ANCHORS,
            maximum_chars=MAX_ANCHOR_CHARS,
            pattern=_ANCHOR_TEXT,
        ),
        "rewrites": _bounded_strings(
            value.get("rewrites"),
            name="rewrites",
            maximum_items=MAX_REWRITES,
            maximum_chars=MAX_REWRITE_CHARS,
            pattern=_REWRITE_TEXT,
        ),
        "usage": _usage(value.get("usage")),
    }


def parse_provider_json(raw: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise CkbError("keyword provider returned invalid JSON") from exc


def _failure(question: str, config: KeywordProviderConfig, failure_type: str) -> dict[str, Any]:
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "failed",
        "failure_type": failure_type,
        "request_id": keyword_request_id(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "keywords": [],
        "anchors": [],
        "rewrites": [],
        "usage": _usage({}),
    }


def keyword_cache_path(output: Path, question: str, config: KeywordProviderConfig) -> Path:
    return _cache_path(output, keyword_cache_key(question, config))


def _cache_path(output: Path, cache_key: str) -> Path:
    return output.resolve() / "workspace-meta" / "keyword-fallback" / "cache" / f"{cache_key}.json"


def _cache_record(question: str, config: KeywordProviderConfig, response: dict[str, Any]) -> dict[str, Any]:
    cache_key = keyword_cache_key(question, config)
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed",
        "cache_key": cache_key,
        "input_hash": keyword_input_hash(question),
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "response": response,
    }


def _read_cache(output: Path, question: str, config: KeywordProviderConfig) -> dict[str, Any] | None:
    path = _cache_path(output, keyword_cache_key(question, config))
    if not path.is_file():
        return None
    try:
        record = json_load(path)
        expected = _cache_record(question, config, record.get("response") if isinstance(record, dict) else {})
        if not isinstance(record, dict) or set(record) != _CACHE_FIELDS:
            return None
        for name in _CACHE_FIELDS - {"response"}:
            if record.get(name) != expected.get(name):
                return None
        response = validate_provider_response(record.get("response"), question=question, config=config)
        if response.get("status") != "passed":
            return None
        return response
    except (CkbError, OSError, ValueError, TypeError):
        return None


def _write_cache(output: Path, question: str, config: KeywordProviderConfig, response: dict[str, Any]) -> Path:
    record = _cache_record(question, config, response)
    path = _cache_path(output, record["cache_key"])
    json_write(path, record)
    return path


def _transient(failure_type: str) -> bool:
    return failure_type in {"process-failed", "rate-limit", "timeout", "unavailable"}


def run_keyword_provider(
    output: Path,
    question: str,
    config: KeywordProviderConfig,
    *,
    use_cache: bool = True,
) -> dict[str, Any]:
    """Call one explicit command/stdio adapter and return only validated fields."""

    validate_provider_config(config)
    missing = sorted(name for name in config.required_environment if not os.environ.get(name))
    if missing:
        return {
            **_failure(question, config, "missing-credentials"),
            "attempts": 0,
            "latency_ms": 0.0,
            "cache_hit": False,
            "missing_environment": missing,
        }
    if use_cache:
        cached = _read_cache(output, question, config)
        if cached is not None:
            return {
                **cached,
                "cached_usage": cached.get("usage", _usage({})),
                "usage": _usage({}),
                "attempts": 0,
                "latency_ms": 0.0,
                "cache_hit": True,
                "cache_key": keyword_cache_key(question, config),
            }
    request = json.dumps(canonical_keyword_request(question), ensure_ascii=False, separators=(",", ":"))
    started = time.perf_counter_ns()
    attempts = 0
    response: dict[str, Any] = _failure(question, config, "unavailable")
    for attempt in range(config.retries + 1):
        attempts = attempt + 1
        failure_type: str | None = None
        try:
            completed = subprocess.run(
                list(config.command),
                input=request,
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=config.timeout_seconds,
                check=False,
                **background_process_options(),
            )
            if completed.returncode:
                diagnostic = f"{completed.stdout}\n{completed.stderr}"
                failure_type = "rate-limit" if re.search(r"rate[ _-]*limit|too many requests|\b429\b", diagnostic, re.IGNORECASE) else "process-failed"
                response = _failure(question, config, failure_type)
            else:
                try:
                    parsed = parse_provider_json(completed.stdout)
                    response = validate_provider_response(parsed, question=question, config=config)
                    failure_type = response.get("failure_type") if response.get("status") != "passed" else None
                except CkbError as exc:
                    failure_type = "invalid-json" if "invalid JSON" in str(exc) else "invalid-output"
                    response = _failure(question, config, failure_type)
        except subprocess.TimeoutExpired:
            failure_type = "timeout"
            response = _failure(question, config, failure_type)
        except (FileNotFoundError, OSError):
            failure_type = "unavailable"
            response = _failure(question, config, failure_type)
        if response.get("status") == "passed" or not failure_type or not _transient(failure_type):
            break
    latency_ms = round((time.perf_counter_ns() - started) / 1_000_000, 6)
    result = {
        **response,
        "attempts": attempts,
        "latency_ms": latency_ms,
        "cache_hit": False,
        "cache_key": keyword_cache_key(question, config),
    }
    if response.get("status") == "passed" and use_cache:
        result["cache"] = str(_write_cache(output, question, config, response).resolve())
    return result


def audit_keyword_cache(output: Path) -> dict[str, Any]:
    """Check bounded cache records without reading or requiring provider secrets."""

    root = output.resolve() / "workspace-meta" / "keyword-fallback" / "cache"
    if not root.is_dir():
        return {"schema_version": 1, "status": "passed", "records": 0, "errors": []}
    errors: list[str] = []
    records = 0
    for path in sorted(root.glob("*.json")):
        records += 1
        try:
            value = json_load(path)
        except (OSError, ValueError) as exc:
            errors.append(f"{path.name}: invalid cache JSON: {type(exc).__name__}")
            continue
        if not isinstance(value, dict) or set(value) != _CACHE_FIELDS:
            errors.append(f"{path.name}: fields differ from the fixed cache schema")
            continue
        if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION or value.get("status") != "passed":
            errors.append(f"{path.name}: cache status or schema mismatch")
        if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
            errors.append(f"{path.name}: prompt schema mismatch")
        cache_key = value.get("cache_key")
        if not isinstance(cache_key, str) or not re.fullmatch(r"[0-9a-f]{64}", cache_key) or path.stem != cache_key:
            errors.append(f"{path.name}: cache key mismatch")
        input_hash = value.get("input_hash")
        if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
            errors.append(f"{path.name}: input hash is invalid")
        for name in ("provider", "model", "version"):
            try:
                _machine_token(value.get(name), name)
            except CkbError as exc:
                errors.append(f"{path.name}: {exc}")
        serialized = json.dumps(value, ensure_ascii=False)
        if _CREDENTIAL_SHAPE.search(serialized):
            errors.append(f"{path.name}: cache contains credential-shaped text")
    unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
    errors.extend(f"unexpected keyword cache entry: {name}" for name in sorted(unexpected))
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "records": records,
        "errors": errors,
    }


def write_keyword_fallback_record(
    output: Path,
    question: str,
    metadata: dict[str, Any],
) -> Path:
    """Persist one bounded request record without the raw question or provider output."""

    input_hash = keyword_input_hash(question)
    provider = str((metadata.get("provider") or {}).get("provider") or "unknown")
    model = str((metadata.get("provider") or {}).get("model") or "unknown")
    version = str((metadata.get("provider") or {}).get("version") or "unknown")
    identity = hashlib.sha256(
        json.dumps(
            {
                "input_hash": input_hash,
                "provider": provider,
                "model": model,
                "version": version,
                "prompt_schema": KEYWORD_PROMPT_SCHEMA,
                "trigger": metadata.get("trigger"),
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    record = {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": metadata.get("status"),
        "input_hash": input_hash,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
        "trigger": metadata.get("trigger"),
        "original": metadata.get("original"),
        "provider": metadata.get("provider"),
        "model_candidates": metadata.get("model_candidates"),
        "validated_extensions": metadata.get("validated_extensions"),
        "final": metadata.get("final"),
    }
    path = output.resolve() / "workspace-meta" / "keyword-fallback" / "requests" / f"{identity}.json"
    json_write(path, record)
    return path


def audit_keyword_fallback(output: Path) -> dict[str, Any]:
    """Audit cache and request records while enforcing the privacy boundary."""

    output = output.resolve()
    cache = audit_keyword_cache(output)
    root = output / "workspace-meta" / "keyword-fallback" / "requests"
    errors = [f"cache: {error}" for error in cache.get("errors", [])]
    records = 0
    if root.is_dir():
        unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
        errors.extend(f"unexpected keyword request entry: {name}" for name in sorted(unexpected))
        for path in sorted(root.glob("*.json")):
            records += 1
            try:
                value = json_load(path)
            except (OSError, ValueError) as exc:
                errors.append(f"{path.name}: invalid request JSON: {type(exc).__name__}")
                continue
            if not isinstance(value, dict) or set(value) != _REQUEST_FIELDS:
                errors.append(f"{path.name}: fields differ from the fixed request schema")
                continue
            if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION:
                errors.append(f"{path.name}: request schema mismatch")
            if value.get("status") not in {"passed", "fallback", "skipped", "no-quality-gain"}:
                errors.append(f"{path.name}: request status is invalid")
            if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
                errors.append(f"{path.name}: prompt schema mismatch")
            if value.get("trigger") not in {"forced", "needs-source-read"}:
                errors.append(f"{path.name}: trigger is invalid")
            input_hash = value.get("input_hash")
            if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
                errors.append(f"{path.name}: input hash is invalid")
            provider = value.get("provider")
            if not isinstance(provider, dict):
                errors.append(f"{path.name}: provider summary must be an object")
                continue
            for name in ("provider", "model", "version"):
                try:
                    _machine_token(provider.get(name), name)
                except CkbError as exc:
                    errors.append(f"{path.name}: {exc}")
            expected_name = hashlib.sha256(
                json.dumps(
                    {
                        "input_hash": input_hash,
                        "provider": provider.get("provider"),
                        "model": provider.get("model"),
                        "version": provider.get("version"),
                        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
                        "trigger": value.get("trigger"),
                    },
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            if path.stem != expected_name:
                errors.append(f"{path.name}: request identity mismatch")
            serialized = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
            if re.search(r'"(?:question|prompt|command|stdout|stderr|secret|credential)"\s*:', serialized, re.IGNORECASE):
                errors.append(f"{path.name}: request record crosses the privacy boundary")
            if _CREDENTIAL_SHAPE.search(serialized):
                errors.append(f"{path.name}: request record contains credential-shaped text")
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "cache_records": cache.get("records", 0),
        "request_records": records,
        "errors": errors,
    }


def unique_casefold(values: Sequence[str]) -> list[str]:
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        normalized = value.strip()
        identity = normalized.casefold()
        if normalized and identity not in seen:
            seen.add(identity)
            result.append(normalized)
    return result

