def _validate_version(value: Any, location: str) -> dict[str, Any]:
    result = _object(value, location)
    _reject_unknown(result, VERSION_KEYS, location)
    if not isinstance(result.get("ckb_version"), str) or not result["ckb_version"]:
        raise CkbError(f"knowledge batch manifest {location}.ckb_version is invalid")
    if not isinstance(result.get("schema_version"), int) or result["schema_version"] < 1:
        raise CkbError(f"knowledge batch manifest {location}.schema_version is invalid")
    protocol = result.get("protocol_version")
    if protocol is not None and (not isinstance(protocol, str) or not protocol):
        raise CkbError(f"knowledge batch manifest {location}.protocol_version is invalid")
    if not isinstance(result.get("release_commit"), str) or not HEX_SHA1.fullmatch(result["release_commit"]):
        raise CkbError(f"knowledge batch manifest {location}.release_commit must be a full commit SHA-1")
    return result


def _validate_snapshot(value: Any, location: str) -> dict[str, str]:
    result = _object(value, location)
    _reject_unknown(result, SNAPSHOT_KEYS, location)
    for field in SNAPSHOT_KEYS:
        if not isinstance(result.get(field), str) or not HEX_SHA1.fullmatch(result[field]):
            raise CkbError(f"knowledge batch manifest {location}.{field} must be a full Git SHA-1")
    return {"commit": result["commit"], "tree": result["tree"]}


def _validate_tree_summary(value: Any, location: str) -> dict[str, Any]:
    result = _object(value, location)
    _reject_unknown(result, TREE_KEYS, location)
    if result.get("algorithm") != "sha256-tree-v1":
        raise CkbError(f"knowledge batch manifest {location}.algorithm must be sha256-tree-v1")
    for field in ("file_count", "byte_count"):
        if not isinstance(result.get(field), int) or result[field] < 0:
            raise CkbError(f"knowledge batch manifest {location}.{field} is invalid")
    if not isinstance(result.get("sha256"), str) or not HEX_SHA256.fullmatch(result["sha256"]):
        raise CkbError(f"knowledge batch manifest {location}.sha256 must be a lowercase SHA-256")
    return dict(result)


def _validate_structural_manifest(manifest: dict[str, Any]) -> tuple[list[Path], list[dict[str, Any]]]:
    _reject_unknown(manifest, MANIFEST_KEYS, "manifest")
    if manifest.get("schema_version") != KNOWLEDGE_BATCH_MANIFEST_SCHEMA_VERSION:
        raise CkbError(f"unsupported knowledge batch manifest schema_version: {manifest.get('schema_version')}")
    batch_id = manifest.get("batch_id")
    if not isinstance(batch_id, str) or not PROJECT_ID.fullmatch(batch_id):
        raise CkbError("knowledge batch manifest batch_id is invalid")
    allowed = manifest.get("allowed_roots")
    if not isinstance(allowed, list) or not allowed:
        raise CkbError("knowledge batch manifest allowed_roots must be a non-empty list")
    roots = [_absolute(value, f"allowed_roots[{index}]") for index, value in enumerate(allowed)]
    if len({str(path) for path in roots}) != len(roots):
        raise CkbError("knowledge batch manifest allowed_roots contains duplicates")
    if any(not root.is_dir() for root in roots):
        raise CkbError("knowledge batch manifest allowed_roots must already exist")
    projects = manifest.get("projects")
    if not isinstance(projects, list) or not (1 <= len(projects) <= MAX_BATCH_PROJECTS):
        raise CkbError(f"knowledge batch manifest projects must contain 1..{MAX_BATCH_PROJECTS} entries")
    ids: set[str] = set()
    outputs: list[Path] = []
    stagings: list[Path] = []
    normalized: list[dict[str, Any]] = []
    for index, raw in enumerate(projects):
        project = _object(raw, f"projects[{index}]")
        _reject_unknown(project, PROJECT_KEYS, f"projects[{index}]")
        project_id = project.get("project_id")
        if not isinstance(project_id, str) or not PROJECT_ID.fullmatch(project_id):
            raise CkbError(f"knowledge batch manifest projects[{index}].project_id is invalid")
        if project_id in ids:
            raise CkbError(f"knowledge batch manifest project_id is duplicated: {project_id}")
        ids.add(project_id)
        output = _absolute(project.get("output"), f"{project_id}.output")
        repository = _absolute(project.get("repository"), f"{project_id}.repository")
        staging = _absolute(project.get("staging"), f"{project_id}.staging")
        if not all(_within_any(path, roots) for path in (output, repository, staging)):
            raise CkbError(f"knowledge batch project path escapes allowed_roots: {project_id}")
        if output == staging or path_inside(output, staging) or path_inside(staging, output):
            raise CkbError(f"knowledge batch OUTPUT and staging overlap: {project_id}")
        outputs.append(output)
        stagings.append(staging)
        normalized.append(project)
    owned = [("output", path) for path in outputs] + [("staging", path) for path in stagings]
    for position, (role, path) in enumerate(owned):
        for other_role, other in owned[position + 1 :]:
            if path == other or path_inside(path, other) or path_inside(other, path):
                raise CkbError(f"knowledge batch {role}/{other_role} paths are duplicate or nested: {path} ; {other}")
    return roots, normalized


def load_knowledge_batch_manifest(path: Path) -> dict[str, Any]:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise CkbError(f"knowledge batch manifest is missing: {path}")
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError("knowledge batch manifest root must be an object")
    _validate_structural_manifest(value)
    return value


def _file_record(output: Path, relative: str) -> dict[str, Any]:
    path = output / relative
    return {
        "path": relative,
        "exists": path.is_file(),
        "size": path.stat().st_size if path.is_file() else None,
        "sha256": sha256_file(path) if path.is_file() else None,
    }


def _origin_health(output: Path) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []

    def check(name: str, passed: bool, detail: Any, category: str) -> None:
        checks.append({"name": name, "passed": bool(passed), "category": category, "detail": detail})

    required = {relative: _file_record(output, relative) for relative in REQUIRED_RECORDS}
    check("required-records", all(item["exists"] for item in required.values()), required, "origin-record-missing")
    state = json_load(output / "state.json") if required["state.json"]["exists"] else {}
    scope = json_load(output / "scope.json") if required["scope.json"]["exists"] else {}
    graph = json_load(output / "graph.json") if required["graph.json"]["exists"] else {}
    audit = json_load(output / "audit/global.json") if required["audit/global.json"]["exists"] else {}
    markers = {
        name: json_load(output / name) if required[name]["exists"] else {}
        for name in (".complete", ".machine.complete", ".human.complete")
    }
    check("state-complete", state.get("status") == "complete", state.get("status"), "origin-state-incomplete")
    check("completion-markers", all(value.get("status") == "complete" for value in markers.values()), markers, "origin-marker-incomplete")
    check("global-audit", audit.get("status") == "passed", audit.get("status"), "origin-global-audit")
    facts = output / "facts"
    check("facts-layer", facts.is_dir() and any(facts.iterdir()), str(facts), "origin-facts-missing")
    reviews = {item.get("id"): item.get("status") for item in state.get("review_packs", [])}
    check("review-packs", bool(reviews) and all(value == "passed" for value in reviews.values()), reviews, "origin-review-incomplete")
    entity_review_errors = [
        item.get("id")
        for item in graph.get("entities", [])
        if item.get("classification") in {"page", "boundary", "appendix"} and item.get("review_status") != "agent-reviewed"
    ]
    check("entity-reviews", not entity_review_errors, entity_review_errors[:40], "origin-review-binding")
    try:
        sqlite_checks = _sqlite_checks(output)
    except sqlite3.Error as exc:
        sqlite_checks = [
            {
                "path": "machine/knowledge.sqlite",
                "integrity_check": "error",
                "foreign_key_errors": None,
                "passed": False,
                "detail": str(exc),
            }
        ]
    required_sqlite = {item["path"]: item for item in sqlite_checks}
    check(
        "double-sqlite",
        all(required_sqlite.get(name, {}).get("passed") for name in ("machine/knowledge.sqlite", "agent-index.sqlite")),
        sqlite_checks,
        "origin-sqlite",
    )
    human = output / "human"
    markdown = output / "markdown"
    check("human-markdown", human.is_dir() and markdown.is_dir(), {"human": human.is_dir(), "markdown": markdown.is_dir()}, "origin-projection-missing")
    mirror_errors: list[dict[str, Any]] = []
    if human.is_dir() and markdown.is_dir():
        excluded = {"AGENTS.md", "CLAUDE.md", "GEMINI.md"}
        human_files = {
            path.relative_to(human).as_posix(): path
            for path in human.rglob("*.md")
            if path.relative_to(human).as_posix() not in excluded
            and not path.relative_to(human).as_posix().startswith((".github/", ".cursor/", ".obsidian/"))
        }
        markdown_files = {
            path.relative_to(markdown).as_posix(): path
            for path in markdown.rglob("*.md")
            if path.relative_to(markdown).as_posix() not in excluded
            and not path.relative_to(markdown).as_posix().startswith((".github/", ".cursor/", ".obsidian/"))
        }
        if set(human_files) != set(markdown_files):
            mirror_errors.append(
                {
                    "reason": "mirror-file-set",
                    "human_only": sorted(set(human_files) - set(markdown_files)),
                    "markdown_only": sorted(set(markdown_files) - set(human_files)),
                }
            )
        for relative in sorted(set(human_files) & set(markdown_files)):
            if human_files[relative].read_bytes() != markdown_files[relative].read_bytes():
                mirror_errors.append({"reason": "mirror-byte-drift", "path": relative})
    check("human-markdown-parity", not mirror_errors, mirror_errors, "origin-mirror-drift")
    readability = json_load(markdown / "readability-audit.json") if (markdown / "readability-audit.json").is_file() else {}
    check(
        "readability-record",
        readability.get("status") == "passed" and not readability.get("errors"),
        readability,
        "origin-readability",
    )
    return {
        "status": "passed" if all(item["passed"] for item in checks) else "failed",
        "checks": checks,
        "state": state,
        "scope": scope,
        "graph": graph,
        "audit": audit,
        "markers": markers,
        "sqlite": sqlite_checks,
    }


def _complete_layer_inventory(output: Path, mutable_files: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    base = _layer_inventory(output, mutable_files)
    names: dict[str, dict[str, str]] = {}
    mirror_errors: list[dict[str, Any]] = []
    for root_name in ("human", "markdown"):
        root = output / root_name / "user"
        for path in sorted(root.glob("*.md")) if root.is_dir() else []:
            entry = names.setdefault(path.name, {})
            entry[root_name] = sha256_file(path)
    for name, hashes in sorted(names.items()):
        if set(hashes) != {"human", "markdown"} or hashes.get("human") != hashes.get("markdown"):
            mirror_errors.append({"name": name, "hashes": hashes})
    reference_files = sorted(path.relative_to(output).as_posix() for path in (output / "references").rglob("*") if path.is_file()) if (output / "references").is_dir() else []
    feedback_files = sorted(path.relative_to(output).as_posix() for path in (output / "workspace-meta/feedback").rglob("*.json")) if (output / "workspace-meta/feedback").is_dir() else []
    operation_files = sorted(path.relative_to(output).as_posix() for path in (output / "workspace-meta/operations").glob("*.jsonl")) if (output / "workspace-meta/operations").is_dir() else []
    automation = output / "machine/automation.sqlite"
    protocol = output / "workspace-meta/agent-protocol.json"
    return {
        **base,
        "learning_note_count": len(names),
        "learning_notes": [{"name": name, "sha256": hashes.get("human"), "mirrors": hashes} for name, hashes in sorted(names.items())],
        "learning_note_mirror_errors": mirror_errors,
        "reference_source_file_count": len(reference_files),
        "reference_source_files": reference_files,
        "feedback_record_count": len(feedback_files),
        "operation_file_count": len(operation_files),
        "automation_database_present": automation.is_file(),
        "agent_protocol_record_present": protocol.is_file(),
        "agent_protocol_record_sha256": sha256_file(protocol) if protocol.is_file() else None,
    }


def _sqlite_schema_versions(output: Path) -> dict[str, str | None]:
    versions: dict[str, str | None] = {}
    for relative in ("machine/knowledge.sqlite", "agent-index.sqlite"):
        path = output / relative
        if not path.is_file():
            versions[relative] = None
            continue
        connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        try:
            row = connection.execute("SELECT value FROM meta WHERE key='schema_version'").fetchone()
        except sqlite3.Error:
            versions[relative] = None
        else:
            versions[relative] = str(row[0]) if row else None
        finally:
            connection.close()
    return versions


def _normalized_scope(value: Any, location: str) -> dict[str, Any]:
    scope = _object(value, location)
    _reject_unknown(scope, SCOPE_KEYS, location)
    result = {
        "scope_paths": list(scope.get("scope_paths") or []),
        "entries": list(scope.get("entries") or []),
        "entry_ids": list(scope.get("entry_ids") or []),
        "expand_depth": int(scope.get("expand_depth", 1)),
        "expand_direction": str(scope.get("expand_direction", "both")),
        "include": list(scope.get("include") or []),
        "csharp_solution": scope.get("csharp_solution"),
        "csharp_project": scope.get("csharp_project"),
        "allow_dotnet_restore": bool(scope.get("allow_dotnet_restore", False)),
    }
    if result["expand_depth"] < 0 or result["expand_direction"] not in {"both", "callers", "callees"}:
        raise CkbError(f"knowledge batch manifest {location} expansion is invalid")
    return result


def _path_risks(paths: list[Path], maximum: int) -> list[dict[str, Any]]:
    return [
        {"path": str(path), "length": len(str(path)), "limit": maximum}
        for path in paths
        if len(str(path)) > maximum
    ]


def _operation_token(operation_id: str, project_id: str) -> str:
    return hashlib.sha256(f"{operation_id}\0{project_id}".encode("utf-8")).hexdigest()[:20]


def _project_operation_id(batch_operation_id: str, project: dict[str, Any]) -> str:
    origin = _object(project.get("origin"), f"{project.get('project_id')}.origin")
    tree = _validate_tree_summary(origin.get("tree"), f"{project.get('project_id')}.origin.tree")
    target = _validate_snapshot(project.get("target_snapshot"), f"{project.get('project_id')}.target_snapshot")
    return stable_id(
        "knowledge-migration",
        batch_operation_id,
        project["project_id"],
        tree["sha256"],
        target["commit"],
    )


def _paths_overlap(left: Path, right: Path) -> bool:
    return left == right or path_inside(left, right) or path_inside(right, left)


def _validate_recovery_topology(
    manifest: dict[str, Any],
    roots: list[Path],
    batch_operation_id: str,
) -> None:
    primary: list[tuple[str, Path]] = []
    recovery: list[tuple[str, str, Path, Path]] = []
    for project in manifest["projects"]:
        project_id = str(project["project_id"])
        output = _absolute(project.get("output"), f"{project_id}.output")
        staging = _absolute(project.get("staging"), f"{project_id}.staging")
        primary.extend(((f"{project_id}.output", output), (f"{project_id}.staging", staging)))
        cutover = _object(project.get("cutover"), f"{project_id}.cutover")
        _reject_unknown(cutover, CUTOVER_KEYS, f"{project_id}.cutover")
        rollback = _object(project.get("rollback"), f"{project_id}.rollback")
        _reject_unknown(rollback, ROLLBACK_KEYS, f"{project_id}.rollback")
        backup_root = _absolute(cutover.get("backup_root"), f"{project_id}.cutover.backup_root")
        quarantine_root = _absolute(rollback.get("quarantine_root"), f"{project_id}.rollback.quarantine_root")
        if not all(_within_any(value, roots) for value in (backup_root, quarantine_root)):
            raise CkbError(f"knowledge batch recovery root escapes allowed_roots: {project_id}")
        operation_id = _project_operation_id(batch_operation_id, project)
        leaf = _operation_token(operation_id, project_id)
        recovery.extend(
            (
                (project_id, "backup", backup_root, backup_root / leaf),
                (project_id, "quarantine", quarantine_root, quarantine_root / leaf),
            )
        )
    for project_id, role, root, target in recovery:
        for primary_role, primary_path in primary:
            if _paths_overlap(root, primary_path) or _paths_overlap(target, primary_path):
                raise CkbError(
                    f"knowledge batch recovery topology overlaps {primary_role}: "
                    f"{project_id}.{role} root={root} target={target}"
                )
    for index, (project_id, role, _root, target) in enumerate(recovery):
        for other_project, other_role, _other_root, other_target in recovery[index + 1 :]:
            if _paths_overlap(target, other_target):
                raise CkbError(
                    "knowledge batch projected recovery targets overlap: "
                    f"{project_id}.{role}={target} ; {other_project}.{other_role}={other_target}"
                )


def _validate_origin_record_keys(value: Any, project_id: str) -> dict[str, str]:
    if not isinstance(value, dict):
        raise BatchProjectError("origin-record-keys", f"origin.records must be an object for {project_id}")
    keys = set(value)
    missing = sorted(REQUIRED_RECORD_SET - keys)
    extra = sorted(keys - REQUIRED_RECORD_SET)
    if missing or extra:
        raise BatchProjectError(
            "origin-record-keys",
            f"origin.records must contain exactly the fixed eight keys for {project_id}: missing={missing}, extra={extra}",
        )
    for relative in value:
        if not isinstance(relative, str) or not relative:
            raise BatchProjectError("origin-record-path", f"origin.records path is not a string for {project_id}")
        normalized = PurePosixPath(relative)
        if (
            "\\" in relative
            or normalized.is_absolute()
            or "." in normalized.parts
            or ".." in normalized.parts
            or normalized.as_posix() != relative
        ):
            raise BatchProjectError("origin-record-path", f"origin.records path is not canonical for {project_id}: {relative}")
    return value


def _inspect_knowledge_project(
    project: dict[str, Any],
    roots: list[Path],
    batch_operation_id: str,
) -> dict[str, Any]:
    project_id = str(project["project_id"])
    output = _absolute(project["output"], f"{project_id}.output")
    repository = _absolute(project["repository"], f"{project_id}.repository")
    staging = _absolute(project["staging"], f"{project_id}.staging")
    source = _validate_version(project.get("source"), f"{project_id}.source")
    target = _validate_version(project.get("target"), f"{project_id}.target")
    origin_snapshot = _validate_snapshot(project.get("origin_snapshot"), f"{project_id}.origin_snapshot")
    target_snapshot = _validate_snapshot(project.get("target_snapshot"), f"{project_id}.target_snapshot")
    format_name = project.get("format")
    if format_name not in {"markdown", "logseq-db", "both"}:
        raise BatchProjectError("format-invalid", f"knowledge output format is invalid for {project_id}")
    scope_selectors = _normalized_scope(project.get("scope_selectors"), f"{project_id}.scope_selectors")
    runtime = _object(project.get("runtime"), f"{project_id}.runtime")
    _reject_unknown(runtime, RUNTIME_KEYS, f"{project_id}.runtime")
    python = _absolute(runtime.get("python"), f"{project_id}.runtime.python")
    ckb = _absolute(runtime.get("ckb"), f"{project_id}.runtime.ckb")
    if not python.is_file() or not ckb.is_file():
        raise BatchProjectError("runtime-missing", f"locked Python or CKB entrypoint is missing for {project_id}")
    workspace_values = project.get("workspace_roots")
    if not isinstance(workspace_values, list):
        raise BatchProjectError("workspace-roots-invalid", f"workspace_roots must be a list for {project_id}")
    workspace_roots = [_absolute(value, f"{project_id}.workspace_roots[{index}]") for index, value in enumerate(workspace_values)]
    if len({str(value) for value in workspace_roots}) != len(workspace_roots):
        raise BatchProjectError("workspace-root-duplicate", f"workspace_roots contains duplicates for {project_id}")
    if any(not value.is_dir() or not _within_any(value, roots) for value in workspace_roots):
        raise BatchProjectError("workspace-root-invalid", f"workspace root is missing or out of bounds for {project_id}")
    harnesses = project.get("harnesses")
    if not isinstance(harnesses, list) or not harnesses or len(set(harnesses)) != len(harnesses):
        raise BatchProjectError("harnesses-invalid", f"harnesses must be a unique non-empty list for {project_id}")
    unsupported = sorted(set(harnesses) - SUPPORTED_HARNESSES)
    if unsupported:
        raise BatchProjectError("harness-unsupported", f"unsupported Harness values for {project_id}: {unsupported}")
    strategies = project.get("strategies")
    if not isinstance(strategies, list) or not strategies or len(set(strategies)) != len(strategies):
        raise BatchProjectError("strategies-invalid", f"strategies must be a unique non-empty list for {project_id}")
    unknown_strategies = sorted(set(strategies) - STRATEGIES)
    if unknown_strategies:
        raise BatchProjectError("strategy-unsupported", f"unsupported migration strategies for {project_id}: {unknown_strategies}")
    cutover = _object(project.get("cutover"), f"{project_id}.cutover")
    _reject_unknown(cutover, CUTOVER_KEYS, f"{project_id}.cutover")
    cutover_output = _absolute(cutover.get("output"), f"{project_id}.cutover.output")
    backup_root = _absolute(cutover.get("backup_root"), f"{project_id}.cutover.backup_root")
    rollback = _object(project.get("rollback"), f"{project_id}.rollback")
    _reject_unknown(rollback, ROLLBACK_KEYS, f"{project_id}.rollback")
    quarantine_root = _absolute(rollback.get("quarantine_root"), f"{project_id}.rollback.quarantine_root")
    if cutover_output != output:
        raise BatchProjectError("cutover-output-mismatch", f"cutover.output must equal output for {project_id}")
    if not all(_within_any(value, roots) for value in (backup_root, quarantine_root)):
        raise BatchProjectError("recovery-path-out-of-bounds", f"backup or quarantine root escapes allowed_roots for {project_id}")
    maximum = project.get("max_path", DEFAULT_PATH_LIMIT)
    if not isinstance(maximum, int) or not (80 <= maximum <= MAX_PATH_LIMIT):
        raise BatchProjectError("path-limit-invalid", f"max_path must be 80..{MAX_PATH_LIMIT} for {project_id}")
    risks = _path_risks([output, repository, staging, backup_root, quarantine_root, *workspace_roots], maximum)
    if risks:
        raise BatchProjectError("path-too-long", f"knowledge batch path preflight failed for {project_id}: {risks}")
    if not output.is_dir():
        raise BatchProjectError("output-missing", f"origin knowledge OUTPUT is missing for {project_id}: {output}")
    if not repository.is_dir():
        raise BatchProjectError("repository-missing", f"target repository is missing for {project_id}: {repository}")
    if staging.exists():
        raise BatchProjectError("staging-conflict", f"staging already exists during read-only plan: {staging}")
    if not backup_root.parent.is_dir() or not quarantine_root.parent.is_dir():
        raise BatchProjectError("recovery-parent-missing", f"backup/quarantine parent must exist for {project_id}")
    origin_descriptor = _object(project.get("origin"), f"{project_id}.origin")
    _reject_unknown(origin_descriptor, ORIGIN_KEYS, f"{project_id}.origin")
    expected_tree = _validate_tree_summary(origin_descriptor.get("tree"), f"{project_id}.origin.tree")
    expected_records = _validate_origin_record_keys(origin_descriptor.get("records"), project_id)
    if any(not isinstance(value, str) or not HEX_SHA256.fullmatch(value) for value in expected_records.values()):
        raise BatchProjectError("origin-record-digest-invalid", f"origin.records contains an invalid SHA-256 for {project_id}")
    missing_records = [relative for relative in expected_records if not (output / relative).is_file()]
    if missing_records:
        raise BatchProjectError("origin-record-missing", f"origin key records are missing for {project_id}: {missing_records}")
    actual_tree = _tree_manifest(output)
    tree_fields = {key: actual_tree[key] for key in TREE_KEYS}
    if tree_fields != expected_tree:
        raise BatchProjectError("origin-tree-drift", f"origin full-tree summary differs from manifest for {project_id}")
    operation_id = _project_operation_id(batch_operation_id, project)
    leaf = _operation_token(operation_id, project_id)
    projected_roots = [staging, backup_root / leaf, quarantine_root / leaf]
    deep_risks = [
        {"path": str(root / item["path"]), "length": len(str(root / item["path"])), "limit": maximum}
        for root in projected_roots
        for item in actual_tree.get("files", [])
        if len(str(root / item["path"])) > maximum
    ]
    if deep_risks:
        raise BatchProjectError("path-too-long", f"knowledge batch descendant path preflight failed for {project_id}: {deep_risks[:20]}")
    record_drift = {
        relative: {"expected": digest, "actual": _file_record(output, relative)["sha256"]}
        for relative, digest in expected_records.items()
        if _file_record(output, relative)["sha256"] != digest
    }
    if record_drift:
        raise BatchProjectError("origin-record-drift", f"origin key record bytes differ from manifest for {project_id}: {record_drift}")
    health = _origin_health(output)
    if health["status"] != "passed":
        failed = [item for item in health["checks"] if not item["passed"]]
        category = failed[0]["category"] if failed else "origin-invalid"
        raise BatchProjectError(category, f"origin knowledge OUTPUT failed completeness preflight for {project_id}: {failed}")
    state = health["state"]
    protocol_path = output / "workspace-meta/agent-protocol.json"
    protocol = json_load(protocol_path) if protocol_path.is_file() else {}
    actual_source = {
        "ckb_version": state.get("version"),
        "schema_version": state.get("schema_version"),
        "protocol_version": protocol.get("protocol_version"),
    }
    expected_source = {
        "ckb_version": source["ckb_version"],
        "schema_version": source["schema_version"],
        "protocol_version": _normalized_protocol(source.get("protocol_version")),
    }
    if actual_source != expected_source:
        raise BatchProjectError("source-version-mismatch", f"origin versions differ from manifest for {project_id}: {actual_source} != {expected_source}")
    state_snapshot = {
        "commit": state.get("repository", {}).get("commit"),
        "tree": state.get("repository", {}).get("tree"),
    }
    if state_snapshot != origin_snapshot:
        raise BatchProjectError("origin-repository-mismatch", f"origin OUTPUT commit/tree differs from manifest for {project_id}")
    if state.get("format") != format_name:
        raise BatchProjectError("format-mismatch", f"origin format differs from manifest for {project_id}")
    actual_scope = _normalized_scope((health["scope"].get("selectors") or {}), f"{project_id}.actual-scope")
    if actual_scope != scope_selectors:
        raise BatchProjectError("scope-selector-mismatch", f"origin scope selectors differ from manifest for {project_id}")
    try:
        repository_state = preflight(repository)
    except CkbError as exc:
        raise BatchProjectError("target-repository-drift", f"target repository is not a clean fixed snapshot for {project_id}: {exc}") from exc
    if {"commit": repository_state["commit"], "tree": repository_state["tree"]} != target_snapshot:
        raise BatchProjectError("target-repository-drift", f"target repository commit/tree differs from manifest for {project_id}")
    if target["ckb_version"] != VERSION or target["schema_version"] != SCHEMA_VERSION or _normalized_protocol(target.get("protocol_version")) != AGENT_PROTOCOL_VERSION:
        raise BatchProjectError("target-not-current", f"target must equal current CKB/Schema/Protocol for {project_id}")
    source_release = _release_for(source)
    target_release = _release_for(target)
    if target_release is None:
        raise BatchProjectError("target-release-unknown", f"target release provenance is absent from the frozen matrix for {project_id}")
    sqlite_versions = _sqlite_schema_versions(output)
    if source_release is not None:
        expected_sqlite_versions = {
            "machine/knowledge.sqlite": str(source_release.machine_schema_version),
            "agent-index.sqlite": "1",
        }
        if sqlite_versions != expected_sqlite_versions:
            raise BatchProjectError(
                "source-sqlite-schema",
                f"origin SQLite schema versions differ from the historical release for {project_id}: {sqlite_versions} != {expected_sqlite_versions}",
            )
    if source_release is None:
        decision = "awaiting-review"
        chain: list[KnowledgeRelease] = []
        reason = "source-release-unknown"
    else:
        try:
            chain = _release_chain(source_release, target_release)
        except CkbError:
            decision = "awaiting-review"
            chain = []
            reason = "version-chain-missing"
        else:
            if not source_release.compatible:
                decision = "cold-build-required"
                reason = "source-release-requires-cold-build"
            elif "compatible-migration" not in strategies:
                decision = "cold-build-required" if "cold-build" in strategies else "awaiting-review"
                reason = "compatible-strategy-not-allowed"
            elif target_snapshot != origin_snapshot and "delta-review" not in strategies:
                decision = "awaiting-review"
                reason = "delta-review-strategy-not-allowed"
            else:
                decision = "ready"
                reason = "compatible-migration"
    if decision == "cold-build-required" and "cold-build" not in strategies:
        decision = "failed"
        reason = "cold-build-strategy-not-allowed"
    try:
        protocol_chain = supported_upgrade_path(str(source["protocol_version"]), AGENT_PROTOCOL_VERSION) if source_release and source_release.protocol_version else []
    except CkbError:
        protocol_chain = []
        if decision == "ready":
            decision = "awaiting-review"
            reason = "protocol-chain-missing"
    layers = _complete_layer_inventory(output)
    return {
        "project_id": project_id,
        "operation_id": operation_id,
        "status": decision,
        "reason": reason,
        "strategy": "compatible-migration" if decision == "ready" else "cold-build" if decision == "cold-build-required" else None,
        "output": str(output),
        "repository": str(repository),
        "staging": str(staging),
        "source": source,
        "target": target,
        "origin_snapshot": origin_snapshot,
        "target_snapshot": target_snapshot,
        "format": format_name,
        "scope_selectors": scope_selectors,
        "runtime": {"python": str(python), "ckb": str(ckb)},
        "workspace_roots": [str(value) for value in workspace_roots],
        "harnesses": sorted(harnesses),
        "strategies": sorted(strategies),
        "version_chain": [item.release_id for item in chain],
        "protocol_chain": protocol_chain,
        "origin_manifest": actual_tree,
        "origin_records": {relative: _file_record(output, relative) for relative in sorted(expected_records)},
        "origin_layers": layers,
        "sqlite": health["sqlite"],
        "sqlite_schema_versions": sqlite_versions,
        "cutover": {"output": str(cutover_output), "backup_root": str(backup_root)},
        "rollback": {"quarantine_root": str(quarantine_root)},
        "max_path": maximum,
        "risks": [
            "delta-agent-review" if target_snapshot != origin_snapshot else "same-snapshot-rekey-audit",
            "mutable-layer-preservation",
            "atomic-per-output-cutover",
        ],
    }


def create_knowledge_batch_plan(manifest_path: Path, write: Path | None = None) -> dict[str, Any]:
    manifest_path = manifest_path.expanduser().resolve()
    manifest = load_knowledge_batch_manifest(manifest_path)
    roots, projects = _validate_structural_manifest(manifest)
    normalized_manifest = {
        "schema_version": KNOWLEDGE_BATCH_MANIFEST_SCHEMA_VERSION,
        "batch_id": manifest["batch_id"],
        "allowed_roots": sorted(str(path) for path in roots),
        "projects": sorted(projects, key=lambda item: str(item["project_id"])),
    }
    manifest_digest = _digest_value(normalized_manifest)
    batch_operation_id = stable_id("knowledge-batch", manifest["batch_id"], manifest_digest)
    _validate_recovery_topology(normalized_manifest, roots, batch_operation_id)
    results: list[dict[str, Any]] = []
    for project in normalized_manifest["projects"]:
        try:
            results.append(_inspect_knowledge_project(project, roots, batch_operation_id))
        except BatchProjectError as exc:
            results.append(
                {
                    "project_id": str(project["project_id"]),
                    "status": "failed",
                    "reason": exc.category,
                    "strategy": None,
                    "output": str(project["output"]),
                    "repository": str(project["repository"]),
                    "staging": str(project["staging"]),
                    "failure": {"category": exc.category, "detail": str(exc)},
                }
            )
        except (CkbError, OSError, ValueError, json.JSONDecodeError, sqlite3.Error) as exc:
            results.append(
                {
                    "project_id": str(project["project_id"]),
                    "status": "failed",
                    "reason": "project-validation-failed",
                    "strategy": None,
                    "output": str(project["output"]),
                    "repository": str(project["repository"]),
                    "staging": str(project["staging"]),
                    "failure": {"category": "project-validation-failed", "detail": str(exc)},
                }
            )
    counts: dict[str, int] = {}
    for item in results:
        counts[item["status"]] = counts.get(item["status"], 0) + 1
    actionable = counts.get("ready", 0) + counts.get("cold-build-required", 0)
    failed = counts.get("failed", 0)
    status = "ready" if actionable == len(results) else "failed" if actionable == 0 else "partial"
    body = {
        "schema_version": KNOWLEDGE_BATCH_PLAN_SCHEMA_VERSION,
        "batch_id": manifest["batch_id"],
        "operation_id": batch_operation_id,
        "status": status,
        "dry_run": True,
        "manifest": str(manifest_path),
        "manifest_digest": manifest_digest,
        "version_matrix": knowledge_version_matrix(),
        "summary": {"projects": len(results), "actionable": actionable, "failed": failed, "counts": dict(sorted(counts.items()))},
        "projects": results,
    }
    plan = {**body, "plan_digest": _digest_value(body)}
    if write is not None:
        write = write.expanduser().resolve()
        if any(path_inside(write, Path(item["output"])) or path_inside(write, Path(item["staging"])) for item in results):
            raise CkbError("knowledge batch plan must be outside every OUTPUT and staging directory")
        json_write(write, plan)
        return {**plan, "plan_path": str(write)}
    return plan


def _load_knowledge_batch_plan(path: Path) -> dict[str, Any]:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise CkbError(f"knowledge batch plan is missing: {path}")
    plan = json_load(path)
    if not isinstance(plan, dict) or plan.get("schema_version") != KNOWLEDGE_BATCH_PLAN_SCHEMA_VERSION:
        raise CkbError(f"unsupported knowledge batch plan schema: {path}")
    digest = plan.get("plan_digest")
    if not isinstance(digest, str) or not HEX_SHA256.fullmatch(digest):
        raise CkbError(f"knowledge batch plan digest is invalid: {path}")
    body = {key: value for key, value in plan.items() if key not in {"plan_digest", "plan_path"}}
    if _digest_value(body) != digest:
        raise CkbError(f"knowledge batch plan digest mismatch: {path}")
    return plan


def _verify_plan_manifest_binding(plan: dict[str, Any]) -> None:
    manifest_path = Path(str(plan.get("manifest"))).expanduser().resolve()
    manifest = load_knowledge_batch_manifest(manifest_path)
    roots, projects = _validate_structural_manifest(manifest)
    normalized = {
        "schema_version": KNOWLEDGE_BATCH_MANIFEST_SCHEMA_VERSION,
        "batch_id": manifest["batch_id"],
        "allowed_roots": sorted(str(path) for path in roots),
        "projects": sorted(projects, key=lambda item: str(item["project_id"])),
    }
    _validate_recovery_topology(normalized, roots, str(plan.get("operation_id")))
    actual = _digest_value(normalized)
    if actual != plan.get("manifest_digest"):
        raise CkbError(
            f"knowledge batch manifest changed after plan: expected {plan.get('manifest_digest')}, found {actual}"
        )


def _save_knowledge_state(path: Path, state: dict[str, Any]) -> None:
    state["updated_at_utc"] = utc_now()
    json_write(path, state)


def _load_knowledge_state(path: Path) -> dict[str, Any]:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise CkbError(f"knowledge batch state is missing: {path}")
    state = json_load(path)
    if not isinstance(state, dict) or state.get("schema_version") != KNOWLEDGE_BATCH_STATE_SCHEMA_VERSION:
        raise CkbError(f"unsupported knowledge batch state schema: {path}")
    if Path(str(state.get("state"))).resolve() != path:
        raise CkbError("knowledge batch state absolute binding is invalid")
    return state


def _state_event(
    state: dict[str, Any],
    project_id: str,
    action: str,
    status: str,
    category: str | None = None,
) -> None:
    events = state.setdefault("events", [])
    events.append(
        {
            "event_id": stable_id("knowledge-batch-event", state["batch_id"], len(events), project_id, action, status),
            "project_id": project_id,
            "action": action,
            "status": status,
            "category": category,
            "recorded_at_utc": utc_now(),
        }
    )
    if len(events) > MAX_STATE_EVENTS:
        del events[: len(events) - MAX_STATE_EVENTS]


def _new_knowledge_state(plan: dict[str, Any], plan_path: Path, state_path: Path) -> dict[str, Any]:
    projects: dict[str, dict[str, Any]] = {}
    for project in plan["projects"]:
        plan_status = project["status"]
        actionable = plan_status in {"ready", "cold-build-required"}
        projects[project["project_id"]] = {
            "project_id": project["project_id"],
            "status": "pending" if actionable else plan_status,
            "plan_status": plan_status,
            "strategy": project.get("strategy"),
            "operation_id": project.get("operation_id") if actionable else None,
            "output": project["output"],
            "staging": project["staging"],
            "origin_digest": (project.get("origin_manifest") or {}).get("sha256"),
            "staging_digest": None,
            "modified_digest": None,
            "audit": None,
            "pending_review_packs": [],
            "backup_output": None,
            "control": None,
            "protocol_backup": None,
            "failure": project.get("failure"),
        }
    stamp = utc_now()
    return {
        "schema_version": KNOWLEDGE_BATCH_STATE_SCHEMA_VERSION,
        "batch_id": plan["batch_id"],
        "operation_id": plan["operation_id"],
        "status": "running",
        "plan": str(plan_path.resolve()),
        "plan_digest": plan["plan_digest"],
        "state": str(state_path.resolve()),
        "created_at_utc": stamp,
        "updated_at_utc": stamp,
        "projects": projects,
        "events": [],
    }


def _summarize_knowledge_state(state: dict[str, Any]) -> str:
    values = [item["status"] for item in state["projects"].values()]
    eligible = [value for value in values if value not in {"failed", "awaiting-review"}]
    if eligible and all(value == "rolled-back" for value in eligible):
        return "rolled-back"
    if values and all(value == "cutover-complete" for value in values):
        return "cutover-complete"
    if any(value == "cutover-complete" for value in values):
        return "partial"
    if any(value in {"failed", "awaiting-review"} for value in values) and any(
        value in {"ready", "review-pending", "pending", "applying", "rolled-back"} for value in values
    ):
        return "partial"
    if any(value == "ready" for value in values):
        return "ready"
    if any(value == "review-pending" for value in values):
        return "review-pending"
    if any(value in {"pending", "applying"} for value in values):
        return "running"
    if values and all(value in {"failed", "awaiting-review", "cold-build-required"} for value in values):
        return "failed"
    return "partial" if any(value == "failed" for value in values) else "running"


def _manifest_matches(expected: dict[str, Any], actual: dict[str, Any]) -> bool:
    return all(expected.get(key) == actual.get(key) for key in ("algorithm", "file_count", "byte_count", "sha256", "files"))


def _manifest_delta(expected: dict[str, Any], actual: dict[str, Any]) -> dict[str, Any]:
    left = {item["path"]: item for item in expected.get("files", [])}
    right = {item["path"]: item for item in actual.get("files", [])}
    changed = [
        path
        for path in sorted(set(left) & set(right))
        if (left[path].get("size"), left[path].get("sha256")) != (right[path].get("size"), right[path].get("sha256"))
    ]
    return {
        "expected_sha256": expected.get("sha256"),
        "actual_sha256": actual.get("sha256"),
        "missing": sorted(set(left) - set(right)),
        "extra": sorted(set(right) - set(left)),
        "changed": changed,
    }


def _verify_plan_bindings(project: dict[str, Any]) -> None:
    output = Path(project["output"]).resolve()
    actual = _tree_manifest(output)
    if not _manifest_matches(project["origin_manifest"], actual):
        raise BatchProjectError("origin-drift", f"origin knowledge OUTPUT changed after plan: {project['project_id']}")
    try:
        repository = preflight(Path(project["repository"]))
    except CkbError as exc:
        raise BatchProjectError("repository-drift", f"target repository is no longer the clean planned snapshot: {project['project_id']}: {exc}") from exc
    if {"commit": repository["commit"], "tree": repository["tree"]} != project["target_snapshot"]:
        raise BatchProjectError("repository-drift", f"target repository changed after plan: {project['project_id']}")


def _knowledge_output_lock(output: Path):
    """Use the proven owner-token lock outside the directory being renamed.

    The Agent Protocol batch lock file lives inside OUTPUT because that batch
    edits individual files.  Complete migration atomically renames OUTPUT, so
    its equivalent lock anchor is a deterministic sibling; otherwise Windows
    would keep an open descriptor inside the directory being promoted.
    """
    anchor = output.resolve().parent / f".{output.name}.knowledge-batch-lock"
    anchor.mkdir(parents=True, exist_ok=True)
    return _output_lock(anchor)


def _detach_staging_workspace_roots(staging: Path, project: dict[str, Any]) -> dict[str, Any]:
    record_path = staging / "workspace-meta/agent-protocol.json"
    if record_path.is_file():
        record = json_load(record_path)
        record["workspace_roots"] = []
        record["output"] = str(staging.resolve())
        record["python"] = project["runtime"]["python"]
        record["ckb"] = project["runtime"]["ckb"]
        json_write(record_path, record)
    # This writes only internal staging adapters.  External Harness roots are
    # upgraded transactionally during cutover and are separately backed up.
    return project_agent_protocol(
        staging,
        python=Path(project["runtime"]["python"]),
        ckb=Path(project["runtime"]["ckb"]),
    )


def _cold_build(project: dict[str, Any]) -> dict[str, Any]:
    previous_output = Path(project["output"]).resolve()
    repository = Path(project["repository"]).resolve()
    staging = Path(project["staging"]).resolve()
    selectors = project["scope_selectors"]
    initialize(
        repository,
        staging,
        project["format"],
        list(selectors.get("scope_paths") or []),
        list(selectors.get("entries") or []),
        int(selectors.get("expand_depth", 1)),
        str(selectors.get("expand_direction", "both")),
        list(selectors.get("include") or []),
        csharp_solution=selectors.get("csharp_solution"),
        csharp_project=selectors.get("csharp_project"),
        allow_dotnet_restore=bool(selectors.get("allow_dotnet_restore", False)),
        page_config_path=previous_output / "page-config.json",
    )
    preserved = _preserve_mutable_layers(previous_output, staging)
    state = json_load(staging / "state.json")
    for batch in state["parse_batches"]:
        build_chunk(staging, batch["id"], "all")
    _reused, delta_ids = _replace_review_packs(staging, {})
    state = json_load(staging / "state.json")
    migration = {
        "schema_version": 1,
        "mode": "cold-build",
        "origin_output": str(previous_output),
        "origin_version": project["source"]["ckb_version"],
        "origin_commit": project["origin_snapshot"]["commit"],
        "target_version": VERSION,
        "target_commit": project["target_snapshot"]["commit"],
        "status": "pending-agent-review",
        "started_at_utc": utc_now(),
    }
    state["migration"] = migration
    json_write(staging / "state.json", state)
    migration_plan = {
        "schema_version": 1,
        "status": "pending-agent-review",
        "mode": "cold-build",
        "origin": {
            "output": str(previous_output),
            "version": project["source"]["ckb_version"],
            "commit": project["origin_snapshot"]["commit"],
        },
        "target": {
            "output": str(staging),
            "version": VERSION,
            "repository": str(repository),
            "commit": project["target_snapshot"]["commit"],
        },
        "files": {"reused": [], "reused_count": 0, "parsed_count": len(state.get("parse_batches", []))},
        "entities": {"reused_review_count": 0, "delta_review_count": len(delta_ids), "old_to_new_id_map": {}},
        "mutable_files": preserved,
        "cold_build": {
            "reused_fact_count": 0,
            "reused_review_count": 0,
            "required_review_entity_ids": sorted(delta_ids),
            "incompatible_layers": ["facts", "graph", "review", "human-projection", "machine-indexes"],
        },
        "created_at_utc": utc_now(),
    }
    json_write(staging / "migration/plan.json", migration_plan)
    return {
        "schema_version": 1,
        "status": "pending-agent-review",
        "output": str(staging),
        "strategy": "cold-build",
        "delta_review_entity_count": len(delta_ids),
        "preserved_mutable_file_count": len(preserved),
    }


def _project_record(staging: Path, batch_id: str, project: dict[str, Any], project_state: dict[str, Any]) -> dict[str, Any]:
    migration_plan = json_load(staging / "migration/plan.json")
    record = {
        "schema_version": KNOWLEDGE_BATCH_PROJECT_SCHEMA_VERSION,
        "batch_id": batch_id,
        "project_id": project["project_id"],
        "operation_id": project_state["operation_id"],
        "status": "review-pending",
        "strategy": project_state["strategy"],
        "bindings": {
            "origin_output": project["output"],
            "staging_output": project["staging"],
            "repository": project["repository"],
            "origin_snapshot": project["origin_snapshot"],
            "target_snapshot": project["target_snapshot"],
        },
        "version_chain": project["version_chain"],
        "protocol_chain": project["protocol_chain"],
        "origin_manifest": project["origin_manifest"],
        "origin_layers": project["origin_layers"],
        "mutable_files": migration_plan.get("mutable_files", []),
        "workspace_roots": project["workspace_roots"],
        "created_at_utc": utc_now(),
    }
    json_write(staging / "knowledge-batch/project.json", record)
    return record


def _pending_reviews(staging: Path) -> list[str]:
    state = json_load(staging / "state.json")
    return [item["id"] for item in state.get("review_packs", []) if item.get("status") != "passed"]


def _mutable_preservation_check(staging: Path, record: dict[str, Any]) -> dict[str, Any]:
    files = list(record.get("mutable_files") or [])
    errors = _preservation_errors(staging, files)
    missing_baselines = []
    for item in files:
        relative = item.get("baseline_relative_target")
        if not relative:
            missing_baselines.append(item.get("relative_target"))
            continue
        path = staging / str(relative)
        if not path.is_file() or sha256_file(path) != item.get("baseline_sha256"):
            missing_baselines.append(item.get("relative_target"))
    return {"passed": not errors and not missing_baselines, "errors": errors, "missing_baselines": missing_baselines}


def _old_entity_id_errors(staging: Path) -> list[str]:
    migration_plan = json_load(staging / "migration/plan.json")
    mapping = (migration_plan.get("entities") or {}).get("old_to_new_id_map", {})
    old_ids = {old for old, new in mapping.items() if old != new}
    graph = json_load(staging / "graph.json") if (staging / "graph.json").is_file() else {}
    new_ids = {item.get("id") for item in graph.get("entities", [])}
    return sorted(old_ids & new_ids)


def _knowledge_project_audit(project: dict[str, Any], project_state: dict[str, Any]) -> dict[str, Any]:
    staging = Path(project["staging"]).resolve()
    record_path = staging / "knowledge-batch/project.json"
    checks: list[dict[str, Any]] = []

    def check(name: str, passed: bool, detail: Any, category: str) -> None:
        checks.append({"name": name, "passed": bool(passed), "category": category, "detail": detail})

    if not record_path.is_file():
        result = {
            "schema_version": KNOWLEDGE_BATCH_PROJECT_SCHEMA_VERSION,
            "project_id": project["project_id"],
            "status": "failed",
            "checks": [{"name": "project-record", "passed": False, "category": "staging-record-missing", "detail": str(record_path)}],
        }
        return result
    record = json_load(record_path)
    check(
        "absolute-bindings",
        record.get("batch_id") is not None
        and record.get("project_id") == project["project_id"]
        and record.get("operation_id") == project_state["operation_id"]
        and Path(record.get("bindings", {}).get("staging_output", "")).resolve() == staging,
        record.get("bindings"),
        "staging-binding",
    )
    try:
        _verify_plan_bindings(project)
    except BatchProjectError as exc:
        check("origin-and-repository-pinned", False, str(exc), exc.category)
    else:
        check("origin-and-repository-pinned", True, project["target_snapshot"], "drift")
    pending = _pending_reviews(staging)
    migration_audit = audit_migration(staging, require_complete_reviews=False)
    check(
        "migration-reuse-and-review-binding",
        migration_audit.get("status") in {"passed", "pending-agent-review"},
        migration_audit,
        "migration-audit",
    )
    if project_state["strategy"] == "cold-build":
        migration_plan = json_load(staging / "migration/plan.json")
        cold = migration_plan.get("cold_build") or {}
        cold_ok = (
            migration_plan.get("files", {}).get("reused_count") == 0
            and migration_plan.get("entities", {}).get("reused_review_count") == 0
            and cold.get("reused_fact_count") == 0
            and cold.get("reused_review_count") == 0
        )
        check("cold-build-does-not-reuse-incompatible-facts", cold_ok, cold, "cold-build-reuse")
    check("delta-reviews-complete", not pending, pending, "review-pending")
    if not pending and all(item["passed"] for item in checks):
        try:
            if json_load(staging / "state.json").get("status") != "complete":
                finalize(staging)
        except (CkbError, OSError, ValueError, json.JSONDecodeError, sqlite3.Error) as exc:
            check("current-finalize", False, str(exc), "global-finalize")
        else:
            check("current-finalize", True, "complete", "global-finalize")
    else:
        check("current-finalize", False, "blocked by pending review or earlier check", "blocked")
    global_audit = json_load(staging / "audit/global.json") if (staging / "audit/global.json").is_file() else {}
    check("global-audit", global_audit.get("status") == "passed", global_audit, "global-audit")
    markers = {
        name: json_load(staging / name) if (staging / name).is_file() else {}
        for name in (".complete", ".machine.complete", ".human.complete")
    }
    check("three-completion-markers", all(value.get("status") == "complete" for value in markers.values()), markers, "completion-markers")
    sqlite_checks = _sqlite_checks(staging)
    required_sqlite = {item["path"]: item for item in sqlite_checks}
    check(
        "double-sqlite-integrity-and-foreign-keys",
        all(required_sqlite.get(name, {}).get("passed") for name in ("machine/knowledge.sqlite", "agent-index.sqlite")),
        sqlite_checks,
        "sqlite-integrity",
    )
    sqlite_versions = _sqlite_schema_versions(staging)
    expected_sqlite_versions = {"machine/knowledge.sqlite": "3", "agent-index.sqlite": "1"}
    check(
        "current-sqlite-schema-versions",
        sqlite_versions == expected_sqlite_versions,
        {"expected": expected_sqlite_versions, "actual": sqlite_versions},
        "sqlite-schema-version",
    )
    preservation = _mutable_preservation_check(staging, record)
    check("all-mutable-layers-preserved", preservation["passed"], preservation, "mutable-layer-loss")
    old_ids = _old_entity_id_errors(staging)
    check("old-entity-id-residue-zero", not old_ids, old_ids[:40], "old-entity-id-residue")
    readability = json_load(staging / "markdown/readability-audit.json") if (staging / "markdown/readability-audit.json").is_file() else {}
    check("human-readability", readability.get("status") == "passed" and not readability.get("errors"), readability, "readability")
    from .agent_protocol import audit_agent_protocol
    from .llm_wiki_capabilities import maintenance_check
    from .operation_journal import audit_operation_journal
    from .reference_documents import audit_references
    from .research_gaps import audit_gap_register

    if global_audit.get("status") == "passed":
        reference = audit_references(staging)
        gaps = audit_gap_register(staging)
        operations = audit_operation_journal(staging)
        agent_policy = audit_agent_protocol(staging)
        maintenance = maintenance_check(staging)
    else:
        reference = gaps = operations = agent_policy = maintenance = {"status": "blocked"}
    _release_audit_handles()
    check("reference-layer", reference.get("status") == "passed", reference, "reference-audit")
    check("research-gap-layer", gaps.get("status") == "passed", gaps, "gap-audit")
    check("operation-journal", operations.get("status") == "passed", operations, "operation-audit")
    check("agent-policy", agent_policy.get("status") == "passed", agent_policy, "agent-policy-audit")
    check("maintain", maintenance.get("status") == "passed", maintenance, "maintain")
    passed = all(item["passed"] for item in checks)
    pending_only = bool(pending) and all(item["passed"] or item["category"] in {"review-pending", "blocked", "global-audit", "completion-markers", "sqlite-integrity", "sqlite-schema-version", "readability", "reference-audit", "gap-audit", "operation-audit", "agent-policy-audit", "maintain"} for item in checks)
    status = "ready" if passed else "review-pending" if pending_only else "failed"
    result = {
        "schema_version": KNOWLEDGE_BATCH_PROJECT_SCHEMA_VERSION,
        "project_id": project["project_id"],
        "operation_id": project_state["operation_id"],
        "status": status,
        "strategy": project_state["strategy"],
        "checks": checks,
        "counts": {"passed": sum(item["passed"] for item in checks), "total": len(checks)},
        "pending_review_packs": pending,
        "origin_layers": record.get("origin_layers"),
        "current_layers": _complete_layer_inventory(staging, record.get("mutable_files")),
        "sqlite": sqlite_checks,
        "sqlite_schema_versions": sqlite_versions,
        "audited_at_utc": utc_now(),
    }
    json_write(staging / "knowledge-batch/audit.json", result)
    record["status"] = status
    record["audited_at_utc"] = result["audited_at_utc"]
    json_write(record_path, record)
    return result


def _apply_one_project(
    state: dict[str, Any],
    state_path: Path,
    project: dict[str, Any],
    *,
    retry_failed: bool,
    fault: str | None = None,
) -> None:
    project_id = project["project_id"]
    item = state["projects"][project_id]
    if project["status"] not in {"ready", "cold-build-required"}:
        return
    if item["status"] in {"ready", "review-pending", "cutover-complete", "rolled-back"}:
        if item["status"] in {"ready", "review-pending"}:
            staging = Path(project["staging"])
            if not staging.is_dir() or not (staging / "knowledge-batch/project.json").is_file():
                raise BatchProjectError("staging-missing", f"recorded staging is missing for {project_id}")
            if item["status"] == "review-pending" and retry_failed:
                with _knowledge_output_lock(Path(project["output"])):
                    audit = _knowledge_project_audit(project, item)
                item["audit"] = str((staging / "knowledge-batch/audit.json").resolve())
                item["pending_review_packs"] = audit.get("pending_review_packs", [])
                item["status"] = audit["status"]
                item["staging_digest"] = _tree_manifest(staging)["sha256"]
                item["failure"] = None if audit["status"] in {"ready", "review-pending"} else {
                    "category": "staging-audit-failed",
                    "detail": item["audit"],
                }
                _state_event(state, project_id, "resume", item["status"], (item.get("failure") or {}).get("category"))
                _save_knowledge_state(state_path, state)
        return
    if item["status"] == "failed" and not retry_failed:
        return
    if item["status"] == "failed":
        item["status"] = "pending"
        item["failure"] = None
    output = Path(project["output"]).resolve()
    staging = Path(project["staging"]).resolve()
    with _knowledge_output_lock(output):
        _verify_plan_bindings(project)
        if item["status"] == "applying" and staging.exists():
            marker = staging / "knowledge-batch/project.json"
            if marker.is_file():
                value = json_load(marker)
                if value.get("operation_id") != item["operation_id"]:
                    raise BatchProjectError("resume-staging-conflict", f"interrupted staging belongs to another operation: {project_id}")
            shutil.rmtree(staging)
            _state_event(state, project_id, "resume", "staging-reset")
            item["status"] = "pending"
            _save_knowledge_state(state_path, state)
        if staging.exists():
            raise BatchProjectError("staging-conflict", f"staging exists before apply: {staging}")
        item["status"] = "applying"
        item["failure"] = None
        _state_event(state, project_id, "apply", "applying")
        _save_knowledge_state(state_path, state)
        if fault == "before-build":
            raise OSError("injected failure before staging build")
        if item["strategy"] == "cold-build":
            _cold_build(project)
        else:
            migrate_output(output, Path(project["repository"]), staging, project["format"])
        _detach_staging_workspace_roots(staging, project)
        _project_record(staging, state["batch_id"], project, item)
        if fault == "after-build":
            raise OSError("injected failure after staging build")
        audit = _knowledge_project_audit(project, item)
        item["audit"] = str((staging / "knowledge-batch/audit.json").resolve())
        item["pending_review_packs"] = audit.get("pending_review_packs", [])
        item["status"] = audit["status"]
        item["staging_digest"] = _tree_manifest(staging)["sha256"]
        item["failure"] = None if audit["status"] in {"ready", "review-pending"} else {
            "category": "staging-audit-failed",
            "detail": str(item["audit"]),
        }
        _state_event(state, project_id, "apply", item["status"], (item.get("failure") or {}).get("category"))
        _save_knowledge_state(state_path, state)


def apply_knowledge_batch_plan(
    plan_path: Path,
    state_path: Path,
    *,
    retry_failed: bool = False,
    faults: dict[str, str] | None = None,
) -> dict[str, Any]:
    plan_path = plan_path.expanduser().resolve()
    state_path = state_path.expanduser().resolve()
    plan = _load_knowledge_batch_plan(plan_path)
    _verify_plan_manifest_binding(plan)
    for project in plan["projects"]:
        if path_inside(state_path, Path(project["output"])) or path_inside(state_path, Path(project["staging"])):
            raise CkbError("knowledge batch state must be outside every OUTPUT and staging directory")
    if state_path.is_file():
        state = _load_knowledge_state(state_path)
        if state.get("operation_id") != plan["operation_id"] or state.get("plan_digest") != plan["plan_digest"]:
            raise CkbError("knowledge batch state is bound to another immutable plan")
    else:
        state = _new_knowledge_state(plan, plan_path, state_path)
        _save_knowledge_state(state_path, state)
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    for project_id in sorted(plan_by_id):
        project = plan_by_id[project_id]
        try:
            _apply_one_project(
                state,
                state_path,
                project,
                retry_failed=retry_failed,
                fault=(faults or {}).get(project_id),
            )
        except BatchProjectError as exc:
            item = state["projects"][project_id]
            item["status"] = "failed"
            item["failure"] = {"category": exc.category, "detail": str(exc)}
            _state_event(state, project_id, "apply", "failed", exc.category)
            _save_knowledge_state(state_path, state)
        except (CkbError, OSError, ValueError, json.JSONDecodeError, sqlite3.Error) as exc:
            item = state["projects"][project_id]
            item["status"] = "failed"
            item["failure"] = {"category": "apply-failed", "detail": str(exc)}
            _state_event(state, project_id, "apply", "failed", "apply-failed")
            _save_knowledge_state(state_path, state)
    state["status"] = _summarize_knowledge_state(state)
    _save_knowledge_state(state_path, state)
    return knowledge_batch_status(state_path)


def resume_knowledge_batch_state(
    state_path: Path,
    *,
    faults: dict[str, str] | None = None,
) -> dict[str, Any]:
    state = _load_knowledge_state(state_path)
    return apply_knowledge_batch_plan(Path(state["plan"]), state_path, retry_failed=True, faults=faults)


def knowledge_batch_status(state_path: Path) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_knowledge_state(state_path)
    plan = _load_knowledge_batch_plan(Path(state["plan"]))
    _verify_plan_manifest_binding(plan)
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    projects = []
    drifted = 0
    for project_id in sorted(state["projects"]):
        value = dict(state["projects"][project_id])
        project = plan_by_id[project_id]
        drift = None
        try:
            if value["status"] in {"ready", "review-pending"}:
                staging = Path(project["staging"])
                if not staging.is_dir():
                    drift = {"category": "staging-missing"}
                else:
                    actual = _tree_manifest(staging)["sha256"]
                    if value.get("staging_digest") and actual != value["staging_digest"]:
                        drift = {"category": "staging-drift", "expected": value["staging_digest"], "actual": actual}
            elif value["status"] == "cutover-complete":
                output = Path(project["output"])
                actual = _tree_manifest(output)["sha256"] if output.is_dir() else None
                if actual != value.get("modified_digest"):
                    drift = {"category": "cutover-output-drift", "expected": value.get("modified_digest"), "actual": actual}
            elif value["status"] == "rolled-back":
                output = Path(project["output"])
                actual = _tree_manifest(output)["sha256"] if output.is_dir() else None
                if actual != value.get("origin_digest"):
                    drift = {"category": "rollback-output-drift", "expected": value.get("origin_digest"), "actual": actual}
        except (CkbError, OSError, ValueError, json.JSONDecodeError, sqlite3.Error) as exc:
            drift = {"category": "status-probe-failed", "detail": str(exc)}
        value["drift"] = drift
        if drift:
            drifted += 1
        value["commands"] = {
            "resume": f"migrate batch resume --state '{state_path}'",
            "audit": f"migrate batch audit --state '{state_path}'",
            "cutover": f"migrate batch cutover --state '{state_path}' --project {project_id}",
            "rollback": f"migrate batch rollback --state '{state_path}' --project {project_id}",
        }
        projects.append(value)
    counts: dict[str, int] = {}
    for item in projects:
        counts[item["status"]] = counts.get(item["status"], 0) + 1
    return {
        "schema_version": KNOWLEDGE_BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "operation_id": state["operation_id"],
        "status": "drifted" if drifted else state["status"],
        "state": str(state_path),
        "plan": state["plan"],
        "summary": {"projects": len(projects), "drifted": drifted, "counts": dict(sorted(counts.items()))},
        "projects": projects,
        "event_count": len(state.get("events", [])),
    }


def audit_knowledge_batch_state(state_path: Path) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_knowledge_state(state_path)
    plan = _load_knowledge_batch_plan(Path(state["plan"]))
    _verify_plan_manifest_binding(plan)
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    results = []
    for project_id in sorted(state["projects"]):
        item = state["projects"][project_id]
        project = plan_by_id[project_id]
        if project["status"] not in {"ready", "cold-build-required"}:
            result = {
                "project_id": project_id,
                "status": project["status"],
                "failure": project.get("failure") or {"category": project.get("reason")},
            }
        elif item["status"] in {"cutover-complete", "rolled-back"}:
            result = {
                "project_id": project_id,
                "status": "passed",
                "phase": item["status"],
                "control": item.get("control"),
            }
        elif not Path(project["staging"]).is_dir():
            result = {
                "project_id": project_id,
                "status": "failed",
                "failure": {"category": "staging-missing"},
            }
            item["status"] = "failed"
            item["failure"] = result["failure"]
        else:
            result = _knowledge_project_audit(project, item)
            item["audit"] = str((Path(project["staging"]) / "knowledge-batch/audit.json").resolve())
            item["pending_review_packs"] = result.get("pending_review_packs", [])
            item["status"] = result["status"]
            item["staging_digest"] = _tree_manifest(Path(project["staging"]))["sha256"]
            item["failure"] = None if result["status"] in {"ready", "review-pending"} else {
                "category": "staging-audit-failed",
                "detail": item["audit"],
            }
        results.append(result)
        _state_event(state, project_id, "audit", result["status"], (result.get("failure") or {}).get("category"))
        _save_knowledge_state(state_path, state)
    state["status"] = _summarize_knowledge_state(state)
    _save_knowledge_state(state_path, state)
    failed = sum(item["status"] in {"failed", "awaiting-review"} for item in results)
    pending = sum(item["status"] == "review-pending" for item in results)
    ready = sum(item["status"] in {"ready", "passed"} for item in results)
    return {
        "schema_version": KNOWLEDGE_BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 and pending == 0 else "review-pending" if failed == 0 else "failed" if ready == 0 else "partial",
        "state": str(state_path),
        "summary": {"projects": len(results), "ready": ready, "review_pending": pending, "failed": failed},
        "projects": results,
    }


def _control_path(output: Path, operation_id: str, project_id: str) -> Path:
    return output.parent / f".{output.name}.knowledge-migration-{_operation_token(operation_id, project_id)}.json"


def _control_records(output: Path) -> list[tuple[Path, dict[str, Any]]]:
    records = []
    for path in sorted(output.parent.glob(f".{output.name}.knowledge-migration-*.json")):
        try:
            value = json_load(path)
        except (CkbError, OSError, ValueError, json.JSONDecodeError):
            continue
        if value.get("schema_version") == KNOWLEDGE_BATCH_PROJECT_SCHEMA_VERSION and value.get("output") == str(output.resolve()):
            records.append((path, value))
    return records


def _active_control(output: Path, actual: dict[str, Any] | None = None) -> tuple[Path, dict[str, Any]] | None:
    actual = actual or _tree_manifest(output)
    matches = [
        (path, value)
        for path, value in _control_records(output)
        if value.get("status") == "cutover-complete"
        and isinstance(value.get("modified_manifest"), dict)
        and _manifest_matches(value["modified_manifest"], actual)
    ]
    if len(matches) > 1:
        raise BatchProjectError("active-chain-ambiguous", f"multiple migration controls match the active OUTPUT: {output}")
    return matches[0] if matches else None


def _protocol_digest(project: dict[str, Any]) -> str:
    return _protocol_snapshot_digest(
        _protocol_snapshot_files(
            Path(project["output"]),
            [Path(value) for value in project.get("workspace_roots", [])],
        )
    )


def _cutover_one(
    state: dict[str, Any],
    state_path: Path,
    project: dict[str, Any],
    *,
    fault: str | None = None,
) -> dict[str, Any]:
    project_id = project["project_id"]
    item = state["projects"][project_id]
    output = Path(project["output"]).resolve()
    staging = Path(project["staging"]).resolve()
    if item["status"] == "cutover-complete":
        control = json_load(Path(item["control"]))
        if not _manifest_matches(control["modified_manifest"], _tree_manifest(output)):
            raise BatchProjectError("cutover-post-drift", f"completed cutover drifted for {project_id}")
        return {"project_id": project_id, "status": "skipped", "control": item["control"]}
    if item["status"] != "ready":
        raise BatchProjectError("not-ready", f"project audit has not marked staging ready: {project_id}")
    with _knowledge_output_lock(output):
        _verify_plan_bindings(project)
        audit = json_load(Path(item["audit"])) if item.get("audit") and Path(item["audit"]).is_file() else {}
        if audit.get("status") != "ready":
            raise BatchProjectError("audit-not-ready", f"staging audit is not ready for {project_id}")
        current_staging = _tree_manifest(staging)
        if current_staging["sha256"] != item.get("staging_digest"):
            raise BatchProjectError("staging-drift", f"staging changed after audit for {project_id}")
        operation_id = item["operation_id"]
        backup_root = Path(project["cutover"]["backup_root"]).resolve()
        backup_root.mkdir(parents=True, exist_ok=True)
        leaf = _operation_token(operation_id, project_id)
        backup = backup_root / leaf
        if backup.exists():
            raise BatchProjectError("cutover-backup-conflict", f"cutover backup already exists: {backup}")
        control_path = _control_path(output, operation_id, project_id)
        previous_attempts: list[dict[str, Any]] = []
        if control_path.exists():
            previous = json_load(control_path)
            if previous.get("status") != "cutover-failed-restored":
                raise BatchProjectError("cutover-control-conflict", f"cutover control already exists: {control_path}")
            previous_attempts = list(previous.get("attempts") or [])
            previous_attempts.append(
                {
                    "status": previous.get("status"),
                    "failure": previous.get("failure"),
                    "origin_restored": previous.get("origin_restored"),
                }
            )
        active_parent = _active_control(output, project["origin_manifest"])
        protocol_backup_root = state_path.parent / ".ckb-knowledge-migration-protocol-backups" / state["batch_id"] / project_id
        protocol_backup_project = {
            "project_id": project_id,
            "output": str(output),
            "workspace_roots": project["workspace_roots"],
        }
        protocol_backup = _create_protocol_backup(protocol_backup_project, protocol_backup_root)
        record = {
            "schema_version": KNOWLEDGE_BATCH_PROJECT_SCHEMA_VERSION,
            "batch_id": state["batch_id"],
            "project_id": project_id,
            "operation_id": operation_id,
            "status": "cutover-started",
            "output": str(output),
            "staging_output": str(staging),
            "backup_output": str(backup),
            "parent_operation_id": active_parent[1]["operation_id"] if active_parent else None,
            "chain_depth": int(active_parent[1].get("chain_depth", 0)) + 1 if active_parent else 1,
            "origin_manifest": project["origin_manifest"],
            "staging_manifest": current_staging,
            "protocol_backup": protocol_backup["manifest_path"],
            "attempts": previous_attempts,
            "started_at_utc": utc_now(),
        }
        json_write(control_path, record)
        moved_staging = False
        try:
            _release_audit_handles()
            output.rename(backup)
            if fault == "after-backup-rename":
                raise OSError("injected failure after backup rename")
            backup_manifest = _tree_manifest(backup)
            if not _manifest_matches(project["origin_manifest"], backup_manifest):
                raise BatchProjectError(
                    "backup-verification",
                    f"cutover backup differs from origin for {project_id}: {_manifest_delta(project['origin_manifest'], backup_manifest)}",
                )
            staging.rename(output)
            moved_staging = True
            if fault == "after-staging-rename":
                raise OSError("injected failure after staging rename")
            pipeline_status(output)
            install_agent_protocol(
                output,
                [Path(value) for value in project["workspace_roots"]],
                python=Path(project["runtime"]["python"]),
                ckb=Path(project["runtime"]["ckb"]),
            )
            if fault == "after-protocol-upgrade":
                raise OSError("injected failure after Agent Protocol upgrade")
            sqlite_checks = _sqlite_checks(output)
            if not sqlite_checks or not all(value["passed"] for value in sqlite_checks):
                raise BatchProjectError("cutover-sqlite", f"promoted SQLite verification failed for {project_id}: {sqlite_checks}")
            from .llm_wiki_capabilities import maintenance_check

            maintenance = maintenance_check(output)
            _release_audit_handles()
            if maintenance.get("status") != "passed":
                raise BatchProjectError("cutover-maintain", f"promoted maintain failed for {project_id}")
            modified = _tree_manifest(output)
            protocol_digest = _protocol_digest(project)
            record.update(
                {
                    "status": "cutover-complete",
                    "backup_manifest": backup_manifest,
                    "modified_manifest": modified,
                    "protocol_applied_digest": protocol_digest,
                    "sqlite": sqlite_checks,
                    "maintenance_status": maintenance.get("status"),
                    "completed_at_utc": utc_now(),
                }
            )
            json_write(control_path, record)
            item["status"] = "cutover-complete"
            item["modified_digest"] = modified["sha256"]
            item["backup_output"] = str(backup)
            item["control"] = str(control_path)
            item["protocol_backup"] = protocol_backup["manifest_path"]
            item["failure"] = None
            _state_event(state, project_id, "cutover", "cutover-complete")
            _save_knowledge_state(state_path, state)
            return {
                "project_id": project_id,
                "status": "cutover-complete",
                "operation_id": operation_id,
                "parent_operation_id": record["parent_operation_id"],
                "chain_depth": record["chain_depth"],
                "output": str(output),
                "backup_output": str(backup),
                "control": str(control_path),
                "sqlite": sqlite_checks,
            }
        except Exception as exc:
            try:
                if moved_staging and output.exists():
                    output.rename(staging)
                if backup.exists() and not output.exists():
                    backup.rename(output)
                _restore_protocol_backup(Path(protocol_backup["manifest_path"]))
            finally:
                restored = output.is_dir() and _manifest_matches(project["origin_manifest"], _tree_manifest(output))
                record.update(
                    {
                        "status": "cutover-failed-restored" if restored else "cutover-failed",
                        "failure": str(exc),
                        "origin_restored": restored,
                    }
                )
                json_write(control_path, record)
            if isinstance(exc, BatchProjectError):
                raise
            raise BatchProjectError("cutover-failed", str(exc)) from exc


def cutover_knowledge_batch_state(
    state_path: Path,
    project_ids: list[str] | None = None,
    *,
    faults: dict[str, str] | None = None,
) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_knowledge_state(state_path)
    plan = _load_knowledge_batch_plan(Path(state["plan"]))
    _verify_plan_manifest_binding(plan)
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    requested = sorted(set(project_ids or []))
    unknown = sorted(set(requested) - set(plan_by_id))
    if unknown:
        raise CkbError(f"unknown knowledge batch cutover project: {', '.join(unknown)}")
    selected = requested or sorted(project_id for project_id, item in state["projects"].items() if item["status"] in {"ready", "cutover-complete"})
    if not selected:
        raise CkbError("knowledge batch cutover has no audit-ready project")
    results = []
    for project_id in selected:
        try:
            result = _cutover_one(state, state_path, plan_by_id[project_id], fault=(faults or {}).get(project_id))
        except BatchProjectError as exc:
            item = state["projects"][project_id]
            item["failure"] = {"category": exc.category, "detail": str(exc)}
            _state_event(state, project_id, "cutover", "failed", exc.category)
            _save_knowledge_state(state_path, state)
            result = {"project_id": project_id, "status": "failed", "failure": item["failure"]}
        results.append(result)
    state["status"] = _summarize_knowledge_state(state)
    _save_knowledge_state(state_path, state)
    failed = sum(item["status"] == "failed" for item in results)
    passed = sum(item["status"] == "cutover-complete" for item in results)
    return {
        "schema_version": KNOWLEDGE_BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 else "failed" if passed == 0 else "partial",
        "state": str(state_path),
        "summary": {"selected": len(results), "cutover_complete": passed, "skipped": len(results) - passed - failed, "failed": failed},
        "projects": results,
    }


def _rollback_one(
    state: dict[str, Any],
    state_path: Path,
    project: dict[str, Any],
    *,
    fault: str | None = None,
) -> dict[str, Any]:
    project_id = project["project_id"]
    item = state["projects"][project_id]
    output = Path(project["output"]).resolve()
    if item["status"] == "rolled-back":
        if not _manifest_matches(project["origin_manifest"], _tree_manifest(output)):
            raise BatchProjectError("rollback-post-drift", f"rolled-back OUTPUT drifted for {project_id}")
        return {"project_id": project_id, "status": "skipped", "idempotent": True}
    if item["status"] != "cutover-complete" or not item.get("control"):
        raise BatchProjectError("rollback-not-eligible", f"project has no completed cutover: {project_id}")
    control_path = Path(item["control"])
    if not control_path.is_file():
        raise BatchProjectError("rollback-control-missing", f"rollback control is missing for {project_id}")
    record = json_load(control_path)
    with _knowledge_output_lock(output):
        actual = _tree_manifest(output)
        if not _manifest_matches(record["modified_manifest"], actual):
            raise BatchProjectError("rollback-external-drift", f"promoted OUTPUT changed after cutover: {project_id}")
        if _protocol_digest(project) != record.get("protocol_applied_digest"):
            raise BatchProjectError("rollback-protocol-drift", f"Agent Protocol managed bytes changed after cutover: {project_id}")
        backup = Path(record["backup_output"])
        if not backup.is_dir() or not _manifest_matches(record["origin_manifest"], _tree_manifest(backup)):
            raise BatchProjectError("rollback-backup-drift", f"rollback backup is missing or changed: {project_id}")
        quarantine_root = Path(project["rollback"]["quarantine_root"]).resolve()
        quarantine_root.mkdir(parents=True, exist_ok=True)
        quarantine = quarantine_root / _operation_token(record["operation_id"], project_id)
        if quarantine.exists():
            raise BatchProjectError("rollback-quarantine-conflict", f"rollback quarantine already exists: {quarantine}")
        restored_origin = False
        try:
            _release_audit_handles()
            output.rename(quarantine)
            if fault == "after-modified-rename":
                raise OSError("injected failure after modified rename")
            backup.rename(output)
            restored_origin = True
            if fault == "after-backup-restore":
                raise OSError("injected failure after backup restore")
            _restore_protocol_backup(Path(record["protocol_backup"]))
            if fault == "after-protocol-restore":
                raise OSError("injected failure after Agent Protocol restore")
            restored = _tree_manifest(output)
            if not _manifest_matches(record["origin_manifest"], restored):
                raise BatchProjectError("rollback-verification", f"restored OUTPUT differs from the exact origin for {project_id}")
            sqlite_checks = _sqlite_checks(output)
            if not sqlite_checks or not all(value["passed"] for value in sqlite_checks):
                raise BatchProjectError("rollback-sqlite", f"restored SQLite verification failed for {project_id}")
            record.update(
                {
                    "status": "rolled-back",
                    "rolled_forward_output": str(quarantine),
                    "restored_manifest": restored,
                    "rollback_sqlite": sqlite_checks,
                    "rolled_back_at_utc": utc_now(),
                }
            )
            json_write(control_path, record)
            item["status"] = "rolled-back"
            item["failure"] = None
            _state_event(state, project_id, "rollback", "rolled-back")
            _save_knowledge_state(state_path, state)
            return {
                "project_id": project_id,
                "status": "rolled-back",
                "operation_id": record["operation_id"],
                "reactivated_operation_id": record.get("parent_operation_id"),
                "output": str(output),
                "modified_output": str(quarantine),
                "control": str(control_path),
                "sqlite": sqlite_checks,
            }
        except Exception as exc:
            try:
                if restored_origin and output.exists():
                    output.rename(backup)
                if quarantine.exists() and not output.exists():
                    quarantine.rename(output)
                # Restore the promoted managed bytes when the old backup was
                # partially applied.  The quarantined promoted OUTPUT carries
                # its exact internal bytes; external blocks are guarded by the
                # applied digest and remain untouched unless backup restore ran.
                if _protocol_digest(project) != record.get("protocol_applied_digest"):
                    install_agent_protocol(
                        output,
                        [Path(value) for value in project["workspace_roots"]],
                        python=Path(project["runtime"]["python"]),
                        ckb=Path(project["runtime"]["ckb"]),
                    )
            finally:
                restored_modified = output.is_dir() and _manifest_matches(record["modified_manifest"], _tree_manifest(output))
                record.update(
                    {
                        "status": "cutover-complete" if restored_modified else "rollback-failed",
                        "last_rollback_failure": str(exc),
                        "modified_restored": restored_modified,
                    }
                )
                json_write(control_path, record)
            if isinstance(exc, BatchProjectError):
                raise
            raise BatchProjectError("rollback-failed", str(exc)) from exc


def rollback_knowledge_batch_state(
    state_path: Path,
    project_ids: list[str] | None = None,
    *,
    faults: dict[str, str] | None = None,
) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_knowledge_state(state_path)
    plan = _load_knowledge_batch_plan(Path(state["plan"]))
    _verify_plan_manifest_binding(plan)
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    requested = sorted(set(project_ids or []))
    unknown = sorted(set(requested) - set(plan_by_id))
    if unknown:
        raise CkbError(f"unknown knowledge batch rollback project: {', '.join(unknown)}")
    selected = requested or sorted(project_id for project_id, item in state["projects"].items() if item["status"] in {"cutover-complete", "rolled-back"})
    if not selected:
        raise CkbError("knowledge batch rollback has no completed project to restore")
    results = []
    for project_id in selected:
        try:
            result = _rollback_one(state, state_path, plan_by_id[project_id], fault=(faults or {}).get(project_id))
        except BatchProjectError as exc:
            item = state["projects"][project_id]
            item["failure"] = {"category": exc.category, "detail": str(exc)}
            _state_event(state, project_id, "rollback", "failed", exc.category)
            _save_knowledge_state(state_path, state)
            result = {"project_id": project_id, "status": "failed", "failure": item["failure"]}
        results.append(result)
    state["status"] = _summarize_knowledge_state(state)
    _save_knowledge_state(state_path, state)
    failed = sum(item["status"] == "failed" for item in results)
    passed = sum(item["status"] == "rolled-back" for item in results)
    return {
        "schema_version": KNOWLEDGE_BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 else "failed" if passed == 0 else "partial",
        "state": str(state_path),
        "summary": {"selected": len(results), "rolled_back": passed, "skipped": len(results) - passed - failed, "failed": failed},
        "projects": results,
    }

def create_knowledge_batch_plan(manifest_path: Path, write: Path | None = None) -> dict[str, Any]:
    manifest_path = manifest_path.expanduser().resolve()
    manifest = load_knowledge_batch_manifest(manifest_path)
    roots, projects = _validate_structural_manifest(manifest)
    normalized_manifest = {
        "schema_version": KNOWLEDGE_BATCH_MANIFEST_SCHEMA_VERSION,
        "batch_id": manifest["batch_id"],
        "allowed_roots": sorted(str(path) for path in roots),
        "projects": sorted(projects, key=lambda item: str(item["project_id"])),
    }
    manifest_digest = _digest_value(normalized_manifest)
    batch_operation_id = stable_id("knowledge-batch", manifest["batch_id"], manifest_digest)
    _validate_recovery_topology(normalized_manifest, roots, batch_operation_id)
    results: list[dict[str, Any]] = []
    for project in normalized_manifest["projects"]:
        try:
            results.append(_inspect_knowledge_project(project, roots, batch_operation_id))
        except BatchProjectError as exc:
            results.append(
                {
                    "project_id": str(project["project_id"]),
                    "status": "failed",
                    "reason": exc.category,
                    "strategy": None,
                    "output": str(project["output"]),
                    "repository": str(project["repository"]),
                    "staging": str(project["staging"]),
                    "failure": {"category": exc.category, "detail": str(exc)},
                }
            )
        except (CkbError, OSError, ValueError, json.JSONDecodeError, sqlite3.Error) as exc:
            results.append(
                {
                    "project_id": str(project["project_id"]),
                    "status": "failed",
                    "reason": "project-validation-failed",
                    "strategy": None,
                    "output": str(project["output"]),
                    "repository": str(project["repository"]),
                    "staging": str(project["staging"]),
                    "failure": {"category": "project-validation-failed", "detail": str(exc)},
                }
            )
    counts: dict[str, int] = {}
    for item in results:
        counts[item["status"]] = counts.get(item["status"], 0) + 1
    actionable = counts.get("ready", 0) + counts.get("cold-build-required", 0)
    failed = counts.get("failed", 0)
    status = "ready" if actionable == len(results) else "failed" if actionable == 0 else "partial"
    body = {
        "schema_version": KNOWLEDGE_BATCH_PLAN_SCHEMA_VERSION,
        "batch_id": manifest["batch_id"],
        "operation_id": batch_operation_id,
        "status": status,
        "dry_run": True,
        "manifest": str(manifest_path),
        "manifest_digest": manifest_digest,
        "version_matrix": knowledge_version_matrix(),
        "summary": {"projects": len(results), "actionable": actionable, "failed": failed, "counts": dict(sorted(counts.items()))},
        "projects": results,
    }
    plan = {**body, "plan_digest": _digest_value(body)}
    if write is not None:
        write = write.expanduser().resolve()
        if any(path_inside(write, Path(item["output"])) or path_inside(write, Path(item["staging"])) for item in results):
            raise CkbError("knowledge batch plan must be outside every OUTPUT and staging directory")
        json_write(write, plan)
        return {**plan, "plan_path": str(write)}
    return plan

def retrieve_machine(
    output: Path,
    question: str,
    budget: int = 1500,
    entity_limit: int = 8,
    profile: str = "fast",
    *,
    keyword_fallback: KeywordFallbackOptions | None = None,
) -> dict[str, Any]:
    """Run deterministic retrieval and, only when explicit, one keyword fallback."""

    original = _retrieve_machine_deterministic(output, question, budget, entity_limit, profile)
    if keyword_fallback is None:
        return original
    trigger = "forced" if keyword_fallback.force else "needs-source-read"
    if original.get("status") != "needs-source-read" and not keyword_fallback.force:
        metadata = {
            "schema_version": 1,
            "status": "skipped",
            "trigger": trigger,
            "original": {
                "status": original.get("status"),
                "terms": original.get("terms", []),
                "anchors": original.get("anchors", []),
            },
            "provider": {
                "status": "not-started",
                "provider": keyword_fallback.config.provider,
                "model": keyword_fallback.config.model,
                "version": keyword_fallback.config.version,
            },
            "model_candidates": {"keywords": [], "anchors": [], "rewrites": []},
            "validated_extensions": {"terms": [], "anchors": [], "rewrites": []},
            "final": {"status": original.get("status"), "deterministic_selection": True},
        }
        return _attach_keyword_fallback(output, question, original, metadata)
    provider = run_keyword_provider(
        output,
        question,
        keyword_fallback.config,
        use_cache=keyword_fallback.use_cache,
    )
    original_terms = list(original.get("terms") or search_terms(question))
    original_anchors = list(original.get("anchors") or explicit_anchors(question))
    candidates = {
        "keywords": list(provider.get("keywords") or []),
        "anchors": list(provider.get("anchors") or []),
        "rewrites": list(provider.get("rewrites") or []),
    }
    extension_terms = unique_casefold(
        [
            term
            for value in [*candidates["keywords"], *candidates["rewrites"]]
            for term in search_terms(value)
        ]
    )
    original_term_ids = {value.casefold() for value in original_terms}
    extension_terms = [value for value in extension_terms if value.casefold() not in original_term_ids]
    original_anchor_ids = {value.casefold() for value in original_anchors}
    extension_anchors = [
        value.casefold()
        for value in unique_casefold(candidates["anchors"])
        if value.casefold() not in original_anchor_ids
    ]
    extensions = {
        "terms": extension_terms,
        "anchors": extension_anchors,
        "rewrites": candidates["rewrites"],
    }
    if provider.get("status") != "passed" or not any(extensions.values()):
        provider_record = _provider_record(provider)
        if provider.get("status") == "passed":
            provider_record = {**provider_record, "status": "failed", "failure_type": "invalid-output"}
        metadata = {
            "schema_version": 1,
            "status": "fallback",
            "trigger": trigger,
            "original": {"status": original.get("status"), "terms": original_terms, "anchors": original_anchors},
            "provider": provider_record,
            "model_candidates": candidates,
            "validated_extensions": extensions,
            "final": {"status": original.get("status"), "deterministic_selection": True},
        }
        return _attach_keyword_fallback(output, question, original, metadata)
    final = _retrieve_machine_deterministic(
        output,
        question,
        budget,
        entity_limit,
        profile,
        extra_terms=extension_terms,
        extra_anchors=extension_anchors,
        rewrite_queries=candidates["rewrites"],
    )
    metadata = {
        "schema_version": 1,
        "status": "passed" if final.get("status") == "passed" else "no-quality-gain",
        "trigger": trigger,
        "original": {"status": original.get("status"), "terms": original_terms, "anchors": original_anchors},
        "provider": _provider_record(provider),
        "model_candidates": candidates,
        "validated_extensions": extensions,
        "final": {
            "status": final.get("status"),
            "deterministic_selection": True,
            "selected_entities": len(final.get("selected_entities") or []),
            "estimated_tokens": final.get("estimated_tokens"),
        },
    }
    return _attach_keyword_fallback(output, question, final, metadata)

"""Harness-neutral conversation bindings for the CKB management Agent.

This module owns only project-management identity, dispatch metadata and the
prompt assembled from existing CKB commands.  Conversation events, feedback,
references, research gaps and reviewed notes remain in their existing stores.
"""

from __future__ import annotations

from contextlib import contextmanager
import copy
import hashlib
import json
import os
from pathlib import Path
import re
import sqlite3
import subprocess
import sys
import time
from typing import Any, Iterator

from .automation import SUPPORTED_HARNESSES
from .common import CkbError, json_load, json_write, run, stable_id, utc_now
from .session_stdio import close_session


MANAGEMENT_SCHEMA_VERSION = 1
MANAGEMENT_PROMPT_VERSION = "1.0.0"
MANAGEMENT_SCHEMA_ID = "https://code-knowledge-builder.local/management-binding-v1.schema.json"
MANAGEMENT_REGISTRY_ENV = "CKB_MANAGER_REGISTRY"
MANAGEMENT_CAPABILITIES = ("binding", "prompt_injection", "event_sync", "task_dispatch")
NOTIFICATION_POLICIES = ("none", "status", "failures")
_BINDING_STATUSES = ("active", "unbound")
_TASK_STATUSES = ("created", "review-passed", "review-failed")
_FORBIDDEN_INPUT_FIELDS = {
    "assistant",
    "assistant_message",
    "authorization",
    "cookie",
    "password",
    "prompt",
    "secret",
    "token",
    "transcript",
    "transcript_path",
}
_OPAQUE_ID = re.compile(r"^[^\x00-\x1f\x7f]{1,512}$")


def default_management_registry_path() -> Path:
    configured = os.environ.get(MANAGEMENT_REGISTRY_ENV)
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "management-bindings.json"


def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    return os.path.normcase(os.path.normpath(value)).replace("\\", "/").rstrip("/")


def _normalized_path(path: Path | str) -> str:
    return str(Path(path).expanduser().resolve())


def _empty_registry() -> dict[str, Any]:
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "bindings": [],
        "tasks": [],
        "audit_log": [],
    }


def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return _empty_registry()
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"management registry must be one JSON object: {path}")
    if value.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"unsupported management registry: {path}")
    for field in ("bindings", "tasks", "audit_log"):
        if not isinstance(value.get(field), list):
            raise CkbError(f"management registry field must be a list: {field}")
    return value


@contextmanager
def _registry_lock(path: Path, timeout: float = 30.0) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = path.with_name(path.name + ".lock")
    deadline = time.monotonic() + timeout
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, f"{os.getpid()}\n{time.time()}\n".encode("ascii"))
        except (FileExistsError, PermissionError):
            try:
                if time.time() - lock.stat().st_mtime > 60:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"management registry is busy: {path}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)


@contextmanager
def _locked_registry(path: Path | None = None) -> Iterator[tuple[Path, dict[str, Any]]]:
    registry = (path or default_management_registry_path()).expanduser().resolve()
    with _registry_lock(registry):
        value = _read_registry(registry)
        before = copy.deepcopy(value)
        yield registry, value
        if value != before:
            json_write(registry, value)
            reopened = _read_registry(registry)
            if reopened != value:
                raise CkbError(f"management registry did not reopen with the written state: {registry}")


def _audit_event(binding_id: str | None, action: str, status: str, reason: str) -> dict[str, Any]:
    stamp = utc_now()
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "event_id": stable_id("manager-event", binding_id or "none", action, status, reason, stamp, time.time_ns()),
        "binding_id": binding_id,
        "action": action,
        "status": status,
        "reason": reason,
        "recorded_at_utc": stamp,
    }


def _capability(available: bool, mode: str) -> dict[str, Any]:
    return {"available": available, "mode": mode}


def harness_capabilities(harness_id: str) -> dict[str, dict[str, Any]]:
    harness = harness_id.strip().casefold()
    if harness not in SUPPORTED_HARNESSES:
        return {
            "binding": _capability(True, "generic-cli"),
            "prompt_injection": _capability(False, "no-adapter"),
            "event_sync": _capability(False, "no-adapter"),
            "task_dispatch": _capability(False, "no-adapter"),
        }
    return {
        "binding": _capability(True, "manager-cli"),
        "prompt_injection": _capability(False, "manual-context"),
        "event_sync": _capability(True, "generic-json" if harness == "generic" else "automation-adapter"),
        "task_dispatch": _capability(True, "manager-cli"),
    }


def binding_schema() -> dict[str, Any]:
    capabilities = {
        name: {
            "type": "object",
            "additionalProperties": False,
            "required": ["available", "mode"],
            "properties": {"available": {"type": "boolean"}, "mode": {"type": "string"}},
        }
        for name in MANAGEMENT_CAPABILITIES
    }
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": MANAGEMENT_SCHEMA_ID,
        "title": "Code Knowledge Builder canonical management binding",
        "type": "object",
        "additionalProperties": False,
        "required": [
            "schema_version",
            "conversation_id",
            "harness_id",
            "workspace_root",
            "repo_root",
            "knowledge_base",
            "integration_branch",
        ],
        "properties": {
            "schema_version": {"const": MANAGEMENT_SCHEMA_VERSION},
            "conversation_id": {"type": "string", "minLength": 1, "maxLength": 512},
            "harness_id": {"type": "string", "minLength": 1, "maxLength": 80},
            "workspace_root": {"type": "string", "minLength": 1},
            "repo_root": {"type": "string", "minLength": 1},
            "knowledge_base": {"type": "string", "minLength": 1},
            "integration_branch": {"type": "string", "minLength": 1},
            "notification_policy": {"enum": list(NOTIFICATION_POLICIES)},
            "capabilities": {
                "type": "object",
                "additionalProperties": False,
                "required": list(MANAGEMENT_CAPABILITIES),
                "properties": capabilities,
            },
        },
        "privacy": {
            "persisted_fields": [
                "opaque conversation/task identity",
                "Harness identity",
                "normalized project paths",
                "integration branch and bound HEAD",
                "lifecycle timestamps and capability declarations",
            ],
            "forbidden_fields": sorted(_FORBIDDEN_INPUT_FIELDS),
            "raw_conversation_content": False,
            "credentials": False,
        },
    }


def canonical_binding_input(payload: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    if not isinstance(payload, dict):
        raise CkbError("management binding input must be one JSON object")
    if payload.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"management binding requires schema_version={MANAGEMENT_SCHEMA_VERSION}")
    allowed = set(binding_schema()["properties"])
    ignored = sorted(str(key) for key in payload if key not in allowed)
    value = {key: payload[key] for key in allowed if key in payload and key != "capabilities"}
    required = set(binding_schema()["required"])
    missing = sorted(field for field in required if not isinstance(value.get(field), (str, int)) or not str(value[field]).strip())
    if missing:
        raise CkbError(f"management binding input is missing required fields: {missing}")
    if int(value["schema_version"]) != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"management binding requires schema_version={MANAGEMENT_SCHEMA_VERSION}")
    for field in ("conversation_id", "harness_id"):
        text = str(value[field]).strip()
        if not _OPAQUE_ID.fullmatch(text):
            raise CkbError(f"management binding {field} must be bounded opaque text")
        value[field] = text
    value["harness_id"] = str(value["harness_id"]).casefold()
    policy = str(value.get("notification_policy", "none")).strip().casefold()
    if policy not in NOTIFICATION_POLICIES:
        raise CkbError(f"unsupported management notification policy: {policy}")
    value["notification_policy"] = policy
    for field in ("workspace_root", "repo_root", "knowledge_base"):
        value[field] = _normalized_path(str(value[field]))
    value["integration_branch"] = str(value["integration_branch"]).strip()
    value["capabilities"] = harness_capabilities(value["harness_id"])
    return value, ignored


def _privacy_errors(value: Any, location: str = "registry") -> list[str]:
    errors: list[str] = []
    if isinstance(value, dict):
        for key, child in value.items():
            lowered = str(key).casefold().replace("-", "_")
            if lowered in _FORBIDDEN_INPUT_FIELDS:
                errors.append(f"{location}: forbidden persisted field: {key}")
            errors.extend(_privacy_errors(child, f"{location}.{key}"))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            errors.extend(_privacy_errors(child, f"{location}[{index}]"))
    return errors


def audit_manager_registry(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_management_registry_path()).expanduser().resolve()
    try:
        value = _read_registry(registry)
    except CkbError as exc:
        return {
            "schema_version": MANAGEMENT_SCHEMA_VERSION,
            "status": "failed",
            "registry": str(registry),
            "binding_count": 0,
            "task_count": 0,
            "errors": [str(exc)],
        }
    errors = _privacy_errors(value)
    binding_ids: set[str] = set()
    active_identities: set[tuple[str, str]] = set()
    for index, binding in enumerate(value["bindings"]):
        prefix = f"binding[{index}]"
        if not isinstance(binding, dict):
            errors.append(f"{prefix}: binding must be an object")
            continue
        binding_id = binding.get("binding_id")
        if not isinstance(binding_id, str) or not binding_id.startswith("manager-binding-"):
            errors.append(f"{prefix}: invalid binding_id")
        elif binding_id in binding_ids:
            errors.append(f"{prefix}: duplicate binding_id")
        else:
            binding_ids.add(binding_id)
        if binding.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
            errors.append(f"{prefix}: schema version mismatch")
        if binding.get("status") not in _BINDING_STATUSES:
            errors.append(f"{prefix}: unsupported status")
        identity = (str(binding.get("harness_id", "")).casefold(), str(binding.get("conversation_id", "")))
        if binding.get("status") == "active":
            if identity in active_identities:
                errors.append(f"{prefix}: duplicate active conversation identity")
            active_identities.add(identity)
        capabilities = binding.get("capabilities")
        if not isinstance(capabilities, dict) or set(capabilities) != set(MANAGEMENT_CAPABILITIES):
            errors.append(f"{prefix}: capability set differs from canonical schema")
        for field in ("workspace_root", "repo_root", "knowledge_base"):
            path = binding.get(field)
            if not isinstance(path, str) or _path_key(path) != _path_key(_normalized_path(path)):
                errors.append(f"{prefix}: {field} is not normalized")
    dispatch_ids: set[str] = set()
    for index, task in enumerate(value["tasks"]):
        prefix = f"task[{index}]"
        if not isinstance(task, dict):
            errors.append(f"{prefix}: task must be an object")
            continue
        dispatch_id = task.get("dispatch_id")
        if not isinstance(dispatch_id, str) or not dispatch_id.startswith("manager-task-"):
            errors.append(f"{prefix}: invalid dispatch_id")
        elif dispatch_id in dispatch_ids:
            errors.append(f"{prefix}: duplicate dispatch_id")
        else:
            dispatch_ids.add(dispatch_id)
        if task.get("binding_id") not in binding_ids:
            errors.append(f"{prefix}: binding_id does not exist")
        if task.get("status") not in _TASK_STATUSES:
            errors.append(f"{prefix}: unsupported status")
        prompt_path = Path(str(task.get("prompt_path", "")))
        if not prompt_path.is_file():
            errors.append(f"{prefix}: task prompt is missing")
        elif hashlib.sha256(prompt_path.read_bytes()).hexdigest() != task.get("prompt_sha256"):
            errors.append(f"{prefix}: task prompt hash mismatch")
        verification_value = task.get("verification_path")
        if verification_value:
            verification_path = Path(str(verification_value))
            if not verification_path.is_file():
                errors.append(f"{prefix}: task verification is missing")
            elif hashlib.sha256(verification_path.read_bytes()).hexdigest() != task.get("verification_sha256"):
                errors.append(f"{prefix}: task verification hash mismatch")
    for index, event in enumerate(value["audit_log"]):
        if not isinstance(event, dict) or set(event) != {
            "schema_version", "event_id", "binding_id", "action", "status", "reason", "recorded_at_utc"
        }:
            errors.append(f"audit_log[{index}]: fields differ from the canonical audit schema")
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "registry": str(registry),
        "binding_count": len(value["bindings"]),
        "active_bindings": sum(item.get("status") == "active" for item in value["bindings"] if isinstance(item, dict)),
        "task_count": len(value["tasks"]),
        "audit_events": len(value["audit_log"]),
        "errors": errors,
    }


def _git(repo: Path, *arguments: str, allow_failure: bool = False) -> str | None:
    completed = run(["git", "-C", str(repo), *arguments], timeout=60)
    if completed.returncode:
        if allow_failure:
            return None
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"management Git command failed: git -C {repo} {' '.join(arguments)}: {detail}")
    return completed.stdout.strip()


def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")


def _git_preflight(
    workspace_root: Path,
    repo_root: Path,
    knowledge_base: Path,
    integration_branch: str,
) -> dict[str, Any]:
    if not workspace_root.is_dir():
        raise CkbError(f"management workspace does not exist: {workspace_root}")
    if not repo_root.is_dir():
        raise CkbError(f"management repository does not exist: {repo_root}")
    if not (_is_within(repo_root, workspace_root) or _is_within(workspace_root, repo_root)):
        raise CkbError("management workspace must contain the repository or be inside it")
    if not knowledge_base.is_dir():
        raise CkbError(f"management knowledge base does not exist: {knowledge_base}")
    if not (knowledge_base / "state.json").is_file():
        raise CkbError(f"management knowledge base is missing state.json: {knowledge_base}")
    top = _git(repo_root, "rev-parse", "--show-toplevel", allow_failure=True)
    if not top or _path_key(top) != _path_key(repo_root):
        raise CkbError(f"management repo_root must be the root of a Git worktree: {repo_root}")
    current_branch = _git(repo_root, "symbolic-ref", "--quiet", "--short", "HEAD", allow_failure=True)
    if not current_branch:
        raise CkbError(f"management integration repository has no attached branch: {repo_root}")
    if current_branch != integration_branch:
        raise CkbError(
            f"management integration branch mismatch: expected={integration_branch}; current={current_branch}"
        )
    branch_head = _git(repo_root, "rev-parse", "--verify", f"refs/heads/{integration_branch}^{{commit}}", allow_failure=True)
    if not branch_head:
        raise CkbError(f"management integration branch does not exist: {integration_branch}")
    current_head = _git(repo_root, "rev-parse", "--verify", "HEAD", allow_failure=True)
    if not current_head:
        raise CkbError(f"management integration repository has no HEAD: {repo_root}")
    dirty = (_git(repo_root, "status", "--porcelain=v1", "--untracked-files=all") or "").splitlines()
    if dirty:
        raise CkbError(f"management integration worktree must be clean: {repo_root}; paths={dirty[:12]}")
    return {
        "workspace_root": str(workspace_root),
        "repo_root": str(repo_root),
        "knowledge_base": str(knowledge_base),
        "integration_branch": integration_branch,
        "current_branch": current_branch,
        "head": current_head,
        "clean": True,
    }


def _binding_identity(binding: dict[str, Any]) -> tuple[str, str]:
    return str(binding["harness_id"]).casefold(), str(binding["conversation_id"])


def _binding_project(binding: dict[str, Any]) -> tuple[str, str]:
    return _path_key(binding["repo_root"]), _path_key(binding["knowledge_base"])


def _binding_id(binding: dict[str, Any]) -> str:
    return stable_id(
        "manager-binding",
        binding["harness_id"],
        binding["conversation_id"],
        _path_key(binding["repo_root"]),
        _path_key(binding["knowledge_base"]),
    )


def bind_conversation(
    payload: dict[str, Any],
    registry_path: Path | None = None,
) -> dict[str, Any]:
    canonical, ignored_fields = canonical_binding_input(payload)
    binding_id = _binding_id(canonical)
    try:
        preflight = _git_preflight(
            Path(canonical["workspace_root"]),
            Path(canonical["repo_root"]),
            Path(canonical["knowledge_base"]),
            canonical["integration_branch"],
        )
    except CkbError as exc:
        with _locked_registry(registry_path) as (_registry, failed_value):
            failed_value["audit_log"].append(_audit_event(binding_id, "bind", "failed", type(exc).__name__))
        raise
    error: CkbError | None = None
    result: dict[str, Any] | None = None
    with _locked_registry(registry_path) as (registry, value):
        try:
            matches = [item for item in value["bindings"] if _binding_identity(item) == _binding_identity(canonical)]
            if matches:
                existing = matches[0]
                if _binding_project(existing) != _binding_project(canonical):
                    raise CkbError(
                        "management conversation identity is already bound to another project: "
                        f"binding_id={existing['binding_id']}"
                    )
                immutable_paths = ("workspace_root", "repo_root", "knowledge_base")
                conflicts = [field for field in immutable_paths if _path_key(existing[field]) != _path_key(canonical[field])]
                if existing["integration_branch"] != canonical["integration_branch"]:
                    conflicts.append("integration_branch")
                if conflicts:
                    raise CkbError(
                        f"management conversation binding conflicts with existing fields: {conflicts}; "
                        f"binding_id={existing['binding_id']}"
                    )
                if existing["status"] == "active":
                    result = {
                        "schema_version": MANAGEMENT_SCHEMA_VERSION,
                        "status": "already-bound",
                        "registry": str(registry),
                        "binding": existing,
                        "ignored_input_fields": ignored_fields,
                        "preflight": preflight,
                    }
                else:
                    stamp = utc_now()
                    existing.update(
                        {
                            "status": "active",
                            "bound_head": preflight["head"],
                            "updated_at_utc": stamp,
                            "unbound_at_utc": None,
                            "prompt_version": MANAGEMENT_PROMPT_VERSION,
                            "capabilities": canonical["capabilities"],
                            "notification_policy": canonical["notification_policy"],
                        }
                    )
                    value["audit_log"].append(_audit_event(existing["binding_id"], "bind", "passed", "reactivated"))
                    result = {
                        "schema_version": MANAGEMENT_SCHEMA_VERSION,
                        "status": "bound",
                        "registry": str(registry),
                        "binding": existing,
                        "ignored_input_fields": ignored_fields,
                        "preflight": preflight,
                    }
            else:
                # Recheck only the first creation while holding the registry
                # lock. Concurrent idempotent bind calls complete from the
                # canonical record instead of serializing repeated Git probes.
                preflight = _git_preflight(
                    Path(canonical["workspace_root"]),
                    Path(canonical["repo_root"]),
                    Path(canonical["knowledge_base"]),
                    canonical["integration_branch"],
                )
                stamp = utc_now()
                binding = {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    "binding_id": binding_id,
                    "conversation_id": canonical["conversation_id"],
                    "harness_id": canonical["harness_id"],
                    "workspace_root": canonical["workspace_root"],
                    "repo_root": canonical["repo_root"],
                    "knowledge_base": canonical["knowledge_base"],
                    "integration_branch": canonical["integration_branch"],
                    "bound_head": preflight["head"],
                    "status": "active",
                    "created_at_utc": stamp,
                    "updated_at_utc": stamp,
                    "unbound_at_utc": None,
                    "prompt_version": MANAGEMENT_PROMPT_VERSION,
                    "notification_policy": canonical["notification_policy"],
                    "capabilities": canonical["capabilities"],
                }
                value["bindings"].append(binding)
                value["bindings"].sort(key=lambda item: item["binding_id"])
                value["audit_log"].append(_audit_event(binding_id, "bind", "passed", "created"))
                result = {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    "status": "bound",
                    "registry": str(registry),
                    "binding": binding,
                    "ignored_input_fields": ignored_fields,
                    "preflight": preflight,
                }
        except CkbError as exc:
            value["audit_log"].append(_audit_event(binding_id, "bind", "failed", type(exc).__name__))
            error = exc
    if error is not None:
        raise error
    assert result is not None
    return result


def _find_binding(
    value: dict[str, Any],
    conversation_id: str,
    harness_id: str,
) -> dict[str, Any] | None:
    identity = (harness_id.strip().casefold(), conversation_id.strip())
    return next((item for item in value["bindings"] if _binding_identity(item) == identity), None)


def _runtime_state(binding: dict[str, Any]) -> dict[str, Any]:
    repo = Path(binding["repo_root"])
    branch = str(binding["integration_branch"])
    state: dict[str, Any] = {
        "repo_exists": repo.is_dir(),
        "git_repository": False,
        "current_branch": None,
        "integration_branch_exists": False,
        "current_head": None,
        "integration_head": None,
        "bound_head": binding["bound_head"],
        "head_drift": None,
        "clean": None,
        "dirty_paths": [],
        "errors": [],
    }
    if not repo.is_dir():
        state["errors"].append("repo-missing")
        return state
    top = _git(repo, "rev-parse", "--show-toplevel", allow_failure=True)
    if not top or _path_key(top) != _path_key(repo):
        state["errors"].append("not-git-root")
        return state
    state["git_repository"] = True
    state["current_branch"] = _git(repo, "symbolic-ref", "--quiet", "--short", "HEAD", allow_failure=True)
    state["current_head"] = _git(repo, "rev-parse", "--verify", "HEAD", allow_failure=True)
    state["integration_head"] = _git(repo, "rev-parse", "--verify", f"refs/heads/{branch}^{{commit}}", allow_failure=True)
    state["integration_branch_exists"] = bool(state["integration_head"])
    state["head_drift"] = state["integration_head"] != binding["bound_head"] if state["integration_head"] else None
    dirty = (_git(repo, "status", "--porcelain=v1", "--untracked-files=all", allow_failure=True) or "").splitlines()
    state["dirty_paths"] = dirty[:100]
    state["clean"] = not dirty
    if state["current_branch"] != branch:
        state["errors"].append("integration-branch-not-checked-out")
    if not state["integration_branch_exists"]:
        state["errors"].append("integration-branch-missing")
    if state["head_drift"]:
        state["errors"].append("integration-head-drift")
    if not state["clean"]:
        state["errors"].append("integration-worktree-dirty")
    return state


def binding_status(
    conversation_id: str,
    harness_id: str,
    registry_path: Path | None = None,
) -> dict[str, Any]:
    registry = (registry_path or default_management_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    binding = _find_binding(value, conversation_id, harness_id)
    if binding is None:
        raise CkbError(f"management conversation binding does not exist: harness={harness_id}; conversation={conversation_id}")
    runtime = _runtime_state(binding)
    active = binding["status"] == "active"
    ready = active and not runtime["errors"]
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "status": "ready" if ready else "unbound" if not active else "blocked",
        "registry": str(registry),
        "binding": binding,
        "runtime": runtime,
        "blockers": ([] if active else ["binding-unbound"]) + runtime["errors"],
    }


def unbind_conversation(
    conversation_id: str,
    harness_id: str,
    registry_path: Path | None = None,
) -> dict[str, Any]:
    error: CkbError | None = None
    result: dict[str, Any] | None = None
    with _locked_registry(registry_path) as (registry, value):
        binding = _find_binding(value, conversation_id, harness_id)
        if binding is None:
            value["audit_log"].append(_audit_event(None, "unbind", "failed", "binding-not-found"))
            error = CkbError(
                f"management conversation binding does not exist: harness={harness_id}; conversation={conversation_id}"
            )
        elif binding["status"] == "unbound":
            result = {
                "schema_version": MANAGEMENT_SCHEMA_VERSION,
                "status": "already-unbound",
                "registry": str(registry),
                "binding": binding,
            }
        else:
            stamp = utc_now()
            binding.update({"status": "unbound", "updated_at_utc": stamp, "unbound_at_utc": stamp})
            value["audit_log"].append(_audit_event(binding["binding_id"], "unbind", "passed", "deactivated"))
            result = {
                "schema_version": MANAGEMENT_SCHEMA_VERSION,
                "status": "unbound",
                "registry": str(registry),
                "binding": binding,
            }
    if error is not None:
        raise error
    assert result is not None
    binding_value = result["binding"]
    result["session_stdio"] = close_session(
        harness=str(binding_value["harness_id"]),
        session_id=str(binding_value["conversation_id"]),
        output=Path(binding_value["knowledge_base"]),
        reason="management-unbind",
    )
    return result


def _sqlite_integrity(path: Path) -> str:
    if not path.is_file():
        return "missing"
    try:
        connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        try:
            row = connection.execute("PRAGMA integrity_check").fetchone()
            return str(row[0]) if row else "missing-result"
        finally:
            connection.close()
    except sqlite3.Error as exc:
        return f"error:{type(exc).__name__}"


def _feedback_snapshot(output: Path) -> dict[str, Any]:
    root = output / "workspace-meta/feedback/open"
    severities = {name: 0 for name in ("error", "warn", "suggest", "info")}
    invalid = 0
    records = []
    if root.is_dir():
        for path in sorted(root.glob("*.json")):
            try:
                item = json_load(path)
            except Exception:
                invalid += 1
                continue
            severity = str(item.get("severity", ""))
            if severity in severities:
                severities[severity] += 1
            else:
                invalid += 1
            records.append({"id": item.get("id"), "severity": severity, "target": item.get("target")})
    return {"count": len(records), "severities": severities, "invalid": invalid, "records": records[:20]}


def _knowledge_snapshot(output: Path, question: str) -> dict[str, Any]:
    from .llm_wiki_capabilities import compact_agent_brief, maintenance_check
    from .machine_knowledge import retrieve_machine
    from .research_gaps import list_gaps

    snapshot: dict[str, Any] = {
        "output_exists": output.is_dir(),
        "state_exists": (output / "state.json").is_file(),
        "machine_integrity": _sqlite_integrity(output / "machine/knowledge.sqlite"),
        "agent_index_integrity": _sqlite_integrity(output / "agent-index.sqlite"),
        "open_feedback": _feedback_snapshot(output),
        "open_gaps": {"status": "unavailable", "count": None},
        "brief": {"status": "unavailable", "reason": "machine-knowledge-missing"},
        "maintenance": {"status": "unavailable", "failed_checks": ["knowledge-base-missing"]},
    }
    if not snapshot["state_exists"]:
        return snapshot
    try:
        snapshot["open_gaps"] = list_gaps(output, "open")
    except Exception as exc:
        snapshot["open_gaps"] = {"status": "failed", "count": None, "error": type(exc).__name__}
    if snapshot["machine_integrity"] == "ok":
        try:
            retrieval = retrieve_machine(output, question, 1800, 8, "fast")
            snapshot["brief"] = compact_agent_brief(output, retrieval)
        except Exception as exc:
            snapshot["brief"] = {"status": "failed", "error": type(exc).__name__, "detail": str(exc)[:500]}
    try:
        snapshot["maintenance"] = maintenance_check(output)
    except Exception as exc:
        snapshot["maintenance"] = {
            "status": "failed",
            "failed_checks": ["maintenance-exception"],
            "error": type(exc).__name__,
            "detail": str(exc)[:500],
        }
    return snapshot


def _single_quote(value: str) -> str:
    return value.replace("'", "''")


def _manager_commands(binding: dict[str, Any], python: Path, ckb: Path, registry: Path) -> dict[str, str]:
    prefix = f"& '{_single_quote(str(python))}' '{_single_quote(str(ckb))}'"
    output = _single_quote(binding["knowledge_base"])
    identity = (
        f"--conversation-id '{_single_quote(binding['conversation_id'])}' "
        f"--harness '{_single_quote(binding['harness_id'])}' --registry '{_single_quote(str(registry))}'"
    )
    return {
        "brief": f"{prefix} brief --out '{output}' 'QUESTION' --budget 1800 --max-pages 8 --profile fast",
        "feedback_list": f"{prefix} feedback list --out '{output}' --status open",
        "gaps_list": f"{prefix} gaps list --out '{output}' --status open",
        "record": f"{prefix} record --out '{output}' --kind analysis --title 'TITLE' --body 'BODY.md' --from-pack 'PACK.json'",
        "reference_list": f"{prefix} reference list --out '{output}' --status all",
        "maintain": f"{prefix} maintain --out '{output}'",
        "manager_status": f"{prefix} manager status {identity}",
        "manager_context": f"{prefix} manager context {identity} --question 'QUESTION'",
        "manager_audit": f"{prefix} manager audit --registry '{_single_quote(str(registry))}'",
    }


def _management_prompt(
    binding: dict[str, Any],
    runtime: dict[str, Any],
    knowledge: dict[str, Any],
    commands: dict[str, str],
    blockers: list[str],
) -> str:
    feedback = knowledge["open_feedback"]
    gaps = knowledge["open_gaps"]
    maintenance = knowledge["maintenance"]
    blocker_lines = [f"- `{item}`" for item in blockers] or ["- 当前没有阻断项。"]
    return f"""# CKB 管理 Agent 完整上下文

## 当前绑定

- binding：`{binding['binding_id']}`
- Harness / conversation：`{binding['harness_id']}` / `{binding['conversation_id']}`
- workspace：`{binding['workspace_root']}`
- repo：`{binding['repo_root']}`
- knowledge base：`{binding['knowledge_base']}`
- integration branch：`{binding['integration_branch']}`
- bound HEAD：`{binding['bound_head']}`
- current integration HEAD：`{runtime.get('integration_head')}`
- HEAD drift：`{runtime.get('head_drift')}`
- integration worktree clean：`{runtime.get('clean')}`

## 当前管理门

- open feedback：{feedback['count']}，其中 error={feedback['severities']['error']}、warn={feedback['severities']['warn']}
- open research gaps：{gaps.get('count')}
- machine SQLite：`{knowledge['machine_integrity']}`
- agent-index SQLite：`{knowledge['agent_index_integrity']}`
- maintain：`{maintenance.get('status')}`，failed_checks={maintenance.get('failed_checks', [])}

阻断项：
{chr(10).join(blocker_lines)}

## 固定读取和维护入口

1. 每次新问题先执行 `brief --profile fast`，打开返回的 pack，再按 pack 使用 `entity`、`neighbors`、`source` 或 `changes`；复杂跨模块问题才用 `precise`。
2. 反馈、参考资料、研究缺口和工作记录继续使用既有单一状态机，不在管理注册表中复制正文或事实。
3. `human/pages`、`markdown/pages`、`human/references`、`markdown/references`、导航、投影清单和 SQLite 由生成器管理，不直接编辑。
4. 分析、修改原因、踩坑和实验只通过 `record` 写入简体中文正文，并从 pack/query 或唯一知识页建立来源链接。

```powershell
{commands['brief']}
{commands['feedback_list']}
{commands['gaps_list']}
{commands['reference_list']}
{commands['record']}
{commands['maintain']}
```

## 开发分支、审阅和合并门

1. 派发开发任务前重新执行 manager status/context；integration branch 必须仍在 bound HEAD、工作树干净且 maintain 通过。
2. 每项开发任务使用固定 bound HEAD 创建独立 branch/worktree；交接 Prompt 必须列出允许/禁止路径、测试、分批 commit 和结构化返回格式。
3. 开发任务不得自行合并或同步稳定知识库。审阅时重新打开 diff，验证开发 worktree 干净、提交可追溯、测试在最终 HEAD 运行且全部通过。
4. 只有明确收到合并指令且所有门通过时才进入合并；合并后必须在 integration branch 重新运行受影响测试，再以最小范围同步稳定知识库并重新执行 maintain，不能复用开发分支的旧测试或旧审计。

## Harness 能力边界

`binding`、`prompt_injection`、`event_sync`、`task_dispatch` 是四项独立能力。当前声明为：

```json
{json.dumps(binding['capabilities'], ensure_ascii=False, indent=2)}
```

`prompt_injection.available=false` 表示本上下文可由 CLI 获取并交给 Harness，但没有本地适配器自动注入；不得将其描述为自动注入。

## 结构化交接返回

最终交接固定列出：branch、base_commit、final_head、worktree clean；commit 表；base..HEAD diff stat 与逐文件用途；literal 测试命令/输出/退出状态；已确认行为、推断、未验证项；知识库影响；逐 commit revert、绑定备份/恢复和 unbind 回滚。不得把 Prompt、assistant 原文、secret、token 或 transcript path 写入管理注册表。
"""


def audit_management_prompt(
    prompt: str,
    binding: dict[str, Any],
    runtime: dict[str, Any],
    commands: dict[str, str],
) -> dict[str, Any]:
    required_fragments = [
        binding["binding_id"],
        binding["workspace_root"],
        binding["repo_root"],
        binding["knowledge_base"],
        binding["integration_branch"],
        binding["bound_head"],
        str(runtime.get("integration_head")),
        "brief --out",
        "feedback list",
        "gaps list",
        "reference list",
        "record --out",
        "maintain --out",
        "prompt_injection",
        "task_dispatch",
        "不得自行合并",
        "结构化交接返回",
    ]
    errors = [f"missing prompt fragment: {fragment}" for fragment in required_fragments if fragment not in prompt]
    for name, command in commands.items():
        if command not in prompt and name not in {"manager_status", "manager_context", "manager_audit"}:
            errors.append(f"missing command in management prompt: {name}")
    if len(re.findall(r"[\u4e00-\u9fff]", prompt)) < 80:
        errors.append("management prompt lacks Simplified-Chinese narrative")
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "prompt_version": MANAGEMENT_PROMPT_VERSION,
        "required_fragment_count": len(required_fragments),
        "errors": errors,
    }


def management_context(
    conversation_id: str,
    harness_id: str,
    question: str,
    registry_path: Path | None = None,
    *,
    python: Path | None = None,
    ckb: Path | None = None,
) -> dict[str, Any]:
    status = binding_status(conversation_id, harness_id, registry_path)
    binding = status["binding"]
    registry = Path(status["registry"])
    output = Path(binding["knowledge_base"])
    knowledge = _knowledge_snapshot(output, question.strip() or "管理当前 Code Knowledge Builder 项目")
    blockers = list(status["blockers"])
    if knowledge["machine_integrity"] != "ok":
        blockers.append("machine-knowledge-integrity")
    if knowledge["agent_index_integrity"] != "ok":
        blockers.append("agent-index-integrity")
    if knowledge["open_feedback"]["severities"]["error"]:
        blockers.append("open-error-feedback")
    if knowledge["open_feedback"]["invalid"]:
        blockers.append("invalid-feedback-record")
    if knowledge["maintenance"].get("status") != "passed":
        blockers.append("maintenance-failed")
    blockers = list(dict.fromkeys(blockers))
    python_path = (python or Path(sys.executable)).expanduser().resolve()
    ckb_path = (ckb or (Path(__file__).resolve().parents[1] / "ckb.py")).expanduser().resolve()
    commands = _manager_commands(binding, python_path, ckb_path, registry)
    prompt = _management_prompt(binding, status["runtime"], knowledge, commands, blockers)
    prompt_audit = audit_management_prompt(prompt, binding, status["runtime"], commands)
    if prompt_audit["status"] != "passed":
        blockers.append("management-prompt-audit-failed")
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "status": "ready" if not blockers else "blocked",
        "registry": str(registry),
        "binding": binding,
        "runtime": status["runtime"],
        "knowledge": knowledge,
        "blockers": blockers,
        "commands": commands,
        "prompt_audit": prompt_audit,
        "prompt_version": MANAGEMENT_PROMPT_VERSION,
        "prompt_sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
        "prompt": prompt,
    }


def _task_id(binding_id: str, task_id: str) -> str:
    return stable_id("manager-task", binding_id, task_id)


def _task_artifact_root(registry: Path) -> Path:
    return registry.parent / f"{registry.stem}-artifacts"


def _find_task(value: dict[str, Any], dispatch_id: str) -> dict[str, Any] | None:
    return next((item for item in value["tasks"] if item.get("dispatch_id") == dispatch_id), None)


def _bounded_values(values: list[str] | None, field: str, *, required: bool = False) -> list[str]:
    result = []
    for raw in values or []:
        text = str(raw).strip()
        if not text or len(text) > 2_000 or "\x00" in text or "\n" in text or "\r" in text:
            raise CkbError(f"management task {field} values must be nonempty bounded single-line text")
        result.append(text)
    result = list(dict.fromkeys(result))
    if required and not result:
        raise CkbError(f"management task requires at least one {field} value")
    return result


def _task_prompt(binding: dict[str, Any], task: dict[str, Any]) -> str:
    allowed = "\n".join(f"- `{item}`" for item in task["allowed_paths"]) or "- 只修改目标成立所需的最小路径。"
    forbidden = "\n".join(f"- `{item}`" for item in task["forbidden_paths"]) or "- 不进入 integration worktree 或稳定知识库。"
    tests = "\n".join(f"- `{item}`" for item in task["tests"])
    return f"""# CKB 独立开发任务交接

## 固定身份

- binding：`{binding['binding_id']}`
- task：`{task['task_id']}`
- integration branch：`{binding['integration_branch']}`
- base commit：`{task['base_commit']}`
- development branch：`{task['branch']}`
- independent worktree：`{task['worktree']}`
- workspace：`{binding['workspace_root']}`
- repository：`{binding['repo_root']}`
- knowledge base（只读）：`{binding['knowledge_base']}`

开始前必须确认 development branch、HEAD=`{task['base_commit']}` 和工作树干净。先执行 CKB `brief --profile fast` 并打开 Agent pack；不得进入 integration worktree，不得自行合并，不得同步稳定知识库。

## 允许路径

{allowed}

## 禁止路径

{forbidden}

## 验证命令

{tests}

## 提交与完成门

1. 按职责分批 commit，禁止 squash；每批只包含对应职责的实现与验证。
2. 覆盖正常行为、输入失败、dirty integration tree、HEAD drift、并发、幂等和隐私负例；静态检查或 Prompt 生成不等于目标行为通过。
3. 在 development branch 最终 HEAD 重新执行全部列出的验证命令，保持 worktree 干净，再交给管理 Agent 运行 `manager task-review`。
4. 返回时不得自行 merge。管理 Agent 只有在 integration HEAD 仍等于 base commit、integration tree 干净、最终测试记录通过且用户明确要求时才进入合并。

## 结构化返回格式

1. branch、base_commit、final_head、worktree clean；
2. commit 表：哈希、标题、文件范围、单批次验证；
3. `git diff {task['base_commit']}...HEAD --stat` 和逐文件用途；
4. canonical schema、关键状态转换与能力边界；
5. literal 命令、输入、输出和退出状态；
6. 正例、负例、并发测试数与结果；
7. 已确认行为、推断、尚未验证项；
8. 知识库影响和合并后最小同步建议；
9. 逐 commit revert、状态数据备份/恢复和解绑回滚；
10. 明确说明没有自行合并、没有修改或同步稳定知识库。
"""


def create_management_task(
    conversation_id: str,
    harness_id: str,
    task_id: str,
    branch: str,
    worktree: Path,
    registry_path: Path | None = None,
    *,
    allowed_paths: list[str] | None = None,
    forbidden_paths: list[str] | None = None,
    tests: list[str] | None = None,
    python: Path | None = None,
    ckb: Path | None = None,
) -> dict[str, Any]:
    task_identity = task_id.strip()
    if not _OPAQUE_ID.fullmatch(task_identity):
        raise CkbError("management task_id must be bounded opaque text")
    branch = branch.strip()
    allowed = _bounded_values(allowed_paths, "allowed_paths")
    forbidden = _bounded_values(forbidden_paths, "forbidden_paths")
    test_commands = _bounded_values(tests, "tests", required=True)
    context = management_context(
        conversation_id,
        harness_id,
        f"派发开发任务 {task_identity}",
        registry_path,
        python=python,
        ckb=ckb,
    )
    if context["status"] != "ready":
        raise CkbError(f"management task dispatch is blocked: {context['blockers']}")
    binding = context["binding"]
    repo = Path(binding["repo_root"])
    workspace = Path(binding["workspace_root"])
    worktree = worktree.expanduser().resolve()
    if worktree == repo or _is_within(worktree, repo):
        raise CkbError("management task worktree must be independent from the integration repository")
    if not _is_within(worktree, workspace):
        raise CkbError(f"management task worktree must stay inside workspace_root: {workspace}")
    check_ref = run(["git", "-C", str(repo), "check-ref-format", "--branch", branch], timeout=30)
    if check_ref.returncode:
        detail = (check_ref.stderr or check_ref.stdout).strip()
        raise CkbError(f"invalid management task branch: {branch}: {detail}")
    registry = (registry_path or default_management_registry_path()).expanduser().resolve()
    dispatch_id = _task_id(binding["binding_id"], task_identity)
    result: dict[str, Any] | None = None
    error: CkbError | None = None
    created_worktree = False
    created_branch = False
    prompt_path: Path | None = None
    with _locked_registry(registry) as (locked_path, value):
        existing = _find_task(value, dispatch_id)
        try:
            if existing:
                expected = {
                    "branch": branch,
                    "worktree": str(worktree),
                    "allowed_paths": allowed,
                    "forbidden_paths": forbidden,
                    "tests": test_commands,
                }
                conflicts = [field for field, expected_value in expected.items() if existing.get(field) != expected_value]
                if conflicts:
                    raise CkbError(f"management task conflicts with existing dispatch fields: {conflicts}")
                result = {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    "status": "already-created",
                    "registry": str(locked_path),
                    "task": existing,
                }
            else:
                # Binding/context was checked immediately before taking the
                # lock; recheck the two Git invariants that protect creation.
                runtime = _runtime_state(binding)
                if runtime["errors"]:
                    raise CkbError(f"management task dispatch Git gate failed: {runtime['errors']}")
                if worktree.exists():
                    raise CkbError(f"management task worktree already exists: {worktree}")
                if _git(repo, "show-ref", "--verify", f"refs/heads/{branch}", allow_failure=True):
                    raise CkbError(f"management task branch already exists: {branch}")
                add = run(
                    ["git", "-C", str(repo), "worktree", "add", "-b", branch, str(worktree), binding["bound_head"]],
                    timeout=120,
                )
                if add.returncode:
                    detail = (add.stderr or add.stdout).strip()
                    raise CkbError(f"management task worktree creation failed: {detail}")
                created_worktree = True
                created_branch = True
                stamp = utc_now()
                task = {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    "dispatch_id": dispatch_id,
                    "binding_id": binding["binding_id"],
                    "task_id": task_identity,
                    "status": "created",
                    "base_commit": binding["bound_head"],
                    "branch": branch,
                    "worktree": str(worktree),
                    "allowed_paths": allowed,
                    "forbidden_paths": forbidden,
                    "tests": test_commands,
                    "created_at_utc": stamp,
                    "updated_at_utc": stamp,
                    "prompt_path": None,
                    "prompt_sha256": None,
                    "verification_path": None,
                    "verification_sha256": None,
                }
                prompt = _task_prompt(binding, task)
                prompt_path = _task_artifact_root(locked_path) / "prompts" / f"{dispatch_id}.md"
                prompt_path.parent.mkdir(parents=True, exist_ok=True)
                if prompt_path.exists():
                    raise CkbError(f"management task prompt already exists without registry state: {prompt_path}")
                prompt_path.write_text(prompt, encoding="utf-8", newline="\n")
                task["prompt_path"] = str(prompt_path.resolve())
                task["prompt_sha256"] = hashlib.sha256(prompt_path.read_bytes()).hexdigest()
                value["tasks"].append(task)
                value["tasks"].sort(key=lambda item: item["dispatch_id"])
                value["audit_log"].append(_audit_event(binding["binding_id"], "task-create", "passed", dispatch_id))
                result = {
                    "schema_version": MANAGEMENT_SCHEMA_VERSION,
                    "status": "created",
                    "registry": str(locked_path),
                    "task": task,
                    "prompt": prompt,
                }
        except CkbError as exc:
            value["audit_log"].append(_audit_event(binding["binding_id"], "task-create", "failed", type(exc).__name__))
            error = exc
    if error is not None:
        if prompt_path is not None:
            prompt_path.unlink(missing_ok=True)
        if created_worktree:
            run(["git", "-C", str(repo), "worktree", "remove", "--force", str(worktree)], timeout=120)
        if created_branch:
            run(["git", "-C", str(repo), "branch", "-D", branch], timeout=60)
        raise error
    assert result is not None
    return result


def management_task_status(dispatch_id: str, registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_management_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    task = _find_task(value, dispatch_id)
    if task is None:
        raise CkbError(f"management task does not exist: {dispatch_id}")
    binding = next((item for item in value["bindings"] if item.get("binding_id") == task["binding_id"]), None)
    if binding is None:
        raise CkbError(f"management task binding does not exist: {task['binding_id']}")
    binding_runtime = _runtime_state(binding)
    worktree = Path(task["worktree"])
    development: dict[str, Any] = {
        "worktree_exists": worktree.is_dir(),
        "branch": None,
        "head": None,
        "clean": None,
        "dirty_paths": [],
        "base_is_ancestor": False,
        "commit_count": 0,
        "prompt_verified": False,
        "verification_verified": False,
        "errors": [],
    }
    prompt_path = Path(task["prompt_path"])
    development["prompt_verified"] = (
        prompt_path.is_file() and hashlib.sha256(prompt_path.read_bytes()).hexdigest() == task["prompt_sha256"]
    )
    if not development["prompt_verified"]:
        development["errors"].append("task-prompt-drift")
    if not worktree.is_dir():
        development["errors"].append("task-worktree-missing")
    else:
        development["branch"] = _git(worktree, "symbolic-ref", "--quiet", "--short", "HEAD", allow_failure=True)
        development["head"] = _git(worktree, "rev-parse", "--verify", "HEAD", allow_failure=True)
        dirty = (_git(worktree, "status", "--porcelain=v1", "--untracked-files=all", allow_failure=True) or "").splitlines()
        development["dirty_paths"] = dirty[:100]
        development["clean"] = not dirty
        if development["branch"] != task["branch"]:
            development["errors"].append("task-branch-mismatch")
        if development["head"]:
            ancestor = run(
                ["git", "-C", str(worktree), "merge-base", "--is-ancestor", task["base_commit"], development["head"]],
                timeout=30,
            )
            development["base_is_ancestor"] = ancestor.returncode == 0
            count = _git(worktree, "rev-list", "--count", f"{task['base_commit']}..{development['head']}", allow_failure=True)
            development["commit_count"] = int(count) if count and count.isdigit() else 0
        if not development["base_is_ancestor"]:
            development["errors"].append("task-history-diverged")
        if not development["clean"]:
            development["errors"].append("task-worktree-dirty")
        if development["commit_count"] < 1:
            development["errors"].append("task-has-no-commits")
    verification_path = Path(task["verification_path"]) if task.get("verification_path") else None
    if verification_path and verification_path.is_file():
        actual_hash = hashlib.sha256(verification_path.read_bytes()).hexdigest()
        try:
            verification = json_load(verification_path)
        except Exception:
            verification = {}
        development["verification_verified"] = bool(
            actual_hash == task.get("verification_sha256")
            and verification.get("status") == "passed"
            and verification.get("development_head") == development["head"]
            and verification.get("integration_head") == binding["bound_head"]
            and verification.get("tests") == task["tests"]
        )
    if task["status"] == "review-passed" and not development["verification_verified"]:
        development["errors"].append("task-verification-stale")
    blockers = ([] if binding["status"] == "active" else ["binding-unbound"]) + binding_runtime["errors"] + development["errors"]
    merge_ready = not blockers and development["verification_verified"]
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "status": "merge-ready" if merge_ready else "blocked",
        "registry": str(registry),
        "binding": binding,
        "task": task,
        "integration": binding_runtime,
        "development": development,
        "blockers": blockers,
        "merge_performed": False,
    }


def review_management_task(dispatch_id: str, registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_management_registry_path()).expanduser().resolve()
    task_lock = _task_artifact_root(registry) / "locks" / dispatch_id
    with _registry_lock(task_lock, timeout=300.0):
        before = management_task_status(dispatch_id, registry)
        if before["status"] == "merge-ready":
            task = before["task"]
            verification_path = Path(task["verification_path"])
            return {
                "schema_version": MANAGEMENT_SCHEMA_VERSION,
                "status": "passed",
                "registry": str(registry),
                "verification": json_load(verification_path),
                "verification_path": str(verification_path),
                "verification_sha256": task["verification_sha256"],
                "gate": before,
                "idempotent": True,
                "merge_performed": False,
            }
        allowed_pre_review = {"task-verification-stale"}
        blockers = [item for item in before["blockers"] if item not in allowed_pre_review]
        if blockers:
            raise CkbError(f"management task review is blocked: {blockers}")
        task = before["task"]
        binding = before["binding"]
        worktree = Path(task["worktree"])
        initial_head = before["development"]["head"]
        results = []
        passed = True
        for command in task["tests"]:
            completed = subprocess.run(
                command,
                cwd=str(worktree),
                shell=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
            )
            results.append(
                {
                    "command": command,
                    "exit_status": completed.returncode,
                    "stdout": completed.stdout[-12_000:],
                    "stderr": completed.stderr[-12_000:],
                }
            )
            if completed.returncode:
                passed = False
        final_head = _git(worktree, "rev-parse", "--verify", "HEAD", allow_failure=True)
        final_dirty = (_git(worktree, "status", "--porcelain=v1", "--untracked-files=all", allow_failure=True) or "").splitlines()
        integration_head = _git(Path(binding["repo_root"]), "rev-parse", "--verify", f"refs/heads/{binding['integration_branch']}^{{commit}}", allow_failure=True)
        if final_head != initial_head or final_dirty or integration_head != binding["bound_head"]:
            passed = False
        verification = {
            "schema_version": MANAGEMENT_SCHEMA_VERSION,
            "status": "passed" if passed else "failed",
            "dispatch_id": dispatch_id,
            "base_commit": task["base_commit"],
            "development_head": final_head,
            "integration_head": integration_head,
            "worktree_clean": not final_dirty,
            "tests": task["tests"],
            "results": results,
            "verified_at_utc": utc_now(),
        }
        verification_path = _task_artifact_root(registry) / "verifications" / f"{dispatch_id}.json"
        json_write(verification_path, verification)
        verification_hash = hashlib.sha256(verification_path.read_bytes()).hexdigest()
        with _locked_registry(registry) as (_locked, value):
            current = _find_task(value, dispatch_id)
            if current is None:
                raise CkbError(f"management task disappeared during review: {dispatch_id}")
            current.update(
                {
                    "status": "review-passed" if passed else "review-failed",
                    "updated_at_utc": utc_now(),
                    "verification_path": str(verification_path.resolve()),
                    "verification_sha256": verification_hash,
                }
            )
            value["audit_log"].append(
                _audit_event(binding["binding_id"], "task-review", "passed" if passed else "failed", dispatch_id)
            )
        after = management_task_status(dispatch_id, registry)
        return {
            "schema_version": MANAGEMENT_SCHEMA_VERSION,
            "status": "passed" if after["status"] == "merge-ready" else "failed",
            "registry": str(registry),
            "verification": verification,
            "verification_path": str(verification_path.resolve()),
            "verification_sha256": verification_hash,
            "gate": after,
            "idempotent": False,
            "merge_performed": False,
        }

def audit_migration(output: Path, *, require_complete_reviews: bool = True) -> dict[str, Any]:
    output = output.resolve()
    state = json_load(output / "state.json")
    plan_path = output / "migration" / "plan.json"
    checks: list[dict[str, Any]] = []

    def check(name: str, passed: bool, detail: Any) -> None:
        checks.append({"name": name, "passed": bool(passed), "detail": detail})

    check("migration-plan-present", plan_path.is_file(), str(plan_path))
    if not plan_path.is_file():
        result = {"schema_version": MIGRATION_SCHEMA_VERSION, "status": "failed", "checks": checks, "audited_at_utc": utc_now()}
        json_write(output / "migration" / "audit.json", result)
        return result
    plan = json_load(plan_path)
    migration = state.get("migration") or {}
    check("target-version-current", state.get("version") == VERSION and migration.get("target_version") == VERSION, {"state": state.get("version"), "target": migration.get("target_version")})
    check("target-commit-pinned", state.get("repository", {}).get("commit") == plan.get("target", {}).get("commit"), state.get("repository", {}).get("commit"))
    catalog = json_load(output / "catalog.json")
    reused_paths = set(plan.get("files", {}).get("reused", []))
    catalog_reused = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
    check("exact-blob-reuse-set", reused_paths == catalog_reused, {"missing": sorted(reused_paths - catalog_reused), "extra": sorted(catalog_reused - reused_paths)})
    reused_records = {
        item["file"]["path"]: item
        for item in catalog.get("files", [])
        if item["file"]["path"] in reused_paths
    }
    reuse_errors = [
        path
        for path in sorted(reused_paths)
        if path not in reused_records or not reused_records[path].get("migration_reuse")
    ]
    check("reused-files-carry-rekey-proof", not reuse_errors, reuse_errors)
    mutable_errors: list[dict[str, Any]] = []
    for item in plan.get("mutable_files", []):
        relative_target = str(item.get("relative_target") or "")
        baseline_relative = str(item.get("baseline_relative_target") or "")
        try:
            target = _mutable_target(output, relative_target)
            baseline = _mutable_target(output, baseline_relative)
        except CkbError as exc:
            mutable_errors.append({"path": relative_target, "reason": str(exc)})
            continue
        expected_baseline = item.get("baseline_sha256")
        if not baseline.is_file() or not expected_baseline or sha256_file(baseline) != expected_baseline:
            mutable_errors.append({"path": relative_target, "reason": "preserved-baseline-missing-or-changed"})
            continue
        if not target.is_file():
            mutable_errors.append({"path": relative_target, "reason": "live-mutable-file-missing"})
            continue
        try:
            suffix = target.suffix.casefold()
            if suffix == ".json":
                json_load(target)
            elif suffix == ".md":
                target.read_text(encoding="utf-8")
            elif suffix in {".sqlite", ".db"}:
                connection = sqlite3.connect(f"file:{target.as_posix()}?mode=ro", uri=True)
                try:
                    integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
                finally:
                    connection.close()
                if integrity != "ok":
                    raise CkbError(f"SQLite integrity_check returned {integrity}")
            else:
                target.read_bytes()
        except (CkbError, OSError, UnicodeError, json.JSONDecodeError, sqlite3.Error) as exc:
            mutable_errors.append({"path": relative_target, "reason": "live-mutable-file-invalid", "detail": str(exc)})
    check("mutable-layers-preserved", not mutable_errors, mutable_errors)
    review_status = {pack["id"]: pack.get("status") for pack in state.get("review_packs", [])}
    reviews_complete = bool(review_status) and all(value == "passed" for value in review_status.values())
    check("migration-review-state", reviews_complete if require_complete_reviews else True, review_status)
    graph_path = output / "graph.json"
    graph_errors: list[Any] = []
    if graph_path.is_file():
        graph = json_load(graph_path)
        target_commit = state["repository"]["commit"]
        id_map = plan.get("entities", {}).get("old_to_new_id_map", {})
        # A CKB-version-only migration may retain the same fixed Git commit.
        # In that case commit-sensitive IDs are intentionally identical and
        # are not obsolete IDs.  Only mappings whose target actually changed
        # may be treated as forbidden old-ID residue.
        old_ids = {old for old, new in id_map.items() if old != new}
        new_ids = {entity["id"] for entity in graph.get("entities", [])}
        if old_ids & new_ids:
            graph_errors.append({"reason": "old-entity-id-remains", "ids": sorted(old_ids & new_ids)[:20]})
        wrong_commit = [entity["id"] for entity in graph.get("entities", []) if entity.get("commit") != target_commit]
        if wrong_commit:
            graph_errors.append({"reason": "entity-commit-mismatch", "ids": wrong_commit[:20]})
    elif require_complete_reviews:
        graph_errors.append({"reason": "graph-not-merged"})
    check("target-graph-has-only-new-provenance", not graph_errors, graph_errors)
    all_checks_passed = all(item["passed"] for item in checks)
    if all_checks_passed and reviews_complete:
        status = "passed"
    elif all_checks_passed and not require_complete_reviews:
        status = "pending-agent-review"
    else:
        status = "failed"
    result = {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": status,
        "checks": checks,
        "counts": {"passed": sum(item["passed"] for item in checks), "total": len(checks)},
        "audited_at_utc": utc_now(),
    }
    if status == "passed":
        plan["status"] = "passed"
        json_write(plan_path, plan)
        state["migration"] = {**migration, "status": "passed", "audited_at_utc": result["audited_at_utc"]}
        json_write(output / "state.json", state)
    json_write(output / "migration" / "audit.json", result)
    return result

"""Bounded, privacy-filtered machine operation journal for completed CKB commands."""

from __future__ import annotations

from collections import Counter
from contextlib import contextmanager
from datetime import date, timedelta
import json
import os
from pathlib import Path, PurePosixPath
import re
import time
from typing import Any, Iterator

from .common import CkbError, json_load, json_write, path_inside, stable_id, utc_now


OPERATION_JOURNAL_SCHEMA_VERSION = 1
OPERATION_TYPES = ("compile", "query", "record", "audit", "maintenance")
MAX_RECORDS_PER_SHARD = 2_000
MAX_SHARD_BYTES = 1_048_576
RETENTION_DAYS = 30
LATEST_EVENT_LIMIT = 20
_EVENT_FIELDS = {
    "schema_version",
    "event_id",
    "recorded_at_utc",
    "operation",
    "command",
    "result_status",
    "evidence_paths",
}
_SAFE_TOKEN = re.compile(r"^[a-z0-9][a-z0-9:._-]{0,79}$")
_SHARD_NAME = re.compile(r"^(\d{4}-\d{2}-\d{2})\.jsonl$")
_EVIDENCE_KEYS = {
    "audit",
    "compatibility_file",
    "file",
    "human_file",
    "manifest",
    "pack",
    "path",
    "record",
    "report",
    "review_template",
    "source",
}


def _root(output: Path) -> Path:
    return output.resolve() / "workspace-meta/operations"


@contextmanager
def _journal_lock(root: Path) -> Iterator[None]:
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + 5.0
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, str(os.getpid()).encode("ascii"))
        except FileExistsError:
            try:
                if time.time() - lock.stat().st_mtime > 30:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"operation journal is busy: {lock}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)


def _read_shard(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    if not path.is_file():
        return records
    for line_number, line in enumerate(path.read_text(encoding="utf-8-sig").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise CkbError(f"invalid operation journal JSONL at {path}:{line_number}: {exc}") from exc
        if not isinstance(value, dict):
            raise CkbError(f"operation journal record must be an object: {path}:{line_number}")
        records.append(value)
    return records


def _serialized_lines(records: list[dict[str, Any]]) -> bytes:
    return ("".join(json.dumps(item, ensure_ascii=False, separators=(",", ":")) + "\n" for item in records)).encode("utf-8")


def _write_shard(path: Path, records: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_bytes(_serialized_lines(records))
    os.replace(temporary, path)


def _state(root: Path) -> dict[str, Any]:
    path = root / "state.json"
    if not path.is_file():
        return {
            "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
            "dropped_records": 0,
            "expired_records": 0,
            "deduplicated_records": 0,
        }
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"operation journal state must be an object: {path}")
    return value


def _retention_cutoff(today: date) -> date:
    return today - timedelta(days=RETENTION_DAYS - 1)


def _prune_expired(root: Path, today: date, state: dict[str, Any]) -> None:
    cutoff = _retention_cutoff(today)
    for path in sorted(root.glob("*.jsonl")):
        matched = _SHARD_NAME.fullmatch(path.name)
        if not matched:
            continue
        shard_date = date.fromisoformat(matched.group(1))
        if shard_date >= cutoff:
            continue
        state["expired_records"] = int(state.get("expired_records", 0)) + len(_read_shard(path))
        path.unlink()


def _all_events(root: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for path in sorted(root.glob("*.jsonl")):
        if _SHARD_NAME.fullmatch(path.name):
            events.extend(_read_shard(path))
    return events


def _latest_summary(root: Path, events: list[dict[str, Any]], state: dict[str, Any]) -> dict[str, Any]:
    shards = []
    for path in sorted(root.glob("*.jsonl")):
        matched = _SHARD_NAME.fullmatch(path.name)
        if not matched:
            continue
        shard_events = _read_shard(path)
        shards.append(
            {
                "date": matched.group(1),
                "path": path.name,
                "records": len(shard_events),
                "bytes": path.stat().st_size,
            }
        )
    by_operation = Counter(str(item.get("operation")) for item in events)
    by_status = Counter(str(item.get("result_status")) for item in events)
    return {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "status": "passed",
        "updated_at_utc": utc_now(),
        "retention_days": RETENTION_DAYS,
        "max_records_per_shard": MAX_RECORDS_PER_SHARD,
        "max_shard_bytes": MAX_SHARD_BYTES,
        "records": len(events),
        "counts_by_operation": {name: by_operation.get(name, 0) for name in OPERATION_TYPES},
        "counts_by_status": dict(sorted(by_status.items())),
        "shards": shards,
        "latest": events[-LATEST_EVENT_LIMIT:],
        "bounded_drops": {
            "size_or_count": int(state.get("dropped_records", 0)),
            "retention": int(state.get("expired_records", 0)),
            "deduplicated": int(state.get("deduplicated_records", 0)),
        },
    }


def _relative_evidence(output: Path, result: dict[str, Any]) -> list[str]:
    evidence: set[str] = set()
    for key in sorted(_EVIDENCE_KEYS):
        value = result.get(key)
        values = value if isinstance(value, list) else [value]
        for candidate in values:
            if not isinstance(candidate, str) or not candidate.strip():
                continue
            path = Path(candidate)
            if not path.is_absolute():
                path = output / path
            try:
                resolved = path.resolve()
            except OSError:
                continue
            if not resolved.exists() or not path_inside(resolved, output):
                continue
            evidence.add(resolved.relative_to(output).as_posix())
    return sorted(evidence)[:8]


def _command_name(args: Any) -> str:
    command = str(getattr(args, "command", "")).strip().lower()
    nested_fields = (
        "migration_command",
        "reference_command",
        "feedback_command",
        "workspace_command",
        "agent_policy_command",
        "automation_command",
        "gaps_command",
    )
    for field in nested_fields:
        value = getattr(args, field, None)
        if value:
            return f"{command}:{str(value).strip().lower()}"
    if command == "audit":
        return "audit:global" if getattr(args, "global_audit", False) else "audit:chunk"
    if command == "record":
        kind = str(getattr(args, "kind", "")).strip().lower()
        return f"record:{kind}" if kind else command
    return command


def _operation_type(command: str) -> str | None:
    root = command.split(":", 1)[0]
    if root in {"init", "run", "build-chunk", "review-chunk", "review-pack", "merge", "finalize", "human-refresh", "reindex", "migrate", "relink"}:
        return "compile"
    if root in {"query", "retrieve", "brief", "keyword-benchmark", "context", "coverage", "entity", "neighbors", "source", "changes", "path", "explain", "status"}:
        return "query"
    if root == "maintain":
        return "maintenance"
    if command == "gaps:list":
        return "query"
    if command == "gaps:audit":
        return "audit"
    if command in {"gaps:create", "gaps:resolve"}:
        return "record"
    if root == "audit" or command in {"reference:audit", "feedback:audit", "agent-policy:check", "migrate:audit"}:
        return "audit"
    if root == "record" or command in {
        "reference:ingest",
        "reference:review",
        "reference:rollback",
        "feedback:create",
        "feedback:resolve",
        "workspace:session-start",
        "workspace:session-finish",
        "automation:review",
    }:
        return "record"
    return None


def record_operation(output: Path, operation: str, command: str, result_status: str, evidence_paths: list[str]) -> dict[str, Any]:
    output = output.resolve()
    if operation not in OPERATION_TYPES:
        raise CkbError(f"unsupported operation journal type: {operation}")
    command = command.strip().lower()
    result_status = result_status.strip().lower() or "completed"
    if not _SAFE_TOKEN.fullmatch(command) or not _SAFE_TOKEN.fullmatch(result_status):
        raise CkbError("operation journal command and status must use bounded machine tokens")
    normalized_evidence = []
    for value in sorted(set(evidence_paths))[:8]:
        path = PurePosixPath(value)
        if path.is_absolute() or ".." in path.parts or not value.strip():
            raise CkbError(f"operation evidence must be relative to OUTPUT: {value}")
        normalized_evidence.append(path.as_posix())
    stamp = utc_now()
    day = stamp[:10]
    event = {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "event_id": stable_id("operation", day, operation, command, result_status, *normalized_evidence),
        "recorded_at_utc": stamp,
        "operation": operation,
        "command": command,
        "result_status": result_status,
        "evidence_paths": normalized_evidence,
    }
    root = _root(output)
    with _journal_lock(root):
        state = _state(root)
        today = date.fromisoformat(day)
        _prune_expired(root, today, state)
        shard = root / f"{day}.jsonl"
        events = _read_shard(shard)
        if any(item.get("event_id") == event["event_id"] for item in events):
            state["deduplicated_records"] = int(state.get("deduplicated_records", 0)) + 1
            json_write(root / "state.json", state)
            all_events = _all_events(root)
            json_write(root / "latest.json", _latest_summary(root, all_events, state))
            return {"status": "passed", "event_id": event["event_id"], "idempotent": True, "journal": str(shard.resolve())}
        events.append(event)
        dropped = 0
        while len(events) > MAX_RECORDS_PER_SHARD or len(_serialized_lines(events)) > MAX_SHARD_BYTES:
            events.pop(0)
            dropped += 1
        state["dropped_records"] = int(state.get("dropped_records", 0)) + dropped
        _write_shard(shard, events)
        json_write(root / "state.json", state)
        all_events = _all_events(root)
        json_write(root / "latest.json", _latest_summary(root, all_events, state))
    return {"status": "passed", "event_id": event["event_id"], "idempotent": False, "journal": str(shard.resolve())}


def record_cli_operation(args: Any, result: Any) -> dict[str, Any] | None:
    if str(getattr(args, "command", "")) == "operations" or not isinstance(result, dict):
        return None
    output_value = getattr(args, "out", None)
    if output_value is None:
        return None
    output = Path(output_value).resolve()
    if not (output / "state.json").is_file():
        return None
    command = _command_name(args)
    operation = _operation_type(command)
    if operation is None:
        return None
    status = str(result.get("status") or "completed")
    evidence = _relative_evidence(output, result)
    return record_operation(output, operation, command, status, evidence)


def list_operations(output: Path, operation: str | None = None, result_status: str | None = None, limit: int = 50) -> dict[str, Any]:
    if operation is not None and operation not in OPERATION_TYPES:
        raise CkbError(f"unsupported operation filter: {operation}")
    if limit < 1 or limit > 500:
        raise CkbError("operation list limit must be between 1 and 500")
    events = _all_events(_root(output))
    selected = [
        item
        for item in events
        if (operation is None or item.get("operation") == operation)
        and (result_status is None or item.get("result_status") == result_status)
    ]
    return {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "status": "ready",
        "filters": {"operation": operation, "result_status": result_status},
        "count": len(selected),
        "operations": selected[-limit:][::-1],
    }


def _event_errors(item: dict[str, Any], path: Path, line_number: int) -> list[str]:
    prefix = f"{path.name}:{line_number}"
    errors = []
    if set(item) != _EVENT_FIELDS:
        errors.append(f"{prefix}: fields differ from the fixed operation schema")
        return errors
    if item.get("schema_version") != OPERATION_JOURNAL_SCHEMA_VERSION:
        errors.append(f"{prefix}: schema version mismatch")
    if item.get("operation") not in OPERATION_TYPES:
        errors.append(f"{prefix}: unsupported operation type")
    if not isinstance(item.get("command"), str) or not _SAFE_TOKEN.fullmatch(item["command"]):
        errors.append(f"{prefix}: invalid command token")
    if not isinstance(item.get("result_status"), str) or not _SAFE_TOKEN.fullmatch(item["result_status"]):
        errors.append(f"{prefix}: invalid result status token")
    if not isinstance(item.get("event_id"), str) or not item["event_id"].startswith("operation-"):
        errors.append(f"{prefix}: invalid event id")
    if not isinstance(item.get("recorded_at_utc"), str) or len(item["recorded_at_utc"]) != 20:
        errors.append(f"{prefix}: invalid recorded timestamp")
    evidence = item.get("evidence_paths")
    if not isinstance(evidence, list) or len(evidence) > 8:
        errors.append(f"{prefix}: evidence_paths must be a bounded list")
    else:
        for value in evidence:
            if not isinstance(value, str):
                errors.append(f"{prefix}: evidence path must be text")
                continue
            relative = PurePosixPath(value)
            if relative.is_absolute() or ".." in relative.parts:
                errors.append(f"{prefix}: evidence path escapes OUTPUT")
    return errors


def audit_operation_journal(output: Path) -> dict[str, Any]:
    output = output.resolve()
    root = _root(output)
    if not root.is_dir():
        return {
            "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
            "status": "passed",
            "records": 0,
            "shards": 0,
            "initialized": False,
            "errors": [],
        }
    errors: list[str] = []
    events: list[dict[str, Any]] = []
    shard_paths = sorted(root.glob("*.jsonl"))
    seen_ids: set[str] = set()
    for path in shard_paths:
        matched = _SHARD_NAME.fullmatch(path.name)
        if not matched:
            errors.append(f"unexpected operation shard name: {path.name}")
            continue
        if path.stat().st_size > MAX_SHARD_BYTES:
            errors.append(f"operation shard exceeds byte limit: {path.name}")
        shard_events = _read_shard(path)
        if len(shard_events) > MAX_RECORDS_PER_SHARD:
            errors.append(f"operation shard exceeds record limit: {path.name}")
        for line_number, item in enumerate(shard_events, start=1):
            errors.extend(_event_errors(item, path, line_number))
            event_id = item.get("event_id")
            if isinstance(event_id, str):
                if event_id in seen_ids:
                    errors.append(f"duplicate operation event id: {event_id}")
                seen_ids.add(event_id)
        events.extend(shard_events)
    state_path = root / "state.json"
    latest_path = root / "latest.json"
    if not state_path.is_file() or not latest_path.is_file():
        errors.append("operation journal state.json and latest.json are required after initialization")
        state = _state(root)
        latest = {}
    else:
        state = _state(root)
        latest = json_load(latest_path)
    expected = _latest_summary(root, events, state)
    for key in (
        "schema_version",
        "status",
        "retention_days",
        "max_records_per_shard",
        "max_shard_bytes",
        "records",
        "counts_by_operation",
        "counts_by_status",
        "shards",
        "latest",
        "bounded_drops",
    ):
        if latest.get(key) != expected.get(key):
            errors.append(f"operation latest summary mismatch: {key}")
    if (output / "human/operations").exists() or (output / "markdown/operations").exists():
        errors.append("machine operation journal must not create human operation pages")
    return {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "records": len(events),
        "shards": len(shard_paths),
        "initialized": True,
        "latest": str(latest_path.resolve()),
        "errors": errors,
    }

from __future__ import annotations

import re
from pathlib import Path
from typing import Any, Iterator

from .common import DependencyError, stable_id


DECLARATION_TYPES = {
    "python": {
        "function_definition": "function",
        "class_definition": "class",
    },
    "javascript": {
        "function_declaration": "function",
        "generator_function_declaration": "function",
        "class_declaration": "class",
        "method_definition": "method",
        "variable_declarator": "variable",
    },
    "c": {
        "function_definition": "function",
        "declaration": "declaration",
        "struct_specifier": "class",
        "enum_specifier": "enum",
        "type_definition": "type",
    },
    "cpp": {
        "function_definition": "function",
        "function_declarator": "function",
        "class_specifier": "class",
        "struct_specifier": "class",
        "enum_specifier": "enum",
        "namespace_definition": "namespace",
        "type_definition": "type",
    },
    "csharp": {
        "namespace_declaration": "namespace",
        "file_scoped_namespace_declaration": "namespace",
        "class_declaration": "class",
        "struct_declaration": "struct",
        "record_declaration": "record",
        "interface_declaration": "interface",
        "delegate_declaration": "delegate",
        "enum_declaration": "enum",
        "enum_member_declaration": "enum_member",
        "method_declaration": "method",
        "local_function_statement": "local_function",
        "constructor_declaration": "constructor",
        "operator_declaration": "operator",
        "conversion_operator_declaration": "conversion_operator",
        "property_declaration": "property",
        "indexer_declaration": "indexer",
        "event_declaration": "event",
        "event_field_declaration": "event",
        "accessor_declaration": "accessor",
        "field_declaration": "field",
    },
}

NAME_FIELDS = ("name", "declarator", "type")


def _language(language: str):
    try:
        from tree_sitter import Language
        modules = {
            "python": "tree_sitter_python",
            "javascript": "tree_sitter_javascript",
            "c": "tree_sitter_c",
            "cpp": "tree_sitter_cpp",
            "csharp": "tree_sitter_c_sharp",
        }
        module = __import__(modules[language])
        return Language(module.language())
    except Exception as exc:
        raise DependencyError(f"Tree-sitter runtime for {language} is unavailable: {exc}") from exc


def _walk(node) -> Iterator[Any]:
    stack = [node]
    while stack:
        current = stack.pop()
        yield current
        stack.extend(reversed(current.children))


def _node_text(node, source: bytes) -> str:
    return source[node.start_byte : node.end_byte].decode("utf-8", errors="replace")


def _byte_position(source: bytes, byte_offset: int) -> tuple[int, int]:
    """Compute 1-based line and UTF-8 byte column without Node Point access."""
    previous_newline = source.rfind(b"\n", 0, byte_offset)
    return source.count(b"\n", 0, byte_offset) + 1, byte_offset - (previous_newline + 1)


def _find_name(node, source: bytes, retained_nodes: list[Any]) -> tuple[str, int, int] | None:
    for field in NAME_FIELDS:
        child = node.child_by_field_name(field)
        if child is not None:
            candidates = [child, *_walk(child)]
            retained_nodes.extend(candidates)
            for value in candidates:
                if value.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
                    line, column = _byte_position(source, value.start_byte)
                    return _node_text(value, source), line, column
    fallback_nodes = list(_walk(node))
    retained_nodes.extend(fallback_nodes)
    for child in fallback_nodes:
        if child.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
            line, column = _byte_position(source, child.start_byte)
            return _node_text(child, source), line, column
    return None


def _public_evidence(language: str, source_text: str, node_text: str, name: str) -> bool:
    if language == "python":
        return not name.startswith("_")
    if language == "javascript":
        return bool(re.search(r"\bexport\b", source_text[max(0, source_text.find(node_text) - 80) : source_text.find(node_text) + 20]))
    return bool(re.search(r"\b(public|protected|internal|extern)\b", node_text)) or language in {"c", "cpp"}


PAGE_ELIGIBLE_KINDS = {
    "class",
    "struct",
    "record",
    "interface",
    "delegate",
    "function",
    "method",
    "local_function",
    "constructor",
    "operator",
    "conversion_operator",
    "property",
    "indexer",
    "event",
    "accessor",
}


def _single_statement_shape(node, source: bytes, kind: str) -> str | None:
    """Return a small deterministic hard-exclusion reason for thin declarations."""
    if kind == "accessor":
        return "accessor"
    if kind not in {"function", "method", "local_function", "constructor", "operator", "conversion_operator", "property", "indexer", "event"}:
        return None
    body = node.child_by_field_name("body")
    if body is None:
        # Expression-bodied C# members and declarations without a block.
        text = _node_text(node, source)
        if "=>" in text:
            return "single-expression-body"
        return None
    named = [child for child in body.named_children if child.type not in {"comment"}]
    if len(named) != 1:
        return None
    statement = named[0]
    text = _node_text(statement, source)
    if statement.type in {"return_statement", "expression_statement"}:
        if not re.search(r"\b(if|for|foreach|while|switch|try|catch|await|yield|throw|lock)\b", text):
            return "single-return-or-call"
    if statement.type in {"assignment_expression", "local_declaration_statement"}:
        return "single-assignment"
    return None


def _csharp_fallback_name(node, source: bytes, kind: str) -> tuple[str, int, int] | None:
    text = _node_text(node, source)
    if kind == "indexer":
        line, column = _byte_position(source, node.start_byte)
        return "this", line, column
    if kind == "accessor":
        match = re.search(r"\b(get|set|init|add|remove)\b", text)
        if match:
            absolute = node.start_byte + len(text[: match.start()].encode("utf-8"))
            line, column = _byte_position(source, absolute)
            return match.group(1), line, column
    if kind in {"operator", "conversion_operator"}:
        match = re.search(r"\boperator\s+([^\s({]+)", text)
        label = f"operator {match.group(1)}" if match else kind.replace("_", " ")
        line, column = _byte_position(source, node.start_byte)
        return label, line, column
    return None


def _has_ancestor(node: Any, node_type: str) -> bool:
    current = node.parent
    while current is not None:
        if current.type == node_type:
            return True
        current = current.parent
    return False


def _cpp_function_declarator_kind(node: Any) -> str | None:
    """Classify C++ function-shaped nodes that require parent context."""
    if _has_ancestor(node, "template_instantiation"):
        return None
    parent = node.parent
    if parent is not None and parent.type == "reference_declarator" and _has_ancestor(node, "compound_statement"):
        # Tree-sitter intentionally resolves the declaration/expression ambiguity
        # without a symbol table.  In a block, ``const T &x(expr);`` is retained as
        # a declaration fact rather than promoted to a standalone function.
        return "declaration"
    return "function"


def _cpp_explicit_class_instantiation_recovery(node: Any, source: bytes) -> dict[str, Any] | None:
    """Recognize the pinned grammar's sole missing-node shape for ``template class``."""
    if not node.is_missing or node.type != "identifier":
        return None
    parent = node.parent
    if parent is None or parent.type != "template_instantiation":
        return None
    type_node = parent.child_by_field_name("type")
    if type_node is None or type_node.type not in {"class_specifier", "struct_specifier"}:
        return None
    name_node = type_node.child_by_field_name("name")
    if name_node is None or name_node.type != "template_type":
        return None
    text = _node_text(parent, source).strip()
    if not re.match(r"^template\s+(?:class|struct)\b", text) or not text.endswith(";"):
        return None
    start_line, _ = _byte_position(source, parent.start_byte)
    end_line, _ = _byte_position(source, parent.end_byte)
    return {
        "kind": "tree-sitter-cpp-explicit-class-template-instantiation",
        "node_type": node.type,
        "start_line": start_line,
        "end_line": end_line,
    }


def _parse_diagnostics(language: str, root: Any, source: bytes) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Split known pinned-grammar recoveries from unresolved syntax diagnostics."""
    error_nodes = [node for node in _walk(root) if node.is_error or node.is_missing]
    recoveries: list[dict[str, Any]] = []
    unresolved: list[dict[str, Any]] = []
    for node in error_nodes:
        recovery = _cpp_explicit_class_instantiation_recovery(node, source) if language == "cpp" else None
        if recovery is not None:
            recoveries.append(recovery)
            continue
        start_line, _ = _byte_position(source, node.start_byte)
        end_line, _ = _byte_position(source, node.end_byte)
        unresolved.append(
            {
                "node_type": node.type,
                "is_error": bool(node.is_error),
                "is_missing": bool(node.is_missing),
                "start_line": start_line,
                "end_line": end_line,
            }
        )
    if root.has_error and not error_nodes:
        unresolved.append(
            {
                "node_type": root.type,
                "is_error": True,
                "is_missing": False,
                "start_line": 1,
                "end_line": max(1, source.count(b"\n") + 1),
            }
        )
    return recoveries, unresolved


def parse_file(repository: dict[str, Any], file_entry: dict[str, Any], source: bytes) -> dict[str, Any]:
    try:
        from tree_sitter import Parser
    except Exception as exc:
        raise DependencyError(f"Tree-sitter Python binding is unavailable: {exc}") from exc
    # Keep the Language wrapper alive for the full tree/node lifetime.  The
    # native binding owns parser tables through this object; a temporary can be
    # collected during large traversals and invalidate later Node access.
    language = _language(file_entry["language"])
    parser = Parser(language)
    tree = parser.parse(source)
    root = tree.root_node
    recoveries, parse_diagnostics = _parse_diagnostics(file_entry["language"], root, source)
    source_text = source.decode("utf-8", errors="replace")
    file_entity = {
        "id": file_entry["id"],
        "kind": "file",
        "name": Path(file_entry["path"]).name,
        "qualified_name": file_entry["path"],
        "language": file_entry["language"],
        "path": file_entry["path"],
        "blob": file_entry["blob"],
        "commit": repository["commit"],
        "range": {
            "start_byte": 0,
            "end_byte": len(source),
            "start_line": 1,
            "end_line": max(1, source.count(b"\n") + 1),
        },
        "parent_id": None,
        "candidate_classification": "page",
        "classification_evidence": ["file-always-page"],
    }
    entities = [file_entity]
    entity_kind_by_id = {file_entity["id"]: "file"}
    ranges: list[tuple[int, int, str, str]] = []
    file_scoped_namespace: tuple[str, str, int] | None = None
    declarations = DECLARATION_TYPES[file_entry["language"]]
    seen: set[tuple[str, int, int]] = set()
    # Keep every wrapper alive until extraction finishes.  tree-sitter 0.26 on
    # Windows can release native node context too early when generator-produced
    # wrappers are destroyed during a long traversal.
    syntax_nodes = list(_walk(root))
    retained_nodes: list[Any] = list(syntax_nodes)
    for node in syntax_nodes:
        node_type = node.type
        kind = declarations.get(node_type)
        if not kind:
            continue
        if file_entry["language"] == "cpp":
            if _has_ancestor(node, "template_instantiation"):
                continue
            if node_type == "function_declarator":
                kind = _cpp_function_declarator_kind(node)
                if kind is None:
                    continue
        start_byte = node.start_byte
        end_byte = node.end_byte
        start_line, _start_column = _byte_position(source, start_byte)
        end_line, _end_column = _byte_position(source, end_byte)
        named = _find_name(node, source, retained_nodes) or _csharp_fallback_name(node, source, kind)
        if file_entry["language"] == "csharp" and kind == "namespace":
            namespace_name = node.child_by_field_name("name")
            if namespace_name is not None:
                line, column = _byte_position(source, namespace_name.start_byte)
                named = (_node_text(namespace_name, source).strip(), line, column)
        if not named:
            continue
        name, name_line, name_column = named
        if not name or len(name) > 240:
            continue
        key = (name, start_byte, end_byte)
        if key in seen:
            continue
        seen.add(key)
        parent_name = None
        parent_id = file_entity["id"]
        for start, end, candidate_name, candidate_id in reversed(ranges):
            if start <= start_byte and end_byte <= end:
                parent_name = candidate_name
                parent_id = candidate_id
                break
        if parent_name is None and file_scoped_namespace and start_byte >= file_scoped_namespace[2]:
            parent_name, parent_id, _namespace_end = file_scoped_namespace
        qualified = f"{parent_name}.{name}" if parent_name else name
        if node_type == "function_declarator" and kind == "function" and entity_kind_by_id.get(parent_id) == "function":
            continue
        node_text = source[start_byte:end_byte].decode("utf-8", errors="replace")
        line_count = end_line - start_line + 1
        hard_exclusion = (
            f"csharp-default-appendix:{kind}"
            if file_entry["language"] == "csharp" and kind in {"property", "indexer", "event", "accessor"}
            # Python exposes module and object access through these protocol
            # methods.  They are accessors rather than navigational landing
            # pages, even when a cross-file reference gives them a high graph
            # rank.  Keep constructors and other substantial dunder methods
            # eligible; only the four attribute-access hooks are deterministic
            # appendix entities.
            else "python-attribute-accessor"
            if file_entry["language"] == "python"
            and name in {"__getattr__", "__getattribute__", "__setattr__", "__delattr__"}
            else _single_statement_shape(node, source, kind)
        )
        simple = kind not in PAGE_ELIGIBLE_KINDS or hard_exclusion is not None
        public = _public_evidence(file_entry["language"], source_text, node_text, name)
        effects = bool(re.search(r"\b(open|write|save|delete|remove|request|fetch|socket|subprocess|exec|spawn|commit|send|recv)\b", node_text, re.I))
        evidence = []
        if public:
            evidence.append("public-or-exported")
        if kind == "class":
            evidence.append("class-boundary")
        if effects:
            evidence.append("side-effect-orchestration")
        if simple:
            evidence.append("simple-attached-entity")
        candidate = "page" if kind in PAGE_ELIGIBLE_KINDS and not simple else "appendix"
        entity_id = stable_id("ent", repository["commit"], file_entry["blob"], file_entry["path"], start_byte, end_byte, kind, name)
        entity = {
            "id": entity_id,
            "kind": kind,
            "name": name,
            "qualified_name": qualified,
            "language": file_entry["language"],
            "path": file_entry["path"],
            "blob": file_entry["blob"],
            "commit": repository["commit"],
            "range": {
                "start_byte": start_byte,
                "end_byte": end_byte,
                "start_line": start_line,
                "end_line": end_line,
                "name_line": name_line,
                "name_column_utf8": name_column,
            },
            "parent_id": parent_id,
            "candidate_classification": candidate,
            "classification_evidence": evidence or ["attached-by-default"],
            "page_eligible": kind in PAGE_ELIGIBLE_KINDS and hard_exclusion is None,
            "hard_exclusion": hard_exclusion,
            "is_public_or_exported": public,
            "is_partial": file_entry["language"] == "csharp" and bool(re.search(r"\bpartial\b", node_text[: min(len(node_text), 240)])),
        }
        entities.append(entity)
        entity_kind_by_id[entity_id] = kind
        ranges.append((start_byte, end_byte, qualified, entity_id))
        if node_type == "file_scoped_namespace_declaration":
            file_scoped_namespace = (qualified, entity_id, end_byte)
    return {
        "file": file_entry,
        "parse": {
            "status": "failed" if parse_diagnostics else "passed",
            "root_type": root.type,
            "has_error": bool(parse_diagnostics),
            "raw_has_error": bool(root.has_error),
            "recoveries": recoveries,
            "diagnostics": parse_diagnostics,
        },
        "entities": entities,
    }


def merge_csharp_partials(repository: dict[str, Any], entities: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge partial C# type declarations into one logical entity with audited fragments."""
    type_kinds = {"class", "struct", "record", "interface"}
    groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for entity in entities:
        if entity.get("language") == "csharp" and entity.get("kind") in type_kinds and entity.get("is_partial"):
            groups.setdefault((entity["kind"], entity["qualified_name"]), []).append(entity)
    replacements: dict[str, str] = {}
    merged_by_old: dict[str, dict[str, Any]] = {}
    removed: set[str] = set()
    for (kind, qualified), values in sorted(groups.items()):
        if len(values) < 2:
            continue
        ordered = sorted(values, key=lambda item: (item["path"], item["range"]["start_byte"], item["id"]))
        primary = sorted(
            ordered,
            key=lambda item: (
                -sum(1 for child in entities if child.get("parent_id") == item["id"] and child.get("page_eligible")),
                item["path"],
                item["range"]["start_byte"],
                item["id"],
            ),
        )[0]
        logical_id = stable_id("ent", repository["commit"], "csharp-partial", kind, qualified)
        logical = dict(primary)
        logical["id"] = logical_id
        logical["partial"] = True
        logical["fragments"] = [
            {
                "fragment_id": value["id"],
                "path": value["path"],
                "blob": value["blob"],
                "range": value["range"],
            }
            for value in ordered
        ]
        logical["classification_evidence"] = sorted(set(logical.get("classification_evidence", []) + ["partial-logical-entity"]))
        for value in ordered:
            replacements[value["id"]] = logical_id
            merged_by_old[value["id"]] = logical
            removed.add(value["id"])
    if not replacements:
        return entities
    result: list[dict[str, Any]] = []
    emitted: set[str] = set()
    for entity in entities:
        if entity["id"] in removed:
            logical = merged_by_old[entity["id"]]
            if logical["id"] not in emitted:
                result.append(logical)
                emitted.add(logical["id"])
            continue
        value = dict(entity)
        if value.get("parent_id") in replacements:
            value["parent_id"] = replacements[value["parent_id"]]
        result.append(value)
    return result


def lexical_links(entities: list[dict[str, Any]], sources: dict[str, bytes]) -> list[dict[str, Any]]:
    by_name: dict[str, list[dict[str, Any]]] = {}
    for entity in entities:
        if entity["kind"] != "file" and len(entity["name"]) >= 2:
            by_name.setdefault(entity["name"], []).append(entity)
    links: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for source_entity in entities:
        if source_entity["kind"] == "file":
            continue
        data = sources.get(source_entity["path"], b"")
        region = data[source_entity["range"]["start_byte"] : source_entity["range"]["end_byte"]].decode("utf-8", errors="replace")
        referenced_names = set(re.findall(r"[A-Za-z_$][A-Za-z0-9_$]*", region))
        for name in sorted(referenced_names.intersection(by_name)):
            targets = by_name[name]
            if name == source_entity["name"]:
                continue
            if len(targets) != 1:
                continue
            target = targets[0]
            if target["id"] == source_entity["id"]:
                continue
            key = (source_entity["id"], target["id"], "references")
            if key in seen:
                continue
            seen.add(key)
            links.append({
                "id": stable_id("link", *key),
                "type": "references",
                "source": source_entity["id"],
                "target": target["id"],
                "provider": "tree-sitter-lexical-candidate",
                "evidence": {"name": name, "source_path": source_entity["path"]},
            })
    for entity in entities:
        if entity["parent_id"]:
            key = (entity["parent_id"], entity["id"], "contains")
            links.append({
                "id": stable_id("link", *key),
                "type": "contains",
                "source": entity["parent_id"],
                "target": entity["id"],
                "provider": "tree-sitter",
                "evidence": {"path": entity["path"], "range": entity["range"]},
            })
    return links

