"""Deterministic query terms for identifiers and Chinese prose."""

from __future__ import annotations

import re
import unicodedata


MAX_QUERY_TERMS = 64
DEFAULT_FTS_TERM_LIMIT = 16

# These fixed query-glue characters are not a segmentation dictionary.  They
# only prevent sliding grams from crossing common grammatical boundaries.  The
# complete CJK run is retained, so negation and exact short phrases remain
# available without promoting fragments such as ``包不满`` or ``回的检``.
_CJK_QUERY_GLUE = frozenset("的了和与及或并而在把被将向从到为对时是会否不")
_CODE_RUN = re.compile(r"[A-Za-z0-9_.$:/\\#+-]+")
_CODE_SEPARATOR = re.compile(r"[._$:/\\#+-]+")
_CJK_RUN = re.compile(r"[\u3400-\u9fff]+")
_CJK_GLUE_RUN = re.compile("[" + "".join(sorted(_CJK_QUERY_GLUE)) + "]+")


def _split_camel(value: str) -> list[str]:
    return [
        part
        for part in re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", value).replace("::", " ").split()
        if part
    ]


def _ranked_terms(text: str) -> list[str]:
    normalized = unicodedata.normalize("NFKC", text)
    priorities: dict[str, int] = {}

    def add(value: str, priority: int) -> None:
        if value:
            priorities[value] = min(priorities.get(value, priority), priority)

    for run in _CODE_RUN.findall(normalized):
        lowered = run.casefold().strip("._$:/\\#+-")
        if len(lowered) >= 2:
            add(lowered, 0)
        for part in _CODE_SEPARATOR.split(run):
            if len(part) >= 2:
                add(part.casefold(), 1)
            for camel in _split_camel(part):
                if len(camel) >= 2:
                    add(camel.casefold(), 1)

    for run in _CJK_RUN.findall(normalized):
        # Preserve the complete phrase, including a single explicit Han
        # character.  FTS filtering separately requires at least three code
        # points because every CKB FTS table uses the trigram tokenizer.
        add(run, 0)
        for span in (value for value in _CJK_GLUE_RUN.split(run) if value):
            if len(span) >= 2:
                add(span, 1)
            for width, priority in ((3, 2), (2, 3)):
                for index in range(max(0, len(span) - width + 1)):
                    add(span[index : index + width], priority)

    return sorted(priorities, key=lambda value: (priorities[value], -len(value), value))


def search_terms(text: str, limit: int = MAX_QUERY_TERMS) -> list[str]:
    """Return bounded query terms in fixed signal, length, and lexical order."""
    if limit < 0:
        raise ValueError("query term limit must be non-negative")
    return _ranked_terms(text)[:limit]


def index_terms(text: str) -> list[str]:
    """Return the same deterministic terms without the query-side cap."""
    return _ranked_terms(text)


def fts_query_terms(text: str, limit: int = DEFAULT_FTS_TERM_LIMIT) -> list[str]:
    """Select trigram-compatible terms from the bounded query ordering."""
    if limit < 0:
        raise ValueError("FTS term limit must be non-negative")
    return [term for term in search_terms(text) if len(term) >= 3][:limit]


def build_fts_query(text: str, limit: int = DEFAULT_FTS_TERM_LIMIT) -> str | None:
    values = fts_query_terms(text, limit)
    if not values:
        return None
    return " OR ".join('"' + value.replace('"', '""') + '"' for value in values)


def explicit_anchors(text: str) -> list[str]:
    """Retain explicit code anchors independently from prose term ranking."""
    normalized = unicodedata.normalize("NFKC", text)
    anchors: set[str] = set()
    for value in re.findall(
        r"[A-Za-z_][A-Za-z0-9_]*(?:(?:::|[./#$:-])[A-Za-z0-9_]+)+|[A-Za-z_][A-Za-z0-9_]{2,}",
        normalized,
    ):
        if (
            any(character.isupper() for character in value[1:])
            or any(character in value for character in "_./#$:-")
            or any(character.isdigit() for character in value)
        ):
            anchors.add(value.casefold())
    return sorted(anchors)

def search_terms(text: str, limit: int = MAX_QUERY_TERMS) -> list[str]:
    """Return bounded query terms in fixed signal, length, and lexical order."""
    if limit < 0:
        raise ValueError("query term limit must be non-negative")
    return _ranked_terms(text)[:limit]

def build(root: Path, output: Path) -> dict[str, object]:
    root = root.resolve()
    output = output.resolve()
    if not root.is_dir():
        raise RuntimeError(f"runtime root is absent: {root}")
    try:
        output.relative_to(root)
    except ValueError:
        pass
    else:
        raise RuntimeError("payload output must be outside the staged runtime root")

    files = relative_files(root)
    manifest = {
        "schema_version": 1,
        "platform": "win-x64",
        "lock_id": "win-x64-2.0.0",
        "files": [
            {
                "path": path.relative_to(root).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    manifest_path = root / MANIFEST_NAME
    manifest_path.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    archive_files = [manifest_path, *files]
    archive_files.sort(key=lambda path: path.relative_to(root).as_posix())

    output.parent.mkdir(parents=True, exist_ok=True)
    if output.exists():
        output.unlink()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in archive_files:
            relative = PurePosixPath(path.relative_to(root).as_posix())
            info = zipfile.ZipInfo(str(relative), date_time=FIXED_TIME)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)

    with zipfile.ZipFile(output) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"payload CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(MANIFEST_NAME))
        if archived_manifest != manifest:
            raise RuntimeError("archived payload manifest differs from staging manifest")
        names = set(archive.namelist())
        expected_names = {path.relative_to(root).as_posix() for path in archive_files}
        if names != expected_names:
            raise RuntimeError("payload member set differs from the staged runtime set")

    return {
        "status": "passed",
        "root": str(root),
        "output": str(output),
        "size": output.stat().st_size,
        "sha256": sha256(output),
        "file_count": len(archive_files),
        "manifest": str(manifest_path),
    }

def keyword_fallback_options(args: argparse.Namespace) -> KeywordFallbackOptions | None:
    if not (args.allow_keyword_fallback or args.force_keyword_fallback):
        return None
    return KeywordFallbackOptions(
        config=keyword_provider_config(args),
        force=bool(args.force_keyword_fallback),
        use_cache=not args.keyword_provider_no_cache,
    )

def _note_documents(markdown_root: Path) -> list[dict[str, Any]]:
    documents = []
    for directory in NOTE_DIRECTORIES:
        for path in sorted((markdown_root / directory).glob("*.md")):
            text = path.read_text(encoding="utf-8")
            title = text.splitlines()[0].removeprefix("# ").strip() if text else path.stem
            tag_match = re.search(r"#类型/[\w\u3400-\u9fff-]+", text)
            documents.append(
                {
                    "title": title,
                    "tag": tag_match.group(0) if tag_match else "",
                    "file": path.relative_to(markdown_root).as_posix(),
                    "content": text,
                    "links": re.findall(r"\[\[([^\]|#]+)", text),
                }
            )
    return documents

def _projection(output: Path) -> tuple[dict[str, Any], str]:
    """Select the richest completed human projection without requiring Markdown."""
    state_path = output / "state.json"
    if state_path.is_file() and json_load(state_path).get("format") == "logseq-db":
        logseq = output / "logseq-db/projection.json"
        if logseq.is_file():
            return json_load(logseq), "logseq-db"
    markdown = output / "markdown/projection.json"
    if markdown.is_file():
        return json_load(markdown), "markdown"
    logseq = output / "logseq-db/projection.json"
    if logseq.is_file():
        return json_load(logseq), "logseq-db"
    raise CkbError("Agent index requires a finalized Markdown or Logseq DB projection")

def _page_documents(
    output: Path,
    projection: dict[str, Any],
    projection_format: str,
    graph: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    """Return readable page documents for either projection.

    Markdown pages are indexed byte-for-byte.  A DB-only build has no page
    files, so the same reviewed source facts are rendered into a compact
    index-only narrative.  This keeps retrieval format-neutral without adding
    another visible knowledge-base projection.
    """
    page_by_id = {page["id"]: page for page in projection.get("pages", [])}
    title_by_id = {page_id: page["title"] for page_id, page in page_by_id.items()}
    owner_by_entity = projection.get("entity_owner_pages", {})
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    owned: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            owned[owner].append(entity)

    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    documents: dict[str, dict[str, Any]] = {}
    for page_id, page in page_by_id.items():
        entity = entity_by_id.get(page_id)
        if projection_format == "markdown":
            relative = Path("markdown") / page["file"]
            content = (output / relative).read_text(encoding="utf-8")
        else:
            relative = Path("logseq-db/normalized.edn")
            lines = [f"# {page['title']}", "", f"标签：{page.get('tag') or ''}", ""]
            if entity:
                overview = " ".join(
                    value.strip()
                    for value in (str(entity.get("meaning_zh", "")), str(entity.get("role_zh", "")))
                    if value.strip()
                )
                if overview:
                    lines.extend([f"> {overview}", ""])
                if entity.get("change_when_zh"):
                    lines.extend(["## 什么时候需要修改", "", str(entity["change_when_zh"]), ""])
                if entity.get("path") and entity.get("range"):
                    lines.extend(
                        [
                            "## 源码位置",
                            "",
                            source_markdown_link(
                                openers,
                                str(entity["path"]),
                                int(entity["range"]["start_line"]),
                                int(entity["range"]["end_line"]),
                            ),
                            "",
                        ]
                    )
            else:
                lines.extend(["> 这是由相关类、函数和辅助实现组成的职责导航页。", ""])
            appendix = [item for item in owned.get(page_id, []) if item.get("classification") == "appendix"]
            if appendix:
                lines.extend(["## 内部细节", ""])
                for item in sorted(appendix, key=lambda value: (value.get("path", ""), value.get("range", {}).get("start_line", 0), value.get("qualified_name", ""))):
                    lines.append(f"- `{item.get('qualified_name') or item.get('name')}`：{item.get('description_zh') or item.get('role_zh') or '承担局部辅助处理。'}")
                lines.append("")
            neighbors = []
            for link in projection.get("links", []):
                if link.get("source") == page_id and link.get("target") in title_by_id:
                    neighbors.append(title_by_id[link["target"]])
                elif link.get("target") == page_id and link.get("source") in title_by_id:
                    neighbors.append(title_by_id[link["source"]])
            if neighbors:
                lines.extend(["## 相关代码", "", *[f"- [[{title}]]" for title in sorted(set(neighbors))], ""])
            content = "\n".join(lines).rstrip() + "\n"
        summary = next(
            (
                line.removeprefix("> ").strip()
                for line in content.splitlines()
                if line.startswith("> ") and line.removeprefix("> ").strip()
            ),
            page["title"],
        )
        source_range = entity.get("range", {}) if entity else {}
        documents[page_id] = {
            "content": content,
            "summary": summary,
            "page_file": relative.as_posix(),
            "source_path": entity.get("path") if entity else None,
            "start_line": source_range.get("start_line"),
            "end_line": source_range.get("end_line"),
        }
    return documents

def build_agent_index(output: Path) -> dict[str, Any]:
    markdown_root = output / "markdown"
    projection, projection_format = _projection(output)
    graph = json_load(output / "graph.json")
    pages = projection.get("pages", [])
    documents = _page_documents(output, projection, projection_format, graph)
    page_by_id = {page["id"]: page for page in pages}
    owner_by_entity = projection.get("entity_owner_pages", {})
    symbols_by_page: dict[str, list[str]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            for value in (entity.get("name"), entity.get("qualified_name")):
                if value:
                    symbols_by_page[owner].append(str(value))
    index = output / "agent-index.sqlite"
    temporary = output / "agent-index.sqlite.tmp"
    temporary.unlink(missing_ok=True)
    connection = sqlite3.connect(temporary)
    try:
        connection.executescript(
            """
            PRAGMA foreign_keys=ON;
            CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE pages(
                page_id TEXT PRIMARY KEY,
                title TEXT NOT NULL UNIQUE,
                page_type TEXT NOT NULL,
                tag TEXT NOT NULL,
                page_file TEXT NOT NULL,
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER,
                summary TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE symbols(
                symbol TEXT NOT NULL,
                qualified_name TEXT NOT NULL,
                owner_page_id TEXT NOT NULL REFERENCES pages(page_id),
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER
            );
            CREATE INDEX symbols_name ON symbols(symbol COLLATE NOCASE);
            CREATE INDEX symbols_qname ON symbols(qualified_name COLLATE NOCASE);
            CREATE TABLE edges(
                source_page_id TEXT NOT NULL REFERENCES pages(page_id),
                target_page_id TEXT NOT NULL REFERENCES pages(page_id),
                relation TEXT NOT NULL,
                weight REAL NOT NULL,
                PRIMARY KEY(source_page_id,target_page_id,relation)
            );
            CREATE INDEX edges_target ON edges(target_page_id);
            CREATE TABLE terms(
                term TEXT NOT NULL,
                page_id TEXT NOT NULL REFERENCES pages(page_id),
                weight REAL NOT NULL,
                PRIMARY KEY(term,page_id)
            );
            CREATE INDEX terms_term ON terms(term);
            CREATE TABLE notes(
                note_title TEXT PRIMARY KEY,
                tag TEXT NOT NULL,
                note_file TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE note_links(
                note_title TEXT NOT NULL REFERENCES notes(note_title),
                page_title TEXT NOT NULL,
                PRIMARY KEY(note_title,page_title)
            );
            CREATE VIRTUAL TABLE page_fts USING fts5(
                page_id UNINDEXED,
                title,
                summary,
                symbols,
                source_path,
                tokenize='trigram'
            );
            CREATE VIRTUAL TABLE note_fts USING fts5(
                note_title UNINDEXED,
                title,
                content,
                tokenize='trigram'
            );
            """
        )
        connection.executemany(
            "INSERT INTO meta(key,value) VALUES(?,?)",
            [
                ("schema_version", str(INDEX_SCHEMA_VERSION)),
                ("status", "ready"),
                ("built_at_utc", utc_now()),
                ("page_count", str(len(pages))),
                ("projection_format", projection_format),
            ],
        )
        entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
        for page in pages:
            document = documents[page["id"]]
            content = document["content"]
            summary = document["summary"]
            source_path = document["source_path"]
            symbols = sorted(set(symbols_by_page.get(page["id"], [])))
            connection.execute(
                "INSERT INTO pages VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (
                    page["id"],
                    page["title"],
                    page["page_type"],
                    page.get("tag") or "",
                    document["page_file"],
                    source_path,
                    document["start_line"],
                    document["end_line"],
                    summary,
                    content,
                    _tokens(content),
                ),
            )
            connection.execute(
                "INSERT INTO page_fts(page_id,title,summary,symbols,source_path) VALUES(?,?,?,?,?)",
                (page["id"], page["title"], summary, " ".join(symbols), source_path or ""),
            )
            weighted_terms: dict[str, float] = {}
            for value, weight in ((page["title"], 8.0), (" ".join(symbols), 6.0), (summary, 3.0), (source_path or "", 2.0)):
                for term in index_terms(value):
                    weighted_terms[term] = max(weighted_terms.get(term, 0.0), weight)
            connection.executemany(
                "INSERT INTO terms(term,page_id,weight) VALUES(?,?,?)",
                [(term, page["id"], weight) for term, weight in sorted(weighted_terms.items())],
            )
        for entity in graph.get("entities", []):
            owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
            if owner not in page_by_id:
                continue
            source_range = entity.get("range", {})
            connection.execute(
                "INSERT INTO symbols VALUES(?,?,?,?,?,?)",
                (
                    str(entity.get("name") or entity.get("qualified_name") or ""),
                    str(entity.get("qualified_name") or entity.get("name") or ""),
                    owner,
                    entity.get("path"),
                    source_range.get("start_line"),
                    source_range.get("end_line"),
                ),
            )
        relation_weight = {"tested-by": 1.4, "calls": 1.3, "invokes": 1.3, "depends-on": 1.2, "uses": 1.1, "contains": 0.8}
        for link in projection.get("links", []):
            if link["source"] not in page_by_id or link["target"] not in page_by_id:
                continue
            connection.execute(
                "INSERT OR REPLACE INTO edges VALUES(?,?,?,?)",
                (link["source"], link["target"], link["type"], relation_weight.get(link["type"], 1.0)),
            )
        for note in _note_documents(markdown_root) if projection_format == "markdown" else []:
            connection.execute(
                "INSERT INTO notes VALUES(?,?,?,?,?)",
                (note["title"], note["tag"], note["file"], note["content"], _tokens(note["content"])),
            )
            connection.execute(
                "INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)",
                (note["title"], note["title"], note["content"]),
            )
            for title in note["links"]:
                connection.execute("INSERT OR IGNORE INTO note_links VALUES(?,?)", (note["title"], title))
        connection.commit()
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        if integrity != "ok" or foreign_keys:
            raise CkbError(f"Agent index integrity failed: integrity={integrity}; foreign_keys={foreign_keys}")
    finally:
        connection.close()
    temporary.replace(index)
    return audit_agent_index(output)

def audit_agent_index(output: Path) -> dict[str, Any]:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        return {"schema_version": 1, "status": "failed", "errors": [{"reason": "agent-index-missing"}]}
    projection, projection_format = _projection(output)
    expected_notes = len(_note_documents(output / "markdown")) if projection_format == "markdown" else 0
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        counts = {
            "pages": connection.execute("SELECT count(*) FROM pages").fetchone()[0],
            "symbols": connection.execute("SELECT count(*) FROM symbols").fetchone()[0],
            "edges": connection.execute("SELECT count(*) FROM edges").fetchone()[0],
            "terms": connection.execute("SELECT count(*) FROM terms").fetchone()[0],
            "notes": connection.execute("SELECT count(*) FROM notes").fetchone()[0],
        }
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
        forbidden_columns = []
        for table in ("pages", "symbols", "edges", "notes", "meta"):
            for row in connection.execute(f"PRAGMA table_info({table})"):
                if "hash" in str(row[1]).casefold():
                    forbidden_columns.append(f"{table}.{row[1]}")
    finally:
        connection.close()
    errors = []
    if integrity != "ok":
        errors.append({"reason": "sqlite-integrity", "detail": integrity})
    if foreign_keys:
        errors.append({"reason": "foreign-key-errors", "detail": foreign_keys})
    if counts["pages"] != len(projection.get("pages", [])):
        errors.append({"reason": "page-count-mismatch", "actual": counts["pages"], "expected": len(projection.get("pages", []))})
    if counts["notes"] != expected_notes:
        errors.append({"reason": "note-count-mismatch", "actual": counts["notes"], "expected": expected_notes})
    if forbidden_columns:
        errors.append({"reason": "new-index-hash-column-present", "columns": forbidden_columns})
    if meta.get("projection_format") != projection_format:
        errors.append({"reason": "projection-format-mismatch", "actual": meta.get("projection_format"), "expected": projection_format})
    return {
        "schema_version": INDEX_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "path": str(index.resolve()),
        "integrity": integrity,
        "counts": counts,
        "projection_format": projection_format,
        "errors": errors,
    }

def _agent_index_ready(output: Path) -> None:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        raise CkbError("Agent index is missing; run reindex or finalize")
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
    except sqlite3.DatabaseError as exc:
        raise CkbError(f"Agent index metadata is unavailable: {exc}") from exc
    finally:
        connection.close()
    if meta.get("status") != "ready" or meta.get("schema_version") != str(INDEX_SCHEMA_VERSION):
        raise CkbError(f"Agent index metadata is incompatible: {meta}")

def supported_upgrade_path(source_version: str, target_version: str) -> list[str]:
    """Return the frozen inclusive path, rejecting unknown or backward/jump-only routes."""
    if source_version not in PROTOCOL_RELEASES:
        raise CkbError(f"unsupported Agent Protocol source version: {source_version}")
    if target_version not in PROTOCOL_RELEASES:
        raise CkbError(f"unsupported Agent Protocol target version: {target_version}")
    path = [source_version]
    while path[-1] != target_version:
        next_version = PROTOCOL_RELEASES[path[-1]].next_version
        if next_version is None:
            raise CkbError(f"no Agent Protocol upgrade path: {source_version} -> {target_version}")
        path.append(next_version)
        if len(path) > len(PROTOCOL_RELEASES):
            raise RuntimeError("Agent Protocol version matrix contains a cycle")
    return path

def version_matrix() -> dict[str, Any]:
    return {
        "schema_version": 1,
        "current_version": AGENT_PROTOCOL_VERSION,
        "releases": [
            {
                "version": release.version,
                "source_commit": release.source_commit,
                "next_version": release.next_version,
                "capabilities": list(release.capabilities),
                "output_contract": release.output_contract,
            }
            for release in PROTOCOL_RELEASES.values()
        ],
    }

def reject_unknown_fields(value: dict[str, Any], allowed: frozenset[str], location: str) -> None:
    unknown = sorted(set(value) - allowed)
    if unknown:
        raise CkbError(f"unknown batch manifest field at {location}: {', '.join(unknown)}")

def require_absolute_path(value: Any, field: str) -> Path:
    if not isinstance(value, str) or not value.strip():
        raise CkbError(f"batch manifest {field} must be a non-empty absolute path")
    path = Path(value).expanduser()
    if not path.is_absolute():
        raise CkbError(f"batch manifest {field} must be absolute: {value}")
    return path.resolve()

class BatchProjectError(CkbError):
    def __init__(self, category: str, detail: str):
        super().__init__(detail)
        self.category = category

def __init__(self, category: str, detail: str):
        super().__init__(detail)
        self.category = category

def _canonical_bytes(value: Any, *, pretty: bool = False) -> bytes:
    if pretty:
        return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode("utf-8")
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")

def command_examples_for_version(version: str, output: Path, python: Path, ckb: Path) -> dict[str, str]:
    if version not in PROTOCOL_RELEASES:
        raise CkbError(f"unsupported Agent Protocol version: {version}")
    py = _single_quote(str(python))
    cli = _single_quote(str(ckb))
    out = _single_quote(str(output.resolve()))
    prefix = f"& '{py}' '{cli}'"
    commands: dict[str, str] = {}
    if version != "1.0.0":
        commands["brief"] = f'{prefix} brief --out \'{out}\' "QUESTION" --budget 1800 --max-pages 8 --profile fast'
    commands.update(
        {
            "retrieve": f'{prefix} retrieve --out \'{out}\' "QUESTION" --budget 1800 --max-pages 8 --profile fast',
            "precise": f'{prefix} retrieve --out \'{out}\' "QUESTION" --budget 3000 --max-pages 12 --profile precise',
            "entity": f'{prefix} entity --out \'{out}\' "SYMBOL"',
            "neighbors": f'{prefix} neighbors --out \'{out}\' "SYMBOL" --depth 2',
            "source": f'{prefix} source --out \'{out}\' "SYMBOL" --context-lines 3',
            "record": f"{prefix} record --out '{out}' --kind analysis --title 'TITLE' --body 'BODY.md' --from-pack 'PACK.json'",
            "append": f"{prefix} record --out '{out}' --kind analysis --title 'EXISTING_TITLE' --body 'BODY.md' --from-pack 'PACK.json' --append",
        }
    )
    if version != "1.0.0":
        commands.update(
            {
                "feedback_list": f"{prefix} feedback list --out '{out}' --status open",
                "feedback_locate": f"{prefix} feedback locate --out '{out}' --feedback 'FEEDBACK_ID'",
                "feedback_audit": f"{prefix} feedback audit --out '{out}'",
            }
        )
    commands["check"] = f"{prefix} agent-policy check --out '{out}'"
    if version != "1.0.0":
        commands["maintain"] = f"{prefix} maintain --out '{out}'"
        commands["capabilities"] = f"{prefix} capabilities --format json"
    if version in {"1.4.0", "1.5.0"}:
        commands["reference_list"] = f"{prefix} reference list --out '{out}' --status all"
        commands["reference_audit"] = f"{prefix} reference audit --out '{out}'"
    if version == "1.5.0":
        commands["gaps_list"] = f"{prefix} gaps list --out '{out}' --status open"
        commands["gaps_audit"] = f"{prefix} gaps audit --out '{out}'"
    return commands

def _record_roots(record: dict[str, Any]) -> list[Path]:
    roots: list[Path] = []
    for value in record.get("workspace_roots", []):
        if not isinstance(value, dict) or not isinstance(value.get("root"), str):
            raise BatchProjectError("protocol-record-invalid", "Agent Protocol workspace root record is invalid")
        roots.append(Path(value["root"]).resolve())
    return roots

def _tracked_paths(output: Path, workspace_roots: list[Path]) -> list[tuple[str, Path]]:
    paths: list[tuple[str, Path]] = [
        ("protocol-record", output / "workspace-meta/agent-protocol.json"),
        ("protocol-audit", output / "workspace-meta/agent-protocol-audit.json"),
    ]
    for root_name in INTERNAL_ROOT_NAMES:
        root = output if root_name == "output" else output / root_name
        for relative in ADAPTER_PATHS.values():
            paths.append((f"internal-adapter:{root_name}", root / relative))
    for root in workspace_roots:
        for relative in ADAPTER_PATHS.values():
            paths.append(("workspace-managed-adapter", root / relative))
    for root_name in ("human", "markdown"):
        root = output / root_name
        paths.extend(
            [
                (f"output-contract:{root_name}", root / ".ckb/output-contract.json"),
                (f"generated-ownership:{root_name}", root / ".ckb-generated-files.json"),
                (f"obsidian-ignore:{root_name}", root / ".obsidian/app.json"),
                (f"obsidian-hide:{root_name}", root / ".obsidian/snippets/ckb.css"),
            ]
        )
    unique: dict[str, tuple[str, Path]] = {}
    for role, path in paths:
        unique[str(path.resolve())] = (role, path.resolve())
    return [unique[key] for key in sorted(unique)]

def snapshot_files(output: Path, workspace_roots: list[Path]) -> list[dict[str, Any]]:
    files = []
    for role, path in _tracked_paths(output.resolve(), workspace_roots):
        exists = path.is_file()
        files.append(
            {
                "role": role,
                "path": str(path),
                "exists": exists,
                "sha256": _sha256_bytes(path.read_bytes()) if exists else None,
                "mode": stat.S_IMODE(path.stat().st_mode) if exists else None,
            }
        )
    return files

def _normalized_managed_block(value: bytes) -> str:
    try:
        text = value.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise BatchProjectError("managed-file-encoding", f"managed instruction file is not UTF-8: {exc}") from exc
    return text.replace("\r\n", "\n").replace("\r", "\n")

def _validate_workspace_managed(path: Path, expected_text: str) -> None:
    if not path.is_file():
        raise BatchProjectError("managed-file-missing", f"workspace managed adapter is missing: {path}")
    text = _normalized_managed_block(path.read_bytes())
    begin_count = text.count(POLICY_BEGIN)
    end_count = text.count(POLICY_END)
    if begin_count > 1 or end_count > 1:
        raise BatchProjectError("managed-block-duplicate", f"workspace instruction file has duplicate managed markers: {path}")
    if begin_count != 1 or end_count != 1 or text.index(POLICY_BEGIN) > text.index(POLICY_END):
        raise BatchProjectError("managed-block-broken", f"workspace instruction file has broken managed markers: {path}")
    start = text.index(POLICY_BEGIN)
    end = text.index(POLICY_END, start) + len(POLICY_END)
    actual = text[start:end].rstrip("\n") + "\n"
    expected = f"{POLICY_BEGIN}\n{expected_text.rstrip()}\n{POLICY_END}\n"
    if actual != expected:
        raise BatchProjectError("managed-block-source-drift", f"workspace managed block differs from declared source version: {path}")

def _validate_internal_adapters(output: Path, expected: dict[str, str]) -> None:
    for root_name in INTERNAL_ROOT_NAMES:
        root = output if root_name == "output" else output / root_name
        if not root.is_dir():
            raise BatchProjectError("internal-root-missing", f"Agent Protocol internal root is missing: {root}")
        for key, relative in ADAPTER_PATHS.items():
            path = root / relative
            if not path.is_file():
                raise BatchProjectError("internal-adapter-missing", f"Agent Protocol internal adapter is missing: {path}")
            try:
                actual = path.read_text(encoding="utf-8-sig")
            except UnicodeDecodeError as exc:
                raise BatchProjectError("internal-adapter-encoding", f"Agent Protocol internal adapter is not UTF-8: {path}") from exc
            if actual != expected[key]:
                raise BatchProjectError("internal-adapter-source-drift", f"Agent Protocol internal adapter differs from declared source version: {path}")

def _validate_structural_manifest(manifest: dict[str, Any]) -> tuple[list[Path], list[dict[str, Any]]]:
    reject_unknown_fields(manifest, MANIFEST_KEYS, "manifest")
    if manifest.get("schema_version") != BATCH_MANIFEST_SCHEMA_VERSION:
        raise CkbError(f"unsupported batch manifest schema_version: {manifest.get('schema_version')}")
    allowed_values = manifest.get("allowed_roots")
    if not isinstance(allowed_values, list) or not allowed_values:
        raise CkbError("batch manifest allowed_roots must be a non-empty list")
    allowed_roots = [require_absolute_path(value, f"allowed_roots[{index}]") for index, value in enumerate(allowed_values)]
    if len({str(path) for path in allowed_roots}) != len(allowed_roots):
        raise CkbError("batch manifest allowed_roots contains duplicates")
    for root in allowed_roots:
        if not root.is_dir():
            raise CkbError(f"batch manifest allowed root is missing: {root}")
    projects = manifest.get("projects")
    if not isinstance(projects, list) or not projects or len(projects) > MAX_BATCH_PROJECTS:
        raise CkbError(f"batch manifest projects must contain 1..{MAX_BATCH_PROJECTS} entries")
    identifiers: set[str] = set()
    outputs: list[Path] = []
    for index, project in enumerate(projects):
        if not isinstance(project, dict):
            raise CkbError(f"batch manifest projects[{index}] must be an object")
        reject_unknown_fields(project, PROJECT_KEYS, f"projects[{index}]")
        project_id = project.get("project_id")
        if not isinstance(project_id, str) or not re.fullmatch(r"[a-z0-9][a-z0-9._-]{0,63}", project_id):
            raise CkbError(f"batch manifest projects[{index}].project_id is invalid")
        if project_id in identifiers:
            raise CkbError(f"batch manifest project_id is duplicated: {project_id}")
        identifiers.add(project_id)
        output = require_absolute_path(project.get("output"), f"projects[{index}].output")
        if not _within_any(output, allowed_roots):
            raise CkbError(f"batch manifest OUTPUT escapes allowed_roots: {output}")
        outputs.append(output)
    for index, output in enumerate(outputs):
        for other in outputs[index + 1 :]:
            if output == other:
                raise CkbError(f"batch manifest OUTPUT is duplicated: {output}")
            if path_inside(output, other) or path_inside(other, output):
                raise CkbError(f"batch manifest OUTPUT values must not be nested: {output} ; {other}")
    return allowed_roots, projects

def load_batch_manifest(path: Path) -> dict[str, Any]:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise CkbError(f"batch manifest is missing: {path}")
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError("batch manifest root must be an object")
    _validate_structural_manifest(value)
    return value

def _inspect_project(project: dict[str, Any], allowed_roots: list[Path]) -> dict[str, Any]:
    project_id = str(project["project_id"])
    output = require_absolute_path(project.get("output"), f"{project_id}.output")
    source_version = str(project.get("source_version") or "")
    target_version = str(project.get("target_version") or "")
    if source_version not in PROTOCOL_RELEASES:
        raise BatchProjectError("source-version-unsupported", f"unsupported Agent Protocol source version: {source_version}")
    if target_version not in PROTOCOL_RELEASES:
        raise BatchProjectError("target-version-unsupported", f"unsupported Agent Protocol target version: {target_version}")
    try:
        path = supported_upgrade_path(source_version, target_version)
    except CkbError as exc:
        raise BatchProjectError("upgrade-path-missing", str(exc)) from exc
    if target_version != AGENT_PROTOCOL_VERSION:
        raise BatchProjectError(
            "target-version-not-current",
            f"batch upgrades must target the current Agent Protocol {AGENT_PROTOCOL_VERSION}: {target_version}",
        )
    if not output.is_dir():
        raise BatchProjectError("output-missing", f"knowledge OUTPUT is missing: {output}")
    state_path = output / "state.json"
    if not state_path.is_file():
        raise BatchProjectError("knowledge-state-missing", f"knowledge build state is missing: {state_path}")
    state = json_load(state_path)
    if not isinstance(state, dict) or not isinstance(state.get("repository"), dict) or not state["repository"].get("root"):
        raise BatchProjectError("knowledge-state-invalid", f"knowledge build state has no repository root: {state_path}")
    repository = str(state["repository"]["root"])
    protocol_path = output / "workspace-meta/agent-protocol.json"
    if not protocol_path.is_file():
        raise BatchProjectError("protocol-record-missing", f"Agent Protocol record is missing: {protocol_path}")
    record_bytes = protocol_path.read_bytes()
    record = json.loads(record_bytes.decode("utf-8-sig"))
    if not isinstance(record, dict):
        raise BatchProjectError("protocol-record-invalid", f"Agent Protocol record must be an object: {protocol_path}")
    if record.get("protocol_version") != source_version:
        raise BatchProjectError(
            "source-version-mismatch",
            f"Agent Protocol source version differs from manifest: {record.get('protocol_version')} != {source_version}",
        )
    expected_digest = project.get("expected_digest")
    if not isinstance(expected_digest, str) or not HEX_SHA256.fullmatch(expected_digest):
        raise BatchProjectError("expected-digest-invalid", f"expected_digest must be a lowercase SHA-256 for {project_id}")
    record_digest = _sha256_bytes(record_bytes)
    if record_digest != expected_digest:
        raise BatchProjectError("expected-digest-mismatch", f"Agent Protocol record digest differs from manifest for {project_id}")
    python = require_absolute_path(project.get("python"), f"{project_id}.python")
    ckb = require_absolute_path(project.get("ckb"), f"{project_id}.ckb")
    if not python.is_file():
        raise BatchProjectError("python-missing", f"Agent Protocol Python executable is missing: {python}")
    if not ckb.is_file():
        raise BatchProjectError("ckb-missing", f"Agent Protocol CKB entrypoint is missing: {ckb}")
    workspace_values = project.get("workspace_roots")
    if not isinstance(workspace_values, list) or len(workspace_values) > MAX_WORKSPACE_ROOTS:
        raise BatchProjectError("workspace-roots-invalid", f"workspace_roots must contain 0..{MAX_WORKSPACE_ROOTS} entries")
    workspace_roots = [require_absolute_path(value, f"{project_id}.workspace_roots[{index}]") for index, value in enumerate(workspace_values)]
    if len({str(root) for root in workspace_roots}) != len(workspace_roots):
        raise BatchProjectError("workspace-root-duplicate", f"workspace_roots contains duplicates for {project_id}")
    for root in workspace_roots:
        if not root.is_dir():
            raise BatchProjectError("workspace-root-missing", f"Agent Protocol workspace root is missing: {root}")
        if not _within_any(root, allowed_roots):
            raise BatchProjectError("workspace-root-out-of-bounds", f"workspace root escapes allowed_roots: {root}")
        repo_path = Path(repository)
        if not (path_inside(output, root) or (repo_path.is_absolute() and path_inside(repo_path, root))):
            raise BatchProjectError("workspace-root-unbound", f"workspace root contains neither repository nor OUTPUT: {root}")
    if {str(root) for root in workspace_roots} != {str(root) for root in _record_roots(record)}:
        raise BatchProjectError("workspace-root-record-mismatch", f"manifest workspace_roots differ from Agent Protocol record for {project_id}")
    harnesses = project.get("harnesses")
    if not isinstance(harnesses, list) or not harnesses or any(not isinstance(value, str) for value in harnesses):
        raise BatchProjectError("harnesses-invalid", f"harnesses must be a non-empty string list for {project_id}")
    if len(set(harnesses)) != len(harnesses):
        raise BatchProjectError("harness-duplicate", f"harnesses contains duplicates for {project_id}")
    unsupported = sorted(set(harnesses) - SUPPORTED_HARNESSES)
    if unsupported:
        raise BatchProjectError("harness-unsupported", f"unsupported Harness values for {project_id}: {', '.join(unsupported)}")
    source_python = Path(str(record.get("python") or "")).resolve()
    source_ckb = Path(str(record.get("ckb") or "")).resolve()
    expected_source = adapter_texts_for_version(source_version, output, repository, source_python, source_ckb)
    _validate_internal_adapters(output, expected_source)
    for root in workspace_roots:
        for key, relative in ADAPTER_PATHS.items():
            _validate_workspace_managed(root / relative, expected_source[key])
    files = snapshot_files(output, workspace_roots)
    observed_digest = snapshot_digest(files)
    risks = []
    if source_version != target_version:
        risks.append("managed-protocol-replacement")
    if workspace_roots:
        risks.append("workspace-user-content-boundary")
    if PROTOCOL_RELEASES[target_version].output_contract:
        risks.append("plugin-output-contract-parity")
    return {
        "project_id": project_id,
        "status": "ready",
        "action": (
            "noop"
            if source_version == target_version and source_python == python and source_ckb == ckb
            else "upgrade"
        ),
        "output": str(output),
        "repository": repository,
        "workspace_roots": [str(value) for value in workspace_roots],
        "source_version": source_version,
        "target_version": target_version,
        "upgrade_path": path,
        "harnesses": sorted(harnesses),
        "python": str(python),
        "ckb": str(ckb),
        "record_digest": record_digest,
        "observed_digest": observed_digest,
        "managed_files": files,
        "risks": sorted(risks),
        "rollback": {"command": f"agent-policy batch rollback --state STATE_PATH --project {project_id}"},
    }

def _load_batch_plan(path: Path) -> dict[str, Any]:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise CkbError(f"Agent Protocol batch plan is missing: {path}")
    plan = json_load(path)
    if not isinstance(plan, dict):
        raise CkbError("Agent Protocol batch plan root must be an object")
    if plan.get("schema_version") != BATCH_PLAN_SCHEMA_VERSION:
        raise CkbError(f"unsupported Agent Protocol batch plan schema: {plan.get('schema_version')}")
    digest = plan.get("plan_digest")
    body = {key: value for key, value in plan.items() if key != "plan_digest"}
    if not isinstance(digest, str) or _digest_value(body) != digest:
        raise CkbError("Agent Protocol batch plan digest mismatch")
    if not isinstance(plan.get("projects"), list) or not isinstance(plan.get("batch_id"), str):
        raise CkbError("Agent Protocol batch plan is structurally invalid")
    return plan

def _desired_project_files(project: dict[str, Any]) -> dict[str, bytes | None]:
    from .obsidian_plugin import obsidian_plugin_installation
    from .output_contract import OUTPUT_CONTRACT_RELATIVE, output_contract_for_runtime

    output = Path(project["output"]).resolve()
    previous = json_load(output / "workspace-meta/agent-protocol.json")
    record, texts = _target_record(project, previous)
    desired: dict[str, bytes | None] = {}
    desired[str((output / "workspace-meta/agent-protocol.json").resolve())] = _json_bytes(record)
    for root_name in INTERNAL_ROOT_NAMES:
        root = output if root_name == "output" else output / root_name
        for key, relative in ADAPTER_PATHS.items():
            desired[str((root / relative).resolve())] = texts[key].encode("utf-8")
    for root_value in project["workspace_roots"]:
        root = Path(root_value).resolve()
        for key, relative in ADAPTER_PATHS.items():
            path = (root / relative).resolve()
            if not path.is_file():
                raise BatchProjectError("managed-file-missing", f"workspace managed adapter is missing: {path}")
            desired[str(path)] = _replace_workspace_block_bytes(path.read_bytes(), texts[key], path)
    python = Path(project["python"]).resolve()
    ckb = Path(project["ckb"]).resolve()
    for root_name in ("human", "markdown"):
        vault = (output / root_name).resolve()
        contract_path = (vault / OUTPUT_CONTRACT_RELATIVE).resolve()
        installation = obsidian_plugin_installation(vault)
        required = PROTOCOL_RELEASES[str(project["target_version"])].output_contract and installation["installed"]
        desired[str(contract_path)] = (
            _json_bytes(output_contract_for_runtime(output, vault, python, ckb)) if required else None
        )
        ownership_path = (vault / ".ckb-generated-files.json").resolve()
        if ownership_path.is_file():
            ownership = json_load(ownership_path)
            files = {str(value) for value in ownership.get("files", [])}
            if required:
                files.add(OUTPUT_CONTRACT_RELATIVE.as_posix())
            else:
                files.discard(OUTPUT_CONTRACT_RELATIVE.as_posix())
            ownership["files"] = sorted(files)
            desired[str(ownership_path)] = _json_bytes(ownership)
        app_path = (vault / ".obsidian/app.json").resolve()
        app = json_load(app_path) if app_path.is_file() else {}
        app["userIgnoreFilters"] = list(dict.fromkeys([*app.get("userIgnoreFilters", []), *OBSIDIAN_IGNORES]))
        desired[str(app_path)] = _json_bytes(app)
        css_path = (vault / ".obsidian/snippets/ckb.css").resolve()
        css = css_path.read_text(encoding="utf-8") if css_path.is_file() else ""
        if OBSIDIAN_HIDE_CSS not in css:
            css = css.rstrip() + ("\n" if css.strip() else "") + OBSIDIAN_HIDE_CSS + "\n"
        desired[str(css_path)] = css.encode("utf-8")
    return desired

def _state_file(path: Path) -> dict[str, Any]:
    exists = path.is_file()
    return {
        "path": str(path.resolve()),
        "exists": exists,
        "sha256": _sha256_bytes(path.read_bytes()) if exists else None,
        "mode": stat.S_IMODE(path.stat().st_mode) if exists else None,
    }

def _desired_inventory(desired: dict[str, bytes | None]) -> list[dict[str, Any]]:
    result = []
    for path_value in sorted(desired):
        value = desired[path_value]
        path = Path(path_value)
        result.append(
            {
                "path": path_value,
                "exists": value is not None,
                "sha256": _sha256_bytes(value) if value is not None else None,
                "mode": stat.S_IMODE(path.stat().st_mode) if path.is_file() else 0o644,
            }
        )
    return result

def _restore_backup(manifest_path: Path) -> None:
    manifest_path = manifest_path.resolve()
    manifest = json_load(manifest_path)
    for item in manifest["files"]:
        path = Path(item["path"])
        if item["exists"]:
            blob = manifest_path.parent / item["backup_blob"]
            value = blob.read_bytes()
            if _sha256_bytes(value) != item["sha256"]:
                raise BatchProjectError("backup-verification-failed", f"backup blob drifted: {blob}")
            _write_bytes_atomic(path, value, int(item["mode"]))
        elif path.exists():
            if path.is_file():
                path.unlink()
            else:
                raise BatchProjectError("rollback-path-type-drift", f"rollback target became a directory: {path}")

def _commit_desired(desired: dict[str, bytes | None]) -> None:
    for path_value in sorted(desired):
        path = Path(path_value)
        value = desired[path_value]
        if value is None:
            if path.is_file():
                path.unlink()
            continue
        mode = stat.S_IMODE(path.stat().st_mode) if path.is_file() else 0o644
        _write_bytes_atomic(path, value, mode)
        if path.read_bytes() != value:
            raise BatchProjectError("atomic-write-verification-failed", f"managed file did not reopen exactly: {path}")

def _descriptor_lock(descriptor: int) -> bool:
    """Acquire one OS-released byte-range/advisory lock without waiting."""
    if os.name == "nt":
        import msvcrt

        os.lseek(descriptor, 0, os.SEEK_SET)
        try:
            msvcrt.locking(descriptor, msvcrt.LK_NBLCK, 1)
            return True
        except OSError:
            return False
    import fcntl

    try:
        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return True
    except (BlockingIOError, OSError):
        return False

def _descriptor_bytes(descriptor: int) -> bytes:
    os.lseek(descriptor, 0, os.SEEK_SET)
    chunks: list[bytes] = []
    while True:
        block = os.read(descriptor, 4096)
        if not block:
            return b"".join(chunks)
        chunks.append(block)

def _new_output_lock_record(owner_token: str) -> dict[str, Any]:
    state, identity = _process_start_identity(os.getpid())
    if state != "alive" or not identity:
        raise BatchProjectError(
            "output-lock-owner-identity-unavailable",
            f"current process identity is unavailable for OUTPUT lock: {os.getpid()}",
        )
    return {
        "schema_version": OUTPUT_LOCK_SCHEMA_VERSION,
        "owner_pid": os.getpid(),
        "owner_token": owner_token,
        "owner_process_start": identity,
        "owner_host": socket.gethostname(),
        "created_at_utc": utc_now(),
    }

def _parse_output_lock(value: bytes) -> tuple[dict[str, Any] | None, str | None]:
    try:
        record = json.loads(value.decode("utf-8-sig"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None, "output-lock-record-invalid"
    if not isinstance(record, dict) or set(record) != OUTPUT_LOCK_FIELDS:
        return None, "output-lock-record-invalid"
    if record.get("schema_version") != OUTPUT_LOCK_SCHEMA_VERSION:
        return None, "output-lock-record-invalid"
    if not isinstance(record.get("owner_pid"), int) or record["owner_pid"] < 1:
        return None, "output-lock-record-invalid"
    if not isinstance(record.get("owner_token"), str) or not OWNER_TOKEN_PATTERN.fullmatch(record["owner_token"]):
        return None, "output-lock-record-invalid"
    for field in ("owner_process_start", "owner_host", "created_at_utc"):
        if not isinstance(record.get(field), str) or not record[field] or len(record[field]) > 128:
            return None, "output-lock-record-invalid"
    return record, None

def _lock_owner_state(record: dict[str, Any]) -> str:
    if record["owner_host"] != socket.gethostname():
        return "output-lock-owner-unverifiable"
    state, identity = _process_start_identity(int(record["owner_pid"]))
    if state == "dead":
        return "output-lock-owner-dead"
    if state != "alive" or not identity:
        return "output-lock-owner-unverifiable"
    if identity != record["owner_process_start"]:
        return "output-lock-owner-pid-reused"
    return "concurrent-output-lock"

def _legacy_lock_owner_state(value: bytes) -> str | None:
    """Treat the former PID-only record conservatively during one-way recovery."""
    try:
        text = value.decode("ascii").strip()
        pid = int(text)
    except (UnicodeDecodeError, ValueError):
        return None
    state, _identity = _process_start_identity(pid)
    if state == "alive":
        return "output-lock-legacy-owner-live"
    if state == "dead":
        return "output-lock-legacy-owner-dead"
    return "output-lock-owner-unverifiable"

def _same_lock_file(lock: Path, descriptor: int) -> bool:
    try:
        left = os.fstat(descriptor)
        right = lock.stat()
    except FileNotFoundError:
        return False
    return (left.st_dev, left.st_ino) == (right.st_dev, right.st_ino)

def _release_output_lock(lock: Path, descriptor: int, owner_token: str) -> None:
    category: str | None = None
    try:
        if not _same_lock_file(lock, descriptor):
            category = "output-lock-release-file-replaced"
        else:
            record, invalid = _parse_output_lock(_descriptor_bytes(descriptor))
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "output-lock-release-owner-token-drift"
    finally:
        _descriptor_unlock(descriptor)
        os.close(descriptor)
    if category is None:
        try:
            record, invalid = _parse_output_lock(lock.read_bytes())
        except FileNotFoundError:
            category = "output-lock-release-missing"
        else:
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "output-lock-release-owner-token-drift"
            else:
                lock.unlink()
    if category:
        raise BatchProjectError(category, f"OUTPUT lock ownership changed before release: {lock}")

def _output_lock(output: Path):
    lock = output.resolve() / "workspace-meta/agent-policy-batch.lock"
    lock.parent.mkdir(parents=True, exist_ok=True)
    deadline = time.monotonic() + LOCK_TIMEOUT_SECONDS
    owner_token = uuid.uuid4().hex
    descriptor: int | None = None
    recovered_category: str | None = None
    last_category = "concurrent-output-lock"
    while descriptor is None:
        created = False
        try:
            candidate = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_RDWR, 0o600)
            created = True
            os.write(candidate, b" ")
        except FileExistsError:
            try:
                candidate = os.open(lock, os.O_RDWR)
            except FileNotFoundError:
                continue
        if not _descriptor_lock(candidate):
            os.close(candidate)
            last_category = "concurrent-output-lock"
        elif not _same_lock_file(lock, candidate):
            _descriptor_unlock(candidate)
            os.close(candidate)
            continue
        elif created:
            _write_lock_descriptor(candidate, _new_output_lock_record(owner_token))
            descriptor = candidate
        else:
            age = max(0.0, time.time() - os.fstat(candidate).st_mtime)
            record, invalid = _parse_output_lock(_descriptor_bytes(candidate))
            if invalid or record is None:
                legacy_state = _legacy_lock_owner_state(_descriptor_bytes(candidate))
                last_category = legacy_state or "output-lock-record-invalid"
                recover = age > LOCK_STALE_SECONDS and last_category in {
                    "output-lock-legacy-owner-dead",
                    "output-lock-record-invalid",
                }
                recovered_category = (
                    "output-lock-record-invalid-stale"
                    if recover and last_category == "output-lock-record-invalid"
                    else last_category if recover else None
                )
            else:
                last_category = _lock_owner_state(record)
                recover = age > LOCK_STALE_SECONDS and last_category in {
                    "output-lock-owner-dead",
                    "output-lock-owner-pid-reused",
                }
                recovered_category = last_category if recover else None
            if recover:
                _write_lock_descriptor(candidate, _new_output_lock_record(owner_token))
                descriptor = candidate
            else:
                _descriptor_unlock(candidate)
                os.close(candidate)
        if descriptor is None:
            if time.monotonic() >= deadline:
                raise BatchProjectError(last_category, f"Agent Protocol batch OUTPUT is busy: {output}")
            time.sleep(0.05)
    body_error = False
    try:
        yield {
            "schema_version": OUTPUT_LOCK_SCHEMA_VERSION,
            "owner_pid": os.getpid(),
            "owner_token": owner_token,
            "recovered_category": recovered_category,
            "_descriptor": descriptor,
        }
    except BaseException:
        body_error = True
        raise
    finally:
        try:
            _release_output_lock(lock, descriptor, owner_token)
        except BatchProjectError:
            if not body_error:
                raise

def _save_state(path: Path, state: dict[str, Any]) -> None:
    state["state_digest"] = _digest_value({key: value for key, value in state.items() if key != "state_digest"})
    json_write(path, state)

def _load_state(path: Path) -> dict[str, Any]:
    path = path.expanduser().resolve()
    if not path.is_file():
        raise CkbError(f"Agent Protocol batch state is missing: {path}")
    state = json_load(path)
    if not isinstance(state, dict) or state.get("schema_version") != BATCH_STATE_SCHEMA_VERSION:
        raise CkbError("Agent Protocol batch state schema is invalid")
    digest = state.get("state_digest")
    body = {key: value for key, value in state.items() if key != "state_digest"}
    if not isinstance(digest, str) or digest != _digest_value(body):
        raise CkbError("Agent Protocol batch state digest mismatch")
    return state

def _current_digest(project: dict[str, Any]) -> str:
    return snapshot_digest(
        snapshot_files(Path(project["output"]), [Path(value) for value in project.get("workspace_roots", [])])
    )

def _recovery_matches(project_state: dict[str, Any], backup: dict[str, Any]) -> bool:
    desired = {item["path"]: item for item in project_state.get("desired_files", [])}
    for original in backup["files"]:
        path = Path(original["path"])
        current = _state_file(path)
        allowed = {(bool(original["exists"]), original["sha256"])}
        target = desired.get(original["path"])
        if target:
            allowed.add((bool(target["exists"]), target["sha256"]))
        if original["role"] == "protocol-audit":
            continue
        if (bool(current["exists"]), current["sha256"]) not in allowed:
            return False
    return True

def _summarize_state(state: dict[str, Any]) -> str:
    statuses = [item["status"] for item in state["projects"].values()]
    if statuses and all(value in {"completed", "skipped", "rolled-back"} for value in statuses):
        return "completed"
    if any(value in {"completed", "skipped", "rolled-back"} for value in statuses):
        return "partial"
    if statuses and all(value == "failed" for value in statuses):
        return "failed"
    return "running"

def batch_status(state_path: Path) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_state(state_path)
    plan = _load_batch_plan(Path(state["plan"]))
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    projects = []
    drifted = 0
    for project_id in sorted(state["projects"]):
        item = dict(state["projects"][project_id])
        plan_project = plan_by_id[project_id]
        current_digest = None
        expected_digest = None
        if plan_project["status"] == "ready":
            current_digest = snapshot_digest(
                snapshot_files(
                    Path(plan_project["output"]),
                    [Path(value) for value in plan_project["workspace_roots"]],
                )
            )
            expected_digest = item["baseline_digest"] if item["status"] == "rolled-back" else item["applied_digest"]
            if expected_digest and current_digest != expected_digest:
                item["drift"] = {"category": "managed-bytes-drift", "expected": expected_digest, "actual": current_digest}
                drifted += 1
            else:
                item["drift"] = None
        item["current_digest"] = current_digest
        item["recovery"] = f"agent-policy batch rollback --state '{state_path}' --project {project_id}"
        projects.append(item)
    counts: dict[str, int] = {}
    for item in projects:
        counts[item["status"]] = counts.get(item["status"], 0) + 1
    status = "drifted" if drifted else state["status"]
    return {
        "schema_version": BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": status,
        "state": str(state_path),
        "plan": state["plan"],
        "summary": {"projects": len(projects), "drifted": drifted, "counts": dict(sorted(counts.items()))},
        "projects": projects,
        "event_count": len(state.get("events", [])),
    }

def audit_batch_state(state_path: Path) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_state(state_path)
    plan = _load_batch_plan(Path(state["plan"]))
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    results = []
    for project_id in sorted(state["projects"]):
        project_state = state["projects"][project_id]
        project = plan_by_id[project_id]
        errors = []
        audit = None
        if project["status"] != "ready":
            errors.append({"category": "plan-project-failed"})
        elif project_state["status"] in {"completed", "skipped"}:
            from .agent_protocol import audit_agent_protocol

            audit = audit_agent_protocol(Path(project["output"]))
            if audit.get("status") != "passed":
                errors.append({"category": "agent-policy-audit-failed", "evidence": str(Path(project["output"]) / "workspace-meta/agent-protocol-audit.json")})
            current = snapshot_digest(
                snapshot_files(Path(project["output"]), [Path(value) for value in project["workspace_roots"]])
            )
            if current != project_state["applied_digest"]:
                errors.append({"category": "applied-bytes-drift", "expected": project_state["applied_digest"], "actual": current})
            evidence = project_state.get("evidence")
            if not evidence or not Path(evidence).is_file():
                errors.append({"category": "batch-evidence-missing"})
        elif project_state["status"] == "rolled-back":
            current = snapshot_digest(
                snapshot_files(Path(project["output"]), [Path(value) for value in project["workspace_roots"]])
            )
            if current != project_state["baseline_digest"]:
                errors.append({"category": "rollback-bytes-drift", "expected": project_state["baseline_digest"], "actual": current})
        else:
            errors.append({"category": "project-not-complete", "status": project_state["status"]})
        result = {
            "project_id": project_id,
            "status": "passed" if not errors else "failed",
            "source_version": project_state["source_version"],
            "target_version": project_state["target_version"],
            "evidence": project_state.get("evidence"),
            "recovery": f"agent-policy batch rollback --state '{state_path}' --project {project_id}",
            "agent_policy": audit,
            "errors": errors,
        }
        results.append(result)
        if project["status"] == "ready" and Path(project["output"]).is_dir():
            evidence = _write_project_evidence(Path(project["output"]), state["batch_id"], project_state, "audit")
            project_state["evidence"] = str(evidence)
            _journal_batch_result(Path(project["output"]), "audit", result["status"], evidence)
    failed = sum(item["status"] == "failed" for item in results)
    _append_state_event(state, "batch", "audit", "passed" if failed == 0 else "failed", None if failed == 0 else "project-audit-failed")
    _save_state(state_path, state)
    return {
        "schema_version": BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 else "failed",
        "state": str(state_path),
        "summary": {"projects": len(results), "passed": len(results) - failed, "failed": failed},
        "projects": results,
    }

def rollback_batch_state(state_path: Path, project_ids: list[str] | None = None) -> dict[str, Any]:
    state_path = state_path.expanduser().resolve()
    state = _load_state(state_path)
    plan = _load_batch_plan(Path(state["plan"]))
    plan_by_id = {item["project_id"]: item for item in plan["projects"]}
    requested = sorted(set(project_ids or []))
    unknown = sorted(set(requested) - set(state["projects"]))
    if unknown:
        raise CkbError(f"unknown Agent Protocol batch rollback project: {', '.join(unknown)}")
    selected = requested or sorted(
        project_id
        for project_id, item in state["projects"].items()
        if item["status"] in {"completed", "skipped"}
    )
    if not selected:
        raise CkbError("Agent Protocol batch rollback has no completed project to restore")
    results = []
    for project_id in selected:
        project_state = state["projects"][project_id]
        project = plan_by_id[project_id]
        output = Path(project["output"]).resolve()
        result = {
            "project_id": project_id,
            "status": "failed",
            "source_version": project_state["source_version"],
            "target_version": project_state["target_version"],
            "failure": None,
            "evidence": project_state.get("evidence"),
        }
        try:
            if project_state["status"] == "rolled-back":
                current = snapshot_digest(
                    snapshot_files(output, [Path(value) for value in project["workspace_roots"]])
                )
                if current != project_state["baseline_digest"]:
                    raise BatchProjectError("rollback-post-drift", f"rolled-back project drifted: {project_id}")
                result["status"] = "skipped"
                results.append(result)
                continue
            if project_state["status"] not in {"completed", "skipped"}:
                raise BatchProjectError("rollback-project-not-complete", f"project is not rollback eligible: {project_id}")
            if not project_state.get("backup") or not Path(project_state["backup"]).is_file():
                raise BatchProjectError("rollback-backup-missing", f"rollback backup is missing: {project_id}")
            with _output_lock(output):
                current = snapshot_digest(
                    snapshot_files(output, [Path(value) for value in project["workspace_roots"]])
                )
                if current != project_state["applied_digest"]:
                    raise BatchProjectError(
                        "rollback-external-drift",
                        f"rollback refuses to overwrite managed bytes changed after batch apply: {project_id}",
                    )
                _restore_backup(Path(project_state["backup"]))
                restored = snapshot_digest(
                    snapshot_files(output, [Path(value) for value in project["workspace_roots"]])
                )
                if restored != project_state["baseline_digest"]:
                    raise BatchProjectError("rollback-verification-failed", f"rollback baseline digest mismatch: {project_id}")
                project_state["status"] = "rolled-back"
                project_state["failure"] = None
                evidence = _write_project_evidence(output, state["batch_id"], project_state, "rollback")
                project_state["evidence"] = str(evidence)
                _append_state_event(state, project_id, "rollback", "rolled-back")
                _save_state(state_path, state)
                _journal_batch_result(output, "rollback", "rolled-back", evidence)
                result["status"] = "passed"
                result["evidence"] = str(evidence)
        except BatchProjectError as exc:
            result["failure"] = {"category": exc.category, "detail": str(exc)}
            _append_state_event(state, project_id, "rollback", "failed", exc.category)
            _save_state(state_path, state)
        except (CkbError, OSError, ValueError, json.JSONDecodeError) as exc:
            result["failure"] = {"category": "rollback-failed", "detail": str(exc)}
            _append_state_event(state, project_id, "rollback", "failed", "rollback-failed")
            _save_state(state_path, state)
        results.append(result)
    state["status"] = _summarize_state(state)
    _save_state(state_path, state)
    failed = sum(item["status"] == "failed" for item in results)
    passed = sum(item["status"] == "passed" for item in results)
    return {
        "schema_version": BATCH_STATE_SCHEMA_VERSION,
        "batch_id": state["batch_id"],
        "status": "passed" if failed == 0 else "failed" if passed == 0 else "partial",
        "state": str(state_path),
        "summary": {"selected": len(results), "passed": passed, "skipped": len(results) - passed - failed, "failed": failed},
        "projects": results,
    }

def default_registry_path() -> Path:
    configured = os.environ.get("CKB_AUTOMATION_REGISTRY")
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "automation-registry.json"

def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    value = os.path.normcase(os.path.normpath(value))
    return value.replace("\\", "/").rstrip("/")

def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")

def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"schema_version": AUTOMATION_SCHEMA_VERSION, "projects": []}
    value = json_load(path)
    if value.get("schema_version") in {1, 2} and isinstance(value.get("projects"), list):
        # Earlier registries matched either the repository only or repository
        # plus workspace roots.  Read both through the current hard activation
        # contract; the next registry write upgrades the document atomically.
        value = {
            **value,
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "projects": [
                {
                    **item,
                    "workspace_roots": list(item.get("workspace_roots") or []),
                    "required_skill": REQUIRED_SKILL,
                    "require_skill_activation": True,
                }
                for item in value["projects"]
            ],
        }
    if value.get("schema_version") != AUTOMATION_SCHEMA_VERSION or not isinstance(value.get("projects"), list):
        raise CkbError(f"unsupported automation registry: {path}")
    for item in value["projects"]:
        item.setdefault("workspace_roots", [])
        item["required_skill"] = REQUIRED_SKILL
        item["require_skill_activation"] = True
    return value

def registry_status(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready",
        "registry": str(registry),
        "project_count": len(value["projects"]),
        "projects": value["projects"],
    }

def _registration_for_event(registry: Path, cwd: Path, harness: str) -> tuple[dict[str, Any], str, str] | None:
    candidates: list[tuple[int, int, dict[str, Any], str, str]] = []
    for item in _read_registry(registry)["projects"]:
        if not item.get("enabled", False) or harness not in item.get("harnesses", []):
            continue
        if _is_within(cwd, item["repo_root"]):
            root = str(item["repo_root"])
            candidates.append((2, len(_path_key(root)), item, "repository", root))
        for workspace_root in item.get("workspace_roots", []):
            if _is_within(cwd, workspace_root):
                candidates.append((1, len(_path_key(workspace_root)), item, "workspace", str(workspace_root)))
    if not candidates:
        return None
    best = max(candidates, key=lambda value: (value[0], value[1]))
    tied = [value for value in candidates if value[:2] == best[:2] and value[2]["registration_id"] != best[2]["registration_id"]]
    if tied:
        raise CkbError(f"automation event cwd matches multiple registrations at the same priority: {cwd}")
    return best[2], best[3], best[4]

def _event_path_text(value: str | Path, *, host_os: str | None = None) -> str:
    """Translate a harness path into the path syntax understood by this runtime.

    Codex Desktop can host ``app-server`` in WSL while a generated Hook invokes
    the bundled Windows Python through WSL interop.  The Hook payload then uses
    ``/mnt/<drive>/...`` even though ``pathlib`` in the receiving process expects
    a drive-letter path.  Normalize that boundary before registration matching
    and changed-path attribution; leave relative paths and native paths intact.
    """
    text = str(value).strip()
    if text.casefold().startswith("file:"):
        parsed = urlparse(text)
        if parsed.scheme.casefold() == "file":
            text = unquote(parsed.path)
            if parsed.netloc and parsed.netloc.casefold() != "localhost":
                text = f"//{parsed.netloc}{text}"
    target_os = os.name if host_os is None else host_os
    if target_os != "nt":
        return text
    normalized = text.replace("\\", "/")
    mounted = re.fullmatch(r"/mnt/([A-Za-z])(?:/(.*))?", normalized)
    if mounted:
        parts = [part for part in (mounted.group(2) or "").split("/") if part]
        return str(PureWindowsPath(f"{mounted.group(1).upper()}:\\", *parts))
    drive_uri = re.fullmatch(r"/([A-Za-z]):(?:/(.*))?", normalized)
    if drive_uri:
        parts = [part for part in (drive_uri.group(2) or "").split("/") if part]
        return str(PureWindowsPath(f"{drive_uri.group(1).upper()}:\\", *parts))
    return text

def _walk_values(value: Any) -> Iterator[tuple[str | None, Any]]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield str(key), child
            yield from _walk_values(child)
    elif isinstance(value, list):
        for child in value:
            yield None, child
            yield from _walk_values(child)

def _first_scalar(value: Any, keys: set[str]) -> str | None:
    lowered = {key.casefold() for key in keys}
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).casefold() in lowered and isinstance(child, (str, int)):
                text = str(child).strip()
                if text:
                    return text
        for child in value.values():
            found = _first_scalar(child, keys)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _first_scalar(child, keys)
            if found:
                return found
    return None

def _text_content(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts = [_text_content(item) for item in value]
        return "\n".join(item for item in parts if item)
    if isinstance(value, dict):
        direct = value.get("text")
        if isinstance(direct, str):
            return direct
        for key in ("content", "parts", "message", "delta", "info", "properties", "data"):
            if key in value:
                text = _text_content(value[key])
                if text:
                    return text
    return ""

def _event_name(raw: dict[str, Any]) -> str:
    for key in ("hook_event_name", "canonical_type", "event_type", "type"):
        value = raw.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    event = raw.get("event")
    if isinstance(event, dict) and isinstance(event.get("type"), str):
        return event["type"]
    return "unknown"

def _normalized_skill_name(value: Any) -> str:
    text = str(value or "").strip().casefold()
    return text.removeprefix("[").removesuffix("]").lstrip("$/").strip()

def _skill_name(raw: dict[str, Any], tool_name: str | None = None, tool_input: Any = None) -> str | None:
    for key, value in _walk_values(raw):
        if not key or key.casefold() not in _SKILL_METADATA_KEYS:
            continue
        values = value if isinstance(value, list) else [value]
        for item in values:
            if isinstance(item, dict):
                item = item.get("name") or item.get("skill") or item.get("skill_name")
            if _normalized_skill_name(item) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    if str(tool_name or "").casefold() == "skill" and isinstance(tool_input, dict):
        for key in ("skill", "name", "skill_name", "command"):
            if _normalized_skill_name(tool_input.get(key)) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    prompt = str(raw.get("prompt") or raw.get("initial_prompt") or "")
    if _SKILL_PROMPT.search(prompt):
        return REQUIRED_SKILL
    return None

def _extract_paths(value: Any) -> list[str]:
    result: list[str] = []
    for key, child in _walk_values(value):
        if key and key.casefold() in _PATH_KEYS:
            if isinstance(child, str):
                result.append(child)
            elif isinstance(child, list):
                result.extend(str(item) for item in child if isinstance(item, (str, Path)))
        if isinstance(child, str):
            result.extend(match.strip() for match in _PATCH_PATH.findall(child))
    return list(dict.fromkeys(path.strip() for path in result if path.strip()))

def _redact_text(text: str, custom: list[re.Pattern[str]], max_chars: int) -> tuple[str, list[str]]:
    types: list[str] = []
    result = text
    for name, pattern in _DEFAULT_STRING_REDACTIONS:
        if pattern.search(result):
            types.append(name)
            if name == "credential-assignment":
                result = pattern.sub(lambda match: f"{match.group(1)}{match.group(2)}[REDACTED:CREDENTIAL]", result)
            else:
                result = pattern.sub(f"[REDACTED:{name.upper()}]", result)
    for index, pattern in enumerate(custom, 1):
        if pattern.search(result):
            types.append(f"custom-{index}")
            result = pattern.sub(f"[REDACTED:CUSTOM-{index}]", result)
    encoded = result.encode("utf-8")
    if len(encoded) > max_chars:
        data = encoded[:max_chars]
        while True:
            try:
                result = data.decode("utf-8") + f"\n[TRUNCATED:{len(encoded) - len(data)}-BYTES]"
                break
            except UnicodeDecodeError as exc:
                data = data[: exc.start]
        types.append("size-limit")
    return result, types

def redact_event(event: dict[str, Any], custom_patterns: list[str], max_chars: int) -> dict[str, Any]:
    custom = [re.compile(pattern) for pattern in custom_patterns]
    redaction_types: list[str] = []

    def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

    result = redact(event)
    result["redaction_count"] = len(redaction_types)
    result["redaction_types"] = sorted(set(redaction_types))
    return result

def redact(value: Any, key: str | None = None) -> Any:
        if key and _SENSITIVE_KEY.search(key) and value not in (None, ""):
            redaction_types.append("sensitive-key")
            return "[REDACTED:SENSITIVE-KEY]"
        if isinstance(value, str):
            text, types = _redact_text(value, custom, max_chars)
            redaction_types.extend(types)
            return text
        if isinstance(value, dict):
            return {str(child_key): redact(child, str(child_key)) for child_key, child in value.items()}
        if isinstance(value, list):
            return [redact(child) for child in value[:200]]
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return str(value)

def _automation_root(output: Path) -> Path:
    root = output / "workspace-meta" / "automation"
    for relative in ("spool/pending", "spool/processed", "spool/failed", "pending-reviews"):
        (root / relative).mkdir(parents=True, exist_ok=True)
    return root

def _git_status_paths(repo: Path) -> list[str]:
    prefix_result = run(["git", "rev-parse", "--show-prefix"], cwd=repo)
    prefix = prefix_result.stdout.strip().replace("\\", "/") if prefix_result.returncode == 0 else ""
    completed = run(["git", "status", "--porcelain=v1", "-z", "--untracked-files=all", "--", "."], cwd=repo)
    if completed.returncode:
        return []
    values: list[str] = []
    for record in completed.stdout.split("\0"):
        if len(record) < 4:
            continue
        path = record[3:].strip()
        if " -> " in path:
            path = path.rsplit(" -> ", 1)[1]
        if path:
            path = path.replace("\\", "/")
            if prefix and path.startswith(prefix):
                path = path[len(prefix) :]
            path = path.removeprefix("./")
            if path and _change_path_allowed(path):
                values.append(path)
    return sorted(set(values))

def _change_path_allowed(relative: str) -> bool:
    path = Path(relative.replace("\\", "/"))
    return not any(part.casefold() in _IGNORED_CHANGE_PARTS for part in path.parts) and path.suffix.casefold() not in _IGNORED_CHANGE_SUFFIXES

def _working_file_state(repo: Path, paths: list[str]) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for relative in paths:
        path = repo / relative
        if not path.is_file():
            result[relative] = {"exists": False, "size": 0, "content_sha256": None}
            continue
        digest = hashlib.sha256()
        try:
            with path.open("rb") as handle:
                for block in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(block)
            result[relative] = {"exists": True, "size": path.stat().st_size, "content_sha256": digest.hexdigest()}
        except OSError:
            result[relative] = {"exists": path.exists(), "size": -1, "content_sha256": None}
    return result

def _relative_changed_paths(paths: list[str], repo: Path, output: Path, event_cwd: Path | None = None) -> list[str]:
    result: list[str] = []
    for value in paths:
        candidate = Path(_event_path_text(value))
        candidates = [candidate] if candidate.is_absolute() else [*([] if event_cwd is None else [event_cwd / candidate]), repo / candidate]
        for possible in candidates:
            if (
                not candidate.is_absolute()
                and event_cwd is not None
                and not _is_within(event_cwd, repo)
                and possible == repo / candidate
                and not possible.exists()
                and run(["git", "ls-files", "--error-unmatch", "--", candidate.as_posix()], cwd=repo).returncode != 0
            ):
                # A workspace-level relative path that is neither present nor
                # tracked in the source repository belongs to scratch/output,
                # not to an imaginary path with the same spelling under repo.
                continue
            try:
                resolved = possible.resolve()
            except OSError:
                continue
            if not _is_within(resolved, repo) or _is_within(resolved, output):
                continue
            try:
                relative = resolved.relative_to(repo.resolve()).as_posix()
            except ValueError:
                continue
            if relative and relative != "." and _change_path_allowed(relative):
                result.append(relative)
                break
    return sorted(set(result))

def _drain_lock(output: Path, timeout: float = 3.0) -> Iterator[bool]:
    root = _automation_root(output)
    lock = root / "drain.lock"
    deadline = time.monotonic() + timeout
    acquired = False
    while time.monotonic() < deadline:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, f"{os.getpid()}\n{time.time()}\n".encode("ascii"))
            os.close(descriptor)
            acquired = True
            break
        except (FileExistsError, PermissionError):
            try:
                if time.time() - lock.stat().st_mtime > 60:
                    lock.unlink()
                    continue
            except FileNotFoundError:
                continue
            time.sleep(0.05)
    try:
        yield acquired
    finally:
        if acquired:
            try:
                lock.unlink()
            except FileNotFoundError:
                pass

def default_session_id(harness: str) -> str | None:
    for key in ("CKB_SESSION_ID", *_SESSION_ENVIRONMENT.get(harness, ())):
        value = os.environ.get(key)
        if value and value.strip():
            return value.strip()
    return None

def _skill_activation(output: Path, repo: Path, harness: str, session_id: str) -> dict[str, Any] | None:
    path = output / AUTOMATION_DATABASE
    if not path.is_file():
        path = initialize_automation_database(output)
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        row = connection.execute(
            "SELECT activation_key,activation_source,activated_at_utc FROM skill_activations WHERE harness=? AND external_session_id=? AND repo_root=? AND skill_name=?",
            (harness, session_id, str(repo), REQUIRED_SKILL),
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        return None
    return {"activation_key": row[0], "activation_source": row[1], "activated_at_utc": row[2]}

def _remove_skill_activation(output: Path, repo: Path, harness: str, session_id: str) -> None:
    path = output / AUTOMATION_DATABASE
    if not path.is_file():
        return
    connection = sqlite3.connect(path, timeout=10)
    try:
        connection.execute(
            "DELETE FROM skill_activations WHERE harness=? AND external_session_id=? AND repo_root=? AND skill_name=?",
            (harness, session_id, str(repo), REQUIRED_SKILL),
        )
        connection.commit()
    finally:
        connection.close()

def _explicit_skill_application(event: dict[str, Any]) -> str | None:
    if event.get("skill_name") == REQUIRED_SKILL:
        if event["canonical_type"] == "skill.applied":
            return "native-skill-event"
        raw = event.get("raw") or {}
        if raw.get("ckb_skill_applied") is True:
            return "explicit-payload-field"
        if _SKILL_PROMPT.search(str(event.get("prompt") or "")):
            return "explicit-prompt-invocation"
        return "harness-skill-metadata"
    return None

def _resolve_turn(
    connection: sqlite3.Connection,
    event: dict[str, Any],
    session_key: str,
) -> tuple[str | None, str | None]:
    canonical = event["canonical_type"]
    if canonical in {"skill.applied", "session.start", "session.end"}:
        return None, None
    supplied = event.get("turn_id")
    if supplied:
        external = str(supplied)
        row = connection.execute("SELECT turn_key FROM turns WHERE session_key=? AND external_turn_id=?", (session_key, external)).fetchone()
        if row:
            return str(row[0]), external
        ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
        key = stable_id("autoturn", session_key, external)
        connection.execute(
            "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
            (key, session_key, external, ordinal, "active", event["received_at_utc"]),
        )
        return key, external
    active = connection.execute(
        "SELECT turn_key,external_turn_id,prompt FROM turns WHERE session_key=? AND status='active' ORDER BY ordinal DESC LIMIT 1",
        (session_key,),
    ).fetchone()
    if canonical == "turn.prompt":
        prompt = event.get("prompt") or ""
        if active and str(active[2]) == prompt:
            return str(active[0]), str(active[1])
        ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
        external = f"turn-{ordinal:06d}"
        key = stable_id("autoturn", session_key, external)
        connection.execute(
            "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
            (key, session_key, external, ordinal, "active", event["received_at_utc"]),
        )
        return key, external
    if active:
        return str(active[0]), str(active[1])
    if canonical in {"turn.assistant", "turn.stop", "compact.before", "compact.after"}:
        latest = connection.execute(
            "SELECT turn_key,external_turn_id FROM turns WHERE session_key=? ORDER BY ordinal DESC LIMIT 1",
            (session_key,),
        ).fetchone()
        if latest:
            return str(latest[0]), str(latest[1])
    ordinal = int(connection.execute("SELECT COALESCE(MAX(ordinal),0)+1 FROM turns WHERE session_key=?", (session_key,)).fetchone()[0])
    external = f"turn-{ordinal:06d}"
    key = stable_id("autoturn", session_key, external)
    connection.execute(
        "INSERT INTO turns(turn_key,session_key,external_turn_id,ordinal,status,started_at_utc) VALUES(?,?,?,?,?,?)",
        (key, session_key, external, ordinal, "active", event["received_at_utc"]),
    )
    return key, external

def _event_id(event: dict[str, Any], session_key: str, turn_key: str | None) -> str:
    explicit = event.get("external_event_id")
    if explicit:
        return stable_id("autoevent", event["harness"], explicit)
    identity_payload = {
        "canonical_type": event["canonical_type"],
        "prompt": event.get("prompt") or "",
        "assistant_message": event.get("assistant_message") or "",
        "tool_name": event.get("tool_name"),
        "tool_use_id": event.get("tool_use_id"),
        "changed_paths": event.get("changed_paths") or [],
        "source": event.get("source"),
    }
    return stable_id(
        "autoevent",
        event["harness"],
        session_key,
        turn_key or "session",
        event["canonical_type"],
        event.get("tool_use_id") or "",
        json.dumps(identity_payload, ensure_ascii=False, sort_keys=True),
    )

