def _markdown_sections(content: str) -> list[tuple[str, str]]:
    result: list[tuple[str, str]] = []
    heading = "正文"
    buffer: list[str] = []
    in_fence = False
    for line in content.replace("\r\n", "\n").splitlines():
        if line.lstrip().startswith(("```", "~~~")):
            in_fence = not in_fence
        match = None if in_fence else re.match(r"^#{1,6}\s+(.+?)\s*$", line)
        if match:
            if any(value.strip() for value in buffer):
                result.append((heading, "\n".join(buffer).strip()))
            heading = match.group(1).strip()
            buffer = []
        else:
            buffer.append(line)
    if any(value.strip() for value in buffer):
        result.append((heading, "\n".join(buffer).strip()))
    return result or [("正文", content.strip())]

def audit_machine_knowledge(output: Path, graph: dict[str, Any] | None = None) -> dict[str, Any]:
    output = output.resolve()
    graph = graph or json_load(output / "graph.json")
    path = output / MACHINE_PATH
    errors: list[dict[str, Any]] = []
    if not path.is_file():
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "failed", "path": str(path), "errors": [{"reason": "machine-sqlite-missing"}]}
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        counts = {
            name: connection.execute(f"SELECT count(*) FROM {name}").fetchone()[0]
            for name in ("files", "entities", "source_ranges", "relations", "reviews", "documents", "sections", "human_projection", "workspace_changes", "reference_sources", "research_gaps")
        }
        meta = dict(connection.execute("SELECT key,value FROM meta"))
        language_errors = [
            row[0]
            for row in connection.execute(
                """
                SELECT entity_id FROM entities
                WHERE (classification='appendix' AND description_zh NOT GLOB '*[一-龥]*')
                   OR (classification<>'appendix' AND (meaning_zh NOT GLOB '*[一-龥]*' OR role_zh NOT GLOB '*[一-龥]*' OR change_when_zh NOT GLOB '*[一-龥]*'))
                   OR evidence_note NOT GLOB '*[一-龥]*'
                """
            )
        ]
        fts_counts = {
            "entity_fts": connection.execute("SELECT count(*) FROM entity_fts").fetchone()[0],
            "section_fts": connection.execute("SELECT count(*) FROM section_fts").fetchone()[0],
            "source_fts": connection.execute("SELECT count(*) FROM source_fts").fetchone()[0],
        }
    finally:
        connection.close()
    expected_entities = len(graph.get("entities", []))
    expected_files = len([entity for entity in graph.get("entities", []) if entity.get("kind") == "file"])
    expected_relations = len(graph.get("links", []))
    from .reference_documents import reference_machine_records
    from .research_gaps import gap_machine_records

    reference_records = reference_machine_records(output)
    gap_records = gap_machine_records(output)
    if integrity != "ok": errors.append({"reason": "sqlite-integrity", "detail": integrity})
    if foreign_keys: errors.append({"reason": "foreign-key-errors", "detail": foreign_keys})
    for name, actual, expected in (
        ("entities", counts["entities"], expected_entities),
        ("source_ranges", counts["source_ranges"], expected_entities),
        ("reviews", counts["reviews"], expected_entities),
        ("human_projection", counts["human_projection"], expected_entities),
        ("files", counts["files"], expected_files),
        ("relations", counts["relations"], expected_relations),
        ("entity_fts", fts_counts["entity_fts"], expected_entities),
        ("source_fts", fts_counts["source_fts"], expected_files),
    ):
        if actual != expected:
            errors.append({"reason": f"{name}-count-mismatch", "actual": actual, "expected": expected})
    if fts_counts["section_fts"] != counts["sections"]:
        errors.append({"reason": "section-fts-count-mismatch", "actual": fts_counts["section_fts"], "expected": counts["sections"]})
    if counts["reference_sources"] != len(reference_records["sources"]):
        errors.append({"reason": "reference-source-count-mismatch", "actual": counts["reference_sources"], "expected": len(reference_records["sources"])})
    if counts["research_gaps"] != len(gap_records["records"]):
        errors.append({"reason": "research-gap-count-mismatch", "actual": counts["research_gaps"], "expected": len(gap_records["records"])})
    reference_documents = counts["documents"] - expected_entities - len(_note_documents(_human_projection(output)[1])) - len(gap_records["documents"])
    if reference_documents != len(reference_records["documents"]):
        errors.append({"reason": "reference-document-count-mismatch", "actual": reference_documents, "expected": len(reference_records["documents"])})
    if language_errors:
        errors.append({"reason": "chinese-description-contract", "entities": language_errors})
    if meta.get("schema_version") != str(MACHINE_SCHEMA_VERSION) or meta.get("status") != "ready":
        errors.append({"reason": "machine-meta-incompatible", "meta": meta})
    result = {
        "schema_version": MACHINE_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "path": str(path.resolve()),
        "integrity": integrity,
        "counts": counts,
        "fts_counts": fts_counts,
        "language_contract": meta.get("language_contract"),
        "retrieval": meta.get("retrieval"),
        "errors": errors,
    }
    json_write(output / "machine/audit.json", result)
    return result

def _fast_graph_scores(
    seeds: list[str],
    seed_scores: dict[str, float],
    adjacency: dict[str, list[tuple[str, float, str]]],
    degree: dict[str, int],
) -> dict[str, float]:
    result: dict[str, float] = defaultdict(float)
    frontier = {seed: seed_scores[seed] for seed in seeds}
    for depth in (1, 2):
        next_frontier: dict[str, float] = defaultdict(float)
        for source in sorted(frontier):
            source_score = frontier[source]
            outgoing = adjacency.get(source, [])
            total = sum(weight for _target, weight, _relation in outgoing) or 1.0
            for target, weight, _relation in outgoing:
                contribution = source_score * (0.28 if depth == 1 else 0.10) * weight / total / math.sqrt(max(1, degree.get(target, 1)))
                if contribution > next_frontier[target]:
                    next_frontier[target] = contribution
                result[target] += contribution
        frontier = next_frontier
    return dict(result)

def _deterministic_ppr(
    seeds: list[str],
    seed_scores: dict[str, float],
    adjacency: dict[str, list[tuple[str, float, str]]],
    degree: dict[str, int],
    iterations: int = 24,
    restart: float = 0.22,
) -> dict[str, float]:
    if not seeds:
        return {}
    total_seed = sum(max(seed_scores[value], 0.0) for value in seeds) or float(len(seeds))
    personalization = {value: max(seed_scores[value], 0.0) / total_seed for value in seeds}
    scores = dict(personalization)
    for _ in range(iterations):
        updated: dict[str, float] = defaultdict(float)
        dangling = 0.0
        for source in sorted(scores):
            source_score = scores[source]
            outgoing = adjacency.get(source, [])
            if not outgoing:
                dangling += source_score
                continue
            normalized = [
                (target, weight / math.sqrt(max(1, degree.get(target, 1))))
                for target, weight, _relation in outgoing
            ]
            total = sum(weight for _target, weight in normalized) or 1.0
            for target, weight in normalized:
                updated[target] += (1.0 - restart) * source_score * weight / total
        for seed, probability in personalization.items():
            updated[seed] += restart * probability + (1.0 - restart) * dangling * probability
        scores = {key: updated[key] for key in sorted(updated)}
    return scores

def _next_pack_path(output: Path) -> tuple[Path, Path]:
    directory = output / "machine/agent-packs"
    directory.mkdir(parents=True, exist_ok=True)
    prefix = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    for counter in range(1, 1000):
        markdown = directory / f"pack-{prefix}-{counter:02d}.md"
        record = markdown.with_suffix(".json")
        if not markdown.exists() and not record.exists():
            return markdown, record
    raise CkbError("machine pack name space is exhausted")

def _sql_placeholders(values: Iterable[Any]) -> str:
    items = list(values)
    if not items:
        raise CkbError("SQL placeholder list must not be empty")
    return ",".join("?" for _ in items)

def _utf8_prefix(value: str, maximum_bytes: int) -> str:
    if maximum_bytes <= 0:
        return ""
    data = value.encode("utf-8")[:maximum_bytes]
    while data:
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            data = data[: exc.start]
    return ""

def _bulk_entity_context(
    connection: sqlite3.Connection,
    entity_ids: list[str],
) -> tuple[dict[str, sqlite3.Row], dict[str, list[sqlite3.Row]]]:
    if not entity_ids:
        return {}, {}
    placeholders = _sql_placeholders(entity_ids)
    entity_rows = {
        row["entity_id"]: row
        for row in connection.execute(
            f"SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode "
            f"FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id) "
            f"WHERE e.entity_id IN ({placeholders})",
            entity_ids,
        )
    }
    sections: dict[str, list[sqlite3.Row]] = defaultdict(list)
    for row in connection.execute(
        f"SELECT d.source_entity_id,s.* FROM sections s JOIN documents d ON d.document_id=s.document_id "
        f"WHERE d.source_entity_id IN ({placeholders}) ORDER BY d.source_entity_id,s.ordinal",
        entity_ids,
    ):
        sections[row["source_entity_id"]].append(row)
    return entity_rows, sections

def _diverse_candidates(
    ordered_ids: list[str],
    entity_rows: dict[str, sqlite3.Row],
    limit: int,
) -> list[str]:
    selected: list[str] = []
    selected_set: set[str] = set()
    paths: set[str] = set()
    for entity_id in ordered_ids:
        row = entity_rows.get(entity_id)
        if row is None or row["source_path"] in paths:
            continue
        selected.append(entity_id)
        selected_set.add(entity_id)
        paths.add(row["source_path"])
        if len(selected) >= limit:
            return selected
    for entity_id in ordered_ids:
        if entity_id in selected_set or entity_id not in entity_rows:
            continue
        selected.append(entity_id)
        if len(selected) >= limit:
            break
    return selected

def _static_retrieval_context(
    connection: sqlite3.Connection,
    output: Path,
    entity_columns: set[str],
    key: str,
) -> dict[str, Any] | None:
    required_columns = {
        "entity_id",
        "kind",
        "name",
        "qualified_name",
        "source_path",
        "meaning_zh",
        "role_zh",
        "change_when_zh",
        "description_zh",
    }
    tables = {
        str(row[0])
        for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")
    }
    if not required_columns.issubset(entity_columns) or not {"source_ranges", "human_projection", "sections", "documents"}.issubset(tables):
        return None
    metadata_rows = [
        dict(row)
        for row in connection.execute(
            "SELECT entity_id,kind,name,qualified_name,source_path,meaning_zh,role_zh,change_when_zh,description_zh FROM entities"
        )
    ]
    entity_rows = {
        row["entity_id"]: dict(row)
        for row in connection.execute(
            "SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode "
            "FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id)"
        )
    }
    sections: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in connection.execute(
        "SELECT d.source_entity_id,s.* FROM sections s JOIN documents d ON d.document_id=s.document_id "
        "WHERE d.source_entity_id IS NOT NULL ORDER BY d.source_entity_id,s.ordinal"
    ):
        sections[row["source_entity_id"]].append(dict(row))
    adjacency, degree = _adjacency(connection)
    value = {
        "metadata_rows": metadata_rows,
        "entity_rows": entity_rows,
        "sections": dict(sections),
        "adjacency": adjacency,
        "degree": degree,
        "linker": SourceLinkRenderer(_openers(output), trusted_relative_paths=True),
        "entity_columns": entity_columns,
    }
    _RETRIEVAL_STATIC_CACHE.clear()
    _RETRIEVAL_STATIC_CACHE[key] = value
    return value

def _openers(output: Path) -> dict[str, Any]:
    path = output / "local-openers.json"
    if path.is_file():
        return json_load(path)
    state = json_load(output / "state.json")
    return {
        "source_editor": "vscode",
        "working_repo_root": state["repository"]["root"],
        "baseline_snapshot_root": (state.get("source_snapshot") or {}).get("root"),
        "source_view": "working",
        "show_source_range": True,
        "custom_template": None,
    }

def _matching_documents(connection: sqlite3.Connection, fts: str | None, limit: int = 8) -> list[dict[str, Any]]:
    if not fts:
        return []
    tables = {str(row[0]) for row in connection.execute("SELECT name FROM sqlite_master WHERE type IN ('table','view')")}
    if not {"section_fts", "sections", "documents"}.issubset(tables):
        return []
    rows = connection.execute(
        "SELECT d.document_id,d.title,d.kind,d.human_file,s.heading,s.content,s.source_path,s.start_line,s.end_line,"
        "bm25(section_fts,0.0,0.0,6.0,2.0,1.0) AS rank "
        "FROM section_fts JOIN sections s ON s.section_id=section_fts.section_id "
        "JOIN documents d ON d.document_id=section_fts.document_id "
        "WHERE section_fts MATCH ? AND d.kind<>'entity' ORDER BY rank,d.document_id,s.ordinal LIMIT 80",
        (fts,),
    ).fetchall()
    result: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        if row["document_id"] in seen:
            continue
        seen.add(row["document_id"])
        result.append(dict(row))
        if len(result) >= limit:
            break
    return result

def _attach_keyword_fallback(
    output: Path,
    question: str,
    result: dict[str, Any],
    metadata: dict[str, Any],
) -> dict[str, Any]:
    record_path = write_keyword_fallback_record(output, question, metadata)
    metadata = {**metadata, "record": str(record_path.resolve())}
    result = {**result, "keyword_fallback": metadata, "keyword_fallback_record": str(record_path.resolve())}
    retrieval_record = result.get("record")
    if isinstance(retrieval_record, str) and Path(retrieval_record).is_file():
        persisted = json_load(Path(retrieval_record))
        if isinstance(persisted, dict):
            persisted["keyword_fallback"] = metadata
            persisted["keyword_fallback_record"] = str(record_path.resolve())
            json_write(Path(retrieval_record), persisted)
    return result

def entity_lookup(output: Path, selector: str) -> dict[str, Any]:
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        rows = connection.execute(
            "SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id) WHERE e.entity_id=? OR e.name=? COLLATE NOCASE OR e.qualified_name=? COLLATE NOCASE ORDER BY e.qualified_name LIMIT 20",
            (selector, selector, selector),
        ).fetchall()
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed" if rows else "not-found", "selector": selector, "candidates": [dict(row) for row in rows]}

def neighbor_lookup(output: Path, selector: str, depth: int = 1, relation: str | None = None, limit: int = 50) -> dict[str, Any]:
    if depth < 1 or depth > 6:
        raise CkbError("neighbor depth must be in [1, 6]")
    found = entity_lookup(output, selector)
    if len(found["candidates"]) != 1:
        return {**found, "reason": "selector must match exactly one entity"}
    root_id = found["candidates"][0]["entity_id"]
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        visited = {root_id}
        frontier = {root_id}
        rows: list[dict[str, Any]] = []
        for current_depth in range(1, depth + 1):
            next_frontier: set[str] = set()
            for entity_id in sorted(frontier):
                query = "SELECT * FROM relations WHERE (source_entity_id=? OR target_entity_id=?)"
                params: list[Any] = [entity_id, entity_id]
                if relation:
                    query += " AND relation=?"
                    params.append(relation)
                query += " ORDER BY relation_id"
                for row in connection.execute(query, params):
                    target = row["target_entity_id"] if row["source_entity_id"] == entity_id else row["source_entity_id"]
                    entity = connection.execute("SELECT name,qualified_name,source_path FROM entities WHERE entity_id=?", (target,)).fetchone()
                    rows.append({"depth": current_depth, "from": entity_id, "entity_id": target, "relation": row["relation"], "direction": "outgoing" if row["source_entity_id"] == entity_id else "incoming", **dict(entity)})
                    if target not in visited:
                        visited.add(target)
                        next_frontier.add(target)
                    if len(rows) >= limit:
                        break
                if len(rows) >= limit:
                    break
            frontier = next_frontier
            if not frontier or len(rows) >= limit:
                break
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "selector": selector, "root_entity_id": root_id, "depth": depth, "relation": relation, "neighbors": rows}

def source_lookup(output: Path, selector: str, context_lines: int = 3) -> dict[str, Any]:
    found = entity_lookup(output, selector)
    if len(found["candidates"]) != 1:
        return {**found, "reason": "selector must match exactly one entity"}
    entity = found["candidates"][0]
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        row = connection.execute("SELECT source_text FROM files WHERE path=?", (entity["source_path"],)).fetchone()
    finally:
        connection.close()
    if row is None:
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "not-found", "selector": selector, "reason": "source file is absent from the fixed snapshot"}
    lines = row[0].splitlines()
    start = max(1, int(entity["start_line"]) - context_lines)
    end = min(len(lines), int(entity["end_line"]) + context_lines)
    excerpt = "\n".join(f"{index:>6}  {lines[index - 1]}" for index in range(start, end + 1))
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "selector": selector, "entity_id": entity["entity_id"], "source_path": entity["source_path"], "start_line": start, "end_line": end, "excerpt": excerpt}

def sync_workspace_changes(output: Path) -> dict[str, Any]:
    path = output / MACHINE_PATH
    overlay = output / "workspace-meta/working-overlay.json"
    if not path.is_file() or not overlay.is_file():
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "skipped", "reason": "machine database or working overlay is absent"}
    value = json_load(overlay)
    connection = sqlite3.connect(path)
    try:
        connection.execute("DELETE FROM workspace_changes")
        detail = json.dumps(value, ensure_ascii=False, sort_keys=True)
        for changed in value.get("changed_paths", []):
            connection.execute("INSERT INTO workspace_changes VALUES(?,?,?)", (changed, "changed", detail))
        for untracked in value.get("untracked_paths", []):
            connection.execute("INSERT INTO workspace_changes VALUES(?,?,?)", (untracked, "untracked", detail))
        connection.commit()
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "changed": len(value.get("changed_paths", [])), "untracked": len(value.get("untracked_paths", []))}

def default_management_registry_path() -> Path:
    configured = os.environ.get(MANAGEMENT_REGISTRY_ENV)
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "management-bindings.json"

def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    return os.path.normcase(os.path.normpath(value)).replace("\\", "/").rstrip("/")

def _empty_registry() -> dict[str, Any]:
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "bindings": [],
        "tasks": [],
        "audit_log": [],
    }

def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return _empty_registry()
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"management registry must be one JSON object: {path}")
    if value.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"unsupported management registry: {path}")
    for field in ("bindings", "tasks", "audit_log"):
        if not isinstance(value.get(field), list):
            raise CkbError(f"management registry field must be a list: {field}")
    return value

def _registry_lock(path: Path, timeout: float = 30.0) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = path.with_name(path.name + ".lock")
    deadline = time.monotonic() + timeout
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, f"{os.getpid()}\n{time.time()}\n".encode("ascii"))
        except (FileExistsError, PermissionError):
            try:
                if time.time() - lock.stat().st_mtime > 60:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"management registry is busy: {path}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)

def harness_capabilities(harness_id: str) -> dict[str, dict[str, Any]]:
    harness = harness_id.strip().casefold()
    if harness not in SUPPORTED_HARNESSES:
        return {
            "binding": _capability(True, "generic-cli"),
            "prompt_injection": _capability(False, "no-adapter"),
            "event_sync": _capability(False, "no-adapter"),
            "task_dispatch": _capability(False, "no-adapter"),
        }
    return {
        "binding": _capability(True, "manager-cli"),
        "prompt_injection": _capability(False, "manual-context"),
        "event_sync": _capability(True, "generic-json" if harness == "generic" else "automation-adapter"),
        "task_dispatch": _capability(True, "manager-cli"),
    }

def canonical_binding_input(payload: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    if not isinstance(payload, dict):
        raise CkbError("management binding input must be one JSON object")
    if payload.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"management binding requires schema_version={MANAGEMENT_SCHEMA_VERSION}")
    allowed = set(binding_schema()["properties"])
    ignored = sorted(str(key) for key in payload if key not in allowed)
    value = {key: payload[key] for key in allowed if key in payload and key != "capabilities"}
    required = set(binding_schema()["required"])
    missing = sorted(field for field in required if not isinstance(value.get(field), (str, int)) or not str(value[field]).strip())
    if missing:
        raise CkbError(f"management binding input is missing required fields: {missing}")
    if int(value["schema_version"]) != MANAGEMENT_SCHEMA_VERSION:
        raise CkbError(f"management binding requires schema_version={MANAGEMENT_SCHEMA_VERSION}")
    for field in ("conversation_id", "harness_id"):
        text = str(value[field]).strip()
        if not _OPAQUE_ID.fullmatch(text):
            raise CkbError(f"management binding {field} must be bounded opaque text")
        value[field] = text
    value["harness_id"] = str(value["harness_id"]).casefold()
    policy = str(value.get("notification_policy", "none")).strip().casefold()
    if policy not in NOTIFICATION_POLICIES:
        raise CkbError(f"unsupported management notification policy: {policy}")
    value["notification_policy"] = policy
    for field in ("workspace_root", "repo_root", "knowledge_base"):
        value[field] = _normalized_path(str(value[field]))
    value["integration_branch"] = str(value["integration_branch"]).strip()
    value["capabilities"] = harness_capabilities(value["harness_id"])
    return value, ignored

def _privacy_errors(value: Any, location: str = "registry") -> list[str]:
    errors: list[str] = []
    if isinstance(value, dict):
        for key, child in value.items():
            lowered = str(key).casefold().replace("-", "_")
            if lowered in _FORBIDDEN_INPUT_FIELDS:
                errors.append(f"{location}: forbidden persisted field: {key}")
            errors.extend(_privacy_errors(child, f"{location}.{key}"))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            errors.extend(_privacy_errors(child, f"{location}[{index}]"))
    return errors

def audit_manager_registry(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_management_registry_path()).expanduser().resolve()
    try:
        value = _read_registry(registry)
    except CkbError as exc:
        return {
            "schema_version": MANAGEMENT_SCHEMA_VERSION,
            "status": "failed",
            "registry": str(registry),
            "binding_count": 0,
            "task_count": 0,
            "errors": [str(exc)],
        }
    errors = _privacy_errors(value)
    binding_ids: set[str] = set()
    active_identities: set[tuple[str, str]] = set()
    for index, binding in enumerate(value["bindings"]):
        prefix = f"binding[{index}]"
        if not isinstance(binding, dict):
            errors.append(f"{prefix}: binding must be an object")
            continue
        binding_id = binding.get("binding_id")
        if not isinstance(binding_id, str) or not binding_id.startswith("manager-binding-"):
            errors.append(f"{prefix}: invalid binding_id")
        elif binding_id in binding_ids:
            errors.append(f"{prefix}: duplicate binding_id")
        else:
            binding_ids.add(binding_id)
        if binding.get("schema_version") != MANAGEMENT_SCHEMA_VERSION:
            errors.append(f"{prefix}: schema version mismatch")
        if binding.get("status") not in _BINDING_STATUSES:
            errors.append(f"{prefix}: unsupported status")
        identity = (str(binding.get("harness_id", "")).casefold(), str(binding.get("conversation_id", "")))
        if binding.get("status") == "active":
            if identity in active_identities:
                errors.append(f"{prefix}: duplicate active conversation identity")
            active_identities.add(identity)
        capabilities = binding.get("capabilities")
        if not isinstance(capabilities, dict) or set(capabilities) != set(MANAGEMENT_CAPABILITIES):
            errors.append(f"{prefix}: capability set differs from canonical schema")
        for field in ("workspace_root", "repo_root", "knowledge_base"):
            path = binding.get(field)
            if not isinstance(path, str) or _path_key(path) != _path_key(_normalized_path(path)):
                errors.append(f"{prefix}: {field} is not normalized")
    dispatch_ids: set[str] = set()
    for index, task in enumerate(value["tasks"]):
        prefix = f"task[{index}]"
        if not isinstance(task, dict):
            errors.append(f"{prefix}: task must be an object")
            continue
        dispatch_id = task.get("dispatch_id")
        if not isinstance(dispatch_id, str) or not dispatch_id.startswith("manager-task-"):
            errors.append(f"{prefix}: invalid dispatch_id")
        elif dispatch_id in dispatch_ids:
            errors.append(f"{prefix}: duplicate dispatch_id")
        else:
            dispatch_ids.add(dispatch_id)
        if task.get("binding_id") not in binding_ids:
            errors.append(f"{prefix}: binding_id does not exist")
        if task.get("status") not in _TASK_STATUSES:
            errors.append(f"{prefix}: unsupported status")
        prompt_path = Path(str(task.get("prompt_path", "")))
        if not prompt_path.is_file():
            errors.append(f"{prefix}: task prompt is missing")
        elif hashlib.sha256(prompt_path.read_bytes()).hexdigest() != task.get("prompt_sha256"):
            errors.append(f"{prefix}: task prompt hash mismatch")
        verification_value = task.get("verification_path")
        if verification_value:
            verification_path = Path(str(verification_value))
            if not verification_path.is_file():
                errors.append(f"{prefix}: task verification is missing")
            elif hashlib.sha256(verification_path.read_bytes()).hexdigest() != task.get("verification_sha256"):
                errors.append(f"{prefix}: task verification hash mismatch")
    for index, event in enumerate(value["audit_log"]):
        if not isinstance(event, dict) or set(event) != {
            "schema_version", "event_id", "binding_id", "action", "status", "reason", "recorded_at_utc"
        }:
            errors.append(f"audit_log[{index}]: fields differ from the canonical audit schema")
    return {
        "schema_version": MANAGEMENT_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "registry": str(registry),
        "binding_count": len(value["bindings"]),
        "active_bindings": sum(item.get("status") == "active" for item in value["bindings"] if isinstance(item, dict)),
        "task_count": len(value["tasks"]),
        "audit_events": len(value["audit_log"]),
        "errors": errors,
    }

def _git(repo: Path, *arguments: str, allow_failure: bool = False) -> str | None:
    completed = run(["git", "-C", str(repo), *arguments], timeout=60)
    if completed.returncode:
        if allow_failure:
            return None
        detail = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"management Git command failed: git -C {repo} {' '.join(arguments)}: {detail}")
    return completed.stdout.strip()

def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")

def _git_preflight(
    workspace_root: Path,
    repo_root: Path,
    knowledge_base: Path,
    integration_branch: str,
) -> dict[str, Any]:
    if not workspace_root.is_dir():
        raise CkbError(f"management workspace does not exist: {workspace_root}")
    if not repo_root.is_dir():
        raise CkbError(f"management repository does not exist: {repo_root}")
    if not (_is_within(repo_root, workspace_root) or _is_within(workspace_root, repo_root)):
        raise CkbError("management workspace must contain the repository or be inside it")
    if not knowledge_base.is_dir():
        raise CkbError(f"management knowledge base does not exist: {knowledge_base}")
    if not (knowledge_base / "state.json").is_file():
        raise CkbError(f"management knowledge base is missing state.json: {knowledge_base}")
    top = _git(repo_root, "rev-parse", "--show-toplevel", allow_failure=True)
    if not top or _path_key(top) != _path_key(repo_root):
        raise CkbError(f"management repo_root must be the root of a Git worktree: {repo_root}")
    current_branch = _git(repo_root, "symbolic-ref", "--quiet", "--short", "HEAD", allow_failure=True)
    if not current_branch:
        raise CkbError(f"management integration repository has no attached branch: {repo_root}")
    if current_branch != integration_branch:
        raise CkbError(
            f"management integration branch mismatch: expected={integration_branch}; current={current_branch}"
        )
    branch_head = _git(repo_root, "rev-parse", "--verify", f"refs/heads/{integration_branch}^{{commit}}", allow_failure=True)
    if not branch_head:
        raise CkbError(f"management integration branch does not exist: {integration_branch}")
    current_head = _git(repo_root, "rev-parse", "--verify", "HEAD", allow_failure=True)
    if not current_head:
        raise CkbError(f"management integration repository has no HEAD: {repo_root}")
    dirty = (_git(repo_root, "status", "--porcelain=v1", "--untracked-files=all") or "").splitlines()
    if dirty:
        raise CkbError(f"management integration worktree must be clean: {repo_root}; paths={dirty[:12]}")
    return {
        "workspace_root": str(workspace_root),
        "repo_root": str(repo_root),
        "knowledge_base": str(knowledge_base),
        "integration_branch": integration_branch,
        "current_branch": current_branch,
        "head": current_head,
        "clean": True,
    }

def _binding_id(binding: dict[str, Any]) -> str:
    return stable_id(
        "manager-binding",
        binding["harness_id"],
        binding["conversation_id"],
        _path_key(binding["repo_root"]),
        _path_key(binding["knowledge_base"]),
    )

def _find_binding(
    value: dict[str, Any],
    conversation_id: str,
    harness_id: str,
) -> dict[str, Any] | None:
    identity = (harness_id.strip().casefold(), conversation_id.strip())
    return next((item for item in value["bindings"] if _binding_identity(item) == identity), None)

def _sqlite_integrity(path: Path) -> str:
    if not path.is_file():
        return "missing"
    try:
        connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        try:
            row = connection.execute("PRAGMA integrity_check").fetchone()
            return str(row[0]) if row else "missing-result"
        finally:
            connection.close()
    except sqlite3.Error as exc:
        return f"error:{type(exc).__name__}"

def _feedback_snapshot(output: Path) -> dict[str, Any]:
    root = output / "workspace-meta/feedback/open"
    severities = {name: 0 for name in ("error", "warn", "suggest", "info")}
    invalid = 0
    records = []
    if root.is_dir():
        for path in sorted(root.glob("*.json")):
            try:
                item = json_load(path)
            except Exception:
                invalid += 1
                continue
            severity = str(item.get("severity", ""))
            if severity in severities:
                severities[severity] += 1
            else:
                invalid += 1
            records.append({"id": item.get("id"), "severity": severity, "target": item.get("target")})
    return {"count": len(records), "severities": severities, "invalid": invalid, "records": records[:20]}

def _knowledge_snapshot(output: Path, question: str) -> dict[str, Any]:
    from .llm_wiki_capabilities import compact_agent_brief, maintenance_check
    from .machine_knowledge import retrieve_machine
    from .research_gaps import list_gaps

    snapshot: dict[str, Any] = {
        "output_exists": output.is_dir(),
        "state_exists": (output / "state.json").is_file(),
        "machine_integrity": _sqlite_integrity(output / "machine/knowledge.sqlite"),
        "agent_index_integrity": _sqlite_integrity(output / "agent-index.sqlite"),
        "open_feedback": _feedback_snapshot(output),
        "open_gaps": {"status": "unavailable", "count": None},
        "brief": {"status": "unavailable", "reason": "machine-knowledge-missing"},
        "maintenance": {"status": "unavailable", "failed_checks": ["knowledge-base-missing"]},
    }
    if not snapshot["state_exists"]:
        return snapshot
    try:
        snapshot["open_gaps"] = list_gaps(output, "open")
    except Exception as exc:
        snapshot["open_gaps"] = {"status": "failed", "count": None, "error": type(exc).__name__}
    if snapshot["machine_integrity"] == "ok":
        try:
            retrieval = retrieve_machine(output, question, 1800, 8, "fast")
            snapshot["brief"] = compact_agent_brief(output, retrieval)
        except Exception as exc:
            snapshot["brief"] = {"status": "failed", "error": type(exc).__name__, "detail": str(exc)[:500]}
    try:
        snapshot["maintenance"] = maintenance_check(output)
    except Exception as exc:
        snapshot["maintenance"] = {
            "status": "failed",
            "failed_checks": ["maintenance-exception"],
            "error": type(exc).__name__,
            "detail": str(exc)[:500],
        }
    return snapshot

def _bounded_values(values: list[str] | None, field: str, *, required: bool = False) -> list[str]:
    result = []
    for raw in values or []:
        text = str(raw).strip()
        if not text or len(text) > 2_000 or "\x00" in text or "\n" in text or "\r" in text:
            raise CkbError(f"management task {field} values must be nonempty bounded single-line text")
        result.append(text)
    result = list(dict.fromkeys(result))
    if required and not result:
        raise CkbError(f"management task requires at least one {field} value")
    return result

def _review_for_new_entity(entity: dict[str, Any], previous: dict[str, Any]) -> dict[str, Any]:
    item: dict[str, Any] = {
        "entity_id": entity["id"],
        "classification": entity["classification"],
        "owner_page_id": entity["owner_page_id"],
        "source_path": entity["path"],
        "start_line": entity["range"]["start_line"],
        "end_line": entity["range"]["end_line"],
        "status": "agent-reviewed",
        "evidence_note": previous.get("evidence_note"),
    }
    if entity["classification"] == "appendix":
        item["description_zh"] = previous.get("description_zh")
    else:
        item.update(
            {
                "meaning_zh": previous.get("meaning_zh"),
                "role_zh": previous.get("role_zh"),
                "change_when_zh": previous.get("change_when_zh"),
            }
        )
    return item

def _copy_file(source: Path, target: Path) -> dict[str, Any]:
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)
    return {
        "source": str(source.resolve()),
        "target": str(target.resolve()),
        "relative_target": target.as_posix(),
        "sha256": sha256_file(target),
        "size": target.stat().st_size,
    }

def _mutable_target(output: Path, relative_target: str) -> Path:
    """Resolve a migration-owned relative path without trusting stale absolutes."""
    target = (output / Path(relative_target.replace("\\", "/"))).resolve()
    try:
        target.relative_to(output.resolve())
    except ValueError as exc:
        raise CkbError(f"migration mutable path escapes output: {relative_target}") from exc
    return target

def _generated_paths(vault: Path) -> set[str]:
    manifest = vault / ".ckb-generated-files.json"
    if not manifest.is_file():
        return set()
    return {str(value).replace("\\", "/") for value in json_load(manifest).get("files", [])}

def _semantic_page_key(entity: dict[str, Any]) -> tuple[str, str, str]:
    kind = "file" if entity.get("kind") == "file" else str(entity.get("kind_original") or entity.get("kind"))
    return (str(entity.get("path")), kind, str(entity.get("qualified_name") or entity.get("name")))

def relink_preserved_notes(output: Path, graph: dict[str, Any], projection: dict[str, Any]) -> dict[str, Any]:
    """Retarget preserved Wiki links after deterministic human titles change."""
    output = output.resolve()
    plan_path = output / "migration" / "plan.json"
    if not plan_path.is_file():
        return {"schema_version": MIGRATION_SCHEMA_VERSION, "status": "not-applicable", "changed_files": []}
    plan = json_load(plan_path)
    origin = Path(plan["origin"]["output"])
    old_graph_path = origin / "graph.json"
    old_projection_path = origin / "markdown" / "projection.json"
    if not old_graph_path.is_file() or not old_projection_path.is_file():
        raise CkbError(f"migration note relink requires the origin graph and Markdown projection: {origin}")
    old_graph = json_load(old_graph_path)
    old_projection = json_load(old_projection_path)
    old_entities = {entity["id"]: entity for entity in old_graph.get("entities", [])}
    new_by_key = {_semantic_page_key(entity): entity for entity in graph.get("entities", [])}
    new_title_by_id = {page["id"]: page["title"] for page in projection.get("pages", [])}
    title_map: dict[str, str] = {}
    for page in old_projection.get("pages", []):
        old_entity = old_entities.get(page.get("id"))
        if not old_entity:
            continue
        new_entity = new_by_key.get(_semantic_page_key(old_entity))
        new_title = new_title_by_id.get(new_entity.get("id")) if new_entity else None
        old_title = page.get("title")
        if old_title and new_title and old_title != new_title:
            title_map[str(old_title)] = str(new_title)

    def replace_links(text: str) -> str:
        result = text
        for old_title, new_title in sorted(title_map.items(), key=lambda item: (-len(item[0]), item[0])):
            result = result.replace(f"[[{old_title}]]", f"[[{new_title}]]")
            result = result.replace(f"[[{old_title}|", f"[[{new_title}|")
        return result

    changed: list[str] = []
    for item in plan.get("mutable_files", []):
        target = _mutable_target(output, str(item["relative_target"]))
        if not target.is_file():
            continue
        if target.suffix.casefold() == ".md":
            text = target.read_text(encoding="utf-8")
            updated = replace_links(text)
            if updated != text:
                target.write_text(updated, encoding="utf-8", newline="\n")
                changed.append(item["relative_target"])
        elif target.suffix.casefold() == ".json" and "workspace-meta" in target.parts:
            try:
                value = json_load(target)
            except (json.JSONDecodeError, OSError):
                continue
            updated = False
            linked = value.get("linked_pages")
            if isinstance(linked, list):
                replacement = [title_map.get(str(page), str(page)) for page in linked]
                if replacement != linked:
                    value["linked_pages"] = replacement
                    updated = True
            for field, root_name in (("file", "human"), ("compatibility_file", "markdown")):
                current = value.get(field)
                if isinstance(current, str):
                    candidate = output / root_name / Path(current.replace("\\", "/")).name
                    kind = str(value.get("kind") or "session")
                    directory = {"change": "changes", "analysis": "analysis", "pitfall": "pitfalls", "experiment": "experiments", "session": "sessions"}.get(kind, "user")
                    candidate = output / root_name / directory / candidate.name
                    rendered = str(candidate.resolve())
                    if rendered != current:
                        value[field] = rendered
                        updated = True
            if isinstance(value.get("compatibility_file"), str):
                uri = "obsidian://open?path=" + quote(value["compatibility_file"], safe="")
                if value.get("obsidian_uri") != uri:
                    value["obsidian_uri"] = uri
                    updated = True
            if updated:
                json_write(target, value)
                changed.append(item["relative_target"])
        item["post_migration_sha256"] = sha256_file(target)
        item["post_migration_size"] = target.stat().st_size
    plan["note_relink"] = {
        "status": "passed",
        "title_map": title_map,
        "changed_files": sorted(set(changed)),
        "updated_at_utc": utc_now(),
    }
    json_write(plan_path, plan)
    result = {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": "passed",
        "title_map_count": len(title_map),
        "changed_files": sorted(set(changed)),
        "title_map": title_map,
    }
    json_write(output / "migration" / "note-relink.json", result)
    return result

def replace_links(text: str) -> str:
        result = text
        for old_title, new_title in sorted(title_map.items(), key=lambda item: (-len(item[0]), item[0])):
            result = result.replace(f"[[{old_title}]]", f"[[{new_title}]]")
            result = result.replace(f"[[{old_title}|", f"[[{new_title}|")
        return result

def migration_status(output: Path) -> dict[str, Any]:
    output = output.resolve()
    state = json_load(output / "state.json")
    migration = state.get("migration")
    if not migration:
        raise CkbError(f"output is not an incremental migration: {output}")
    pending = [pack for pack in state.get("review_packs", []) if pack.get("status") != "passed"]
    audit = audit_migration(output, require_complete_reviews=False)
    if state.get("status") == "complete" and audit.get("status") == "passed":
        status = "complete"
    else:
        status = "pending-agent-review" if pending else "ready-to-finalize"
    return {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": status,
        "migration": migration,
        "pending_review_packs": [pack["id"] for pack in pending],
        "next_review_template": pending[0].get("review_template_path") if pending else None,
        "audit": audit,
    }

def _journal_lock(root: Path) -> Iterator[None]:
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + 5.0
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, str(os.getpid()).encode("ascii"))
        except FileExistsError:
            try:
                if time.time() - lock.stat().st_mtime > 30:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"operation journal is busy: {lock}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)

def _read_shard(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    if not path.is_file():
        return records
    for line_number, line in enumerate(path.read_text(encoding="utf-8-sig").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise CkbError(f"invalid operation journal JSONL at {path}:{line_number}: {exc}") from exc
        if not isinstance(value, dict):
            raise CkbError(f"operation journal record must be an object: {path}:{line_number}")
        records.append(value)
    return records

def _state(root: Path) -> dict[str, Any]:
    path = root / "state.json"
    if not path.is_file():
        return {
            "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
            "dropped_records": 0,
            "expired_records": 0,
            "deduplicated_records": 0,
        }
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"operation journal state must be an object: {path}")
    return value

def _prune_expired(root: Path, today: date, state: dict[str, Any]) -> None:
    cutoff = _retention_cutoff(today)
    for path in sorted(root.glob("*.jsonl")):
        matched = _SHARD_NAME.fullmatch(path.name)
        if not matched:
            continue
        shard_date = date.fromisoformat(matched.group(1))
        if shard_date >= cutoff:
            continue
        state["expired_records"] = int(state.get("expired_records", 0)) + len(_read_shard(path))
        path.unlink()

def _all_events(root: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for path in sorted(root.glob("*.jsonl")):
        if _SHARD_NAME.fullmatch(path.name):
            events.extend(_read_shard(path))
    return events

def _relative_evidence(output: Path, result: dict[str, Any]) -> list[str]:
    evidence: set[str] = set()
    for key in sorted(_EVIDENCE_KEYS):
        value = result.get(key)
        values = value if isinstance(value, list) else [value]
        for candidate in values:
            if not isinstance(candidate, str) or not candidate.strip():
                continue
            path = Path(candidate)
            if not path.is_absolute():
                path = output / path
            try:
                resolved = path.resolve()
            except OSError:
                continue
            if not resolved.exists() or not path_inside(resolved, output):
                continue
            evidence.add(resolved.relative_to(output).as_posix())
    return sorted(evidence)[:8]

def _operation_type(command: str) -> str | None:
    root = command.split(":", 1)[0]
    if root in {"init", "run", "build-chunk", "review-chunk", "review-pack", "merge", "finalize", "human-refresh", "reindex", "migrate", "relink"}:
        return "compile"
    if root in {"query", "retrieve", "brief", "keyword-benchmark", "context", "coverage", "entity", "neighbors", "source", "changes", "path", "explain", "status"}:
        return "query"
    if root == "maintain":
        return "maintenance"
    if command == "gaps:list":
        return "query"
    if command == "gaps:audit":
        return "audit"
    if command in {"gaps:create", "gaps:resolve"}:
        return "record"
    if root == "audit" or command in {"reference:audit", "feedback:audit", "agent-policy:check", "migrate:audit"}:
        return "audit"
    if root == "record" or command in {
        "reference:ingest",
        "reference:review",
        "reference:rollback",
        "feedback:create",
        "feedback:resolve",
        "workspace:session-start",
        "workspace:session-finish",
        "automation:review",
    }:
        return "record"
    return None

def record_cli_operation(args: Any, result: Any) -> dict[str, Any] | None:
    if str(getattr(args, "command", "")) == "operations" or not isinstance(result, dict):
        return None
    output_value = getattr(args, "out", None)
    if output_value is None:
        return None
    output = Path(output_value).resolve()
    if not (output / "state.json").is_file():
        return None
    command = _command_name(args)
    operation = _operation_type(command)
    if operation is None:
        return None
    status = str(result.get("status") or "completed")
    evidence = _relative_evidence(output, result)
    return record_operation(output, operation, command, status, evidence)

def list_operations(output: Path, operation: str | None = None, result_status: str | None = None, limit: int = 50) -> dict[str, Any]:
    if operation is not None and operation not in OPERATION_TYPES:
        raise CkbError(f"unsupported operation filter: {operation}")
    if limit < 1 or limit > 500:
        raise CkbError("operation list limit must be between 1 and 500")
    events = _all_events(_root(output))
    selected = [
        item
        for item in events
        if (operation is None or item.get("operation") == operation)
        and (result_status is None or item.get("result_status") == result_status)
    ]
    return {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "status": "ready",
        "filters": {"operation": operation, "result_status": result_status},
        "count": len(selected),
        "operations": selected[-limit:][::-1],
    }

def _event_errors(item: dict[str, Any], path: Path, line_number: int) -> list[str]:
    prefix = f"{path.name}:{line_number}"
    errors = []
    if set(item) != _EVENT_FIELDS:
        errors.append(f"{prefix}: fields differ from the fixed operation schema")
        return errors
    if item.get("schema_version") != OPERATION_JOURNAL_SCHEMA_VERSION:
        errors.append(f"{prefix}: schema version mismatch")
    if item.get("operation") not in OPERATION_TYPES:
        errors.append(f"{prefix}: unsupported operation type")
    if not isinstance(item.get("command"), str) or not _SAFE_TOKEN.fullmatch(item["command"]):
        errors.append(f"{prefix}: invalid command token")
    if not isinstance(item.get("result_status"), str) or not _SAFE_TOKEN.fullmatch(item["result_status"]):
        errors.append(f"{prefix}: invalid result status token")
    if not isinstance(item.get("event_id"), str) or not item["event_id"].startswith("operation-"):
        errors.append(f"{prefix}: invalid event id")
    if not isinstance(item.get("recorded_at_utc"), str) or len(item["recorded_at_utc"]) != 20:
        errors.append(f"{prefix}: invalid recorded timestamp")
    evidence = item.get("evidence_paths")
    if not isinstance(evidence, list) or len(evidence) > 8:
        errors.append(f"{prefix}: evidence_paths must be a bounded list")
    else:
        for value in evidence:
            if not isinstance(value, str):
                errors.append(f"{prefix}: evidence path must be text")
                continue
            relative = PurePosixPath(value)
            if relative.is_absolute() or ".." in relative.parts:
                errors.append(f"{prefix}: evidence path escapes OUTPUT")
    return errors

def _runtime_binding(output: Path) -> tuple[Path, Path]:
    record_path = output / "workspace-meta/agent-protocol.json"
    record = json_load(record_path) if record_path.is_file() else {}
    python = Path(str(record.get("python") or sys.executable)).resolve()
    ckb = Path(str(record.get("ckb") or _default_ckb())).resolve()
    return python, ckb

def expected_output_contract(output: Path, vault: Path) -> dict[str, Any]:
    output = output.resolve()
    vault = vault.resolve()
    python, ckb = _runtime_binding(output)
    return output_contract_for_runtime(output, vault, python, ckb)

def _update_ownership(vault: Path, *, present: bool) -> None:
    ownership_path = vault / ".ckb-generated-files.json"
    if not ownership_path.is_file():
        return
    ownership = json_load(ownership_path)
    files = {str(value) for value in ownership.get("files", [])}
    relative = OUTPUT_CONTRACT_RELATIVE.as_posix()
    if present:
        files.add(relative)
    else:
        files.discard(relative)
    ownership["files"] = sorted(files)
    json_write(ownership_path, ownership)

def remove_output_contract(vault: Path) -> dict[str, Any]:
    vault = vault.resolve()
    path = vault / OUTPUT_CONTRACT_RELATIVE
    path.unlink(missing_ok=True)
    parent = path.parent
    if parent.is_dir() and not any(parent.iterdir()):
        parent.rmdir()
    _update_ownership(vault, present=False)
    return {"schema_version": OUTPUT_CONTRACT_SCHEMA_VERSION, "status": "removed", "path": str(path)}

def _language(language: str):
    try:
        from tree_sitter import Language
        modules = {
            "python": "tree_sitter_python",
            "javascript": "tree_sitter_javascript",
            "c": "tree_sitter_c",
            "cpp": "tree_sitter_cpp",
            "csharp": "tree_sitter_c_sharp",
        }
        module = __import__(modules[language])
        return Language(module.language())
    except Exception as exc:
        raise DependencyError(f"Tree-sitter runtime for {language} is unavailable: {exc}") from exc

def _walk(node) -> Iterator[Any]:
    stack = [node]
    while stack:
        current = stack.pop()
        yield current
        stack.extend(reversed(current.children))

def _byte_position(source: bytes, byte_offset: int) -> tuple[int, int]:
    """Compute 1-based line and UTF-8 byte column without Node Point access."""
    previous_newline = source.rfind(b"\n", 0, byte_offset)
    return source.count(b"\n", 0, byte_offset) + 1, byte_offset - (previous_newline + 1)

def _find_name(node, source: bytes, retained_nodes: list[Any]) -> tuple[str, int, int] | None:
    for field in NAME_FIELDS:
        child = node.child_by_field_name(field)
        if child is not None:
            candidates = [child, *_walk(child)]
            retained_nodes.extend(candidates)
            for value in candidates:
                if value.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
                    line, column = _byte_position(source, value.start_byte)
                    return _node_text(value, source), line, column
    fallback_nodes = list(_walk(node))
    retained_nodes.extend(fallback_nodes)
    for child in fallback_nodes:
        if child.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
            line, column = _byte_position(source, child.start_byte)
            return _node_text(child, source), line, column
    return None

def _public_evidence(language: str, source_text: str, node_text: str, name: str) -> bool:
    if language == "python":
        return not name.startswith("_")
    if language == "javascript":
        return bool(re.search(r"\bexport\b", source_text[max(0, source_text.find(node_text) - 80) : source_text.find(node_text) + 20]))
    return bool(re.search(r"\b(public|protected|internal|extern)\b", node_text)) or language in {"c", "cpp"}

def _single_statement_shape(node, source: bytes, kind: str) -> str | None:
    """Return a small deterministic hard-exclusion reason for thin declarations."""
    if kind == "accessor":
        return "accessor"
    if kind not in {"function", "method", "local_function", "constructor", "operator", "conversion_operator", "property", "indexer", "event"}:
        return None
    body = node.child_by_field_name("body")
    if body is None:
        # Expression-bodied C# members and declarations without a block.
        text = _node_text(node, source)
        if "=>" in text:
            return "single-expression-body"
        return None
    named = [child for child in body.named_children if child.type not in {"comment"}]
    if len(named) != 1:
        return None
    statement = named[0]
    text = _node_text(statement, source)
    if statement.type in {"return_statement", "expression_statement"}:
        if not re.search(r"\b(if|for|foreach|while|switch|try|catch|await|yield|throw|lock)\b", text):
            return "single-return-or-call"
    if statement.type in {"assignment_expression", "local_declaration_statement"}:
        return "single-assignment"
    return None

def _has_ancestor(node: Any, node_type: str) -> bool:
    current = node.parent
    while current is not None:
        if current.type == node_type:
            return True
        current = current.parent
    return False

def _cpp_explicit_class_instantiation_recovery(node: Any, source: bytes) -> dict[str, Any] | None:
    """Recognize the pinned grammar's sole missing-node shape for ``template class``."""
    if not node.is_missing or node.type != "identifier":
        return None
    parent = node.parent
    if parent is None or parent.type != "template_instantiation":
        return None
    type_node = parent.child_by_field_name("type")
    if type_node is None or type_node.type not in {"class_specifier", "struct_specifier"}:
        return None
    name_node = type_node.child_by_field_name("name")
    if name_node is None or name_node.type != "template_type":
        return None
    text = _node_text(parent, source).strip()
    if not re.match(r"^template\s+(?:class|struct)\b", text) or not text.endswith(";"):
        return None
    start_line, _ = _byte_position(source, parent.start_byte)
    end_line, _ = _byte_position(source, parent.end_byte)
    return {
        "kind": "tree-sitter-cpp-explicit-class-template-instantiation",
        "node_type": node.type,
        "start_line": start_line,
        "end_line": end_line,
    }

def _parse_diagnostics(language: str, root: Any, source: bytes) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Split known pinned-grammar recoveries from unresolved syntax diagnostics."""
    error_nodes = [node for node in _walk(root) if node.is_error or node.is_missing]
    recoveries: list[dict[str, Any]] = []
    unresolved: list[dict[str, Any]] = []
    for node in error_nodes:
        recovery = _cpp_explicit_class_instantiation_recovery(node, source) if language == "cpp" else None
        if recovery is not None:
            recoveries.append(recovery)
            continue
        start_line, _ = _byte_position(source, node.start_byte)
        end_line, _ = _byte_position(source, node.end_byte)
        unresolved.append(
            {
                "node_type": node.type,
                "is_error": bool(node.is_error),
                "is_missing": bool(node.is_missing),
                "start_line": start_line,
                "end_line": end_line,
            }
        )
    if root.has_error and not error_nodes:
        unresolved.append(
            {
                "node_type": root.type,
                "is_error": True,
                "is_missing": False,
                "start_line": 1,
                "end_line": max(1, source.count(b"\n") + 1),
            }
        )
    return recoveries, unresolved

def merge_csharp_partials(repository: dict[str, Any], entities: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge partial C# type declarations into one logical entity with audited fragments."""
    type_kinds = {"class", "struct", "record", "interface"}
    groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for entity in entities:
        if entity.get("language") == "csharp" and entity.get("kind") in type_kinds and entity.get("is_partial"):
            groups.setdefault((entity["kind"], entity["qualified_name"]), []).append(entity)
    replacements: dict[str, str] = {}
    merged_by_old: dict[str, dict[str, Any]] = {}
    removed: set[str] = set()
    for (kind, qualified), values in sorted(groups.items()):
        if len(values) < 2:
            continue
        ordered = sorted(values, key=lambda item: (item["path"], item["range"]["start_byte"], item["id"]))
        primary = sorted(
            ordered,
            key=lambda item: (
                -sum(1 for child in entities if child.get("parent_id") == item["id"] and child.get("page_eligible")),
                item["path"],
                item["range"]["start_byte"],
                item["id"],
            ),
        )[0]
        logical_id = stable_id("ent", repository["commit"], "csharp-partial", kind, qualified)
        logical = dict(primary)
        logical["id"] = logical_id
        logical["partial"] = True
        logical["fragments"] = [
            {
                "fragment_id": value["id"],
                "path": value["path"],
                "blob": value["blob"],
                "range": value["range"],
            }
            for value in ordered
        ]
        logical["classification_evidence"] = sorted(set(logical.get("classification_evidence", []) + ["partial-logical-entity"]))
        for value in ordered:
            replacements[value["id"]] = logical_id
            merged_by_old[value["id"]] = logical
            removed.add(value["id"])
    if not replacements:
        return entities
    result: list[dict[str, Any]] = []
    emitted: set[str] = set()
    for entity in entities:
        if entity["id"] in removed:
            logical = merged_by_old[entity["id"]]
            if logical["id"] not in emitted:
                result.append(logical)
                emitted.add(logical["id"])
            continue
        value = dict(entity)
        if value.get("parent_id") in replacements:
            value["parent_id"] = replacements[value["parent_id"]]
        result.append(value)
    return result

def lexical_links(entities: list[dict[str, Any]], sources: dict[str, bytes]) -> list[dict[str, Any]]:
    by_name: dict[str, list[dict[str, Any]]] = {}
    for entity in entities:
        if entity["kind"] != "file" and len(entity["name"]) >= 2:
            by_name.setdefault(entity["name"], []).append(entity)
    links: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for source_entity in entities:
        if source_entity["kind"] == "file":
            continue
        data = sources.get(source_entity["path"], b"")
        region = data[source_entity["range"]["start_byte"] : source_entity["range"]["end_byte"]].decode("utf-8", errors="replace")
        referenced_names = set(re.findall(r"[A-Za-z_$][A-Za-z0-9_$]*", region))
        for name in sorted(referenced_names.intersection(by_name)):
            targets = by_name[name]
            if name == source_entity["name"]:
                continue
            if len(targets) != 1:
                continue
            target = targets[0]
            if target["id"] == source_entity["id"]:
                continue
            key = (source_entity["id"], target["id"], "references")
            if key in seen:
                continue
            seen.add(key)
            links.append({
                "id": stable_id("link", *key),
                "type": "references",
                "source": source_entity["id"],
                "target": target["id"],
                "provider": "tree-sitter-lexical-candidate",
                "evidence": {"name": name, "source_path": source_entity["path"]},
            })
    for entity in entities:
        if entity["parent_id"]:
            key = (entity["parent_id"], entity["id"], "contains")
            links.append({
                "id": stable_id("link", *key),
                "type": "contains",
                "source": entity["parent_id"],
                "target": entity["id"],
                "provider": "tree-sitter",
                "evidence": {"path": entity["path"], "range": entity["range"]},
            })
    return links

def audit_global(output: Path) -> dict[str, Any]:
    state = _load_state(output)
    clear_markers(output)
    if state.get("status") == "complete":
        state["status"] = "in-progress"
        json_write(output / "state.json", state)
    graph_path = output / "graph.json"
    if not graph_path.is_file():
        raise AuditError("merge must produce graph.json before global audit")
    graph = json_load(graph_path)
    page_config = normalize_page_config(graph.get("page_config", DEFAULT_PAGE_CONFIG))
    logical = _logical_projection(graph)
    checks: list[dict[str, Any]] = []
    pinned_config_path = output / state["page_config"]["relative_path"]
    config_hash = page_config_sha256(page_config)
    checks.append(
        {
            "name": "page-configuration-pinned",
            "passed": (
                pinned_config_path.is_file()
                and sha256_file(pinned_config_path) == state["page_config"]["sha256"]
                and config_hash == state["page_config"]["sha256"]
                and graph.get("page_config_sha256") == config_hash
                and page_config_bytes(page_config) == pinned_config_path.read_bytes()
            ),
            "detail": {
                "path": str(pinned_config_path.resolve()),
                "state_sha256": state["page_config"]["sha256"],
                "graph_sha256": graph.get("page_config_sha256"),
                "actual_sha256": sha256_file(pinned_config_path) if pinned_config_path.is_file() else None,
                "page_limits": page_config["page_limits"],
                "content": page_config["content"],
            },
        }
    )
    snapshot_errors: list[dict[str, Any]] = []
    try:
        if not isinstance(state.get("source_snapshot"), dict):
            snapshot_errors.append({"reason": "fixed-source-snapshot-missing"})
        else:
            assert_source_snapshot(state["repository"], state["source_snapshot"])
    except CkbError as exc:
        snapshot_errors.append({"reason": "fixed-source-snapshot-invalid", "detail": str(exc)})
    checks.append(
        {
            "name": "fixed-source-snapshot",
            "passed": not snapshot_errors,
            "detail": {
                "errors": snapshot_errors,
                "snapshot": state.get("source_snapshot"),
                "live-worktree-may-change": True,
            },
        }
    )
    if state.get("migration"):
        from .migration import audit_migration

        migration_audit = audit_migration(output, require_complete_reviews=True)
        checks.append(
            {
                "name": "incremental-migration",
                "passed": migration_audit.get("status") == "passed",
                "detail": migration_audit,
            }
        )
    chunk_audits = []
    for chunk in state["chunks"]:
        audit = audit_chunk(output, chunk["id"])
        chunk_audits.append(audit)
    checks.append({"name": "all-chunk-audits-passed", "passed": all(item["status"] == "passed" for item in chunk_audits), "detail": {item["chunk_id"]: item["status"] for item in chunk_audits}})
    review_pack_status = {item["id"]: item["status"] for item in state.get("review_packs", [])}
    checks.append({"name": "all-review-packs-passed", "passed": bool(review_pack_status) and all(value == "passed" for value in review_pack_status.values()), "detail": review_pack_status})
    catalog, scope_doc, _boundary_doc = _selected_catalog(output)
    scope_ids = set(scope_doc["selected_entity_ids"])
    graph_ids = {entity["id"] for entity in graph["entities"]}
    checks.append({"name": "global-entity-set-exact", "passed": graph_ids == scope_ids, "detail": {"missing": sorted(scope_ids - graph_ids), "extra": sorted(graph_ids - scope_ids)}})
    dangling = [link["id"] for link in graph["links"] if link["source"] not in graph_ids or link["target"] not in graph_ids]
    checks.append({"name": "global-link-endpoints", "passed": not dangling, "detail": dangling})
    chinese_description_errors: list[dict[str, Any]] = []
    for entity in graph["entities"]:
        if entity.get("classification") == "appendix":
            if not contains_chinese_narrative(entity.get("description_zh")):
                chinese_description_errors.append({"entity_id": entity["id"], "field": "description_zh"})
        else:
            for field in ("meaning_zh", "role_zh", "change_when_zh"):
                if not contains_chinese_narrative(entity.get(field)):
                    chinese_description_errors.append({"entity_id": entity["id"], "field": field})
        if not contains_chinese_narrative(entity.get("evidence_note")):
            chinese_description_errors.append({"entity_id": entity["id"], "field": "evidence_note"})
    checks.append(
        {
            "name": "simplified-chinese-description-contract",
            "passed": not chinese_description_errors,
            "detail": {
                "rule": "所有叙述字段使用简体中文；英文专有名词、路径和代码标识符可以保留。",
                "errors": chinese_description_errors,
            },
        }
    )
    navigation_plan = graph.get("navigation_plan", {})
    planned = {item["entity_id"]: item for item in navigation_plan.get("decisions", [])}
    navigation_errors = []
    for entity in graph["entities"]:
        decision = planned.get(entity["id"])
        if not decision:
            navigation_errors.append({"id": entity["id"], "reason": "missing-navigation-decision"})
        elif entity.get("classification") != decision.get("classification") or entity.get("owner_page_id") != decision.get("owner_page_id"):
            navigation_errors.append({"id": entity["id"], "reason": "navigation-decision-drift"})
    navigation_config_equal = navigation_plan.get("page_limits") == page_config["page_limits"]
    checks.append({"name": "deterministic-navigation-plan", "passed": navigation_plan.get("status") == "passed" and not navigation_plan.get("quota_errors") and not navigation_errors and navigation_config_equal, "detail": {"algorithm": navigation_plan.get("algorithm"), "quota_errors": navigation_plan.get("quota_errors"), "decision_errors": navigation_errors, "page_limits_equal": navigation_config_equal}})
    page_entities = [entity for entity in graph["entities"] if entity.get("classification") == "page"]
    actual_page_ids = {entity["id"] for entity in page_entities}
    planned_page_ids = set(navigation_plan.get("page_entity_ids", []))
    module_count = len(logical["module_page_ids"])
    entry_cluster_count = len(navigation_plan.get("entry_clusters", []))
    maximum_pages = page_limit(len(scope_doc["selected_file_paths"]), module_count, entry_cluster_count, logical["boundary_group_count"], page_config)
    checks.append({"name": "human-page-count-bounded", "passed": actual_page_ids == planned_page_ids and len(logical["pages"]) <= maximum_pages, "detail": {"actual_navigation_pages": len(logical["pages"]), "maximum_navigation_pages": maximum_pages, "planned_page_entity_delta": sorted(actual_page_ids ^ planned_page_ids)}})
    appendix_errors = []
    page_ids = {entity["id"] for entity in page_entities}
    for entity in graph["entities"]:
        if entity.get("classification") != "appendix":
            continue
        if entity.get("owner_page_id") not in page_ids:
            appendix_errors.append({"id": entity["id"], "reason": "owner-not-source-page", "owner": entity.get("owner_page_id")})
        if not _single_chinese_sentence(entity.get("description_zh")):
            appendix_errors.append({"id": entity["id"], "reason": "description-not-one-reviewed-sentence"})
    checks.append({"name": "appendix-ownership-and-description", "passed": not appendix_errors, "detail": appendix_errors})
    title_counts: dict[str, int] = defaultdict(int)
    for page in logical["pages"]:
        title_counts[page["title"]] += 1
    title_errors = [title for title, count in title_counts.items() if count != 1]
    tag_errors = [
        {"page": page["id"], "tag": page.get("tag"), "expected": page_tag(page["page_type"])}
        for page in logical["pages"]
        if page.get("tag") != page_tag(page["page_type"])
    ]
    relation_budget_errors = []
    for page in logical["pages"]:
        counts: dict[str, int] = defaultdict(int)
        for link in page["outgoing"]:
            if link.get("category") != "navigation":
                counts[link["category"]] += 1
        for category, limit in logical["relation_limits"].items():
            if counts.get(category, 0) > limit:
                relation_budget_errors.append({"page": page["id"], "category": category, "count": counts[category], "limit": limit})
        if any(link not in logical["links"] for link in page["outgoing"]):
            relation_budget_errors.append({"page": page["id"], "reason": "outgoing-not-in-visible-link-set"})
    backlinks = {(link["id"], link["source"], link["target"]) for page in logical["pages"] for link in page["backlinks"]}
    visible = {(link["id"], link["source"], link["target"]) for link in logical["links"]}
    checks.append({"name": "titles-tags-links-and-backlinks-complete", "passed": not title_errors and not tag_errors and not relation_budget_errors and backlinks == visible, "detail": {"duplicate_titles": title_errors, "tag_errors": tag_errors, "relation_budget_errors": relation_budget_errors, "backlink_delta": sorted(backlinks ^ visible)}})
    contexts = _logical_context_budgets(logical)
    task_context_limit = int(page_config["context"]["task_max_tokens"])
    context_errors = []
    for module, record in contexts["modules"].items():
        if record["status"] != "passed" and (record.get("required_mode") != "task-subgraph" or record.get("task_subgraph_limit") != task_context_limit):
            context_errors.append({"module": module, "record": record})
    checks.append({"name": "context-budget-contract", "passed": not context_errors, "detail": {"errors": context_errors, "modules": contexts["modules"]}})
    file_by_path = {item["file"]["path"]: item["file"] for item in catalog["files"]}
    audit_paths = {entity["path"] for entity in graph["entities"]}
    audit_paths.update(fragment["path"] for entity in graph["entities"] for fragment in entity.get("fragments", []))
    audit_files = [file_by_path[path] for path in sorted(audit_paths)]
    audit_sources = blob_bytes_many(state["repository"], audit_files)
    source_errors = [
        {"id": entity["id"], "reason": reason}
        for entity in graph["entities"]
        if (reason := _source_check(entity, audit_sources.get(entity["path"]), file_by_path.get(entity["path"], {}).get("blob")))
    ]
    source_errors.extend(error for entity in graph["entities"] for error in _partial_fragment_source_errors(entity, audit_sources, file_by_path))
    checks.append({"name": "global-git-source-authentic", "passed": not source_errors, "detail": source_errors})
    csharp_workspace = state.get("csharp_workspace")
    csharp_workspace_errors: list[dict[str, Any]] = []
    if csharp_workspace:
        restore = csharp_workspace.get("restore") or {}
        fallback = csharp_workspace.get("fallback") or {}
        if not restore.get("requested") and restore.get("network_restore"):
            csharp_workspace_errors.append({"reason": "network-restore-without-explicit-request"})
        if restore.get("performed"):
            workspace_root = Path(csharp_workspace["workspace_root"])
            head = run(["git", "-C", str(workspace_root), "rev-parse", "HEAD"], timeout=30)
            if head.returncode or head.stdout.strip() != state["repository"]["commit"]:
                csharp_workspace_errors.append({"reason": "restore-worktree-commit-drift", "output": head.stdout + head.stderr})
            manifest_path = Path(restore.get("file_manifest", ""))
            if not manifest_path.is_file():
                csharp_workspace_errors.append({"reason": "restore-file-manifest-missing"})
            else:
                runtime_root = workspace_root.parent
                for item in json_load(manifest_path).get("files", []):
                    path = runtime_root / item["path"]
                    if not path.is_file() or path.stat().st_size != int(item["size"]) or sha256_file(path) != item["sha256"]:
                        csharp_workspace_errors.append({"reason": "restore-file-hash-mismatch", "path": item["path"]})
                        break
        if csharp_workspace.get("precision") == "exact" and not csharp_workspace.get("path"):
            csharp_workspace_errors.append({"reason": "exact-csharp-workspace-without-project"})
        if csharp_workspace.get("precision") == "bounded-approximate":
            workspace_root = Path(csharp_workspace.get("workspace_root", ""))
            project = workspace_root / str(csharp_workspace.get("path", ""))
            head = run(["git", "-C", str(workspace_root), "rev-parse", "HEAD"], timeout=30) if workspace_root.is_dir() else None
            if head is None or head.returncode or head.stdout.strip() != state["repository"]["commit"]:
                csharp_workspace_errors.append({"reason": "fallback-worktree-commit-drift"})
            if not project.is_file() or sha256_file(project) != fallback.get("project_sha256"):
                csharp_workspace_errors.append({"reason": "fallback-project-hash-mismatch", "path": str(project)})
            if fallback.get("network_restore"):
                csharp_workspace_errors.append({"reason": "fallback-project-network-restore"})
    checks.append({"name": "csharp-workspace-and-restore", "passed": not csharp_workspace_errors, "detail": {"workspace": csharp_workspace, "errors": csharp_workspace_errors}})
    projections: dict[str, Any] = {}
    projections["facts"] = build_facts_layer(output, graph)
    facts_errors = audit_facts_layer(output, graph).get("errors", [])
    checks.append({"name": "facts-layer-valid", "passed": not facts_errors, "detail": projections["facts"]})
    projections["graphify"] = project_graphify(output, graph)
    graphify_errors = audit_graphify(output, graph, projections["graphify"])
    checks.append(
        {
            "name": "graphify-projection-valid",
            "passed": not graphify_errors,
            "detail": {
                "errors": graphify_errors,
                "node_count": projections["graphify"].get("node_count"),
                "link_count": projections["graphify"].get("link_count"),
                "community_count": projections["graphify"].get("community_count"),
                "graphify_commit": projections["graphify"].get("graphify_commit"),
            },
        }
    )
    # Version 5 always emits a conservative Markdown human layer.  The format
    # flag still controls whether a Logseq DB projection is additionally built.
    projections["markdown"] = project_markdown(output, graph, logical)
    projections["agent-protocol"] = project_agent_protocol(output)
    if state.get("migration"):
        from .migration import relink_preserved_notes

        projections["markdown"]["migration_note_relink"] = relink_preserved_notes(output, graph, projections["markdown"])
    pending_notes = materialize_pending_notes(output)
    projections["markdown"]["materialized_pending_notes"] = pending_notes
    json_write(output / "markdown/projection.json", projections["markdown"])
    errors = _audit_markdown(output, graph, logical)
    checks.append({"name": "markdown-valid", "passed": not errors, "detail": errors})
    readability = json_load(output / "markdown" / "readability-audit.json")
    checks.append(
        {
            "name": "human-readable-pages",
            "passed": readability.get("status") == "passed" and not readability.get("errors"),
            "detail": readability,
        }
    )
    projections["human"] = sync_human_layer(output, graph)
    from .obsidian_plugin import deploy_registered_plugin_if_available

    projections["human"]["companion_plugin"] = deploy_registered_plugin_if_available(output / "human", output)
    human_audit = audit_human_layer(output, graph)
    checks.append({"name": "human-layer-valid", "passed": human_audit.get("status") == "passed", "detail": human_audit})
    if state["format"] in {"logseq-db", "both"}:
        projections["logseq-db"] = project_logseq(output, graph, logical)
        checks.append({"name": "logseq-db-valid", "passed": Path(projections["logseq-db"]["db_path"]).read_bytes()[:16] == b"SQLite format 3\x00", "detail": projections["logseq-db"].get("validation")})
        checks.append({"name": "logseq-human-readable", "passed": projections["logseq-db"]["human_readability"]["status"] == "passed", "detail": projections["logseq-db"]["human_readability"]})
        checks.append({"name": "logseq-worker-cleanup", "passed": projections["logseq-db"]["worker_cleanup"]["all_stopped"], "detail": projections["logseq-db"]["worker_cleanup"]})
    projections["machine"] = build_machine_knowledge(output, graph, logical)
    machine_audit = audit_machine_knowledge(output, graph)
    checks.append({"name": "machine-layer-valid", "passed": machine_audit.get("status") == "passed", "detail": machine_audit})
    from .reference_documents import audit_references

    reference_audit = audit_references(output)
    checks.append({"name": "reviewed-reference-layer-valid", "passed": reference_audit.get("status") == "passed", "detail": reference_audit})
    projections["agent-index"] = build_agent_index(output)
    index_audit = audit_agent_index(output)
    checks.append(
        {
            "name": "agent-index-valid",
            "passed": index_audit.get("status") == "passed",
            "detail": index_audit,
        }
    )
    agent_protocol_audit = audit_agent_protocol(output)
    checks.append(
        {
            "name": "agent-protocol-valid",
            "passed": agent_protocol_audit.get("status") == "passed",
            "detail": agent_protocol_audit,
        }
    )
    if state["format"] == "both":
        markdown_projection = projections["markdown"]
        logseq_projection = projections["logseq-db"]
        md_pages = {(item["id"], item["title"], item["page_type"], item["human_page_kind"], item.get("tag")) for item in markdown_projection["pages"]}
        db_pages = {(item["id"], item["title"], item["page_type"], item["human_page_kind"], item.get("tag")) for item in logseq_projection["pages"]}
        md_links = {json.dumps(item, sort_keys=True, ensure_ascii=False) for item in markdown_projection["links"]}
        db_links = {json.dumps(item, sort_keys=True, ensure_ascii=False) for item in logseq_projection["links"]}
        owner_equal = markdown_projection["entity_owner_pages"] == logseq_projection["entity_owner_pages"]
        source_equal = markdown_projection["source_manifest"] == logseq_projection["source_manifest"]
        edn_equal = markdown_projection["normalized_edn_sha256"] == logseq_projection["normalized_edn_sha256"]
        config_equal = (
            markdown_projection.get("page_config") == logseq_projection.get("page_config") == page_config
            and markdown_projection.get("page_config_sha256") == logseq_projection.get("page_config_sha256") == config_hash
        )
        checks.append({
            "name": "dual-projection-parity",
            "passed": md_pages == db_pages and md_links == db_links and owner_equal and source_equal and edn_equal and config_equal,
            "detail": {
                "page_delta": sorted(md_pages ^ db_pages),
                "link_delta": sorted(md_links ^ db_links),
                "entity_ownership_equal": owner_equal,
                "source_manifest_equal": source_equal,
                "normalized_edn_equal": edn_equal,
                "page_config_equal": config_equal,
            },
        })
    status = "passed" if all(item["passed"] for item in checks) else "failed"
    result = {"schema_version": SCHEMA_VERSION, "status": status, "checks": checks, "projections": projections, "audited_at_utc": utc_now()}
    json_write(output / "audit" / "global.json", result)
    write_marker(
        output,
        ".pending-agent-review" if status == "passed" else ".failed",
        {"status": "global-audit-passed-finalize-required" if status == "passed" else "failed", "audit": str((output / "audit" / "global.json").resolve())},
    )
    return result

def _version_matches(expected: str, output: str) -> bool:
    lowered = output.lower()
    return expected.lower() in lowered or (len(expected) == 40 and expected[:7].lower() in lowered)

def private_runtime_root() -> Path:
    override = os.environ.get("CKB_RUNTIME_ROOT")
    if override:
        return Path(override).expanduser().resolve()
    return Path.home() / ".codex" / "cache" / "code-knowledge-builder" / "runtime" / "win-x64"

def _runtime_bin_candidates() -> list[Path]:
    root = private_runtime_root()
    if not root.is_dir():
        return []
    result: list[Path] = []
    for lock_dir in sorted(root.iterdir(), reverse=True):
        for rel in ("bin", "node", "python", "llvm/bin", "logseq", "dotnet", "dotnet-tools"):
            path = lock_dir / rel
            if path.is_dir():
                result.append(path)
    return result

def resolve_executable(name: str) -> str | None:
    env_name = "CKB_" + re.sub(r"[^A-Za-z0-9]", "_", name).upper() + "_COMMAND"
    if os.environ.get(env_name):
        return os.environ[env_name]
    names = [name]
    if os.name == "nt":
        names.extend([name + ".cmd", name + ".exe"])
    for directory in _runtime_bin_candidates():
        for candidate in names:
            path = directory / candidate
            if path.is_file():
                return str(path.resolve())
    for candidate in names:
        found = shutil.which(candidate)
        if found:
            return found
    return None

def path_to_uri(path: Path) -> str:
    value = path.resolve().as_posix()
    if os.name == "nt":
        return "file:///" + quote(value, safe="/:@")
    return "file://" + quote(value, safe="/:@")

def uri_to_path(uri: str) -> Path:
    parsed = urlparse(uri)
    value = unquote(parsed.path)
    if os.name == "nt" and value.startswith("/") and len(value) > 2 and value[2] == ":":
        value = value[1:]
    return Path(value).resolve()

class LspClient:
    def __init__(self, command: list[str], cwd: Path, env: dict[str, str] | None = None):
        self.command = command
        self.cwd = cwd
        self.env = env
        self.process: subprocess.Popen[bytes] | None = None
        self._id = 0
        self._messages: "queue.Queue[dict[str, Any]]" = queue.Queue()
        self._pending: dict[int, dict[str, Any]] = {}
        self.transcript: list[dict[str, Any]] = []
        self.stderr: list[str] = []

    def start(self) -> None:
        self.process = subprocess.Popen(
            self.command,
            cwd=str(self.cwd),
            env=self.env,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            **background_process_options(),
        )
        threading.Thread(target=self._read_stdout, daemon=True).start()
        threading.Thread(target=self._read_stderr, daemon=True).start()

    def _read_stdout(self) -> None:
        assert self.process and self.process.stdout
        stream = self.process.stdout
        while True:
            headers: dict[str, str] = {}
            while True:
                line = stream.readline()
                if not line:
                    return
                if line in (b"\r\n", b"\n"):
                    break
                key, value = line.decode("ascii", errors="replace").split(":", 1)
                headers[key.lower()] = value.strip()
            length = int(headers.get("content-length", "0"))
            body = stream.read(length)
            if not body:
                return
            message = json.loads(body.decode("utf-8"))
            self.transcript.append({"direction": "in", "message": message})
            self._messages.put(message)

    def _read_stderr(self) -> None:
        assert self.process and self.process.stderr
        for line in iter(self.process.stderr.readline, b""):
            self.stderr.append(line.decode("utf-8", errors="replace").rstrip())

    def send(self, message: dict[str, Any]) -> None:
        assert self.process and self.process.stdin
        body = json.dumps(message, separators=(",", ":")).encode("utf-8")
        header = f"Content-Length: {len(body)}\r\n\r\n".encode("ascii")
        self.transcript.append({"direction": "out", "message": message})
        self.process.stdin.write(header + body)
        self.process.stdin.flush()

    def notify(self, method: str, params: Any) -> None:
        self.send({"jsonrpc": "2.0", "method": method, "params": params})

    def request(self, method: str, params: Any, timeout: int = 60) -> Any:
        self._id += 1
        request_id = self._id
        self.send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if request_id in self._pending:
                message = self._pending.pop(request_id)
            else:
                try:
                    message = self._messages.get(timeout=min(0.5, max(0.01, deadline - time.monotonic())))
                except queue.Empty:
                    continue
            if message.get("method") and "id" in message:
                server_method = message.get("method")
                if server_method == "workspace/configuration":
                    items = (message.get("params") or {}).get("items") or []
                    server_result: Any = [{} for _ in items]
                elif server_method in {"client/registerCapability", "client/unregisterCapability", "window/workDoneProgress/create"}:
                    server_result = None
                else:
                    server_result = None
                self.send({"jsonrpc": "2.0", "id": message["id"], "result": server_result})
                continue
            if message.get("id") == request_id:
                if "error" in message:
                    raise CkbError(f"LSP {method} failed: {message['error']}")
                return message.get("result")
            if "id" in message:
                self._pending[int(message["id"])] = message
        raise CkbError(f"LSP request timed out: {method}")

    def stop(self) -> int | None:
        if not self.process:
            return None
        try:
            self.request("shutdown", None, timeout=10)
            self.notify("exit", None)
        except Exception:
            pass
        try:
            return self.process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self.process.terminate()
        try:
            return self.process.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self.process.kill()
            return self.process.wait(timeout=5)

